/* Курированная база ЕГЭ №26. Только требуемые предложения и ключ из двух заданных Google Docs. */
window.TR26_TASKS=[{"id":"R2548","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 9−14 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":9,"hi":14,"s":[[9,"Небо над головой у меня свежо голубело, как в ветреном марте."],[10,"Ближе к западному краю к его ясной лазури примешивалась трудноуловимая жемчужная муть."],[11,"Я долго лежал под этим небом."],[12,"Ощутив голод, пожевал сухарей."],[13,"Наевшись сухарей и почувствовав жажду, сделал пару глотков из фляги."],[14,"Пригревшись на солнышке, даже вздремнул."]],"a":[10],"why":"Притяжательное местоимение «его» (то есть чьё?) в предложении 10 заменяет существительное «небо» из предложения 9.","verifiedBy":"ключ источника"},{"id":"R2587","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 7-14 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":7,"hi":14,"s":[[7,"Я не мог не восхититься тем, как трогательно и тщательно хранят в Стратфорде память о своём гениальном земляке."],[8,"Но наш гид, местный уроженец, быстро развеял мои иллюзии."],[9,"Улыбнувшись, он сказал, что современники и соседи поэта имели весьма приблизительное представление о его литературных занятиях."],[10,"И в церкви Шекспир был похоронен не как гений, а как примерный и достаточно щедрый прихожанин."],[11,"Я не мог в это поверить."],[12,"— А почему же тогда сохранили его дом и даже жилище любимой девушки?"],[13,"Гид пожал плечами:"],[14,"— А зачем их рушить?"]],"a":[11],"why":"Указательное местоимение «это» в предложении 11 указывает на факт, изложенный в предложении 10.","verifiedBy":"выведено из пояснения"},{"id":"R2626","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 10-15 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи лексического повтора. Напишите номер(-а) этого(-их) предложения(-ий).","lo":10,"hi":15,"s":[[10,"Ближе к западному краю к его ясной лазури примешивалась трудноуловимая жемчужная муть."],[11,"Я долго лежал под этим небом."],[12,"Ощутив голод, пожевал сухарей."],[13,"Наевшись сухарей и почувствовав жажду, сделал пару глотков из своей фляги."],[14,"Пригревшись на солнышке, даже вздремнул."],[15,"3а это время меня никто не потревожил, ни один человек не прошёл по дороге, на обочине которой я расположился."]],"a":[13],"why":"В предложениях 12-13 используется лексический повтор слова «сухарей».","verifiedBy":"выведено из пояснения"},{"id":"R2767","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 31-35 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":31,"hi":35,"s":[[31,"Я дочитывал мамино письмо со слезами на глазах."],[32,"Из дали прошедших лет я снова услышал её тёплый голос, который принёс мне любовь и утешение, как «незаслуженное земное блаженство»."],[33,"И тогда я подумал, что наша любовь — это нить, которой мы привязаны к любимому человеку."],[34,"Кто любит, у того сердце цветёт и благоухает, и он дарит свою любовь так, как цветок свой запах."],[35,"Такой человек не чувствует себя одиноким."]],"a":[35],"why":"Предложение 35 «Такой человек не чувствует себя одиноким» соединяется с предыдущим при помощи указательного местоимения «такой».","verifiedBy":"выведено из пояснения"},{"id":"R2806","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 37−43 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения, контекстных синонимов и форм слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":37,"hi":43,"s":[[37,"Кажется, в их душах живёт смутное представление о каком-то неведомом крае, где жизнь праведнее и лучше."],[38,"Но ещё вернее будет сказать, что они от чего-то бегут."],[39,"А бегут, конечно, от тоски — этой совсем особенной, непонятной, невыразимой, иногда беспричинной русской тоски."],[40,"В «Борисе Годунове» Мусоргским с потрясающей силой нарисован своеобразный представитель этой бродяжной России — Варлаам."],[41,"Мусоргский с несравненным искусством и мощью передал мироощущение этого бродяги — не то монаха-расстриги, не то просто какого-то бывшего церковного служителя."],[42,"Тоска в Варлааме бездонная, как океан."],[43,"Куда бы этот бродяга ни пошёл, он идёт с готовым сознанием своей абсолютной ненужности."]],"a":[41],"why":"Предложение 41 «Мусоргский (форма слова) с несравненным искусством и мощью передал мироощущение этого (указательное местоимение) бродяги (синоним „Варлаам“)  — не то монаха-расстриги, не то просто какого-то бывшего церковного служителя».","verifiedBy":"ключ источника"},{"id":"R2845","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 56-61 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи форм слова и указательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":56,"hi":61,"s":[[56,"Почему же так долго не мог взяться художник - признанный мастер пейзажа - за кисти и краски?"],[57,"Чего он ждал, чего ему не хватало?"],[58,"Он ждал и нашёл наконец такой момент, когда в природе вдруг всё стало меняться."],[59,"Теперь он мог показать природу в движении."],[60,"«Грачи прилетели!» — так сказалось, так и назвал он свою картину, ставшую впоследствии знаменитой."],[61,"В этой картине он выразил всё, что томило его, чего ожидал он с таким нетерпением, - первое дуновение весны."]],"a":[61],"why":"Сопоставим два предложения:","verifiedBy":"ключ источника"},{"id":"R2944","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 35–40 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":35,"hi":40,"s":[[35,"И вот он под ногами – полюс."],[36,"Величественный белый мир."],[37,"Чуть шевелится флаг на мачте, будто во сне."],[38,"Под ним на льду – шар-контейнер с такими дорогими для нас символами родной земли."],[39,"Это останется на полюсе."],[40,"Остаются у флага и портреты легендарных полярников: Седова, Русанова, Толля."]],"a":[38],"why":"Предложение 38 «»Под ним на льду  — шар-контейнер с такими дорогими для нас символами родной земли» соединяется с предыдущим предложением 37 при помощи личного местоимения ПОД НИМ (Под ним, т. е. под флагом, о котором говорится в предложении 37».","verifiedBy":"выведено из пояснения"},{"id":"R2983","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1–7 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи противительного союза. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":7,"s":[[1,"В некотором городе жил один чудак…"],[2,"Был он очень богат и имел всё из вещей, что человек может себе только пожелать."],[3,"Дом его украшали мраморные лестницы, персидские ковры и золочёная мебель."],[4,"В саду, окружавшем этот роскошный дворец, благоухали цветы, били прохладные фонтаны, заморские птицы услаждали слух своим причудливым пением."],[5,"Однако, несмотря на внешнее благополучие, наш чудак чувствовал, что ему не хватает чего-то самого главного, чего он даже и назвать не мог."],[6,"Человек решительный и отважный, он так много мог, он почти всё смел, но он не знал такого, к чему можно стремиться, и жизнь казалась ему бессмысленной и мёртвой."],[7,"Ничто не радовало его, и богатство, всё более умножаясь, постепенно становилось для него горестным бременем."]],"a":[5],"why":"К противительным союзам относятся союзы: А, НО, ДА (В ЗНАЧЕНИИ НО), ОДНАКО.","verifiedBy":"проверено по пояснению"},{"id":"R3022","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 35–40 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":35,"hi":40,"s":[[35,"И вот он под ногами – полюс."],[36,"Величественный белый мир."],[37,"Чуть шевелится флаг на мачте, будто во сне."],[38,"Под ним на льду – шар-контейнер с такими дорогими для нас символами родной земли."],[39,"Это останется на полюсе."],[40,"Остаются у флага и портреты легендарных полярников: Седова, Русанова, Толля."]],"a":[39],"why":"Указательные местоимения: ЭТА, ЭТОТ, ЭТО, ТА, ТОТ, ТО.","verifiedBy":"проверено по пояснению"},{"id":"R3061","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1–7 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":7,"s":[[1,"Жил однажды чудак…"],[2,"Он был очень богат и имел всё из вещей, что человек может себе только пожелать."],[3,"Дом его украшали мраморные лестницы, персидские ковры и золочёная мебель."],[4,"В саду, окружавшем этот роскошный дворец, благоухали цветы, били прохладные фонтаны, заморские птицы услаждали слух своим причудливым пением."],[5,"Однако, несмотря на внешнее благополучие, наш чудак чувствовал, что ему не хватает чего-то самого главного, чего он даже и назвать не мог."],[6,"Человек решительный и отважный, он так много мог, он почти всё смел, но он не знал такого, к чему можно стремиться, и жизнь казалась ему бессмысленной и мёртвой."],[7,"Ничто не радовало его, и богатство, всё более умножаясь, постепенно становилось для него горестным бременем."]],"a":[3],"why":"Притяжательные местоимения отвечают на вопрос ЧЕЙ? Предложение 3: Дом ЧЕЙ? его. А во втором предложении речь идет о чудаке, так что дом чудака, а ЕГО  — притяжательное местоимение.","verifiedBy":"выведено из пояснения"},{"id":"R3136","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 3–7 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":3,"hi":7,"s":[[3,"Но вот однажды, когда разгулялся на море шторм, кончилась дружба двух приятелей: одного из них подхватила забежавшая на берег волна и унесла с собой далеко в море."],[4,"Другой камень, уцепившись за гнилую корягу, сумел удержаться на берегу и долго не мог прийти в себя от страха."],[5,"А когда немного успокоился, нашёл себе новых друзей."],[6,"Это были старые, высохшие и потрескавшиеся от времени комья глины."],[7,"Они с утра до вечера слушали рассказы Камня о том, как он рисковал жизнью, какой подвергался опасности во время бури."]],"a":[7],"why":"Личные местоимения чаще всего ОН, ОНО, ОНИ, ОНА заменяют существительные из предыдущего предложении.","verifiedBy":"ключ источника"},{"id":"R3175","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 30−38 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":30,"hi":38,"s":[[30,"Константин Николаевич дёрнул в раздражении головой и ушёл в свою комнату."],[31,"Встал у окна, бездумно глядя на улицу."],[32,"«Чёрт знает что, − кипело у него на сердце, − и она ещё иронизирует."],[33,"Нет, надо вернуться и заставить её снять паутину, потыкать носом, а то «придираешься»..."],[34,"И он пошёл к жене."],[35,"Но то, что он увидал, заставило его замереть."],[36,"Анастасия Петровна стояла в углу и напряжённо, как это бывает у плохо видящего человека, всматривалась в стены, видимо отыскивая паутину."],[37,"В её лице и во всей фигуре было что-то жалкое, беспомощное."],[38,"− Настя! − встревоженно позвал Константин Николаевич."]],"a":[37],"why":"Притяжательные местоимения, как и притяжательные прилагательные отвечают на вопрос ЧЕЙ. НАПРИМЕР, МОЙ, ТВОЙ, ЕГО, ЕЕ (НЕ ПУТАЙТЕ С ЛИЧНЫМИ МЕСТОИМЕНИЯМИ, СТАВЬТЕ ВОПРОСЫ). В предложении 37: В ЛИЦЕ (ЧЬЕМ?) ЕЕ..","verifiedBy":"выведено из пояснения"},{"id":"R3244","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 52-62 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза, личного местоимения и указательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":52,"hi":62,"s":[[52,"Трусость в тяжкий для Родины час требует наказания."],[53,"Но у кого поднялась бы сейчас рука на этого жалкого, ссохшегося, с потухшими от страдания глазами человека, пережившего семь тысяч дней страха, наказавшего себя сверх всякой меры!"],[54,"Этот человек и теперь говорит: «Живём один раз»."],[55,"Но он понимает, как беспощадны для него эти слова."],[56,"Двадцать золотых лет зачёркнуто в жизни."],[57,"Да и теперь что за жизнь?"],[58,"Не всякий подаёт руку."],[59,"А когда идёт по селу, острый слух ловит шёпот:"],[60,"— Дезертир..."],[61,"Презрение людей – самое тяжкое наказание для человека."],[62,"А живём один раз..."]],"a":[55],"why":"Но он понимает, как беспощадны для него эти слова.","verifiedBy":"ключ источника"},{"id":"R5476","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 7−14 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения. Напишите номер этого предложения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":7,"hi":14,"s":[[7,"Командир отвинтил крышку с алюминиевого цилиндра, вытащил бумагу, свёрнутую трубкой, и прочитал:"],[8,"«Вы окружены со всех сторон."],[9,"Предлагаю вам капитулировать."],[10,"Условия капитуляции: весь гарнизон форта без оружия идёт на площадь возле кирхи."],[11,"Ровно в шесть часов по среднеевропейскому времени на вершине кирхи должен быть выставлен белый флаг."],[12,"За это я обещаю вам подарить жизнь."],[13,"В противном случае – смерть."],[14,"Командир немецкого десанта контр-адмирал фон Эвершарп»."]],"a":[12],"why":"Предложение 12 связано с предложением 11 с помощью указательного местоимения ЭТО.","verifiedBy":"выведено из пояснения"},{"id":"R5515","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 31−41 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения. Напишите номер этого предложения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":31,"hi":41,"s":[[31,"Крики остановились в той стороне толпы, с которой шёл ребёнок, и толпа, расступаясь перед ним, как перед силой, пропускала ребёнка всё ближе и ближе к отцу."],[32,"−Тебе сколько лет, мальчик?"],[33,"−Что вы с батей хотите делать? − отвечал мальчик."],[34,"−Иди домой, мальчик, иди к матери, − сказал мальчику один из мужчин."],[35,"Пленный уже слышал голос мальчика и слышал, что говорили ему."],[36,"Лицо его стало ещё мрачнее."],[37,"−У него нет матери! − крикнул он на слова того, кто отсылал ребёнка к матери."],[38,"Всё ближе и ближе протискиваясь в толпе, мальчик добрался до отца и полез к нему на руки."],[39,"В толпе кричали всё то же:"],[40,"«Убить!"],[41,"Повесить!"]],"a":[36],"why":"Предложение 36 связано с предыдущим с помощью притяжательного местоимения ЕГО.","verifiedBy":"выведено из пояснения"},{"id":"R5554","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 14−20 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи противительного союза. Напишите номер(-а) этого(-их) предложения(-ий).","lo":14,"hi":20,"s":[[14,"Ишь ведь испужался, ай-ай! – качал он головой."],[15,"Полно, родный."],[16,"Ишь, малец, ай!"],[17,"Он протянул руку и вдруг погладил меня по щеке. −"],[18,"Полно же, ну, Христос с тобой, окстись."],[19,"Но я не крестился: углы моих губ вздрагивали, и, кажется, это особенно его поразило."],[20,"И тогда Марей протянул свой толстый, с чёрным ногтем, запачканный в земле палец и тихонько дотронулся до вспрыгивающих моих губ. −"]],"a":[19],"why":"Предложение 19 соединяется с предыдущим при помощи противительного союза НО.","verifiedBy":"выведено из пояснения"},{"id":"R6034","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 49-58 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи сочинительного союза, личного и указательного местоимений. Напишите номер(-а) этого(-их) предложения(-ий).","lo":49,"hi":58,"s":[[49,"Ещё чище!"],[50,"Здравствуйте!"],[51,"Теперь уж и мать плохая!"],[52,"Не видали вы плохих-то матерей."],[53,"Вон по двору детишки бегают: у иного и под носом не промыто, и пуговицы все оборванные..."],[54,"А у моей всё начищено да наглажено."],[55,"Я берегу девочку, чтобы никакой работы, никакой заботы, не позволяю ей носового платка выстирать!"],[56,"И незачем ей это делать: у нас есть домработница, мы за это ей платим..."],[57,"Ишь ты!"],[58,"Это я-то плохая мать!"]],"a":[56],"why":"Предложение 56 связано с предыдущим с помощью сочинительного союза И, указательного местоимения ЭТО и личного местоимения ЕЙ.","verifiedBy":"выведено из пояснения"},{"id":"R6073","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1−7 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи вводного слова и личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":7,"s":[[1,"И думать нечего: он совершенно чужой мне человек..."],[2,"Когда я смотрю на фотографии, я едва могу представить себе, какой он сейчас, как говорит, смеётся, как держит на руках свою маленькую дочь."],[3,"Кажется, её зовут Марина..."],[4,"Впрочем, всё это ни к чему."],[5,"Мы уже давно совершенно чужие люди..."],[6,"Мама рассталась с отцом лет десять назад."],[7,"И хотя она уверяет меня, что я не могу ничего помнить, так как была слишком мала, я помню."]],"a":[3],"why":"Предложение 3 соединяется с предыдущими при помощи вводного слова «кажется» и личного местоимения «её».","verifiedBy":"выведено из пояснения"},{"id":"R6254","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 7–18 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного наречия и личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":7,"hi":18,"s":[[7,"И вот он, бой."],[8,"Танк, в котором они находились, мотало из стороны в сторону, трясло так, что Катя едва удерживалась на сиденье."],[9,"«Если так будет дальше, как же стрелять?» — думала она."],[10,"Хотя её дело было не наводить пушку, а подавать снаряды."],[11,"Тужливо рыча, машины настырно карабкались вверх, от моторов, пущенных на полные обороты, жара стояла несусветная, ещё пахло соляркой, забивало отработанными газами, свежим воздухом тянуло только через технические зазоры и смотровую щель."],[12,"Тут по раскалённой от боя броне танка что-то застрекотало, однако Катя не сразу осознала, что их обстреливают."],[13,"Всё дальнейшее слилось для неё в сплошной грохот, дым, крики в переговорном устройстве."],[14,"Лупили то подкалиберными, то бронебойно-зажигательными, то осколочными снарядами."],[15,"Катя не понимала, что происходит снаружи, не могла ещё по видам снарядов, подаваемых ею, определить обстановку."],[16,"Она только слышала грохот; её, такую хрупкую и маленькую девушку, дёргало вместе с огромной машиной."],[17,"Страха, как ни странно, Катя вовсе не испытывала: она плохо соображала, что к чему, только слышала команды и выполняла их."],[18,"Бой шёл как бы сам по себе, а она была сама по себе."]],"a":[9],"why":"Предложение 9 соединяется с предыдущими при помощи указательного наречия «так» и личного местоимения «она».","verifiedBy":"выведено из пояснения"},{"id":"R6293","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 11—18 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":11,"hi":18,"s":[[11,"Наш караван остановился у мыса, ожидая приближения заинтересовавшего всех предмета."],[12,"— А ведь это, братцы, козули, — сказал наконец один из ямщиков."],[13,"Действительно, это оказались две горные козы."],[14,"Теперь уже ясно были видны их тёмные изящные фигурки среди настоящего ледяного кошмара."],[15,"Одна из коз была побольше, другая поменьше."],[16,"Мы предположили, что это были мать и дочь."],[17,"Причём старшая явно руководила переправой."],[18,"Вокруг них безжалостные льдины бились, сталкивались, вертелись и крошились; в промежутках что-то кипело и брызгало пеной, а нежные животные, насторожившись, стояли на ледяном куске, подобрав в одно место свои тоненькие ножки..."]],"a":[14],"why":"Предложение 14 соединяется с предыдущими при помощи притяжательного местоимения «их».","verifiedBy":"выведено из пояснения"},{"id":"R6332","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1—9 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи контекстного синонима. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":9,"s":[[1,"— Мне в Борисоглебский переулок, — сообщила я молодому таксисту, — дом-музей Марины Цветаевой."],[2,"— Парень включил навигатор, стал всматриваться в карту маршрута."],[3,"— Там она и жила с семьёй, — добавила я задумчиво скорее самой себе."],[4,"— Кто жил? — переспросил он через минуту."],[5,"— Цветаева, поэт, знаете?"],[6,"Он улыбнулся:"],[7,"— Не-а."],[8,"Такого ответа я никак не ожидала."],[9,"В принципе, размышляла я, уставившись в окно перед собой и изредка косясь на водителя, симпатичного и блондинистого, человеком можно быть хорошим... и не знать поэтов-писателей."]],"a":[2],"why":"Предложение 2 соединяется с предыдущим с помощью контекстного синонима: молодой таксист  — парень.","verifiedBy":"выведено из пояснения"},{"id":"R6371","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1—11 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза и однокоренного слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":11,"s":[[1,"Художественное творчество, с моей точки зрения, не просто способ самовыражения."],[2,"Порой оно может стать спасительной соломинкой, уцепившись за которую человек может пройти через многие тяжёлые испытания и выжить."],[3,"И вот один из поразительных примеров."],[4,"Удивительная женщина, художник-любитель Евфросинья Антоновна Керсновская много лет провела в сталинском лагере, после чего начала зарисовывать всю свою жизнь с самого начала: детство в Бессарабии, как была арестована в Румынии, как её в Сибирь сослали."],[5,"Много лет она изображала быт, детали и комментировала свои рисунки."],[6,"Вот что она пишет маме:"],[7,"«Я их рисовала для тебя, думая о тебе..."],[8,"Я начала рисовать там, в Норильске, сразу после того, как вышла из лагеря."],[9,"Не было ещё ни тюфяка, ни простыни, не было даже своего угла."],[10,"Но я уже мечтала нарисовать что-то красивое, напоминающее прошлое — то прошлое, которое неразрывно было связано с тобой, моя родная!"],[11,"И единственное, что я могла придумать, это — рисовать...»"]],"a":[11],"why":"Предложение 11 соединяется с предыдущим при помощи союза «И» и однокоренного слова «РИСОВАТЬ».","verifiedBy":"ключ источника"},{"id":"R6715","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 37—43 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":37,"hi":43,"s":[[37,"Но он не изменил своего решения."],[38,"На его последний урок пришло много ребят."],[39,"Мы ожидали, что он скажет нам что-нибудь на прощание, ожидали каких-то особенных и значительных слов: мы знали, это он умел."],[40,"Но он ушёл буднично, назвал номера параграфов, заданных на дом, кивнул и только у дверей чуть задержался."],[41,"Мы встали, нестройно хлопнув крышками парт, он посмотрел на нас и тихо сказал:"],[42,"— Когда у вас будет новый классный … не устраивайте этого."],[43,"Мы поняли, о чём он говорил."]],"a":[38],"why":"Предложение 38 связано с предыдущим с помощью притяжательного местоимения (обозначающего принадлежность) ЕГО.","verifiedBy":"выведено из пояснения"},{"id":"R6754","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 12—19 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":12,"hi":19,"s":[[12,"Итак — искусство жизни!"],[13,"Прежде всего: спокойно и мужественно смотреть в глаза врагу!"],[14,"Нам никогда не избавиться от будней."],[15,"Они будут всегда."],[16,"Они составляют материю нашей жизни."],[17,"И если праздник служит лишь тому, чтобы, подобно молнии, осветить серость будней и обличить повседневность, то он нам вреден и мы недостойны его."],[18,"Только тот заслужил радость праздника, кто полюбил свои будни."],[19,"Как этого добиться?"]],"a":[19],"why":"Предложение 19 связано с предыдущим с помощью указательного местоимения ЭТОГО, местоимением заменяется целое предложение 18.","verifiedBy":"ключ источника"},{"id":"R7020","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 39–48 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи противительного союза и указательного наречия. Напишите номер(-а) этого(-их) предложения(-ий).","lo":39,"hi":48,"s":[[39,"Пошёл к мусорному отсеку, наивно надеясь, что её отнесли туда – причём бережно, не отломав головы…"],[40,"«И это в век, когда время – деньги?"],[41,"Размечтался."],[42,"Уймись!» – размышлял я по дороге."],[43,"Конечно, возле баков никакой снежной бабы не было."],[44,"Зато там стояли ёлки."],[45,"И я расстроился ещё больше: Новый год не пришёл, а они уже выброшены…"],[46,"Отпразднуют в офисе – и ёлки выносят, как мусор."],[47,"Обидно."],[48,"Кончился праздник, ещё не начавшись?"]],"a":[44],"why":"Предложение 44 связано с предыдущим с помощью указательного местоименного наречия ТАМ и союза ЗАТО.","verifiedBy":"выведено из пояснения"},{"id":"R7060","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 3–9 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи форм слова, указательного местоимения и синонима. Напишите номер(-а) этого(-их) предложения(-ий).","lo":3,"hi":9,"s":[[3,"В кустах возле орудия поставили зеркало и столик, все сгрудились вокруг, нетерпеливо дожидаясь очереди и заранее гладя подбородки."],[4,"Пощёлкивая ножницами, как кастаньетами, парикмахер Леонард пел, мурлыкал, острил, гибкие его пальцы играли блестящими инструментами."],[5,"Дождавшись своей очереди, я сел на стул и невольно залюбовался в зеркале пальцами этого цирюльника."],[6,"Каждый палец его, бледный и изящный, жил, казалось, своей осмысленной, умной жизнью, подхватывая кольцо ножниц, зажимая гребёнку или выбивая трель на машинке, в весёлой шаловливости, в постоянном следовании за песенкой, сопровождавшей работу."],[7,"Не удержавшись, я сказал: −"],[8,"С такими пальцами и слухом вам бы, пожалуй, на скрипке играть."],[9,"Он посмотрел на меня в зеркало и хитро подмигнул. −"]],"a":[5],"why":"Предложение 5 связано с предыдущим с помощью синонимов «парикмахер-цирюльник», указательного местоимения «этого» и форм слов «пальцы  — пальцами».","verifiedBy":"выведено из пояснения"},{"id":"R7099","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 27–39 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи однокоренного слова, указательного местоимения и личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":27,"hi":39,"s":[[27,"Филатов, расталкивая встречных, бежал на корму, и Кротких догадался, что тот задумал."],[28,"Догадка эта поразила его."],[29,"И тут же в голове вспыхнула мысль: комиссар не должен погибнуть, он должен остаться в команде, иначе как же корабль без него!"],[30,"Забыв о страхе, в два прыжка парнишка очутился у ящика и ухватился за дно."],[31,"Ящик был слишком тяжёл для одного человека."],[32,"Тогда он присел на корточки и схватил одну горячую мину."],[33,"Ладонь зашипела, острая боль на миг захолонула сердце, но Андрей всё же отправил мину за борт."],[34,"И тотчас схватил другую."],[35,"Выпрямляясь с очередной миной в руках, он увидел комиссара: тот был уже совсем близко к своей возможной гибели."],[36,"Тогда Кротких, надсаживаясь, поднял на поручни опустошённый уже наполовину ящик."],[37,"Пламя лизнуло его лицо."],[38,"Бушлат загорелся."],[39,"Он отвернул лицо и сильным, резким толчком сбросил за борт ящик."]],"a":[28],"why":"Предложение 28 присоединяется к предыдущему при помощи указательного местоимения ЭТА, личного местоимения ЕГО и однокоренного слова «догадался(№ 27)  — догадка (№ 28)».","verifiedBy":"выведено из пояснения"},{"id":"R7138","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1–9 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения и указательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":9,"s":[[1,"Накануне Витю предупредили, что завтра пионеры, члены кружка собаководов, будут передавать своих подросших, повзрослевших щенков пограничникам, чтобы четвероногие солдаты верой и правдой служили на благо Отечества."],[2,"Ему было и грустно, и радостно от этого."],[3,"Завтра его Буян уедет далеко-далеко, и Витя больше никогда не увидит его…"],[4,"Буян – это овчарка; она появилась у Вити в доме ещё слепым щенком."],[5,"А после того как пёс подрос, мальчик обучал его различным командам, холил, лелеял и просто любил всем сердцем."],[6,"Минула ночь."],[7,"Всё это утро Витя был молчалив и задумчив."],[8,"Отец и мать обменивались понимающими взглядами, но ни о чём не спрашивали сына."],[9,"В половине двенадцатого Витя надел на пса ошейник, прицепил Буяна к поводку и в последний раз повёл."]],"a":[2],"why":"Предложение 2 присоединяется к предыдущему при помощи указательного местоимения ЭТОГО и личного местоимения ЕМУ.","verifiedBy":"выведено из пояснения"},{"id":"R8151","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 15—20 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":15,"hi":20,"s":[[15,"В детстве я любил рассматривать старый английский журнал периода войны четырнадцатого года."],[16,"У него не было ни начала, ни конца, зато были изумительные картинки — большие, на целую страницу: английские томми в окопах, атаки, морские сражения с пенящимися волнами и таранящими друг друга миноносцами, смешные, похожие на этажерки, парящие в воздухе «блерио», «фарманы» и «таубе»."],[17,"Трудно было оторваться."],[18,"Но страшнее всего было громадное, на двух средних страницах, до дрожи мрачное изображение горящего от немецких бомбардировок Лувена."],[19,"Тут были и пламя, и клубы дыма, похожие на вату, и бегущие люди, и разрушенные дома, и прожекторы в зловещем небе."],[20,"0дним словом, это было до того страшно и пленительно, что перевернуть страницу не было никаких сил."]],"a":[16],"why":"Предложение 16 связано с предыдущим при помощи личного местоимения «у него».","verifiedBy":"ключ источника"},{"id":"R8176","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1−8 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза и лексического повтора. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":8,"s":[[1,"Деньги — это средство распределения материальных благ по труду, а отнюдь не цель существования, не основа престижа и влиятельности личности."],[2,"Однако при всей служебности своей роли деньги постоянно присутствуют в наших взаимоотношениях, и вопросы, связанные с деньгами, представляют широкое поле для формирования таких качеств, как честность, благородство, скромность, деликатность, обязательность."],[3,"Кроме того, воспитание правильного взгляда на роль денег состоит в том, чтобы внушить детям их истинное значение, показать их действительное место в ряду основных жизненных ценностей: познания, творческого труда, духовного и интеллектуального общения."],[4,"Наверное, именно поэтому сегодня родителей очень волнуют вопросы влияния семьи на отношение к материальным ценностям, к деньгам."],[5,"Что должна и что может сделать семья, для того чтобы предотвратить в детях проявления мещанского своекорыстия, собственничества, «вещизма»?"],[6,"Что должна и что может сделать семья для того, чтобы дети, которые растут в материальном достатке, в окружении множества добротных и красивых вещей, не оказались у них в духовном плену?"],[7,"Сначала никто в семье не придал значения тому, что маленькая Алёнка на просьбу: «Дай мне игрушку», — неизменно отвечала решительным отказом, энергично прижимая к груди погремушку или резиновую зверушку."],[8,"Вскоре характер Алёнки стал вызывать некоторое беспокойство: у неё стали постоянно возникать ссоры с детьми из-за игрушек."]],"a":[2],"why":"Предложение 2 связывается с предыдущим с помощью лексического повтора (деньги) и союза (однако). 6-е подошло бы, но в нём нет союза.","verifiedBy":"ключ источника"},{"id":"R8201","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 30—35 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи подчинительного союза. Напишите номер(-а) этого(-их) предложения(-ий).","lo":30,"hi":35,"s":[[30,"И волноваться, мне кажется, стоит!"],[31,"Это не так давно произошло, фактически лет десять-пятнадцать мы так активно обсуждаем проблемы русского языка, в 1990-е это не обсуждалось."],[32,"В советское время это обсуждалось, но только с точки зрения пуризма, например, с точки зрения невозможности говорить слово «пока», потому что это вульгарно и недопустимо."],[33,"Но мы видим, что «пока» говорят все, и образованные люди в том числе."],[34,"Так что само волнение я расцениваю, скорее, как положительный фактор."],[35,"3начит, нам интересен русский язык!"]],"a":[34],"why":"Предложение 34 связывается с предыдущим с помощью подчинительного союза ТАК ЧТО.","verifiedBy":"ключ источника"},{"id":"R8226","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 11—15 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":11,"hi":15,"s":[[11,"Так воевал лейтенант Егор Дрёмов, покуда не случилось с ним несчастье."],[12,"Во время Курского побоища, когда немцы уже истекали кровью и дрогнули, его танк — на бугре, на пшеничном поле — был подбит снарядом, двое из экипажа тут же убиты, от второго снаряда танк загорелся."],[13,"Водитель Чувилев, выскочивший через передний люк, опять взобрался на броню и успел вытащить лейтенанта: он был без сознания, комбинезон на нём горел."],[14,"Чувилев кидал пригоршнями рыхлую землю на лицо лейтенанта, на голову, на одежду, чтобы сбить огонь."],[15,"Потом пополз с ним от воронки к воронке на перевязочный пункт..."]],"a":[12],"why":"В предложении 12 есть притяжательное местоимение ЕГО, которое связывает предложение с предыдущим.","verifiedBy":"ключ источника"},{"id":"R8276","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 23—27 найдите найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью лексического повтора и личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":23,"hi":27,"s":[[23,"0 кувшинках я упомянул вскользь, дожидаясь восторженного отношения к ним Валерии."],[24,"Она оживилась и начала вспоминать, но только не о жёлтых кувшинках, а о белых лилиях."],[25,"— Ты знаешь, однажды я плавала на лодке по старому руслу какой-то реки."],[26,"3аплыли в такое место, что плыть дальше было нельзя, кроме как по ковру из белых душистых лилий."],[27,"И эта сказка длилась полчаса, может быть, час..."]],"a":[24],"why":"Предложение 24 связано с предыдущим с помощью лексического повтора (кувшинки) и личного местоимения (она).","verifiedBy":"ключ источника"},{"id":"R8326","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 39—43 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":39,"hi":43,"s":[[39,"Впоследствии я убеждался не раз, что правила эти существуют в любом обществе, в каждом коллективе."],[40,"Кое в чём они различаются."],[41,"Это зависит от условий, в которых живут люди."],[42,"Но каких правил поведения ни коснись, в главном они всегда одни и те же: уважай окружающих, считайся с ними."],[43,"Строго соблюдая правила поведения, ты будешь хорошим товарищем всем, кто общается с тобой в семье, в школе, на отдыхе."]],"a":[40],"why":"Предложение 40 связывается с предыдущим с помощью личного местоимения ОНИ (правила).","verifiedBy":"ключ источника"},{"id":"R8426","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 10—14 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личных местоимений. Напишите номер(-а) этого(-их) предложения(-ий).","lo":10,"hi":14,"s":[[10,"Далее моста, по правую сторону реки, отделяются на небосклоне зубчатые силуэты Алексеевского монастыря; по левую, на равнине между кровлями купеческих домов, блещут верхи Донского монастыря."],[11,"А за ним, одеты голубым туманом, восходящим от студёных волн реки, начинаются Воробьёвы горы, увенчанные густыми рощами, которые с крутых вершин глядятся в реку, извивающуюся у их подошвы подобно змее, покрытой серебристою чешуёй."],[12,"Когда склоняется день, когда розовая мгла одевает дальние части города и окрестные холмы, тогда только можно видеть нашу древнюю столицу во всём её блеске, ибо подобно красавице, показывающей только вечером свои лучшие уборы, она только в этот торжественный час может произвести на душу сильное, неизгладимое впечатление."],[13,"Что сравнить с этим Кремлём, который, окружась зубчатыми стенами, красуясь золотыми главами соборов, возлежит на высокой горе, как державный венец на челе грозного владыки?"],[14,"Он алтарь России, на нём должны совершаться и уже совершались многие жертвы, достойные Отечества."]],"a":[14],"why":"Предложение 14 связывается с предыдущим с помощью личных местоимений: ОН, на НЁМ.","verifiedBy":"ключ источника"},{"id":"R8451","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 14—17 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза. Напишите номер(-а) этого(-их) предложения(-ий).","lo":14,"hi":17,"s":[[14,"Нечто подобное испытываешь во сне, когда, подкравшись к двери, слышишь за нею скрытое, затаившееся дыхание какого-то неописуемого существа, которое только и ждёт момента вставить колено, чуть приоткроется малая щёлка, и ворваться к тебе в тёплое, обжитое жильё."],[15,"Такое впечатление, что человечество приблизилось к финалу отпущенной ему скромной вечности."],[16,"А наука, с разбегу пробившись сквозь нулевую фазУ времени и физического бытия, ворвётся в иное, ещё не освоенное математическое пространство с переносом туда интеллектуальной столицы мироздания."],[17,"Очевидный теперь крах вчерашней эры завершится неминуемым пересмотром печально не оправдавшей себя парности Добра и Зла."]],"a":[16],"why":"Предложение 16 связано с предыдущим с помощью сочинительного союза А.","verifiedBy":"ключ источника"},{"id":"R8476","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 10—17 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза, указательного местоимения и форм слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":10,"hi":17,"s":[[10,"Часы показывали два."],[11,"— Но ведь у меня кровь течёт, помогите мне!"],[12,"И тогда она не крикнула."],[13,"Спокойно сказала: — Выйдите отсюда!"],[14,"Я, конечно, вышла."],[15,"Я плакала»."],[16,"«Вы правы, — пишет она дальше, — сравнивая травму, нанесённую криком, с ударом ножа."],[17,"Но такой удар можно нанести и без крика."]],"a":[17],"why":"Предложение 17 связано с предыдущим при помощи союза НО, указательного местоимения ТАКОЙ и форм слова УДАР  — УДАРОМ.","verifiedBy":"ключ источника"},{"id":"R8501","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 36—42 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза, частицы и личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":36,"hi":42,"s":[[36,"Прошло много лет."],[37,"Уже давно серьёзная музыка для меня — необходимость, потребность, счастье."],[38,"А ведь можно было — навсегда и непоправимо — разминуться с ней."],[39,"И обездолить себя."],[40,"Этого не случилось."],[41,"Во-первых, я не встал в позу человека, который, не понимая чего-нибудь, говорит вслух или мысленно: «Ну и не надо!»."],[42,"И потому что не захотел притворяться, делая вид, что понимаю, когда ещё был очень далёк от этого."]],"a":[38],"why":"Предложение 38 связано с предыдущим при помощи союза А, частицы ВЕДЬ и личного местоимения НЕЙ (это форма местоимения ОНА)","verifiedBy":"ключ источника"},{"id":"R8798","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1—8 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":8,"s":[[1,"Детство у меня было замечательным."],[2,"В детстве не было денег, не было интересной работы, но всё это — дело наживное."],[3,"Зато в детстве были отец и мать."],[4,"В нашей семье всегда царил отец со своим непререкаемым авторитетом."],[5,"В мальчишеских играх не было места матери."],[6,"Конечно, без её завтраков, обедов и ужинов я не мог бы жить, но это было так обыденно, что и незаметно..."],[7,"Нежности не были приняты в нашей семье."],[8,"Мы не целовали маму перед сном и не говорили в порыве чувств: — Я тебя люблю..."]],"a":[6],"why":"Предложение 6 связано с предыдущим с помощью притяжательного местоимения ЕЁ.","verifiedBy":"ключ источника"},{"id":"R8848","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1—7 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза, наречия и личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":7,"s":[[1,"Скажу «Таня» — и распахнётся что-то..."],[2,"Словно откроешь утром плотные шторы — и свет ворвётся в дом."],[3,"С Таней мы знакомы с детского садика: ещё совсем крохами ходили в одну группу."],[4,"Но там я её не помню, а первое воспоминание такое."],[5,"Мы с папой гуляли в парке, и вдруг я услышал пронзительный, яркий крик: кто-то звал меня."],[6,"Оказывается, это какая-то девчонка меня окликала."],[7,"Впервые меня так радостно звали."]],"a":[4],"why":"Предложение 4 связано с предыдущим с помощью союза НО, наречия ТАМ и личного местоимения ЕЁ.","verifiedBy":"ключ источника"},{"id":"R8873","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 7—11 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи форм слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":7,"hi":11,"s":[[7,"У каждого яблока на одной и той же яблоньке такое разное выражение."],[8,"Есть яблоко умное, выглядывает из-за листика выпуклиной своего лобика, а есть яблоко любимое — наверху круглое, с круглыми дольками, всегда мне сверху весело смеётся."],[9,"И, бывает, я ему даже пальцем погрожу и скажу..."],[10,"Благодарю язык мой, спасающий меня от тяжёлого молчания, вызывающий мне друга даже из яблоньки!"],[11,"Искусство — это сила восстановления утраченного родства."]],"a":[8,10],"why":"Предложение 8 связано с предыдущим с помощью форм слова: ЯБЛОКА  — ЯБЛОКО.","verifiedBy":"ключ источника"},{"id":"R8898","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 12—16 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи лексического повтора. Напишите номер(-а) этого(-их) предложения(-ий).","lo":12,"hi":16,"s":[[12,"Есть немало людей, разнообразие жизненного репертуара которых сводится к чередованию «Чижика-пыжика» и «Собачьего вальса», оставляя «Танец маленьких лебедей» в области недосягаемой мечты о «высоком»."],[13,"Многие ли хотят хорошо жить, если отличать желание хорошо жить от желания, чтобы хорошо жилось?»"],[14,"Но наряду с такими «существователями» есть и те, кто напряжённо ищет истину."],[15,"Как педагогу, мне довелось встречать молодых людей, жаждущих ясного и чёткого ответа на вопрос о высших ценностях жизни."],[16,"0 ценностях, позволяющих отличать добро от зла и выбирать лучшее и достойнейшее."]],"a":[16],"why":"Предложение 16 связано с предыдущим с помощью лексического повтора ЦЕННОСТЯХ-ЦЕННОСТЯХ.","verifiedBy":"ключ источника"},{"id":"R8923","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 32—38 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи однокоренных слов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":32,"hi":38,"s":[[32,"Никто не ждал, что Мишку взорвёт таким образом: он вдруг начал орать, наступая то на одного, то на другого."],[33,"— Ишь, какие ловкие — в чужую суму-то глядеть!"],[34,"Нет у меня ничего в тумбочке, можете проверить."],[35,"Разрешается."],[36,"При этом он успел метнуть хитрый взгляд на свой тяжёлый замок ."],[37,"Навалившаяся болезнь, страшная усталость, сердоболие, вложенное матерью в единственный каравай хлеба, бесцеремонность, с которой у меня забрали этот каравай, огорчение, что не принёс его, забота ребят, бесстыдная Мишкина ложь — всё это вдруг начало медленно клубиться во мне, как клубится, делаясь всё темнее и страшнее, июльская грозовая туча."],[38,"Клубы росли, расширялись, застилали глаза и вдруг ударили снизу в мозг тёмной волной."]],"a":[38],"why":"Предложение 38 связано с предыдущим с помощью однокоренных слов: клубиться  — клубы.","verifiedBy":"ключ источника"},{"id":"R8948","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 6−14 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения и контекстных синонимов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":6,"hi":14,"s":[[6,"Весь подъезд помнил историю с Иваном, тринадцатилетним подростком, переехавшим в наш дом с больной матерью и полуслепой бабушкой."],[7,"3а свою короткую жизнь подросток успел побывать в колонии за воровство, в подъезде поначалу звучала его громкая ругань."],[8,"С согласия его матери бабушка взялась устроить Ивана на подработку в театр юного зрителя."],[9,"Полгода она буквально за руку водила его на спектакли, горячо обсуждала с ним полученные впечатления, просила описать свои ощущения и эмоции."],[10,"Потом, шаг за шагом, научила работать над собой с помощью дневника."],[11,"Результат превзошёл все ожидания."],[12,"Ванечка, как называла его бабушка, обладая замечательной памятью и абсолютным слухом, оказался одарён и артистическим талантом."],[13,"В течение года он выучил все роли и с лёгкостью подменял отсутствующих актёров."],[14,"Закончив после войны режиссёрское и сценарное отделение ВГИКа, Иван впоследствии стал заслуженным артистом и режиссёром."]],"a":[8],"why":"(7)3а свою короткую жизнь подросток успел побывать в колонии за воровство, в подъезде поначалу звучала его громкая ругань. (8)С согласия его матери бабушка взялась устроить Ивана на подработку в театр юного зрителя.","verifiedBy":"ключ источника"},{"id":"R8973","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 59—64 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи форм слова и притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":59,"hi":64,"s":[[59,"Вот тогда-то и включился Семён Митрофанович на последнем, так сказать, этапе."],[60,"Восемь раз в Архитектурное управление он наведывался; просил, умолял, доказывал."],[61,"Школу нашёл, где танкисты эти учились, музей там организовал."],[62,"С частью списался, с деревней Константиновкой: и из части, и из деревни в назначенный день делегации приехали."],[63,"Матери альбом от части преподнесли и модель «тридцатьчетвёрки», а от деревни четыре урны с землёй."],[64,"С могилы земля, где все четверо её сыновей, все её внуки и все правнуки лежали."]],"a":[64],"why":"Предложение 64 связано с предыдущим с помощью форм слова: землёй  — земля  — и притяжательного местоимения ЕЁ.","verifiedBy":"ключ источника"},{"id":"R8998","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 28—33 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи контекстных синонимов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":28,"hi":33,"s":[[28,"Тётка моя невоздержанна на слово была, взялась полоть в огороде и ну по-чёрному бранить медуницу с календулой."],[29,"Я — доблестный хозяин — к тётке присоединился."],[30,"Приезжаю следующей весной — в огороде у меня пусто и голо, скорбная земля в прошлогодней траве и плесени, ни медуницы, ни календулы нет, и другие растения как-то испуганно растут, к забору жмутся, под строениями прячутся."],[31,"Поскучнел мой огород, впору его уж участком назвать."],[32,"Лишь поздней порой где-то в борозде, под забором, увидел я униженно прячущуюся, сморщенно синеющую медуничку."],[33,"Встал на колени, разгрёб мусор и старую траву вокруг цветка, взрыхлил пальцами землю и попросил у растения прощения за бранные слова."]],"a":[33],"why":"Предложение 33 связано с предыдущим с помощью контекстных синонимов: медуничку  — цветка  — растения.","verifiedBy":"ключ источника"},{"id":"R9048","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1—5 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью указательного местоимения и контекстных синонимов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":5,"s":[[1,"В первую очередь Пелагея сходила в тёмную, без света, боковушку, вынесла небольшую рамку с фотографиями."],[2,"Она дрожащими пальцами потрогала стекло в том месте, где была вставлена крошечная фотокарточка с уголком для печати."],[3,"На снимке просматривались одни только глаза да ещё солдатская пилотка, косо сидевшая на стриженой голове."],[4,"Вот-вот истают с этого кусочка бумаги последние человеческие черты, подёрнутся жёлтым налётом небытия."],[5,"И даже память, быть может, всё труднее, всё невернее воскрешает далёкие, годами застланные черты."]],"a":[4],"why":"Предложение 4 связано с предыдущим с помощью указательного местоимения ЭТОГО и контекстных синонимов: СНИМОК  — КУСОЧЕК БУМАГИ.","verifiedBy":"ключ источника"},{"id":"R9262","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 20−25 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза и личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":20,"hi":25,"s":[[20,"Потом идём к цветущей медоносной траве."],[21,"Дети слышат пчелиную арфу, жужжанье шмеля."],[22,"А он, большой, лохматый, то поднимается над цветком, то опускается."],[23,"Дети в восторге: ведь это почти такая же мелодия, как и записанная, но в музыкальном произведении есть какая-то своеобразная красота, которую композитор подслушал в природе и передал нам."],[24,"Детям хочется ещё раз услышать записанную мелодию."],[25,"В том, что до сих пор казалось им обычным, открылась красота − такова сила музыки."]],"a":[22],"why":"Предложение 22 связано с предыдущим спомощью союза А и личного местоимения ОН.","verifiedBy":"ключ источника"},{"id":"R9318","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 30–37 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":30,"hi":37,"s":[[30,"Целясь, он прижался смуглой щекой к гранатомёту, улёгся поудобней."],[31,"Я ещё подумал: вот так, наверное, все морские пехотинцы, скрывшиеся в складках земной поверхности, исправно и по-хозяйски приготовились к тяжёлой, но необходимой работе."],[32,"А кругом уже ревели моторы, тяжко грохотали гусеницы."],[33,"Казалось, весь мир заполнился железным воем и скрежетом."],[34,"Подняв голову, я увидел танк совсем близко − прёт прямо на нас."],[35,"Его тень, длинная и уродливая, покачиваясь, легла на соседние кусты."],[36,"Когда оглянулся, стальная махина уже проскочила линию окопов, а Садык Джураев, стоя, бросал ей вслед свои учебные гранаты."],[37,"Поглядев на него, я вспомнил про те, что были у меня…"]],"a":[35],"why":"Предложение 35 связано с предыдущим с помощью притяжательного местоимения ЕГО.","verifiedBy":"ключ источника"},{"id":"R9343","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 47−53 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза, личного местоимения и притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":47,"hi":53,"s":[[47,"…Когда же судьба покажет Семенюте не свирепое, а милостивое лицо?"],[48,"И покажет ли?"],[49,"Я думаю − да."],[50,"И будет жить Семенюта вместе со своей мамашей ещё очень долго, будет с ней жить в тихом, скромном и тёплом уюте."],[51,"Но никогда старушка не намекнёт на то, что она знала о его обмане, а он никогда не проговорится о том, что он знал, что она знает."],[52,"Это острое место всегда будет осторожно обходиться."],[53,"Святая ложь − это такой трепетный и стыдливый цветок, который увядает от прикосновения."]],"a":[51],"why":"Местоимения должны заменять слова из предыдущего предложения. И должен быть по условию союз.","verifiedBy":"ключ источника"},{"id":"R9368","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 36−43 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения и форм слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":36,"hi":43,"s":[[36,"…Он силится сблизить руки, свести концы провода вместе."],[37,"Он напрягает мышцы до судорог."],[38,"Всего лишь несколько сантиметров разделяют теперь концы провода!"],[39,"Отсюда к переднему краю обороны, где ожидают сообщения отрезанные товарищи, идёт этот провод…"],[40,"И назад, к командному пункту, тянется он."],[41,"И надрываются до хрипоты телефонисты…"],[42,"А спасительные слова помощи не могут пробиться через какие-то жалкие сантиметры проклятого обрыва!"],[43,"Неужели не хватит жизни, не будет уже времени соединить концы провода?"]],"a":[39],"why":"Предложение 39 связано с предыдущим с помощью указательного местоимения ЭТОТ и форм слов ПРОВОДА  — ПРОВОД.","verifiedBy":"ключ источника"},{"id":"R9396","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 23−30 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения и форм слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":23,"hi":30,"s":[[23,"…Батарея старшего лейтенанта Быкова отбила танковую атаку."],[24,"Огибая берёзовую рощу, пятьдесят танков надвигались на наши боевые порядки."],[25,"«Не пропустить!» − была команда Быкова."],[26,"Уже раненный, этот человек оставался на посту."],[27,"А после на поле боя чернели остатки двадцати шести немецких танков."],[28,"По замыслу немцев, эти танки должны были дойти до Индии."],[29,"Но они погибли."],[30,"У берёзовой рощи…"]],"a":[28],"why":"Предложение 28 связано с предыдущим с помощью указательного местоимения ЭТИ и форм слова ТАНКИ.","verifiedBy":"ключ источника"},{"id":"R9951","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 13−16 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза, указательного местоимения и форм слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":13,"hi":16,"s":[[13,"Мы произносим при детях фразы, которым не придаём значения, но им-то они представляются полными скрытого смысла."],[14,"И взрослому человеку даже сложно представить, сколько невысказанных опасений, сколько невообразимых понятий начинает роиться в детских головках от этих, казалось бы, незначительных фраз!"],[15,"Я вспоминаю, что, когда мне было лет пять или шесть, в наш городок приехала на гастроли театральная труппа и повсюду были расклеены афиши с названием спектакля «Сюрпризы развода»."],[16,"Я не знал тогда значение слова «развод», но смутное предчувствие подсказывало мне, что это одно из тех запретных, притягательных и опасных слов, что приоткрывают завесу над тайнами взрослых."]],"a":[14],"why":"Предложение номер 14 соединяется с предыдущим при помощи союза И, указательного местоимения ЭТИХ и форм слова ФРАЗЫ − ФРАЗ.","verifiedBy":"ключ источника"},{"id":"R10368","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 4—8 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения и форм слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":4,"hi":8,"s":[[4,"Взрослые радуются их вопросам не к месту, а потерю - если не сказать отсутствие - наивности расценивают как шаг вперёд в развитии юного поколения."],[5,"Именно поэтому ребёнок, которого я сегодня увидела, привлёк моё внимание."],[6,"Он на самом деле был ребёнком - доверчивым и бесхитростным, как и должно быть в его возрасте, с сияющими, любопытными глазами, с живыми и лёгкими движениями, естественными для человечка, не так давно появившегося на свет."],[7,"Я видела, как он идёт, пытливо глядя на всё вокруг и стараясь раскрыть тайну, спящую за внешней стороной предметов и событий."],[8,"С его губ беспрестанно слетали вопросы - так велика была в нём жажда познания."]],"a":[6],"why":"В предложении 6","verifiedBy":"ключ источника"},{"id":"R10418","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 22—27 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":22,"hi":27,"s":[[22,"Берг взял краски, бумагу и, не напившись даже чаю, пошёл на озеро."],[23,"Ваня перевёз его на дальний берег."],[24,"Берг торопился."],[25,"Берг хотел всю силу красок, всё умение своих рук, всё то, что дрожало где-то на сердце, отдать этой бумаге, чтобы хоть в сотой доле изобразить великолепие этих лесов, умирающих величаво и просто."],[26,"Берг работал как одержимый, пел и кричал. ..."],[27,"Через два месяца в дом Берга принесли извещение о выставке, в которой тот должен был участвовать: просили сообщить, сколько своих работ художник выставит на этот раз."]],"a":[23],"why":"Предложение 23 «Ваня перевёз его на дальний берег» связано с 22 при помощи местоимение его. (Берга)","verifiedBy":"ключ источника"},{"id":"R10661","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 16–22 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи сочинительного союза и личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":16,"hi":22,"s":[[16,"А в другом письме: «...даже кувалда, которой в своё время орудовал в литейном цехе, не выматывала так, как „лёгонькое“ перо писателя."],[17,"Но и, конечно же, ни одна моя работа и не приносила столько восторга, как это литературное дело."],[18,"Когда вдруг из ничего, из обыкновенного пузырька с чернилами извлечёшь что-то похожее на жизнь, воссоздашь из слов дорогую себе, а иногда и другим людям картинку или характер и замрёшь, как художник перед полотном, поражённый этим волшебством – ведь из ничего получилось!"],[19,"Господи!"],[20,"Да неужели это я сделал?»"],[21,"Безусловно, душа Астафьева, звезда Астафьева будет вечно светить настоящим и будущим его читателям."],[22,"И он вечно будет наш…"]],"a":[22],"why":"(22)И он вечно будет наш…","verifiedBy":"ключ источника"},{"id":"R10780","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 28–33 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи сочинительного союза и указательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":28,"hi":33,"s":[[28,"Вот почему сфера добра требует от каждого из нас внимания к истории – своей и мировой, к культурным ценностям, накопленным всем человечеством, к ценностям гуманитарным в первую очередь."],[29,"Изобразительное искусство, литература, музыка, архитектура, градостроительство и природный ландшафт, созданный одной природой или природой в союзе с человеком, – изучение всех этих гуманитарных ценностей умножает, укрепляет, повышает нравственность отдельного человека и всего общества."],[30,"А без нравственности, в свою очередь, не действуют социальные и экономические, исторические и любые другие законы, которые создают благосостояние и самосознание человечества."],[31,"И в этом огромный практический результат «непрактического» по своей природе добра."],[32,"Вот почему дело каждого в отдельности и всех вместе – приумножать добро, чтить и хранить традиции, знать и уважать родную историю и историю всего человечества."],[33,"Знать это, помнить об этом всегда и следовать путями добра и доброты – очень и очень важно."]],"a":[31],"why":"(30)А без нравственности, в свою очередь, не действуют социальные и экономические, исторические и любые другие законы, которые создают благосостояние и самосознание человечества.","verifiedBy":"ключ источника"},{"id":"R10890","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 9–15 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного наречия. Напишите номер(-а) этого(-их) предложения(-ий).","lo":9,"hi":15,"s":[[9,"…Недавно я стоял у себя в саду у костра, подбрасывая в него листья и сухие ветки."],[10,"Мимо колючей изгороди проходила какая-то старая женщина, лет, наверное, восьмидесяти, она остановилась и стала наблюдать за мной."],[11,"Я поздоровался с ней, тогда она засмеялась и сказала: «"],[12,"Правильно сделали, что развели костёр."],[13,"В нашем возрасте надо приноравливаться к аду»."],[14,"Так был задан тон разговору, в котором мы жаловались друг другу на всяческие болячки и беды, но каждый раз шутливо."],[15,"А в конце беседы мы признались, что при всём при том мы ещё не так уж страшно стары."]],"a":[14],"why":"(13)В нашем возрасте надо приноравливаться к аду». (14)Так был задан тон разговору, в котором мы жаловались друг другу на всяческие болячки и беды, но каждый раз шутливо.","verifiedBy":"ключ источника"},{"id":"R10968","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 20–39 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью однокоренных слов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":20,"hi":39,"s":[[20,"Целые дни он лежал на полянах и с любопытством рассматривал цветы и травы."],[21,"Берг собирал ягоды шиповника и пахучий можжевельник, тщательно рассматривал осенние листья."],[22,"На закатах журавлиные стаи с курлыканьем летели над озером на юг."],[23,"Берг впервые почувствовал глупую обиду: журавли показались ему предателями."],[24,"Они бросали без сожаления этот пустынный, лесной и торжественный край, полный безымянных озёр и непролазных зарослей."],[25,"В сентябре пошли дожди."],[26,"Ярцев собрался уезжать."],[27,"Берг рассердился."],[28,"Как можно было уезжать в разгар этой необыкновенной осени?"],[29,"Отъезд Ярцева Берг ощутил теперь так же, как когда-то отлёт журавлей, – это была измена."],[30,"Чему?"],[31,"На этот вопрос Берг вряд ли мог ответить."],[32,"Измена лесам, озёрам, осени, наконец, тёплому небу, моросившему частым дождём."],[33,"— Я остаюсь, – сказал Берг резко."],[34,"Я хочу написать эту осень."],[35,"Ярцев уехал."],[36,"На следующий день Берг проснулся от солнца."],[37,"Лёгкие тени ветвей дрожали на чистом полу, а за дверью разлилась тихая синева."],[38,"Слово «сияние» Берг встречал только в книгах поэтов, считал его пафосным и лишённым ясного смысла."],[39,"Но теперь он понял, как точно это слово передаёт тот особый свет, какой исходит от сентябрьского неба и солнца."]],"a":[23,29],"why":"В предложении 23 есть слово «журавли», которое является однокоренным к слову «журавлиные», содержащемуся в предложении 22.","verifiedBy":"ключ источника"},{"id":"R12392","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 18–23 найдите такое, которое связано с предыдущим с помощью сочинительного союза и форм слова.","lo":18,"hi":23,"s":[[18,"И наконец, правда ли, что возможно только возможное, а невозможное и в самом деле невозможно?"],[19,"Не таятся ли в вещах и душах, окружающих нас, такие возможности, о которых не всякий и говорить решается?"],[20,"Вот о чём спрашивает человек, и особенно русский человек, свою сказку."],[21,"И сказка отвечает не о том, чего нет и не бывает, а о том, что теперь есть и всегда будет."],[22,"Ведь сказка – это ответ всё испытавшей древности на вопросы вступающей в мир детской души."],[23,"Здесь мудрая древность благословляет русское младенчество на ещё не испытанную им трудную жизнь, созерцая из глубины своего национального опыта трудности жизненного пути."]],"a":[21],"why":"Рассмотрим связь между предложениями.","verifiedBy":"ключ источника"},{"id":"R12442","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 44–54 найдите такое, которое связано с предыдущим с помощью сочинительного союза и форм слова. Напишите номер этого предложения.","lo":44,"hi":54,"s":[[44,"А ты попробуй удивиться."],[45,"Всё в этом мире непросто."],[46,"Всё находится во взаимосвязи."],[47,"Поэтому существуют прекрасные вещи и прекрасные сказки."],[48,"Поэтому существуют мечты и реальность."],[49,"Поэтому существуют дружба и борьба."],[50,"И настоящая музыка, и настоящая живопись, и настоящие стихи."],[51,"И поэтому люди бывают счастливы."],[52,"Жизнь удивительна."],[53,"И люди тоже удивительны."],[54,"И каждый, если бы захотел, мог бы увидеть и узнать в тысячу раз больше, чем знает и видит."]],"a":[53],"why":"Рассмотрим связь между предложениями.","verifiedBy":"ключ источника"},{"id":"R12494","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 15–23 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью сочинительного союза и личного местоимения. Напишите номер(-а) этого(-их) предложения(-й).","lo":15,"hi":23,"s":[[15,"Он вынул левую руку и скорбно провёл ею по лицу."],[16,"«А ведь как легко можно было бы помочь людскому горю: стоило бы только пальцем шевельнуть."],[17,"Вот, например, идёт богатая похоронная процессия."],[18,"Шестерня лошадей в чёрных попонах везёт пышный гроб, а сзади едет чуть ли не на версту вереница карет."],[19,"Факельщики важно выступают с фонарями."],[20,"На лошадях болтаются картонные гербы: хоронят важное лицо, должно быть, сановник умер."],[21,"А сделал ли он во всю жизнь хоть одно доброе дело?"],[22,"Пригрел ли бедняка?"],[23,"Конечно, нет… мишура!»"]],"a":[21],"why":"Рассмотрим связь между предложениями.","verifiedBy":"ключ источника"},{"id":"R12545","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1–7 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью сочинительного союза, указательного местоимения и форм слова.","lo":1,"hi":7,"s":[[1,"Я получил недавно письмо, в котором школьница пишет о своей подруге."],[2,"Учительница литературы предложила этой подруге написать сочинение об очень крупном советском писателе."],[3,"И в этом сочинении школьница, отдавая должное и гениальности писателя, и его значению в истории литературы, написала, что у него были ошибки."],[4,"Учительница сочла всё это неуместным и очень её бранила."],[5,"И вот подруга той школьницы обращается ко мне с вопросом: можно ли писать об ошибках великих людей?"],[6,"Я ей ответил, что не только можно, но и нужно писать об ошибках великих людей, что велик человек не тем, что он ни в чём не ошибался."],[7,"Никто не свободен от ошибок в нашей жизни, в нашей сложной жизни."]],"a":[3],"why":"Рассмотрим связь между предложениями.","verifiedBy":"ключ источника"},{"id":"R12595","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 20–26 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью определительного местоимения, указательного местоимения и лексического повтора. Напишите номер(-а) этого(-их) предложения(-ий).","lo":20,"hi":26,"s":[[20,"По двору, там и сям, были разбросаны деревянные домики, занесённые снегом, забитые досками."],[21,"С ранней весны и до глубокой осени через город проходили переселенцы."],[22,"Их бывало так много, и так они были бедны, что добрые люди выстроили им эти домики, которые сторожил Митрич."],[23,"К осени дома освобождались, а к зиме не оставалось уже никого, кроме Митрича и Аграфены да ещё нескольких детей, неизвестно чьих."],[24,"У этих детей родители либо умерли, либо ушли неизвестно куда."],[25,"Всех таких детей набралось у Митрича в эту зиму восемь человек."],[26,"Он поселил их всех вместе в один домик, где и собирался нынче устроить праздник."]],"a":[25],"why":"Рассмотрим связь между предложениями.","verifiedBy":"ключ источника"},{"id":"R12646","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 64—72 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи собирательного числительного. Напишите номер(-а) этого(-их) предложения(-ий).","lo":64,"hi":72,"s":[[64,"Бубенчиков передразнивал походку Пауля Сеппа."],[65,"Анна Сергеевна нашла, что очень похоже и очень смешно, и засмеялась."],[66,"Козовалов сардонически улыбался."],[67,"Лиза обернулась к матери и крикнула: — Мама, поди сюда!"],[68,"Она и Пауль Сепп остановились у края дороги."],[69,"У обоих были счастливые, сияющие лица."],[70,"Вместе с Анною Сергеевною подошли Козовалов и Бубенчиков."],[71,"Козовалов сказал на ухо Анне Сергеевне: — А нашему эстонцу очень к лицу воинственное воодушевление."],[72,"Смотрите, какой красавец, точно рыцарь Парсифаль."]],"a":[69],"why":"Предложение 69 связано с предыдущим с помощью собирательного числительного «обоих».","verifiedBy":"ключ источника"},{"id":"R12775","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 56–64 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью указательного местоимения, личного местоимения и синонимов.","lo":56,"hi":64,"s":[[56,"— Так ведь это я должен исповедоваться."],[57,"— Сначала я!"],[58,"Помнишь, в шестьдесят девятом была недостача, ты тогда подумал, что Сэм Уиллис прихватил деньги с собой в Мексику?"],[59,"— Конечно, Сэм тогда украл бабки, кто же ещё."],[60,"— Всё это моих рук дело, я прикарманил деньги и свалил на него!"],[61,"— Ну, это не такой уж тяжкий грех, – произнёс Уолтер."],[62,"— Теперь насчёт школьного выпускного в пятьдесят восьмом."],[63,"Ты хотел, чтобы в тот вечер тебя сопровождала Мэри-Джейн Карузо."],[64,"Но я рассказал ей про тебя всякие гадости, и она отказалась!"]],"a":[60],"why":"Предложение 60 связано с предыдущим с помощью указательного местоимения «это», личного местоимения «него» и синонимов «деньги − бабки».","verifiedBy":"ключ источника"},{"id":"R12833","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 41–56 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью определительного местоимения и указательного местоимения.","lo":41,"hi":56,"s":[[41,"— Помните, – начал он, – наш разговор в коридоре у фикуса?"],[42,"— Не помню."],[43,"Какой фикус?"],[44,"Какой разговор?"],[45,"— А я помню."],[46,"Фикус – упрямый, стойкий."],[47,"Его стригут, укрощают, калечат, а он растёт всё в том же направлении – вверх, вверх и вверх."],[48,"Я вспомнила всё это."],[49,"И поняла, зачем Чагин позвал меня."],[50,"— Сращения нет? – всё же спросила я с крупицей надежды."],[51,"— Сращения нет."],[52,"И новая операция вряд ли что-нибудь даст."],[53,"— А перспективы?"],[54,"— Полной реабилитации ждать нельзя."],[55,"Частичная возможна."],[56,"Всё это зависит от Вас."]],"a":[48,56],"why":"Предложение 48 и предложение 56 связаны с предыдущими с помощью определительного местоимения «всё» и указательного местоимения «это».","verifiedBy":"ключ источника"},{"id":"R13776","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 77–86 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим(-ими) при помощи лексического повтора. Запишите номер(-а) этого(-их) предложения(-ий).","lo":77,"hi":86,"s":[[77,"Когда я вышла, Доната и его отца в купе уже не было."],[78,"Поезд прибывал в Москву, и пассажиры пробирались к выходу."],[79,"Тут я заметила на своём чемодане листок бумаги."],[80,"Это оказалась моя записка с адресом института и номером телефона..."],[81,"Может быть, ещё не всё пропало?"],[82,"Может быть, мне удастся отыскать в безднах Москвы мальчика со странным, редким именем Донат?"],[83,"Мальчика, который оказался лишён детства."],[84,"И своего собственного, выбранного душой будущего."],[85,"Непонятого и закрытого ребёнка."],[86,"Живущего в своей, никому не ведомой «долине ужасов»."]],"a":[82,83],"why":"Предложение 83 связано с предыдущим с помощью повтора слова МАЛЬЧИК. В 82 предложении повторяется сочетание МОЖЕТ БЫТЬ.","verifiedBy":"ключ источника"},{"id":"R13828","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 9–15 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью сочинительного союза, личного, определительного и указательного местоимений. Укажите номер(-а) этого(-их) предложения(-ий).","lo":9,"hi":15,"s":[[9,"Скоков взял пятидневный отпуск."],[10,"В этот же день он вынул из банка все деньги и запер их в своём крошечном сундуке."],[11,"А следующий день – канун – Скоков намеревался употребить для приготовлений: оповестить и пригласить сослуживцев, снять ресторанный зал с кабинетами, потревожить портных, цветочные магазины – выполнить всё необходимое кутящему миллионеру."],[12,"Однако, пока он продумывал всё это, в голове зашевелилась одна мысль."],[13,"Как примет организм после десятилетнего истинно аскетического образа жизни всё это обилие чувственных восприятий: вкус тонких, жирных, вкусных, преимущественно рыбных и мясных, яств?"],[14,"Напряжённое волнение музыки?"],[15,"Запах и блеск цветов?"]],"a":[12],"why":"Предложение 12 связано с предыдущим с помощью сочинительного союза ОДНАКО, личного местоимения ОН, определительного местоимение ВСЁ и указательного местоимения ЭТО.","verifiedBy":"ключ источника"},{"id":"R13885","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 38–43 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза, частицы и форм слова. Укажите номер(-а) этого(-их) предложения(-ий).","lo":38,"hi":43,"s":[[38,"Меня много упрекали за сибирский диалект, которым я пользуюсь якобы без меры."],[39,"Но что такое диалект?"],[40,"Это местные прибавки к языку, заимствования от местных народов, подвёрнутые под нашу речь, обозначение областной предметности."],[41,"Пользоваться диалектом действительно нужно разумно."],[42,"Но ведь за диалект зачастую принимают сам досельный русский язык, его заглубленную позднейшими наростами корневую породу."],[43,"А её предлагают зарыть ещё глубже: своё зарыть, а чужое, валом повалившее из «красивых» стран, принять с великими почестями."]],"a":[42],"why":"Предложение 42 и предложение 41 связаны с предыдущими с помощью союза НО, частицы ВЕДЬ и форм слова «диалектом−диалект».","verifiedBy":"ключ источника"},{"id":"R14945","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 9–14 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения и контекстных синонимов.","lo":9,"hi":14,"s":[[9,"— Молодой ещё и глупый."],[10,"Почитай, ему ещё и двух месяцев нет."],[11,"— Так его приучать надо, воспитывать!"],[12,"Возвращаясь из гимназии, дядюшка зашёл в лавку и купил мышеловку."],[13,"За обедом он нацепил на крючок кусочек котлеты и поставил западню под диван."],[14,"Ровно в шесть часов вечера под диваном вдруг раздалось «хлоп!»."]],"a":[13],"why":"Предложения 13 связано с предыдущим с помощью контекстных синонимов «мышеловка − западня» и личного местоимения ОН.","verifiedBy":"ключ источника"},{"id":"R16730","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 14–22 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи однокоренных слов и личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":14,"hi":22,"s":[[14,"Через год, в другом госпитале, в Польше, медсестра дала почитать книжку стихов Есенина."],[15,"Читал его впервые, читал всей палате и заметил, что читать было тяжело."],[16,"А «Анну Снегину» я дочитать не смог."],[17,"Прочитал: «Когда-то у той вон калитки мне было шестнадцать лет, и девушка в белой накидке сказала мне ласково: „Нет“»."],[18,"И запнулся."],[19,"И дышать стало трудно."],[20,"И сколько ребята ни просили, не стал читать дальше и накрылся одеялом с головой."],[21,"И заплакал."],[22,"И вспомнил свою историю, которая до сих пор не имеет конца."]],"a":[15],"why":"Предложение 15 связано с предложением 14 с помощью однокоренных слов «почитать − читать − читал» и личного местоимения «его».","verifiedBy":"ключ источника"},{"id":"R16991","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 27–34 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения и форм слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":27,"hi":34,"s":[[27,"Работа закипела."],[28,"Ванька ловко резал жестяные заготовки из консервной банки, распрямлял их молотком, я размечал, он кроил, вырезал, загибал края и плющил детали ротора и статора, обматывая их медной проволокой, доверив мне тонкую работу по изготовлению контактов якоря из кусочков жести и изоленты."],[29,"Я умолил отца купить в Москве плоскую батарейку, и вот она присоединена к моторчику."],[30,"Чудо!"],[31,"Моторчик зажужжал, подрагивая на деревянной дощечке."],[32,"Есть изделие!"],[33,"Наутро я принёс моторчик на урок физики и продемонстрировал учителю Михаилу Родионовичу."],[34,"Он похвалил меня, и в моём дневнике появилась пятёрка."]],"a":[34],"why":"Предложение 34 связано с предложением 33 с помощью личного местоимения «он» и форм слова «я−меня».","verifiedBy":"ключ источника"},{"id":"R17046","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 40–46 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи сочинительного союза, личного местоимения, форм слов и однокоренных слов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":40,"hi":46,"s":[[40,"Он задумал очень большое дело, хочет сделать людям подарок…"],[41,"За этим человеком охотятся исполнители приговора."],[42,"Настигнут обязательно."],[43,"Так что осталось очень мало времени."],[44,"И человек намерен за год или за два успеть прожить заново свою жизнь."],[45,"А что бы получилось, живи он с максимальной интенсивностью все годы?"],[46,"Жизни у него было бы, может, побольше, чем девятьсот лет."]],"a":[45],"why":"Предложение 45 связано с предложением 44 с помощью однокоренных слов «жизнь − живи», форм слов «год − годы» и сочинительного союза «а».","verifiedBy":"ключ источника"},{"id":"R18088","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 39–45 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения и однокоренных слов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":39,"hi":45,"s":[[39,"Он подходит к снегуру и медлит минуту."],[40,"Потом решительно, с удовольствием ударяет в него ногою."],[41,"Летят рога, рассыпается белыми комьями бычья голова..."],[42,"Ещё один удар — и остаётся только куча снега."],[43,"Озарённый луной, Хрущёв стоит над нею и, засунув руки в карманы куртки, глядит на блещущую крышу."],[44,"Он наклоняет к плечу своё бледное лицо с чёрной бородой, свою оленью шапку, стараясь уловить и запомнить оттенок блеска."],[45,"Потом поворачивается и медленно идёт по тропинке от дома к скотному двору."]],"a":[44],"why":"Предложение 44 связано с предложением 43 с помощью личного местоимения «он» и однокоренных слов «блещущую−блеска».","verifiedBy":"ключ источника"},{"id":"R18196","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 20–30 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущими при помощи сочинительного союза и указательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":20,"hi":30,"s":[[20,"— Наша больница в Круглогорье является самым крупным лечебным учреждением на всём пространстве Круглогорского куста, со стационаром на двадцать пять коек."],[21,"Как видите, задачи перед нами стоят большие, и мы должны быть на высоте."],[22,"Но сейчас мы не на высоте!"],[23,"Больше того, мы представляем из себя совершенно невероятный экспонат прошлого столетия."],[24,"В век телевидения и электроники работаем вслепую."],[25,"А между тем у нас есть и рентгеновский аппарат, и лабораторное оборудование."],[26,"Но всё это поломанное, грязное."],[27,"И в чём же здесь дело?"],[28,"Некому было заняться?"],[29,"Нет, дело в косности."],[30,"Вот вы, Макар Иванович…"]],"a":[26],"why":"Предложение 26 связано с предложением 25 с помощью сочинительного союза «но» и указательного местоимения «это».","verifiedBy":"ключ источника"},{"id":"R18224","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 13–20 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи лексического повтора, указательного местоимения и контекстного синонима. Напишите номер(-а) этого(-их) предложения(-ий).","lo":13,"hi":20,"s":[[13,"В конце недели Зеленин собрал производственное совещание."],[14,"Пришли все работники больницы: пять медсестёр, фельдшер, санитарки, бухгалтер, завхоз и кучер Филимон."],[15,"Все эти люди со скрытой насмешкой, с любопытством и недоверием поглядывали на беспокойного худого юношу, который теперь стал их начальником."],[16,"Персонал привык к тишине и спокойствию."],[17,"Больных было мало, потому что всех мало-мальски серьёзных отправляли в район."],[18,"Для выполнения плана койко-дней Макар Иванович клал в больницу знакомых старушек и упражнялся на них в диагностике."],[19,"Зеленин подумал и неожиданно для самого себя густым голосом сказал:"],[20,"— Наша больница является самым крупным лечебным учреждением на всём пространстве Круглогорского куста, со стационаром на двадцать пять коек."]],"a":[15],"why":"Сопоставим предложения 14 и 15:","verifiedBy":"ключ источника"},{"id":"R18960","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1–10 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи сочинительного союза и личного местоимения.","lo":1,"hi":10,"s":[[1,"Пляж был пуст."],[2,"Друзья прошли на самый край мола1 и постояли там, не в силах оторвать взгляда от заката."],[3,"Солнце, как купол сказочного дворца, возвышалось над сверкающим горизонтом."],[4,"Через всё море, словно след от удара бичом, тянулась красная дрожащая полоса."],[5,"— Вредное зрелище — закат, — сказал Максимов."],[6,"— А по-моему, прекрасное, —ответил Саша Зеленин."],[7,"— А по-моему, вредное."],[8,"Утрачивается уверенность."],[9,"Кажется, что за горизонтом раскинулась прекрасная неведомая страна, где говорят на высоких тонах и все взволнованны и очень счастливы."],[10,"Но на самом-то деле её нет."]],"a":[10],"why":"Предложение 10 связано с предложением 9 с помощью сочинительного союза «но» и личного местоимения «её».","verifiedBy":"ключ источника"},{"id":"R28371","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 35–39 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи противительного союза и лексического повтора. Напишите номер(-а) этого(-их) предложения(-ий).","lo":35,"hi":39,"s":[[35,"Итак, мой секретный внутренний мир — он не был каким-нибудь вызывающим: он всё ещё никак не шумел, но он начинал заселяться и заселяться всё плотнее, теснее…"],[36,"И окно-театр, в котором живые повара плясали вместе со своими тенями, набегавшими на пламенное стекло, — живые с нарисованными рядом, — явилось такой важной вехой моего земного странствия в самом начале его, что, быть может, кому-то это покажется даже смешным."],[37,"При всех возможных скидках на причуды малолетнего воображения подобный тип «открытий», может быть, и вправду смешон!"],[38,"Порядочные люди, вон, открывают законы, эликсиры, заливы, проливы, острова, земли и звёзды, а я-то открыла… лишь несколько человек поваров, работающих в вечернюю смену, не более!"],[39,"Но… судя по необъятным размерам и высокому качеству моего восторга в тот вечер, я, видимо, всё же узнала тогда, что испытывает про себя настоящий, напавший на новую мысль изобретатель или поражённый великим пейзажем подлинный путешественник."]],"a":[39],"why":"Предложение 39 связано с предложением 38 с помощью противительного союза «но» и лексического повтора «я».","verifiedBy":"ключ источника"},{"id":"R29830","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 6–10 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения и форм слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":6,"hi":10,"s":[[6,"Ах, какие это были сны, если, конечно, мне везло и они в самом деле проходили передо мною, как на экране!"],[7,"Признаться, это случается со мной и сейчас, хотя возраст — как бы это поизящнее выразиться — внёс существенные коррективы в мои сценарии снов."],[8,"В детстве я мечтал обрести способность оказаться в любимых книгах и не только зримо увидеть их героев, но и запросто пообщаться с ними."],[9,"С Питером Марицем, юным буром из Трансвааля, с неугомонным бретёром д'Артаньяном, со знаменитым пиратом капитаном Флинтом или князем Серебряным."],[10,"В детстве я свято верил, что в книгах излагаются исторические события, что их герои — в самом деле существовавшие и, что самое любопытное, продолжающие существовать люди, с которыми можно запросто встретиться где-то там, вне реальности, но вполне реально."]],"a":[7],"why":"Предложение 7 связано с предложением 6 с помощью указательного местоимения «это» и форм слова «мне−мной».","verifiedBy":"ключ источника"},{"id":"R33941","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 2—9 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи сочинительного союза, контекстных антонимов, личного местоимения и однокоренных слов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":2,"hi":9,"s":[[2,"Вспомнил и заволновался."],[3,"Когда-то давно, в детстве, он храбро прыгал и со стула, и со стола, и даже со шкафа, прыгал с высокой ветки в пруд, с крыши своей избы в снежный сугроб, с сарая — в сено, но с парашютом из-под самых облаков — никогда."],[4,"И ему стало страшно!"],[5,"Чтобы никто не догадался о его страхе, Николай решил весь день перед прыжками улыбаться, но тут же почувствовал, что рядом с ним под шинелью дрожит солдат Карасёв, которого все называли Селёдкиным и который тоже сегодня должен будет первый раз в жизни прыгать с парашютом — наверное, поэтому дрожит от страха."],[6,"После подъёма все солдаты выбежали на зарядку."],[7,"И в то утро Николай особенно бодро бегал, так что никто из солдат или офицеров даже подумать не мог, что он боится прыгать."],[8,"А Селёдкин трусил за ним вялой трусцой и думал, какую бы ему придумать неправду, чтобы увильнуть от прыжков."],[9,"Через час после укладки парашютов солдаты Исаев и Карасёв уже шагали по полевой дороге на прыжки."]],"a":[8],"why":"Предложение 8 связано с предложением 7 с помощью сочинительного союза «а», , личного местоимения «(за) ним» и однокоренных слов «прыгать − прыжков».","verifiedBy":"ключ источника"},{"id":"R34136","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 10—15 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения и антонимов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":10,"hi":15,"s":[[10,"Зал замер."],[11,"И тут Лида задела головой декорацию, висевшую под потолком."],[12,"От неожиданности девушка качнулась и начала падать."],[13,"Глеб пытался помочь ей вытянуться, но ему не удалось это, и они оба стали медленно валиться назад."],[14,"Я видела напряжённые руки и спину Володи, невероятные усилия всех трёх выровнять положение."],[15,"И вот, подчиняясь усилиям их воли и мускулов, пирамида стала выпрямляться."]],"a":[13],"why":"Предложение 13 связано с предложением 12 с помощью личного местоимения «ей» и антонимов «падать  — вытянуться».","verifiedBy":"ключ источника"},{"id":"R35462","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 63−70 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи сочинительного союза, указательного местоимения, контекстных синонимов и форм слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":63,"hi":70,"s":[[63,"Пишет вам сестра Ираклия, так как его несколько дней не будет дома."],[64,"Мы все очень рады, что вы выслали деньги, то есть, простите, рады не за деньги, а за вашу честность."],[65,"Был у нас такой случай."],[66,"Наш старший брат одолжил 200 рублей одному приезжему."],[67,"Однако этот человек не только не отдал деньги, но даже не признал брата, когда тот поехал к нему за деньгами."],[68,"А теперь, когда будете в Сухуми, обязательно приезжайте к нам."],[69,"Мы всегда рады людям с добрым и честным сердцем."],[70,"До свидания»."]],"a":[67],"why":"Предложение 67 связано с предложением 66 с помощью сочинительного союза «однако», указательного местоимения «этот», контекстных синонимов «одолжил  — не отдал» и форм слова «брат  — брата».","verifiedBy":"ключ источника"},{"id":"R36126","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 5−14 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи сочинительного союза, частицы, указательного наречия и форм слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":5,"hi":14,"s":[[5,"К восьмидесятилетию она бросила курить, потому что, когда зачем-то полезла на стул, у неё закружилась голова, и это её насторожило."],[6,"И только тогда до меня дошло и восхитило: она опять поступила на работу."],[7,"Мама всегда гордилась тем, что она профессионал."],[8,"Теперь её профессией стала жизнь."],[9,"Своим стареющим сыновьям она зарабатывала уже не на жизнь, а саму жизнь: способность прожить не меньше."],[10,"Как молодой специалист, она не избежала ошибок."],[11,"Чем немощней она становилась, тем настойчивей отбывала срок."],[12,"Никогда ничего не попросить и ни у кого не одалживаться — избыточная самостоятельность её и подвела: каждый день ставя себе цель и неуклонно к ней стремясь, именно с неё она и начала падать, ломая то руку, то ногу, мужественно выкарабкиваясь и ломая снова."],[13,"Так ей исполнилось восемьдесят пять, и она взяла установку на девяносто."],[14,"Но её беспокоила нога."]],"a":[6],"why":"Предложение 6 связано с предыдущим при помощи сочинительного союза «и», частицы «только», указательного наречия «тогда» и форм слова «её  — она».","verifiedBy":"ключ источника"},{"id":"R37072","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 47−53 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи противительного союза и форм слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":47,"hi":53,"s":[[47,"— Вот это верно, — сказал Маленький принц."],[48,"А что же ты с ними делаешь?"],[49,"— Распоряжаюсь ими, — ответил делец."],[50,"Считаю их и пересчитываю."],[51,"Это, признаюсь, для меня очень трудно."],[52,"Но я человек серьёзный."],[53,"Однако Маленькому принцу этого было мало."]],"a":[52],"why":"Предложение 52 связано с предыдущим при помощи противительного союза «но» и форм слова «меня—я».","verifiedBy":"ключ источника"},{"id":"R37957","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 18−23 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи сочинительного союза, указательного местоимения, контекстных синонимов и форм слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":18,"hi":23,"s":[[18,"Бабка Анна хорошо знала не только агротехнику."],[19,"Ей была знакома и психология."],[20,"Горожане готовы были платить любые деньги за довоенную забытую невидаль, за сказочную роскошь — за огурцы, за воспоминание о своём счастливом прошлом."],[21,"И она это знала вперёд и сажала у себя на участке не картошку, не просо, не лук, не жито, которые нужны были голодным людям, как сама жизнь, — потому не сажала, что их снимешь один раз — и конец, а огурцы всё время идут волна за волной, был бы полив, а солнышка в Поволжье сколько хочешь!"],[22,"И она увозила в город мешки огурцов и привозила из города мешки денег."],[23,"А я таскал и таскал эти будто кирпичами нагруженные вёдра, рвал свои мышчонки изо дня в день, из недели в неделю без выходных."]],"a":[21],"why":"Предложение 21 связано с предыдущим при помощи сочинительного союза «И», указательного местоимения «ЭТО»,","verifiedBy":"ключ источника"},{"id":"R39761","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1−6 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного и притяжательного местоимений. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":6,"s":[[1,"Полжизни Виктор Дмитриевич Дувакин проработал на филологическом факультете Московского университета."],[2,"Нам, его последним дипломникам, он казался в нашу студенческую пору старым-престарым."],[3,"Ещё бы: он был на похоронах Есенина, дважды видел Маяковского..."],[4,"Массивный, медлительный, по-профессорски рассеянный, Виктор Дмитриевич никак не мог избежать внимания записных остроумцев."],[5,"Их удачи он принимал без видимого огорчения — снисходительно и добродушно, а то и с откровенным удовольствием."],[6,"«Уж полночь близится — Дувакина всё нет!..» — пели, изображая отчаяние, заждавшиеся студенты в университетском капустнике."]],"a":[2,5],"why":"Предложение 2 связано с предыдущим с помощью личного местоимения «он» и притяжательного местоимения «его».","verifiedBy":"ключ источника"},{"id":"R39797","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 26−33 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи сочинительного союза, личного местоимения и указательного наречия. Напишите номер(-а) этого(-их) предложения(-ий).","lo":26,"hi":33,"s":[[26,"«Бесконечность» Виктора Дмитриевича стала очевидной для многих в феврале 1966 года, когда судили Андрея Синявского, его бывшего студента из семинара по Маяковскому."],[27,"Дувакина вызвали в суд свидетелем."],[28,"И он сказал там то, что сказал бы у себя дома, на кафедре или в студенческой аудитории."],[29,"Он помнил Андрюшу с первых занятий, когда тот выглядел ещё классическим гадким утёнком."],[30,"Но время шло, и гадкий утёнок на глазах превратился в прекрасного белого лебедя..."],[31,"Судья вынужден был остановить свидетеля."],[32,"Для этого мрачного места больше подходили другие слова, которыми, кстати, вовсю осыпали Синявского и Даниэля в газетах: подонки, оборотни, пасквилянты, нравственные уроды, наследники Смердякова..."],[33,"Если бы Дувакин ими воспользовался, если бы подтолкнул своего воспитанника за решётку, он выполнил бы долг советского преподавателя и коллеги по филфаку гордились бы им."]],"a":[28],"why":"Предложение 28 связано с предыдущим с помощью сочинительного союза И, личного местоимения ОН и указательного наречия ТАМ.","verifiedBy":"ключ источника"},{"id":"R41239","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 44−53 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи противительного союза, частицы и притяжательного местоимения. Запишите номер(а) этого(-их) предложения(-ий).","lo":44,"hi":53,"s":[[44,"Почему же не сказалось то же у братьев и сестёр?"],[45,"А потому, что они были нормальными и счастливыми."],[46,"Меня же унижала всё время глухота, бедная жизнь и неудовлетворённость."],[47,"Но именно она то и дело подгоняла мою волю, заставляла работать, искать."],[48,"Возможно, что умственные задатки у меня слабее, чем у братьев: я же был моложе всех и потому поневоле должен быть слабее умственно и физически."],[49,"И только крайнее напряжение сил сделало меня тем, что я есть."],[50,"Глухота — ужасное несчастье, и я никому её не желаю."],[51,"Но всё-таки теперь признаю́ её великое значение в моей деятельности — в связи, конечно, с другими условиями."],[52,"Безусловно, причин ещё множество: например, наследственность, удачное сочетание родителей, гнёт судьбы."],[53,"Но всего предвидеть и понять невозможно."]],"a":[51],"why":"Предложение 51 связано с предыдущим при помощи противительного союза НО, частицы ВСЁ-ТАКИ и притяжательного местоимения ЕЁ.","verifiedBy":"ключ источника"},{"id":"R43661","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 26−33 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательной частицы, указательного местоимения и однокоренных слов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":26,"hi":33,"s":[[26,"Нет, нам нужна другая грамотность."],[27,"Сравнивал ли кто-нибудь количество слов (а следовательно, и понятий), которыми пользовался рабочий царской России, со словарным запасом современного рабочего?"],[28,"Ежедневный бытовой словарь рабочего?"],[29,"Такой подсчёт дал бы ярчайшие результаты."],[30,"И стал бы в какой-то степени измерителем роста культуры."],[31,"Нам нужно обогащать свой словарь, свой мозг."],[32,"Учёные подсчитали, что Шекспир в своих произведениях воспользовался 12 тысячами слов."],[33,"Вот таким словарём культурнейшего человека эпохи должна обладать и наша производственная интеллигенция, которая делается культурнейшей интеллигенцией мира."]],"a":[33],"why":"Предложение 33 связано с предыдущим с помощью указательной частицы «вот», указательного местоимения «таким» и однокоренных слов «слов  — словарём».","verifiedBy":"ключ источника"},{"id":"R43717","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 28−32 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Запишите номер(а) этого(-их) предложения(-ий).","lo":28,"hi":32,"s":[[28,"А порой, разгорячённые, все вместе шли в библиотеку — искать ответ в книгах."],[29,"Благополучно законченная операция у Оли Виноградовой была для врачей не случайной победой."],[30,"Ей предшествовала двухлетняя кропотливая подготовительная работа."],[31,"Операция положила начало более быстрому развитию этого раздела хирургии в клинике Н. Н. Петрова."],[32,"Вслед за ней мы провели несколько подобных: по удалению долей лёгкого, затем по удалению всего лёгкого при абсцессе…"]],"a":[30,32],"why":"Предложение 30 связано с предыдущим с помощью личного местоимения «ей». Предложение 32 связано с предыдущим с помощью личного местоимения «ней».","verifiedBy":"ключ источника"},{"id":"R44677","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 15−27 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":15,"hi":27,"s":[[15,"Гаражей с каждым годом всё больше, как и легковых автомобилей, которые полонят округу: не только улицы, но и дворы, тротуары."],[16,"Они газуют, рычат, сердито сигналят, прогоняя с пути тихоходов, старых или малых, вроде нас."],[17,"Есть и ещё одно развлеченье."],[18,"«Кран», «мусорка», «мусоровоз», «свалка» появились в числе первых слов Мити."],[19,"Потому что рядом целых три «мусорки» с железными баками."],[20,"Одно из любимых зрелищ для малыша — подъём и опрокидывание баков с мусором в просторное чрево мусоровоза."],[21,"Натужное гуденье подъёмника, грохот — разве не развлеченье?"],[22,"А здесь, в дне сегодняшнем, была просто осень."],[23,"И ничего более."],[24,"Обычный погожий денёк с редкими тучами, солнцем."],[25,"Просторная вода, прозрачная у песчаного берега, словно летняя."],[26,"Только ракушек нет."],[27,"Они ушли в глубину, на зимовку."]],"a":[16,27],"why":"Предложение 16 связано с предыдущим с помощью личного местоимения «они». Предложение 27 связано с предыдущим с помощью личного местоимения «они».","verifiedBy":"ключ источника"},{"id":"R44704","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 12−16 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного и определительного местоимений. Напишите номер(-а) этого(-их) предложения(-ий).","lo":12,"hi":16,"s":[[12,"Наши обычные с внуком пешие прогулки — возле его жилья, пятиэтажного дома."],[13,"Ближняя округа — дома́, в основном двухэтажные, а между ними — дощатые, почерневшие от времени сараи да сарайчики с погребами для картошки и прочих запасов; а ещё — гаражи."],[14,"Всё это тесной толпой, плечом к плечу."],[15,"Гаражей с каждым годом всё больше, как и легковых автомобилей, которые полонят округу: не только улицы, но и дворы, тротуары."],[16,"Они газуют, рычат, бухтят моторами, сердито сигналят, прогоняя с пути тихоходов, старых да малых, вроде нас."]],"a":[14],"why":"Предложение 14 связано с предыдущим с помощью указательного местоимения «это» и определительного местоимения «всё».","verifiedBy":"ключ источника"},{"id":"R46278","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 37−45 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью указательного местоимения и форм слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":37,"hi":45,"s":[[37,"Я всегда радовался, когда вызывал у людей смех."],[38,"Кто смеётся добрым смехом, заражает добротой и других."],[39,"После такого смеха иной становится атмосфера: мы забываем многие жизненные неприятности, неудобства."],[40,"Много доброго можно сделать, если у тебя хорошее настроение."],[41,"Так и на войне."],[42,"Смеясь, мы забывали об угрозе смерти, которая ежечасно нас подстерегала, становилось легче жить, появлялись оптимизм и вера…"],[43,"Я лично на себе всё это испытал, и не раз."],[44,"Слышать смех — для меня радость."],[45,"Вызвать смех — для меня гордость."]],"a":[39],"why":"Предложение 39 связано с предыдущим с помощью указательного местоимения «такого» и форм слова «смехом  — смеха».","verifiedBy":"ключ источника"},{"id":"R48145","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 8−16 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью лексического повтора и притяжательного местоимения. Напишите номер(а) этого(-их) предложения(-ий).","lo":8,"hi":16,"s":[[8,"По утрам он иногда видел виноватую фигуру отца."],[9,"Отец возвращался откуда-то и быстро семенил к себе в кабинет."],[10,"Саша прекрасно знал его походку: так отец являлся домой, когда боялся матери."],[11,"К вечеру отец исчезал."],[12,"Случалось, что кабинет пустовал и день, и два."],[13,"В кабинете Александр научился распоряжаться, как в захваченном вражеском лагере."],[14,"Он перечёл много книг, лежавших в беспорядке на окнах."],[15,"Это были анекдоты, быстрые и отрывистые."],[16,"Он узнал об изменах, об острых ответах королей, о римских полководцах, прочёл о людях, которые, умирая на плахе, делали острые замечания."]],"a":[10],"why":"Предложение 10 связано с предыдущим с помощью притяжательного местоимения «его» и лексического повтора «отец».","verifiedBy":"ключ источника"},{"id":"R48173","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1–7 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения и форм слов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":7,"s":[[1,"Мать маленького Александра Пушкина была где-то далеко, в поместье чёрного деда, о котором родители не говорили."],[2,"Саша привык к любопытству мальчишек и прохожих: лицо его было смуглое, волосы, светлые, непослушные, курчавились."],[3,"Ему говорили, что дед умер; теперь он умер вторично."],[4,"Судьба этого тёмного деда чрезвычайно его занимала."],[5,"Теперь у них было поместье, о котором отец сказал, что там прекрасное озеро."],[6,"Мать уехала, расцеловав маленьких в щёки, а его — в голову."],[7,"И теперь он был на свободе."]],"a":[4],"why":"Предложение 4 связано с предыдущим с помощью указательного местоимения «этого» и форм слов «деда—дед».","verifiedBy":"ключ источника"},{"id":"R49150","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 4−11 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи сочинительного союза и указательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":4,"hi":11,"s":[[4,"Возьмём Бетховена."],[5,"Бог его целует, но по прошествии времени видит, что у Бетховена ничего не получается так, как он, Бог, хотел."],[6,"Тогда Господь его оглушает: будешь глухим композитором."],[7,"И после этого Бетховен начинает писать величайшую музыку."],[8,"Точно так же Бог целует Моцарта."],[9,"Тебе вся гармония принадлежит, твоя миссия — спасать людей, появится даже понятие «эффект Моцарта» — такой красоты будет твоя музыка."],[10,"А Моцарт пишет музыку, подражая всяким модным в его время дяденькам, даже Иоганну Христиану Баху, одному из детей Иоганна Себастьяна Баха."],[11,"И тогда Бог не даёт Моцарту в полной мере наслаждаться жизнью: у композитора слабое, подверженное всяческим болезням тело, в любой момент он рискует умереть от самой ерундовой хвори — отсюда его фобия смерти..."]],"a":[7],"why":"Предложение 7 связано с предыдущим с помощью сочинительного союза «и» и указательного местоимения «(после) этого».","verifiedBy":"ключ источника"},{"id":"R49978","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 4–9 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного и притяжательного местоимений, форм слова и лексического повтора. Запишите номер(-а) этого(-их) предложения(-ий).","lo":4,"hi":9,"s":[[4,"Так получилось и с этой книгой."],[5,"На сей раз началось с телефонного звонка."],[6,"Тамара Александровна Ворошилова, ответственный секретарь пресс-клуба «01» Главного управления пожарной охраны, сказала, что с интересом относится к моим полярным книгам, но думает, что на главную свою тему я ещё не вышел."],[7,"Таковой, по её глубокому убеждению, является тема пожарная, в которой я найду экстремальных ситуаций больше, чем на обоих полюсах Земли."],[8,"Во время первых же бесед выяснилось, что мои представления о пожарных отличаются вопиющим, из ряда вон выходящим невежеством."],[9,"Я был уличён в том, что абсолютно не понимаю элементарного — ни масштабов пожаров, ни причин, их вызывающих, ни людей, которые ценой жизни своей и здоровья эти пожары тушат."]],"a":[7],"why":"Предложение 7 связано с предыдущим при помощи указательного местоимения «таковой», притяжательного местоимения её«», форм слова «тема  — тему» и лексического повтора «я».","verifiedBy":"ключ источника"},{"id":"R50227","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 8−13 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим(-и) при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":8,"hi":13,"s":[[8,"Что-то знакомое почудилось мне в лице."],[9,"Мать и дочь прошли вперёд и исчезли за одной из дверей этого старого пышного особняка, где сейчас находился Дворец бракосочетаний."],[10,"Я поднялась по белой лестнице наверх."],[11,"И спустя некоторое время увидела их фигуры снова."],[12,"Девушка стояла посреди зала на ковре, покрывающем блестящий, как озеро, паркет."],[13,"Рядом с нею был юноша в очках, с длинной шеей и длинными, словно у подростка, руками, с лицом, пожалуй, даже некрасивым, но непередаваемо привлекательным своей спокойной добротой."]],"a":[13],"why":"Предложение 13 связано с предыдущим с помощью личного местоимения «нею».","verifiedBy":"ключ источника"},{"id":"R50314","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 39−45 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи форм(-ы) слов(-а). Напишите номер(-а) этого(-их) предложения(-ий).","lo":39,"hi":45,"s":[[39,"«Добавлю за это тысячу двести, всего будет шестнадцать с половиной», — произнёс он."],[40,"«Что вы, что вы, — замахала руками Анна Вячеславовна, — это не продаётся»."],[41,"Молодой человек не стал настаивать."],[42,"Он попросил пачку старых газет и принялся паковать вещи."],[43,"Анне Вячеславовне хотелось, чтобы он поскорее ушёл, и отчего-то было стыдно."],[44,"«Да, вы знаете, — сказал молодой человек. — у меня есть друг, он фанат Симонова, трясётся над каждой его строчкой."],[45,"Можно я возьму у вас книжечку на пару дней, другу покажу."]],"a":[40,45],"why":"Предложение 40 связано с предыдущим с помощью форм слова «это (вин. падеж)  — это (именит. падеж)».","verifiedBy":"ключ источника"},{"id":"R50341","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 11−21 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":11,"hi":21,"s":[[11,"Дома Анна Вячеславовна после некоторого раздумья набрала записанный номер."],[12,"Голос в телефонной трубке внушал доверие."],[13,"Он выслушал Анну Вячеславовну, записал адрес и пообещал подъехать сегодня же."],[14,"Антиквар оказался сравнительно молодым человеком, высоким, улыбчивым, приятной наружности, располагающим к себе."],[15,"«Ну, показывайте, что у вас тут есть», — по-хозяйски огляделся он."],[16,"Анна Вячеславовна показала статуэтку."],[17,"«А вот там и там у вас еще что?» — стал спрашивать тот."],[18,"Анна Вячеславовна заикнулась было, что ничего больше она продавать не собирается, ей бы только до пенсии дожить."],[19,"«А перед следующей пенсией снова мне позвоните?"],[20,"Давайте создадим задел, чтоб у вас был небольшой капитал на чёрный день», — молодой человек звучал убедительно."],[21,"К тому же Анна Вячеславовна чувствовала, как на неё накатывает усталость, сил сопротивляться не было."]],"a":[13],"why":"Предложение 13 связано с предыдущим с помощью личного местоимения «он».","verifiedBy":"ключ источника"},{"id":"R51846","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 3−9 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи определительного и указательного местоимений. Запишите номер(-а) этого(-их) предложения(-ий).","lo":3,"hi":9,"s":[[3,"Я и сам знаю, что из просторного, во всю стену, окна открывается картина приглядная."],[4,"В свою пору зеленеют, желтеют ли тополя да берёзы под окнами, в сквере, дальше — Волга, просторные воды её, синева ли, голубизна, а то и свинцовая стынь, за рекой светит песчаный берег, его косы да отмели, займищный лес — до самого горизонта, потом небо, простор его."],[5,"Всё это я вижу и, конечно, ценю."],[6,"Старая мать моя говорит: «Здесь только художнику жить, рисовать...»"],[7,"Она права."],[8,"Утром проснёшься, в день погожий, — в комнате светло, за окном разгорается заря от нежной алости до пламенного полыханья."],[9,"Потом солнце встаёт."]],"a":[5],"why":"Указанные средства связи есть между предложением 4 и 5:","verifiedBy":"ключ источника"},{"id":"R52541","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 18−22 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи наречия, синонимов и формы слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":18,"hi":22,"s":[[18,"Именно Хейердал «открыл» для широкой публики остров Пасхи: в 1955 году он организовал отдельную солидную экспедицию и прожил здесь полгода."],[19,"Написал, помимо популярной книжки «Аку-Аку», несколько серьёзных монографий и установил, в частности, что три столетия назад остров населял не один народ, а два, внешне отличавшихся друг от друга."],[20,"Одно племя жило тут издревле, второе приплыло на лодках и нагло оккупировало часть острова; далее разразилась кровопролитная война, закончившаяся жестоким истреблением пришельцев, тела их сожгли; Хейердал раскопал могильники и добыл множество обугленных костей."],[21,"Фантастическое, или инопланетное, происхождение каменных изваяний Хейердал также опроверг: под его руководством и за его счёт местные мужики вручную вырубили новодельного истукана, неотличимого от оригинальных, затем переволокли к берегу и поставили на попа."],[22,"Использовались только мускульная сила и брёвна-рычаги."]],"a":[20],"why":"Указанная связь есть между предложениями 19 и 20.","verifiedBy":"ключ источника"},{"id":"R52973","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 5−8 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи наречия. Напишите номер(-а) этого(-их) предложения(-ий).","lo":5,"hi":8,"s":[[5,"Со временем этот список сменился другим, обновлённым, и по просьбе заведующего все мы приняли участие в его составлении."],[6,"Там оказались слова «качественно» в значении «высококачественно», «переживать» в значении «волноваться», «волнительно» и много чего другого."],[7,"На одном из моих первых докладов в Пушкинском Доме Лихачёв также попросил меня не употреблять выражение «честно говоря» («Разве всё остальное вы говорите нечестно?» — спросил академик)."],[8,"Поблагодарив за поправку, я (честно говоря) испытал в тот момент некоторые сомнения в её справедливости."]],"a":[6],"why":"Указанная связь есть между предложениями 5 и 6.","verifiedBy":"ключ источника"},{"id":"R53319","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 69−77 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи форм слова. Запишите номер(-а) этого(-их) предложения(-ий).","lo":69,"hi":77,"s":[[69,"— Мне что... — пробормотал парень, затравленно покосился назад и нагнулся к девушке."],[70,"Потом выпрямился, словно кончил тяжёлую работу, вскочил на подножку."],[71,"Под вагонами зашипело, сдавленно крикнул впереди паровоз, и так же сдавленно отозвалось из леса короткое, глухое эхо."],[72,"Вагоны едва уловимо тронулись."],[73,"Заскрипели шпалы."],[74,"Парень стоял на подножке, хмуро смотрел на девушку, потом покраснел и негромко крикнул: — Слышь..."],[75,"Не приеду я больше!"],[76,"Слышь..."],[77,"Он оскалился, сильно втянул в себя воздух, сказал ещё что-то непонятное, злое и, взяв с подножки чемодан, боком полез в тамбур."]],"a":[72],"why":"Указанная связь есть между предложениями 71 и 72.","verifiedBy":"ключ источника"},{"id":"R54192","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 40−45 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":40,"hi":45,"s":[[40,"За обедом на третье подали компот."],[41,"Я доставал из него фрукты и скромно ел их, аккуратно выкладывая косточки в тарелку, а не стараясь, как обычно, выдуть их кому-нибудь в лицо."],[42,"Сам я о груше не напоминал, но мне казалось естественным, что другие о ней вспомнят."],[43,"Однако все весело уплетали компот, и никто не вспоминал о моей груше."],[44,"Неблагодарность человечества слегка уязвила меня, и я почувствовал себя совсем взрослым."],[45,"Мне было приятно видеть вокруг себя столько неблагодарных детей."]],"a":[41],"why":"Указанная связь есть между предложениями 40 и 41.","verifiedBy":"ключ источника"},{"id":"R54233","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 46−52 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":46,"hi":52,"s":[[46,"Но самое страшное ждало впереди."],[47,"Выйдя из детского сада, я заметил тётю Веру, она стояла на тротуаре и разговаривала с кем-то."],[48,"В руках её покачивалась сетка, на дне которой лежала моя груша."],[49,"Моя груша!"],[50,"Я не мог не узнать её красный бок."],[51,"Но я не хотел верить своим глазам."],[52,"Я обошёл тётю Веру и посмотрел на грушу с другого бока."]],"a":[48,50],"why":"Указанная связь есть между предложениями 47 и 48.","verifiedBy":"ключ источника"},{"id":"R56103","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 35–43 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения и контекстных синонимов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":35,"hi":43,"s":[[35,"Благов кончил работу над рукописью только к утру."],[36,"Мне он рукописи не показал, пока мы не пришли в редакцию и машинистка не переписала её начисто."],[37,"Я прочёл рассказ и онемел."],[38,"Это была прозрачная, литая проза."],[39,"Всё стало выпуклым, ясным."],[40,"От прежней скомканности и словесного разброда не осталось и тени."],[41,"При этом действительно не было выброшено или прибавлено ни одного слова."],[42,"Я посмотрел на Благова."],[43,"Он курил толстую папиросу из чёрного, как чай, кубанского табака и усмехался."]],"a":[38],"why":"Между предложениями 37 и 38 есть указанная связь.","verifiedBy":"ключ источника"},{"id":"R56520","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 8–13 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи наречия и форм(-ы) слов(-а). Напишите номер(-а) этого(-их) предложения(-ий).","lo":8,"hi":13,"s":[[8,"Волна подарила и ритм."],[9,"В основе музыки лежит ритм волн и ритм движения светил по небесам."],[10,"Потому музыка и проникает в глубины мировой гармонии дальше других искусств."],[11,"Сам звук тоже имеет волновую природу."],[12,"Медленный накат волны на отмель, вальс и ритм биения человеческого сердца чрезвычайно близки."],[13,"Потому вальс невредимым пройдёт сквозь джазы."]],"a":[10],"why":"Среди предложений 8–13 с предыдущим при помощи наречия и формы слова связано предложение 10.","verifiedBy":"ключ источника"},{"id":"R57091","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 2–6 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Запишите номер(-а) этого(-их) предложения(-ий).","lo":2,"hi":6,"s":[[2,"И вспомнилась Олегу мама с мягкими, добрыми руками... «"],[3,"...Мама, мама!"],[4,"Я помню руки твои с того мгновения, как я стал сознавать себя на свете."],[5,"За лето их всегда покрывал загар, он уже не отходил и к весне — он был такой ровный, только чуть-чуть темнее на жилочках."],[6,"А может быть, они были и грубее, руки твои, — ведь им столько выпало работы в жизни, — но они всегда казались мне такими нежными, и я так любил целовать их прямо в тёмные жилочки."]],"a":[5],"why":"Указанными средствами связывается предложение №5 с №4.","verifiedBy":"ключ источника"},{"id":"R57528","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1–5 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи лексического повтора, контекстных синонимов и однокоренных слов. Запишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":5,"s":[[1,"У каждого из нас бывает иногда чувство, что его силы приходят к концу, что он «больше не может»: «жизнь так тягостна, так унизительна и ужасна, что переносить её дальше нельзя»..."],[2,"Но время идёт; оно приносит новые трудности и новые опасности — и мы выносим их."],[3,"Мы справляемся с невзгодами, не примиряясь, и сами не знаем потом, как мы могли пережить и перенести произошедшее."],[4,"Иллюзия «невозможности» рассеивается при приближении к событиям, душа черпает откуда-то новые силы, и люди живут дальше, от времени до времени снова впадая в ту же иллюзию."],[5,"Это понятно: взор у нас близорук и поле зрения невелико; мы сами не обозреваем тех сил, которые нам даны, и недооцениваем их."]],"a":[3],"why":"Предложение 3 связано со 2-м при помощи указанных средств.","verifiedBy":"ключ источника"},{"id":"R58105","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 17−21 найдите такое (-ие), которое (-ые) связано (-ы) с предыдущим при помощи притяжательного местоимения. Запишите номер(а) этого (-их) предложения (-ий).","lo":17,"hi":21,"s":[[17,"То была эпоха могучего американского атлета Пола Эндерсона."],[18,"Я жадно впитывал крохи сведений о его тренировках из спортивных журналов."],[19,"Я старался разгадать природу этой поразительной силы."],[20,"Я не связывал её лишь с весом."],[21,"Должно было быть в тренировках Эндерсона и нечто своё, отличное от принятого, того, к чему мы привыкли."]],"a":[18],"why":"Предложение 35 связано с 34-м при помощи указанных средств.","verifiedBy":"ключ источника"},{"id":"R59262","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 6–9 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза, лексического повтора и форм слова. Запишите номер(-а) этого(-их) предложения(-ий).","lo":6,"hi":9,"s":[[6,"Девочка думала, что её роль говорит сама за себя своей простотой и наивностью, что истинно красивое просто и что нужно быть простой и верной правде, чтобы тронуть сердца зрителей."],[7,"И она была уверена: она тронет их."],[8,"И её внутреннее чувство говорило, что она идёт на большое и важное дело, ибо говорить толпе просто и хорошо о душе́, и о сердце, и обо всём, чем живут люди, — это крупное и важное, это мучительное и честное дело для того, кто верит в хорошее и доброе."],[9,"А она верила, потому что она была молода."]],"a":[9],"why":"Среди предложений 6–9 с предыдущим при помощи союза, лексического повтора и форм слова связано предложение 9.","verifiedBy":"ключ источника"},{"id":"R59890","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1−4 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения, контекстных синонимов, лексического повтора и форм слова. Запишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":4,"s":[[1,"В самом конце XIX века английский натуралист доктор Карутерс наблюдал над Красным морем грандиозное переселение саранчи с берегов Северной Африки в Аравию."],[2,"В течение трёх дней плотные тучи этих насекомых, закрывая солнце, непрерывно проносились над головой наблюдателя."],[3,"Обычное в таких местах, часто повторяющееся явление поразило Карутерса своими размерами, и он решил определить количество насекомых в одной из туч, пролетевшей над ним 25 ноября 1889 года."],[4,"Оказалось, что эта туча занимала пространство в 5967 квадратных километров и весила 44 миллиона тонн."]],"a":[3],"why":"Указанная связь есть между предложениями 2 и 3.","verifiedBy":"ключ источника"},{"id":"R60232","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 55–59 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи лексического повтора и контекстных синонимов. Запишите номер(-а) этого(-их) предложения(-ий).","lo":55,"hi":59,"s":[[55,"Евгений Иванович помолчал, а Лёшка поинтересовался: — А что такое бомбоубежище?"],[56,"— Это дом в земле, в котором люди прятались в войну от бомбёжки, чтобы их не убило, — пояснила Елена Ивановна."],[57,"— А зачем их убивать? — опять спросил Лёшка."],[58,"— Зачем убивать... — повторил Евгений Иванович, посмотрел на сестру и физиономию вытянул: мол, вот парень даёт: какие вопросы забивает."],[59,"— Знаешь, Лёха, честно говоря, долго это тебе объяснять, да ты сейчас всего и не поймёшь."]],"a":[58],"why":"Почему подходит предложение 58:","verifiedBy":"ключ источника"},{"id":"R60943","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 5–12 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи лексического повтора и однокоренных слов. Запишите номер(-а) этого(-их) предложения(-ий).","lo":5,"hi":12,"s":[[5,"А мне говорили, что у вас три головы, когти, огромный рост! Шарлемань."],[6,"Господин Дракон так давно живёт здесь, среди людей, что иногда сам превращается в человека и заходит сюда в гости по-дружески. Дракон."],[7,"О, мы воистину друзья, дорогой Шарлемань, мы давно знаем друг друга, я даже более чем просто друг."],[8,"Я друг детства вашего отца, деда, прадеда."],[9,"Я помню вашего прапрадеда в коротеньких детских штанах."],[10,"Чёрт... непрошеная слеза!"],[11,"А-а... приезжий таращит глаза!"],[12,"Ты не ожидал от меня таких чувств, отвечай!"]],"a":[7,9],"why":"Проанализируем связь между предложениями в указанном диапазоне:","verifiedBy":"ключ источника"},{"id":"R60970","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 69–76 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения и форм слова. Запишите номер(-а) этого(-их) предложения(-ий).","lo":69,"hi":76,"s":[[69,"У меня хранится документ, подписанный вами триста восемьдесят два года назад, на котором стоит подпись: «Дракон». Дракон."],[70,"Ну и что? Шарлемань."],[71,"Всякий вызвавший вас — в безопасности до дня боя."],[72,"И день боя назначаете не вы, а он — так сказано в том документе и подтверждено клятвой. Дракон."],[73,"Когда был написан этот документ? Шарлемань."],[74,"Триста восемьдесят два года назад. Дракон."],[75,"Я был тогда наивным, сентиментальным, неопытным мальчишкой."],[76,"Довольно о документах: мы взрослые люди. Шарлемань."]],"a":[73],"why":"Предложение 73 связано с предыдущим (72) при помощи:","verifiedBy":"ключ источника"},{"id":"R61511","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 26–34 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи противительного союза и форм(ы) слов(а). Запишите номер(-а) этого(-их) предложения(-ий).","lo":26,"hi":34,"s":[[26,"Такое случается часто: год-два тебя не было в каком-то районе, и, приезжая туда вновь, не узнаёшь того, что осталось в памяти, — настолько всё изменилось."],[27,"Это нормально: присутствует в этом отголосок нашего времени — город растёт бурно."],[28,"Новое же всегда вызывает любопытство просто потому, что оно новое, недавнее по времени."],[29,"Как сюрприз."],[30,"Но тут что-то не то."],[31,"Вдали, за Садовой, возвели новый жилой дом, который возвышается теперь над улицей, будто гигантский сундук."],[32,"И в тысячный раз подумалось: а к чему он здесь?"],[33,"Какое он имеет отношение к тому, что я только что видел?"],[34,"А никакого."]],"a":[28],"why":"Предложение 28 связано с предыдущим (27-м) при помощи:","verifiedBy":"ключ источника"},{"id":"R65192","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 11–14 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного и личного местоимений, однокоренного слова. Запишите номер(-а) этого(-их) предложения(-ий).","lo":11,"hi":14,"s":[[11,"У нас всегда была и до сих пор имеется масса людей, которая угадывает за художника истоки его творчества: и замысел объяснят, и в тайны души его проникнут."],[12,"Я этого не умею и не хочу делать хотя бы потому, что сам в какой-то мере человек творческий и не только объяснить не могу самому себе, например, природу творческого замысла, но и понять до сих пор не могу, что это такое."],[13,"Более того, я, может, и примитивно, но, основываясь на сорокалетнем опыте работы в литературе, пришёл к выводу, что и отгадывать сию тайну не надо, потому как, отгадавши её, что станет делать человек?"],[14,"Кончится его воображение, и он кончится как существо творческое, сделается механической, заводной штучкой, заранее знающей всё и вся."]],"a":[14],"why":"Предложение 14 связано с предыдущим (13) тремя средствами связи одновременно:","verifiedBy":"ключ источника"},{"id":"R67136","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 47–52 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи лексического повтора и синонимов. Запишите номер(-а) этого(-их) предложения(-ий).","lo":47,"hi":52,"s":[[47,"Вскоре после этого я уже участвовал в спектакле статистом."],[48,"Меня одели в тёмный, гладкий костюм и намазали мне лицо жжёной пробкой3, обещав дать пятачок за это посрамление личности."],[49,"Я подчинился окрашиванию не только безбоязненно, но и с великим наслаждением, яростно кричал «ура» в честь Васко да Гама и вообще чувствовал себя превосходно."],[50,"Но вскоре мной овладело великое смущение."],[51,"Я убедился, что пробку с лица не так-то легко смыть."],[52,"Идя домой, я тёр лоб и щёки снегом, истратил его целый сугроб и всё-таки явился... с копчёной физиономией негра."]],"a":[52],"why":"Предложение 52 связано с предыдущим предложением 51 с помощью двух указанных средств связи:","verifiedBy":"ключ источника"},{"id":"R67163","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 14–22 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи форм(-ы) слов(-а), контекстных антонимов и личного местоимения. Запишите номер(-а) этого(-их) предложения(-ий).","lo":14,"hi":22,"s":[[14,"Я действительно ничего не делал и учился плохо."],[15,"Когда я спрашивал отца, можно ли идти в театр, он не пускал меня."],[16,"Отец говорил: — В дворники надо идти!"],[17,"В дворники, а не в театр!"],[18,"Дворником надо быть, и будет у тебя кусок хлеба!"],[19,"А что в театре хорошего?"],[20,"Ты вот не захотел мастеровым быть и сгниёшь в тюрьме."],[21,"Мастеровые вон как живут: сыты, одеты, обуты, — говорил отец."],[22,"Я видел мастеровых по большей части оборванными, полуголодными и пьяными и не верил ему."]],"a":[22],"why":"Предложение 22 связано с предыдущим предложением 21 с помощью трёх указанных средств связи:","verifiedBy":"ключ источника"},{"id":"R67300","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 15–23 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи однокоренных слов. Запишите номер(-а) этого(-их) предложения(-ий).","lo":15,"hi":23,"s":[[15,"Существительное — это изображение, глагол — действие."],[16,"По соотношению количества существительных с количеством глаголов можно судить о качестве прозы."],[17,"В хорошей прозе изобразительное и повествовательное уравновешено."],[18,"Боюсь, что я нарушаю равновесие и злоупотребляю существительными и прилагательными."],[19,"Существительное, кстати, включает в себя часто и эпитет."],[20,"К слову «бриллиант», например, не надо прибавлять слово «сверкающий»."],[21,"Значение эпитета уже заключено в само́м существительном."],[22,"Излишество описаний, изображений — это болезнь нашего века."],[23,"Почти всегда в хорошей современной прозе изобразительное превышает повествовательное."]],"a":[18,23],"why":"В указанном фрагменте связь с предыдущим предложением при помощи однокоренных слов представлена дважды:","verifiedBy":"ключ источника"},{"id":"R67327","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1–6 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения, форм(-ы) слов(-а) и однокоренных слов. Запишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":6,"s":[[1,"Переходя по диагонали оживлённый перекрёсток из синей тени на залитую почти африканским солнцем сторону, я промочил туфли возле раковины углового фонтана с мадонной в нише, украшенной цветами и разноцветными лампадками."],[2,"Но это неважно, извините, я отвлёкся."],[3,"Важно то, что в туристском автобусе мы объехали весь треугольник Сицилии, окружённый со всех сторон синевой Средиземного моря, останавливаясь по дороге возле древнегреческих храмов."],[4,"Храмы эти не из белого мрамора, как в само́й Греции, а из местного жёлтого камня, они стоят, неплохо сохранившиеся, прямо возле мраморных развалин римских городов, поверженных в прах войсками Ганнибала."],[5,"След карфагенского войска — этот ужасный след шагнувших под трубный рёв боевых слонов — он тянется через Сицилию на Апеннинский полуостров по дороге к золотым воротам Рима..."],[6,"А может быть, города эти были разрушены не войной, а землетрясениями в те дни, когда вдруг просыпалась Этна1, извергая из своих семи кратеров огонь и дым и швыряя в небо раскалённые каменные бомбы."]],"a":[4],"why":"Предложение 4 связано с предыдущим предложением 3 с помощью трёх указанных средств связи:","verifiedBy":"ключ источника"},{"id":"R3608","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 19–25 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":19,"hi":25,"s":[[19,"Годами не убывающая очередь стоит в Эрмитаж."],[20,"С утра до вечера его залы полны горожан и приезжих издалека."],[21,"Какая-то часть из приходящих сюда действительно что-то получит для себя, как-то взволнуется произведениями великих мастеров, но сколько зайдёт сюда, чтобы отметиться, чтобы сказать, что был в Эрмитаже, для престижа, сколько из них скользят равнодушно-спокойным взглядом, запоминая, чтобы знать!"],[22,"Ермаков, тот вообще не был в Эрмитаже, и в Павловске не был, и в Пушкине."],[23,"Был в Петергофе, фонтаны смотрел."],[24,"Огромная культурно-художественная жизнь такого города, как Петербург, проходит мимо него."],[25,"Но, может быть, этот откровенный неинтерес более честен, чем формальное приобщение к культуре."]],"a":[20],"why":"(19)Годами не убывающая очередь стоит в Эрмитаж. (20)С утра до вечера его залы полны горожан и приезжих издалека.","verifiedBy":"ключ источника"},{"id":"R3803","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 44−48 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":44,"hi":48,"s":[[44,"- Постой здесь!"],[45,"Я спрошу у кого-нибудь! — сказал я и направился через дорогу к женщине, которая возилась с цветами в палисаднике."],[46,"Ничего не узнав от неё, я пошёл дальше."],[47,"Но во дворах никого не было, я пересёк улицу, потом ещё один проулок..."],[48,"А потом пошёл в университет."]],"a":[46],"why":"(45)Я спрошу у кого-нибудь!  — сказал я и направился через дорогу к женщине, которая возилась с цветами в палисаднике. (46)Ничего не узнав от неё, я пошёл дальше.","verifiedBy":"ключ источника"},{"id":"R3842","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 7−15 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":7,"hi":15,"s":[[7,"В глухой, далёкой деревне, где до ближайшей станции больше ста километров, где любая поездка становится целым путешествием, сама эта мысль казалась безумием."],[8,"Жизненная стезя каждого человека здесь была ровной и прямой: после школы мальчики получали права на управление трактором и становились механизаторами, а самые смелые оканчивали водительские курсы и работали в селе шофёрами."],[9,"Ездить по земле — вот удел человека."],[10,"А тут летать на самолёте!"],[11,"На Кольку смотрели как на чудака, и отец надеялся, что вздорная идея как-нибудь сама собой улетучится из головы сына."],[12,"Мало ли чего мы хотим в молодости!"],[13,"Жизнь — жестокая штука, она всё расставит по своим местам и равнодушно, как маляр, закрасит серой краской наши пылкие мечты, нарисованные в юности."],[14,"Но Колька не сдавался."],[15,"Ему грезились серебристые крылья, несущие его над влажным снегом облаков, и густой упругий воздух, чистый и холодный, как родниковая вода, наполнял его лёгкие."]],"a":[15],"why":"(14)Но Колька не сдавался. (15)Ему грезились серебристые крылья, несущие его над влажным снегом облаков, и густой упругий воздух, чистый и холодный, как родниковая вода, наполнял его лёгкие.","verifiedBy":"ключ источника"},{"id":"R3881","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 9−16 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":9,"hi":16,"s":[[9,"Однажды после обеда послышался гул машины."],[10,"Дядя так рано никогда не приезжал — мы решили, что это разбойники-грабители."],[11,"Схватив лук и стрелы, мы выскочили из палатки, чтобы дать отпор незваным гостям."],[12,"Возле пасеки остановилась «Волга»."],[13,"Высокий мужчина лет сорока, обойдя машину, открыл заднюю дверь и помог выйти маленькому старичку."],[14,"Тот, шатаясь на слабых ногах, тяжело осел на траву и стал с жадной пронзительностью смотреть кругом, словно чуял в летнем зное какой-то неотчётливый запах и пытался понять, откуда он исходит."],[15,"Вдруг ни с того ни с сего старичок заплакал."],[16,"Его лицо не морщилось, губы не дрожали, просто из глаз часто-часто потекли слёзы и стали падать на траву."]],"a":[16],"why":"(15)Вдруг ни с того ни с сего старичок заплакал. (16)Его лицо не морщилось, губы не дрожали, просто из глаз часто-часто потекли слёзы и стали падать на траву.","verifiedBy":"выведено из пояснения"},{"id":"R3920","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 15−22 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":15,"hi":22,"s":[[15,"Среди плотной мелкой травки, растущей на лужайке, образовалось зловещее чёрное пятно."],[16,"Три года земля не могла залечить место ожога, и только потом плешина снова затянулась травой."],[17,"Под окном, конечно, заметно."],[18,"Я жалел, что поступил неосторожно, испортил лужайку."],[19,"Но ведь это под собственным окном!"],[20,"Каждый день ходишь мимо, видишь и вспоминаешь."],[21,"Если же где-нибудь подальше от глаз, в овраге, на лесной опушке, в придорожной канаве, да, господи, мало ли на земле травы?"],[22,"Жалко ли её?"]],"a":[22],"why":"(21)Если же где-нибудь подальше от глаз, в овраге, на лесной опушке, в придорожной канаве, да, господи, мало ли на земле травы? (22)Жалко ли её?","verifiedBy":"выведено из пояснения"},{"id":"R3959","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 26−29 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения и контекстных синонимов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":26,"hi":29,"s":[[26,"Люди узнали об этом через много лет."],[27,"Оказывается, архитектор сделал на каменных плитах маяка углубления и в них высек слова: \"Сострат, сын Дексифана из Книда, - богам-спасителям ради мореходов\"."],[28,"Надпись он залепил известью, затёр её мраморной крошкой и на ней начертал, как того требовал фараон: \"Птолемей Филадельф\"."],[29,"Так всегда бывает."]],"a":[28],"why":"(27)Оказывается, архитектор сделал на каменных плитах маяка углубления и в них высек слова: «Сострат, сын Дексифана из Книда,  — богам-спасителям ради мореходов». (28)Надпись он залепил известью, затёр её мраморной крошкой и на ней начертал, как того требовал фараон: «Птолемей Филадельф».","verifiedBy":"выведено из пояснения"},{"id":"R4076","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 39−44 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":39,"hi":44,"s":[[39,"...Плетёнкин хмуро намыливал руки."],[40,"Он подумал, что обязательно встретит её и вернёт ей двести, нет, не двести, а все пятьсот рублей..."],[41,"Но с отчаянием понял, что никогда не сделает этого."],[42,"— Ты чего там застрял?"],[43,"Всё стынет на столе! — потеряв терпение, крикнула из кухни жена."],[44,"«Разве ты меня обманул?» — вновь вспомнилось ему, и он поплёлся есть остывающий суп."]],"a":[40],"why":"(39)...Плетёнкин хмуро намыливал руки. (40)Он подумал, что обязательно встретит её и вернёт ей двести, нет, не двести, а все пятьсот рублей...","verifiedBy":"выведено из пояснения"},{"id":"R4115","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 27−34 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи лексического повтора и контекстного синонима. Напишите номер(-а) этого(-их) предложения(-ий).","lo":27,"hi":34,"s":[[27,"Я поставил ногу на табурет и начал обматывать ею ногу, но продолжал говорить:"],[28,"— И этому научу вас!"],[29,"Слушатели задохнулись от смеха."],[30,"«Всё погибло!» — подумал я с отчаянием."],[31,"Но отступать некуда."],[32,"Делая вид, что не слышу смеха, я приказал:"],[33,"— Раскрыть любой устав на любом месте!"],[34,"Дежурный поспешил раскрыть одну из синих книжек."]],"a":[33],"why":"(33)— Раскрыть любой устав на любом месте!","verifiedBy":"выведено из пояснения"},{"id":"R4154","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 27−35 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":27,"hi":35,"s":[[27,"Нужно было возвращаться назад."],[28,"Савушкин спустился с холма и заплакал."],[29,"По его лицу, мешаясь с потом, текли слёзы и, будто кислота, разъедали кожу..."],[30,"Она молчит, просто смотрит внутрь себя и молчит, потому что знает: никто не поможет."],[31,"И ты видишь, как твой ребёнок в одиночестве блуждает по бесконечным лабиринтам боли."],[32,"Вдруг Савушкин замер."],[33,"В овражке, прорытом вешними водами, стояла антилопа."],[34,"Совсем близко, под самым носом, шагах в двадцати."],[35,"Савушкин осторожно снял с плеча ружьё, взвёл курки."]],"a":[29],"why":"(28)Савушкин спустился с холма и заплакал. (29)По его лицу, мешаясь с потом, текли слёзы и, будто кислота, разъедали кожу...","verifiedBy":"выведено из пояснения"},{"id":"R4193","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 43−48 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза и личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":43,"hi":48,"s":[[43,"Наверное, у всех, как и у меня, отступило, забылось дневное, несладкое, а проснулось, нахлынуло иное, ведь и вправду Новый год близок..."],[44,"Я вышел из вагона с лёгким сердцем, торопиться не стал, пропуская спешащих."],[45,"Дорога славная: берёзы да сосны сторожат тропинку; не больно холодно, а на душе вовсе тепло."],[46,"Спасибо той девочке, которую унесла электричка."],[47,"А в помощь ей — малиновый чистый закат над чёрными елями, бормочущая во тьме речушка под гибким деревянным мостком, говор вдали, детский смех и, конечно, надежда."],[48,"Так что шагай, человече..."]],"a":[47],"why":"(46)Спасибо той девочке, которую унесла электричка. (47)А в помощь ей  — малиновый чистый закат над чёрными елями.","verifiedBy":"выведено из пояснения"},{"id":"R4232","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 13−19 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения и однокоренных слов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":13,"hi":19,"s":[[13,"Пользуются спросом специальная литература и книги, содержащие разного рода практические советы."],[14,"Что же касается «художественной» литературы, то развлекательное чтиво: детективы, приключения, «семейные» романы — явно потеснило всё прочее."],[15,"«Спрос определяет предложение», — разводят руками издатели."],[16,"Да, современному человеку, озабоченному материальными и прочими проблемами, не до серьёзного чтения."],[17,"Читает он преимущественно в транспорте, по дороге на работу и с работы."],[18,"А что можно читать в автобусной сутолоке?"],[19,"Желание отвлечься, снять нервное напряжение заставляет предпочесть лёгкое чтение, не требующее размышлений и глубокого проникновения в текст."]],"a":[17],"why":"(16)Да, современному человеку, озабоченному материальными и прочими проблемами, не до серьёзного чтения. (17)Читает он преимущественно в транспорте, по дороге на работу и с работы.","verifiedBy":"выведено из пояснения"},{"id":"R4271","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1−5 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи лексического повтора. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":5,"s":[[1,"Когда размышляют о том, каким должен быть хороший врач, то часто профессиональное мастерство, знания, опыт противопоставляются нравственным качествам: чуткости, простоте, общительности."],[2,"Кто-то резонно говорит, что врач не священник, что его дело — грамотно лечить, а не утешать."],[3,"Другие возражают: физическое здоровье человека неразрывно связано со здоровьем душевным."],[4,"Добрым словом, сочувствием, отзывчивостью можно добиться большего, чем самыми эффективными лекарственными препаратами."],[5,"17 июня два выпускника медицинской академии, Кирилл Максимов и Артём Беляков, одетые в строгие костюмы, торопливо шагали по улице, боясь опоздать на торжественное вручение дипломов."]],"a":[2],"why":"(1)Когда размышляют о том, каким должен быть хороший врач, то часто профессиональное мастерство, знания, опыт противопоставляются нравственным качествам: чуткости, простоте, общительности. (2)Кто-то резонно говорит, что врач не священник, что его дело  — грамотно лечить, а не утешать.","verifiedBy":"выведено из пояснения"},{"id":"R4310","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 6−11 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи наречия и лексического повтора. Напишите номер(-а) этого(-их) предложения(-ий).","lo":6,"hi":11,"s":[[6,"Однажды в одной из столичных газет, известной своим обличительным пафосом, мне попалась статья, в которой автор утверждал, что патриотизм свойствен лишь натурам серым, примитивным, недостаточно развитым, в которых индивидуальное чувство ещё не вызрело в полной мере."],[7,"3атем автор, доказывая тезис о том, что героическая самоотверженность порождена не благородством, как это принято думать, а неразвитостью личностного начала, приводит выдержки из прощального письма Ульяны Громовой."],[8,"Эта девушка во время Великой Отечественной войны стала одним из руководителей подпольной организации «Молодая гвардия», куда входили люди, многим из которых не было и двадцати лет."],[9,"Ребята расклеивали листовки с сообщениями о положении на фронте, вывешивали красные флаги, показывали всем, что оккупанты завоевали город, но не покорили людей."],[10,"Фашисты схватили подпольщиков, изуверски пытали их, а потом казнили."],[11,"Ульяна Громова перед самой смертью успела написать письмо родным."]],"a":[7],"why":"(б)Однажды в одной из столичных газет, известной своим обличительным пафосом, мне попалась статья, в которой автор утверждал, что патриотизм свойствен лишь натурам серым, примитивным, недостаточно развитым, в которых индивидуальное чувство ещё не вызрело в полной мере. (7)3атем автор, доказывая тезис о том, что героическая самоотверженность порождена не благородством, как это принято думать, а неразвитостью личностного начала, приводит выдержки из прощального письма Ульяны Громовой.","verifiedBy":"выведено из пояснения"},{"id":"R4388","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 18−23 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":18,"hi":23,"s":[[18,"Тенденция к самореализации — знаковое направление для сегодняшнего юного поколения."],[19,"А повышенное внимание подростков к определённым товарам, стилю жизни было и будет, так как это входит в круг ценностей, которыми надо обладать, чтобы вписаться в среду сверстников."],[20,"Надо быть как все."],[21,"Что же наиболее значимо в жизни, по мнению самих подростков?"],[22,"На первом месте у них — хорошая работа, карьера и образование."],[23,"Подростки осознают: чтобы в будущем хорошо жить, надо приложить к этому собственные усилия."]],"a":[22],"why":"(21)Что же наиболее значимо в жизни, по мнению самих подростков? (22)На первом месте у них  — хорошая работа, карьера и образование.","verifiedBy":"ключ источника"},{"id":"R4427","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 7–15 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения и контекстного синонима. Напишите номер(-а) этого(-их) предложения(-ий).","lo":7,"hi":15,"s":[[7,"— Наверно, у нас ничего не получится."],[8,"Я плохо..."],[9,"—Ничего."],[10,"Прошу."],[11,"Как-нибудь."],[12,"Красавец танцевал бесстрастно, щегольски и, полный холодного высокомерия, не глядел на неё, она же топталась неумело, мотая юбкой, нацелив напряжённые глаза ему в галстук, и вдруг толчком вскинула голову — вокруг перестали танцевать, выходили из круга, послышался свист; за ними наблюдали, видимо, его приятели и делали замечания с едкой насмешливостью, передразнивали её движения, трясясь и корчась от смеха."],[13,"Её партнёр каменно изображал городского кавалера, а она всё поняла, всю непростительную низость, но не оттолкнула, не выбежала из круга, только сняла руку с его плеча и, ало краснея, постучала пальцем ему в грудь, как обычно стучат в дверь."],[14,"Он, удивлённый, склонился к ней, поднял брови, она снизу вверх медленно посмотрела ему в зрачки с непроницаемо-презрительным выражением опытной красивой женщины, уверенной в своей неотразимости, и ничего не сказала."],[15,"Нельзя позабыть, как он переменился в лице, потом он отпустил её и в замешательстве как-то чересчур вызывающе повёл к колонне, где стояли её подруги."]],"a":[13],"why":"(12)Красавец танцевал бесстрастно, щегольски и, полный холодного высокомерия, не глядел на неё, она же топталась неумело, мотая юбкой, нацелив напряжённые глаза ему в галстук, и вдруг толчком вскинула голову  — вокруг перестали танцевать, выходили из круга, послышался свист; за ними наблюдали, видимо, его приятели и делали замечания с едкой насмешливостью, передразнивали её движения, трясясь и корчась от смеха.","verifiedBy":"ключ источника"},{"id":"R4466","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 7−15 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":7,"hi":15,"s":[[7,"Недавно над этими местами летал самолёт и опрыскивал лес химической жидкостью."],[8,"Было задумано расширить площадь лугов."],[9,"Подсчитали, что корчевать живой лес дороже, чем отравить его с самолёта, а потом уж корчевать."],[10,"Дело не новое, оно привлекательно дешевизной и потому считается прогрессивным и выгодным."],[11,"Несомненно, есть в этом деле значительные плюсы."],[12,"Но есть и очень большие минусы."],[13,"Их не всегда замечают."],[14,"А ведь здесь погибло двадцать семь лосей, загублены тетерева, мелкие птицы, спасавшие окрестные поля и лес от вредителей."],[15,"Гибнут насекомые, многие из которых — наши друзья."]],"a":[13],"why":"(12)Но есть и очень большие минусы. (13)Их не всегда замечают.","verifiedBy":"выведено из пояснения"},{"id":"R4505","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 6–11 найдите такое, которое связано с предыдущим при помощи личного местоимения. Напишите номер этого предложения.","lo":6,"hi":11,"s":[[6,"...Шёл апрель 1947 года."],[7,"Мы, разлучённые войной со своими отцами, росли без царя в голове, не признавая ни законов, ни правил."],[8,"Голод, постоянные лишения, суровые жизненные условия — всё это наложило свой отпечаток на наши характеры."],[9,"Тогда считалось нормальным всячески показывать своё пренебрежение к учителям, и чем более дерзко ты себя вёл, тем больше тебя уважали в мальчишеской компании."],[10,"Учитель физики Иван Васильевич Матвеев пришёл к нам в седьмой класс."],[11,"Ходил он медленно, с усилием опираясь на палочку, и когда нечаянно задевал раненой ногой угол парты, то лицо чуть заметно вздрагивало от боли."]],"a":[11],"why":"(10)Учитель физики Иван Васильевич Матвеев пришёл к нам в седьмой класс. (11)Ходил он медленно, с усилием опираясь на палочку, и когда нечаянно задевал раненой ногой угол парты, то лицо чуть заметно вздрагивало от боли.","verifiedBy":"выведено из пояснения"},{"id":"R4544","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1−5 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":5,"s":[[1,"3а несколько дней до войны Академия архитектуры в Москве решила реставрировать редкие и наиболее ценные издания своей библиотеки."],[2,"Огромные тома Витрувия или Палладио, источенные червями или обветшавшие от времени, требовали тончайшего мастерства переплётчика, который должен был вернуть им первоначальный вид."],[3,"Такие золотые руки нашлись в Москве."],[4,"Это был старый переплётчик Эльяшев, родом из Николаева, человек, тонко чувствовавший эпоху, бескорыстно влюблённый в своё дело, виртуозный переплётчик и футлярщик."],[5,"Его пригласили в библиотеку Академии архитектуры, и Эльяшев реставрировал там или, вернее, воссоздал ряд замечательных книг, так что даже самый опытный взгляд не обнаружил бы изъянов."]],"a":[4],"why":"(4)Это был старый переплётчик Эльяшев, родом из Николаева, человек, тонко чувствовавший эпоху, бескорыстно влюблённый в своё дело, виртуозный переплётчик и футлярщик.","verifiedBy":"выведено из пояснения"},{"id":"R4583","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 21–30 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":21,"hi":30,"s":[[21,"Суд."],[22,"Родителей нигде не могли найти, и на заседании сидела классная руководительница."],[23,"Ни лица, ни имени её я не помню."],[24,"Помню только, что она была совсем молоденькой девчонкой."],[25,"Прокурор задал ей какой-то вопрос, она встала и вдруг заплакала."],[26,"Она плакала и говорила: «Не надо сажать его в тюрьму!"],[27,"Пожалуйста»."],[28,"Прокурор ей строго говорит: «Не плачьте, вы на вопрос ответьте»."],[29,"А она опять — плачет и только одно твердит: «Не сажайте его в тюрьму»."],[30,"И в этот момент я испытал чувство, которое невозможно описать никакими словами."]],"a":[23],"why":"(22)Родителей нигде не могли найти, и на заседании сидела классная руководительница. (23)Ни лица, ни имени её я не помню.","verifiedBy":"ключ источника"},{"id":"R4622","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 11–14 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":11,"hi":14,"s":[[11,"Учёные не могут закрывать глаза на опасность уничтожения человеческой цивилизации, не могут не видеть нищету, хронический голод и безграмотность сотен и сотен миллионов жителей нашей планеты."],[12,"Как исследователи, как гуманисты они могут и должны вносить свой вклад в решение этих острейших проблем современности."],[13,"Джон Бернал, выдающийся учёный и общественный деятель, размышляя о судьбах науки, писал, что первый и самый трудный шаг состоит в том, чтобы использовать наши знания против устранимого зла."],[14,"А вторым шагом является поиск средств борьбы со злом, против которого сегодня мы ещё бессильны."]],"a":[12],"why":"(11)Учёные не могут закрывать глаза на опасность уничтожения человеческой цивилизации, не могут не видеть нищету, хронический голод и безграмотность сотен и сотен миллионов жителей нашей планеты. (12)Как исследователи, как гуманисты они могут и должны вносить свой вклад в решение этих острейших проблем современности.","verifiedBy":"ключ источника"},{"id":"R4739","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 2–6 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения и синонимов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":2,"hi":6,"s":[[2,"Но есть один момент, таинственный, почти мистический, который требует глубокого осмысления."],[3,"Представим, что вы играете в шахматы с уважаемым гроссмейстером."],[4,"Ваше положение аховое, столпившиеся зрители уже обречённо махнули рукой, предлагают вам не тянуть понапрасну время и выбросить белый флаг."],[5,"Что сделает в такой ситуации любой человек, знакомый с правилами игры?"],[6,"Он проанализирует позицию на доске и, осознав бесперспективность своего сопротивления, смиренно капитулирует."]],"a":[5],"why":"(4)Ваше положение аховое, столпившиеся зрители уже обречённо махнули рукой, предлагают вам не тянуть понапрасну время и выбросить белый флаг. (5)Что сделает в такой ситуации любой человек, знакомый с правилами игры?","verifiedBy":"выведено из пояснения"},{"id":"R4778","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 10–16 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи контекстных синонимов и личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":10,"hi":16,"s":[[10,"Словно вода в пересыхающем степном колодце, таяли силы, мало-помалу отчаяние и безнадёжность овладевали людьми, которые оказались в западне."],[11,"Царь Пётр, пожалуй, лучше остальных понимал серьёзность создавшегося положения, но ему нужно было думать не о собственной жизни, а о судьбе страны, которая могла лишиться правителя."],[12,"Тогда царь отправил письмо в Боярскую Думу, которое правильнее было бы назвать завещанием."],[13,"В коротком послании он даёт последние распоряжения своим сподвижникам, просит их руководствоваться в своей деятельности государственными интересами."],[14,"Турки схватили посыльного, нашли депешу и внимательно её прочитали."],[15,"Карл XII, который прятался у турок, довольно потирал руки: письмо ясно указывало на то, что положение русских не просто тяжёлое, оно безнадёжное."],[16,"Но великий визирь, напротив, погрузился в задумчивость, а потом внезапно объявил, что решил заключить перемирие с окружённым русским войском и отпускает его на все четыре стороны."]],"a":[13],"why":"(12)Тогда царь отправил письмо в Боярскую Думу, которое правильнее было бы назвать завещанием. (13)В коротком послании он даёт последние распоряжения своим сподвижникам, просит их руководствоваться в своей деятельности государственными интересами.","verifiedBy":"ключ источника"},{"id":"R4856","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 13–19 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":13,"hi":19,"s":[[13,"Память может что-то объяснить, она может быть даже орудием исследования."],[14,"Одним людям память дана как наказание, другим — как ответственность."],[15,"Человек не может заставить себя не думать, не вспоминать, не обобщать."],[16,"Процесс познания начинается с прошлого, он не может быть отъединён от настоящего и локализован."],[17,"И я думаю, что такой памятью-ответственностью и памятью познания были наделены и Михаил Шолохов, и Леонид Леонов, и Алексей Толстой, когда в тридцатых годах писали свои знаменитейшие романы."],[18,"Это было глубочайшее проникновение в прошлое, а следовательно, никогда не терявшее своей новизны открытие."],[19,"Двадцатые, а также тридцатые годы, таким образом, всеобъёмно исследовались советской литературой."]],"a":[17,18],"why":"(16)Процесс познания начинается с прошлого, он не может быть отъединён от настоящего и локализован. (17)И я думаю, что такой памятью-ответственностью и памятью познания были наделены и Михаил Шолохов, и Леонид Леонов, и Алексей Толстой, когда в тридцатых годах писали свои знаменитейшие романы.","verifiedBy":"ключ источника"},{"id":"R4895","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 29–35 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного и личного местоимений. Напишите номер(-а) этого(-их) предложения(-ий).","lo":29,"hi":35,"s":[[29,"Там действительно собралось много начальства."],[30,"И это были последние слова Славы, потому что он-то знал, что уже никто не может выйти из лодки."],[31,"Но вокруг него в отсеке были люди, и старший помощник командира считал необходимым острить, чтобы поддержать в них волю."],[32,"Шторм оборвал аварийный буй, через который осуществлялась связь, и больше Слава ничего не смог сказать."],[33,"Когда лодку подняли, старшего помощника нашли на самой нижней ступеньке трапа к выходному люку."],[34,"Его подчинённые были впереди него."],[35,"Он выполнил свой долг морского офицера до самого конца."]],"a":[34],"why":"(ЗЗ)Когда лодку подняли, старшего помощника нашли на самой нижней ступеньке трапа к выходному люку. (34)Его подчинённые были впереди него.","verifiedBy":"выведено из пояснения"},{"id":"R4934","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 13–17 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":13,"hi":17,"s":[[13,"«Простое размышление о смысле жизни, — говорил Альберт Швейцер, — уже само по себе имеет ценность»."],[14,"Человек смотрит в небо, на звёзды — это ему необходимо потому, что он — человек."],[15,"Он смотрит не как вершина горы, дерево, кошка."],[16,"И смотрит, спрашивая и за себя, и за гору, и за кошку: что и зачем?"],[17,"А что же сегодня главное, какие вопросы самые актуальные?"]],"a":[15],"why":"(14)Человек смотрит в небо, на звёзды  — это ему необходимо потому, что он  — человек. (15)Он смотрит не как вершина горы, дерево, кошка.","verifiedBy":"выведено из пояснения"},{"id":"R4973","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 3–10 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи форм слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":3,"hi":10,"s":[[3,"У каждого готов свой ответ на заданный ещё Герценом вопрос."],[4,"Огромная, наполненная природными ресурсами страна обладает таким же огромным интеллектуальным потенциалом."],[5,"А большая часть населения прозябает в бедности!"],[6,"Почему?"],[7,"Кто виноват?"],[8,"Мне кажется, что причина всех наших проблем коренится глубже, чем мы себе представляем: ни гуманистические призывы, ни экономические реформы, ни набившие оскомину обещания новой жизни не могут сами по себе решить главного."],[9,"Она в нашем неуважении человека."],[10,"Надо сделать человека высшей ценностью."]],"a":[10],"why":"(9)Она в нашем неуважении кого? чего? человека. (10)Надо сделать кого? что? человека высшей ценностью.","verifiedBy":"выведено из пояснения"},{"id":"R5012","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 27–37 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":27,"hi":37,"s":[[27,"В моём детстве в реке была рыба, клевали на удочку здоровущие окуни, не то что сейчас — всякая мелкота!"],[28,"Мне кажется, что всё было лучше, но я знаю, что заблуждаюсь."],[29,"Кому дано волшебное право сравнивать детства?"],[30,"Какой счастливец смог дважды начать свою жизнь, чтобы сравнить два начала?"],[31,"Нет таких."],[32,"Моё детство видится мне прекрасным, и такое право есть у каждого, в какое бы время он ни жил."],[33,"Но жаль прогонять заблуждение."],[34,"Оно мне нравится и кажется важным."],[35,"Я понимаю: в детстве есть похожесть, но нет повторимости."],[36,"У каждого детства свои глаза."],[37,"Но как бы сделать так, чтобы, несмотря на трудности, мир остался по-детски ненаглядным?"]],"a":[31],"why":"(30)Какой счастливец смог дважды начать свою жизнь, чтобы сравнить два начала? (31)Нет таких.","verifiedBy":"ключ источника"},{"id":"R6861","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1−6 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения и контекстного синонима. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":6,"s":[[1,"Был поздний вечер."],[2,"Домашний учитель Егор Алексеич Свойкин, чтобы не терять попусту времени, от доктора отправился прямо в аптеку."],[3,"За жёлтой, лоснящейся конторкой стоял высокий господин с солидно закинутой назад головой, строгим лицом и с выхоленными бакенами, по всем видимостям провизор."],[4,"Начиная с маленькой плеши на голове и кончая длинными розовыми ногтями, всё на этом человеке было старательно выутюжено, вычищено и словно вылизано."],[5,"Нахмуренные глаза его глядели свысока на газету, лежавшую на конторке."],[6,"Он читал."]],"a":[4],"why":"Предложение 4-е связано с 3-им предложением при помощи слов на этом человеке.","verifiedBy":"выведено из пояснения"},{"id":"R6877","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 25-30 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения и контекстных синонимов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":25,"hi":30,"s":[[25,"...Прошло много лет."],[26,"И вот однажды в конце войны я стоял возле пушек в разрушенном польском городе."],[27,"Кругом пахло гарью, пылью."],[28,"И вдруг в доме, расположенном через улицу от меня, раздались звуки органа."],[29,"Эта музыка разбередила воспоминания."],[30,"Когда-то мне хотелось умереть от непонятной печали и восторга после того, как я послушал полонез Огинского."]],"a":[29],"why":"(28)И вдруг в доме, расположенном через улицу от меня, раздались звуки органа. (29)Эта музыка разбередила воспоминания.","verifiedBy":"ключ источника"},{"id":"R6900","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 4−9 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":4,"hi":9,"s":[[4,"В развитых западных странах образование доступно всем при наличии соответствующего желания, средств и стараний."],[5,"Однако свобода в получении образования имеет и другую сторону."],[6,"Это относится и к школам, и к высшим учебным заведениям."],[7,"Статистика свидетельствует, что выпускники не только государственных, но и частных школ далеко не всегда являются носителями высокой культуры, людьми высоких нравственных критериев."],[8,"Принято считать, что человек с университетским дипломом олицетворяет не только профессионализм, но и высокий уровень культуры."],[9,"Но какой уровень культуры может олицетворять выпускница университета, которая на вопрос профессора о роли языка в её жизни ответила: «Чтобы на тусовке сказать молодым людям что-нибудь эдакое»?.."]],"a":[6],"why":"(6) Это относится и к школам, и к высшим учебным заведениям.","verifiedBy":"ключ источника"},{"id":"R6939","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1–8 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи однокоренных слов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":8,"s":[[1,"Сто двадцать пять лет очень немного на весах истинного искусства."],[2,"За такое короткое время можно, однако, успеть повернуться спиной к своему собственному восторгу и поставить над вчерашним днём подлинного искусства вопросительный знак."],[3,"Мы призваны — согласились — и я в том числе — писать о гении."],[4,"Писать — значит судить."],[5,"Подлежит ли гений суду?"],[6,"Возможна ли канцелярская бумага, посланная Александру Сергеевичу Пушкину с требованием немедленно пересмотреть «Бориса Годунова» и выкинуть из этой книги всё, что я не понимаю или с чем не согласен?"],[7,"Ответ ясен."],[8,"Итак, можно написать только, что дал он тебе и что ты взял от него и, пожалуй, ещё: сохранил ли до сего дня?"]],"a":[5],"why":"Предложения 4 и 5 есть связываются словами судить— суду.","verifiedBy":"ключ источника"},{"id":"R6978","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 14−17 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза. Напишите номер(-а) этого(-их) предложения(-ий).","lo":14,"hi":17,"s":[[14,"Нечто подобное испытываешь во сне, когда, подкравшись к двери, слышишь за нею скрытное, затаившееся дыхание какого-то неописуемого существа, которое только и ждёт момента вставить колено, чуть приоткроется малая щёлка, и ворваться к тебе в тёплое, обжитое жильё."],[15,"Такое впечатление, что человечество приблизилось к финалу отпущенной ему скромной вечности."],[16,"А наука, с разбегу пробившись сквозь нулевую фазу времени и физического бытия, ворвётся в иное, ещё не освоенное математическое пространство с переносом туда интеллектуальной столицы мироздания."],[17,"Очевидный теперь крах вчерашней эры завершится неминуемым пересмотром печально не оправдавшей себя парности Добра и Зла."]],"a":[16],"why":"Ищем союз в начале предложения.","verifiedBy":"ключ источника"},{"id":"R37","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 15–19 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":15,"hi":19,"s":[[15,"Сожги это письмо, тебе одной на всём свете могу я рассказать про это, – Варя перевернула страничку."],[16,"Происшествие случилось в одной русской деревне, которую наша часть проходила в отступлении."],[17,"Я шёл последним в роте... а может, и во всей армии последним."],[18,"Перед нами на дороге встала местная девочка лет девяти, совсем ребёнок, видимо, на школьной скамье приученная любить Красную Армию..."],[19,"Конечно, она не очень разбиралась в стратегической обстановке."]],"a":[18,19],"why":"(18)Перед нами на дороге встала местная ДЕВОЧКА лет девяти, совсем ребёнок, видимо, на школьной скамье приученная любить Красную Армию... (19)Конечно, ОНА не очень разбиралась в стратегической обстановке.","verifiedBy":"ключ источника"},{"id":"R113","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 15—23 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью антонимов и частицы. Напишите номер(-а) этого(-их) предложения(-ий).","lo":15,"hi":23,"s":[[15,"— Хорошо, а когда же тогда писать? — спросите вы."],[16,"— Когда?"],[17,"После работы."],[18,"В дни отдыха."],[19,"В месяц отпуска, — отвечу я."],[20,"— Много ли тогда напишешь?"],[21,"— И очень хорошо, что немного."],[22,"Всё, что тогда напишется, будет полноценно, нужно."],[23,"А так, по совести сказать, взять почти у каждого писателя полное собрание его сочинений — много ли потеряет литература, если выбросить из неё три четверти написанного?"]],"a":[20],"why":"(20)— Много ли тогда напишешь?","verifiedBy":"выведено из пояснения"},{"id":"R151","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 10—19 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":10,"hi":19,"s":[[10,"Всюду языковое разноцветье."],[11,"Какое поле для наблюдения лингвистов, литераторов, актёров!"],[12,"Но как необычно, одухотворённо звучат в нашей сверхделовой речи старинные слова, которые ушли временно, но живут на страницах классиков и ждут светлых дней."],[13,"Ни в коем случае не стоит закрывать глаза на то, что, кроме иноязычных слов, нас захлёстывает и уголовная лексика."],[14,"Откуда пришли эти «крутые», «прикольные», «крыши», «клёвые»?"],[15,"Их источник ясен."],[16,"Но почему они расцветают среди вполне приличной молодежи, звучат с экрана, пестрят в печати?"],[17,"Этот разговор может продолжить каждый, кто радеет за наш язык."],[18,"Он ведь и сейчас «великий, могучий, правдивый и свободный»."],[19,"Только портим его мы сами, забывая о том, что он живой, поэтому не надо обижать его пошлостью, чужим сором, ненормативной лексикой, канцелярскими изысками, несовместимой мешаниной."]],"a":[15],"why":"(14)Откуда пришли эти «крутые», «прикольные», «крыши», «клёвые»? (15)Их источник ясен.","verifiedBy":"ключ источника"},{"id":"R189","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1—5 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи определительного и указательного местоимений. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":5,"s":[[1,"Как художник создаёт пейзажную картину, так и целый народ постепенно, невольно даже, быть может, штрих за штрихом на протяжении столетий создаёт ландшафт и пейзаж своей страны."],[2,"Лицо старой, дореволюционной России определялось, например, в большой степени теми сотнями тысяч церквей и колоколен, которые были расставлены по всем её просторам на возвышенных преимущественно местах и которые определяли силуэт каждого города — от самого большого до самого маленького, а также сотнями монастырей, бесчисленным количеством ветряных и водяных мельниц."],[3,"Немалую долю в ландшафт и пейзаж страны привносили и десятки тысяч помещичьих усадеб с их парками, системами прудов."],[4,"Но, конечно, в первую очередь, и небольшие деревеньки и сёла с ветлами, колодцами, сараями, баньками, тропинками, садами, огородами, залогами, пряслами, резными наличниками, коньками, крылечками, ярмарками, сарафанами, хороводами, покосами, пастушьими рожками, серпами, цепами, соломенными крышами, маленькими единоличными полями, лошадками на пахоте..."],[5,"Изменилось лицо страны, когда все эти факторы, определяющие пейзаж, исчезли."]],"a":[5],"why":"(5)Изменилось лицо страны, когда все эти факторы, определяющие пейзаж, исчезли. Определительное местоимение ВСЕ и указательное  — ЭТИ указывают на слова, употребленные в предыдущем предложении.","verifiedBy":"выведено из пояснения"},{"id":"R227","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 31—39 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью вводного слова и антонимов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":31,"hi":39,"s":[[31,"Воспитание вкуса — отдельная тема."],[32,"Это можно делать только на высоких образцах."],[33,"К сожалению, сейчас появилось много художественных произведений весьма невысокого художественного уровня."],[34,"Привыкая к ним, мы теряем ориентиры."],[35,"Воспитывать вкус можно на Толстом, на Достоевском, на Пушкине."],[36,"Главное — научиться различать, что действительно красиво, а что подделка."],[37,"Что ново и оригинально, а что банально и истёрто, тысячу раз встречалось."],[38,"Поэтому — не искусство: искусство всегда ново, что-то открывает."],[39,"Воспитать вкус можно лишь чтением, вдумыванием, вглядыванием в тексты истинно совершенные."]],"a":[33],"why":"(32)Это можно делать только на ВЫСОКИХ образцах. (33)К СОЖАЛЕНИЮ, сейчас появилось много художественных произведений весьма НЕВЫСОКОГО художественного уровня.","verifiedBy":"выведено из пояснения"},{"id":"R265","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 5—12 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":5,"hi":12,"s":[[5,"Как может устареть чувство чести, чувство собственного достоинства, сугубо личное нравственное чувство?"],[6,"Как может устареть понятие чести, которая даётся человеку однажды, вместе с именем, и которую нельзя ни возместить, ни исправить, которую можно только беречь?"],[7,"Мне вспоминается случай, связанный с именем А.П Чехова."],[8,"В 1902 году царское правительство аннулировало избрание Максима Горького в почётные академики."],[9,"В знак протеста Короленко и Чехов отказались от звания академиков."],[10,"Для Чехова это был акт не только общественный, но и личный."],[11,"Он писал в заявлении, что при избрании Горького он повидался с ним и первый поздравил его."],[12,"А теперь, когда Академия наук известила, что выборы недействительны, выходит, что он, Чехов, как академик, признаёт это."]],"a":[11],"why":"Личное местоимение «он» в предложении 11 заменяет имя собственное «Чехов» из предложения 10.","verifiedBy":"выведено из пояснения"},{"id":"R341","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 15—21 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью противительного союза и указательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":15,"hi":21,"s":[[15,"Конечно, второй случай предпочтительнее, но разлад есть разлад."],[16,"Поэтому мы видим, что общественная ориентация отнюдь не всегда безошибочна и что мода вообще вредна в таком деле, как дело нахождения себя."],[17,"Почему, собственно, считается творческой только жизнь артиста или художника?"],[18,"Ведь артистом и художником можно быть в любом деле."],[19,"Это должно быть нормой."],[20,"Ореол исключительности той или иной профессии, деление труда по таким принципам, как «почётно-непочётно», «интересно-неинтересно», как раз и поощряет мысль о недоступности творчества для всех и для каждого."],[21,"Но это вполне устраивает сторонников нивелирования личности, которые выделяют безликую толпу бездарных людей и противопоставляют ей людей талантливых."]],"a":[20],"why":"(20)Ореол исключительности той или иной профессии, деление труда по таким принципам, как «почётно-непочётно», «интересно-неинтересно», как раз и поощряет мысль о недоступности творчества для всех и для каждого.","verifiedBy":"выведено из пояснения"},{"id":"R379","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 12—15 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью лексического повтора. Напишите номер(-а) этого(-их) предложения(-ий).","lo":12,"hi":15,"s":[[12,"Но можно нередко встретить таких людей, которые, по своей ли вине или просто из-за дурных условий существования, не получив в молодости достаточного образования, вступили в жизнь без всяких познаний и подготовки для деятельности в качестве полезного члена общества."],[13,"Эти люди, если они не испытали всех трудностей первых лет учения по своей лености, всегда упрекают самих себя и начинают «учиться» уже в зрелых годах."],[14,"Пока не сделаются образованными, они не могут рассчитывать на те выгоды и ту пользу, которую другие люди получают после многих лет труда и лишений' ради образования."],[15,"Вместе с теми, кому мешали раньше учиться внешние обстоятельства, они, начиная заниматься, с удовольствием переносят все трудности учения и думают вместе с поэтом, который, «погубив много жизни на разные забавы», с сожалением говорил:"]],"a":[15],"why":"Указанное средство связи есть между предложениями 14 и 15:","verifiedBy":"ключ источника"},{"id":"R417","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 37—42 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью сочинительного союза и личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":37,"hi":42,"s":[[37,"Но неужели всё так безнадёжно?"],[38,"Неужели читателю, любящему живую книгу, остаётся утешаться нетленной классикой?"],[39,"К счастью, нет."],[40,"Поразительная закономерность."],[41,"Живая книга чудом пробивается к читателю."],[42,"И диктат рынка ей не слишком большая помеха."]],"a":[42],"why":"Предложение 42 (И диктат рынка ей не слишком большая помеха) связано с предыдущим союзом И и личным местоимением ЕЙ.","verifiedBy":"выведено из пояснения"},{"id":"R455","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 4—8 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью контекстного синонима. Напишите номер(-а) этого(-их) предложения(-ий).","lo":4,"hi":8,"s":[[4,"Научная мысль примечательна тем, что она является одним из организующих начал человеческой психики и направлена на сохранение, постоянное обновление, исправление, пересмотр результатов своей деятельности."],[5,"Именно поэтому она предполагает смелость, постоянство, упорство, что и придаёт будничному труду учёного подлинный драматизм."],[6,"Наукой заниматься не только трудно."],[7,"Наукой заниматься необходимо."],[8,"Исследовательская деятельность — мудрый педагог — воспитывает личность, развивает память и наблюдательность, точность и тонкость мышления."]],"a":[7],"why":"(7)Наукой заниматься необходимо.","verifiedBy":"выведено из пояснения"},{"id":"R493","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 15—22 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью союза, лексического повтора и антонимов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":15,"hi":22,"s":[[15,"Такие люди не нарушают моральных законов, но бездуховность их сразу видна."],[16,"Добрый и работящий человек, но не мучается его душа, не может, не хочет он выйти за круг бытовых забот."],[17,"Чего жаждет человек, когда у него духовное томление?"],[18,"Обычно желания делят на высокие и низкие, добрые и дурные."],[19,"Но разделим их по иному принципу: на конечные и бесконечные."],[20,"Конечные желания могут быть осуществлены к такому-то числу; это желания приобрести, получить, достичь, стать..."],[21,"Но никогда не исполнятся полностью, не исчерпают себя желания бесконечные — назовём их стремлениями: «священный сердца жар, к высокому стремленье» (Пушкин)."],[22,"Бесконечно стремление к добру, неутолима жажда правды, ненасытен голод по красоте... (С. Соловейчик)"]],"a":[21],"why":"(20)Конечные желания могут быть осуществлены к такому-то числу; это желания приобрести, получить, достичь, стать... (21)Но никогда не исполнятся полностью, не исчерпают себя желания бесконечные  — назовём их стремлениями: «священный сердца жар, к высокому стремленье» (Пушкин).","verifiedBy":"выведено из пояснения"},{"id":"R531","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 24—28 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":24,"hi":28,"s":[[24,"Плакали дети, лампочка, мигая от перепадов напряжения, разбрызгивала пучки жёлтенького света, запах чего-то несвежего и затхлого забивал лёгкие."],[25,"Вдруг в мои ноги уткнулся вырвавшийся из рук измученной мамы мальчик в синей кофточке."],[26,"Я погладил его пушистую головку, и малыш доверчивыми глазами посмотрел на меня."],[27,"Я улыбнулся."],[28,"Молодая мама усадила его на место."]],"a":[26],"why":"(25)Вдруг в мои ноги уткнулся вырвавшийся из рук измученной мамы мальчик в синей кофточке. (26)Я погладил его пушистую головку, и малыш доверчивыми глазами посмотрел на меня.","verifiedBy":"выведено из пояснения"},{"id":"R569","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1—8 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью однокоренного слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":8,"s":[[1,"Надобно сказать, что у нас на Руси если не угнались ещё кой в чём другом за иностранцами, то далеко перегнали их в умении обращаться."],[2,"Пересчитать нельзя всех оттенков и тонкостей нашего обращения."],[3,"Француз или немец век не смекнёт и не поймёт всех его особенностей и различий; он почти тем же голосом и тем же языком станет говорить и с миллионщиком, и с мелким табачным торгашом, хотя, конечно, в душе поподличает в меру перед первым."],[4,"У нас не то: у нас есть такие мудрецы, которые с помещиком, имеющим двести душ, будут говорить совсем иначе, нежели с тем, у которого их триста, а с тем, у которого их триста, будут говорить опять не так, как с тем, у которого их пятьсот, а с тем, у которого их пятьсот, опять не так, как с тем, у которого их восемьсот, — словом, хоть восходи до миллиона, всё найдутся оттенки."],[5,"Положим, например, существует канцелярия, не здесь, а в тридевятом государстве, а в канцелярии, положим, существует правитель канцелярии."],[6,"Прошу посмотреть на него, когда он сидит среди своих подчинённых, — да просто от страха и слова не выговоришь! гордость и благородство, и уж чего не выражает лицо его? просто бери кисть, да и рисуй: Прометей, решительный Прометей!"],[7,"Высматривает орлом, выступает плавно, мерно."],[8,"Тот же самый орёл, как только вышел из комнаты и приближается к кабинету своего начальника, куропаткой такой спешит с бумагами под мышкой, что мочи нет."]],"a":[2],"why":"(1)Надобно сказать, что у нас на Руси если не угнались ещё кой в чём другом за иностранцами, то далеко перегнали их в умении обращаться. (2)Пересчитать нельзя всех оттенков и тонкостей нашего обращения.","verifiedBy":"ключ источника"},{"id":"R607","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 7—12 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью союза и контекстных синонимов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":7,"hi":12,"s":[[7,"Обогащается или портится природная речь благодаря заимствованиям — вопрос непростой и неоднозначный."],[8,"Языковая стихия берёт из окружающего мира всё, что ей потребно, и выбрасывает на берег лишнее."],[9,"Но когда сплошь и рядом в кириллические устоявшиеся написания внедряются латинские и иные графические символы, то это ведёт не к обогащению языка, а к нарушению его функционирования, к размыванию веками устанавливавшихся норм."],[10,"Англо- и иноязычными словами в их натуральном написании сегодня пестрят страницы прессы, эти слова вторгаются в текст, наводняют рекламу."],[11,"Но одно дело, когда просто употребляется лексика на латинице, и совсем другое, если чужие буквы оказываются внутри слова, ломают его изнутри."],[12,"Любой юрист подтвердит, что это нарушение гораздо более тяжкое."]],"a":[11],"why":"(10)Англо- и иноязычными словами в их натуральном написании сегодня пестрят страницы прессы, эти слова вторгаются в текст, наводняют рекламу. (11)Но одно дело, когда просто употребляется лексика на латинице, и совсем другое, если чужие буквы оказываются внутри слова, ломают его изнутри.","verifiedBy":"ключ источника"},{"id":"R683","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 7—13 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":7,"hi":13,"s":[[7,"Я поднял к глазам бинокль."],[8,"В стёклах заколыхались белые надстройки теплохода, спасательные вельботы, тёмные от дождя чехлы и птицы — распушённые ветром мокрые комочки."],[9,"Они метались между антеннами и пытались спрятаться от ветра за трубой."],[10,"Палубу нашего теплохода выбрали эти маленькие бесстрашные птицы в качестве временного пристанища в своём долгом пути на юг."],[11,"Конечно, вспомнился Саврасов: грачи, весна, ещё лежит снег, а деревья проснулись."],[12,"И всё вообще вспомнилось, что бывает вокруг нас и что бывает внутри наших душ, когда приходит русская весна и прилетают грачи и скворцы."],[13,"Это не опишешь."]],"a":[9],"why":"Личное местоимение «они» в предложении 9 заменяет существительное «птицы» из предложения 8.","verifiedBy":"выведено из пояснения"},{"id":"R721","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 5—12 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":5,"hi":12,"s":[[5,"Если на маленьком космическом корабле космонавты начнут суетливо перерезать проводочки, развинчивать винтики, просверливать дырочки в обшивке, то это придется квалифицировать как самоубийство."],[6,"Но принципиальной разницы у маленького корабля с большим нет."],[7,"Вопрос только размеров и времени."],[8,"Человечество, по-моему, — это своеобразная болезнь планеты."],[9,"3авелись, размножаются, кишат микроскопические, в планетарном, а тем более во вселенском, масштабе существа."],[10,"Скапливаются они в одном месте, и тут же появляются на теле земли глубокие язвы и разные наросты."],[11,"Стоит только привнести капельку зловредной (с точки зрения земли и природы) культуры в зелёную шубу Леса (бригада лесорубов, один барак, два трактора) — и вот уж распространяется от этого места характерное, симптоматическое, болезненное пятно."],[12,"Снуют, размножаются, делают своё дело, выедая недра, истощая плодородие почвы, отравляя ядовитыми отправлениями своими реки и океаны, саму атмосферу Земли."]],"a":[10],"why":"Личное местоимение «они» в предложении 10 заменяет существительное «существа» из предложения 9.","verifiedBy":"выведено из пояснения"},{"id":"R759","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 6—11 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":6,"hi":11,"s":[[6,"Смешное детство!"],[7,"Оно вписалось в мою жизнь далёким неверным маревом, раскрашивая будущее яркими мечтательными мазками."],[8,"Вот кольцо последнего года войны, последнего боя, последнего марша на танках."],[9,"А это кривое кольцо очень долгого года несчастной любви, метаний..."],[10,"Каждый новый круг обнимает всё прошлое, расходится вширь; кажется, и жизнь расширяется, захватывая всё новые пространства."],[11,"Каждый круг будто волна, которая разбегается во все стороны, всё дальше от сердцевины, от моей человеческой сути."]],"a":[7],"why":"Личное местоимение «оно» в предложении 7 заменяет существительное «детство» из предложения 6.","verifiedBy":"выведено из пояснения"},{"id":"R797","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1—9 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи частицы, указательного местоимения и контекстного синонима.. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":9,"s":[[1,"В письме к жене 18 мая 1836 года Пушкин удивлялся: откуда взялись эти благоразумные молодые люди, «которым плюют в глаза, а они утираются» вместо того, чтобы защитить свою честь?"],[2,"Иногда кажется, что мы вышли из шинелей именно этих людей."],[3,"Звон упругой стали более не слышится нам в слове честь."],[4,"Откроем словарь Даля, чтобы вспомнить, во имя чего ставилась на карту жизнь, полная великих надежд и гениальных замыслов."],[5,"Итак, «честь — внутреннее нравственное достоинство человека, доблесть, честность, благородство души и чистая совесть»."],[6,"И тут же примеры: «Человек незапятнанной чести. По чести... Уверяю вас честью. Поступок, несовместимый с честью... Знал бы ты честь... Поле чести... Честь моя требует крови...»."],[7,"Дуэль!"],[8,"Только этот разряд убийственной силы мог стремительно восстановить нравственное равновесие."],[9,"Подлец знал, что его подлость может быть наказана не взиманием штрафа через год по приговору суда, а сегодня вечером."]],"a":[8],"why":"Указательное местоимение «этот» в предложении 8 указывает на существительное «дуэль» из предложения 7. Частица «только» соединяет предложение 8 с предложением 7. Контекстные синонимы в этих двух предложениях  — «дуэль» и «разряд убийственной силы».","verifiedBy":"ключ источника"},{"id":"R835","source":"РЕШУ ЕГЭ","prompt":"Какое из предложений 15—23 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения.Напишите номер(-а) этого(-их) предложения(-ий).","lo":15,"hi":23,"s":[[15,"В ней сейчас тридцать три дома."],[16,"Над одиннадцатью крышами поднимаются антенны."],[17,"Первый телевизор куплен в 1959 году, последний — неделю назад."],[18,"Оказалось, что по степени интереса на первом месте стоит кино."],[19,"3атем постановки, то есть спектакли."],[20,"На третьем месте — футбол, «Клуб путешественников», пение, концерты, «Огонёк»."],[21,"Интересно, что, так сказать, наименьшее количество очков, а именно по круглому нулю, получили, с одной стороны, симфоническая и всякая оркестровая музыка и даже опера, а с другой стороны, беседы по агротехнике и вообще специальные сельскохозяйственные передачи."],[22,"Над этим стоит задуматься."],[23,"Представьте себе передачу об основах стихосложения."]],"a":[22],"why":"Указательное местоимение «этим» в предложении 22 указывает на мысль, выраженную в предложении 21.","verifiedBy":"выведено из пояснения"},{"id":"R873","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1—5 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи местоимения и однокоренного слова.Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":5,"s":[[1,"С чьей-то лёгкой руки природу русского Севера журналисты называют неброской, неяркой и скромной."],[2,"Между тем нигде по стране нет таких ярких, таких выразительных, очень контрастных и многозвучных красок, как на Севере России."],[3,"Красота этих мест обусловлена не одним лишь разнообразием ландшафтов, сочетающих невысокие горы, холмы, долины, распадки, озёра и реки, обрамлённые лесами, лугами, кустарниками; она обусловлена и разнообразными, то и дело сменяющими друг друга пейзажными настроениями."],[4,"Эта смена происходит порою буквально в считаные секунды, не говоря уже о переменах, связанных с четырьмя временами года."],[5,"Лесное озеро из густо-синего моментально может преобразиться в серебристо-сиреневое, стоит подуть из леса лёгкому шуточному ветерку."]],"a":[4],"why":"(3)Красота этих мест обусловлена не одним лишь разнообразием ландшафтов, сочетающих невысокие горы, холмы, долины, распадки, озёра и реки, обрамлённые лесами, лугами, кустарниками; она обусловлена и разнообразными, то и дело сменяющими друг друга пейзажными настроениями. (4)Эта смена происходит порою буквально в считаные секунды, не говоря уже о переменах, связанных с четырьмя временами года.","verifiedBy":"ключ источника"},{"id":"R911","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 39—44 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения и контекстного синонима.Напишите номер(-а) этого(-их) предложения(-ий).","lo":39,"hi":44,"s":[[39,"Робка также и муза."],[40,"Как легко спугнуть её шумом!.."],[41,"Нежна её сущность, голос её нежен."],[42,"А шум — дерзкий парень."],[43,"Ничего не знает этот грубиян о таинственной изначальной мелодии, которая поднимается из колодца души, иногда вопрошая, иногда взывая, иногда вздыхая."],[44,"Он вытесняет эту мелодию из земной жизни и земной музыки..."]],"a":[43],"why":"Указательное местоимение «этот» в предложении 43 указывает на существительное «шум» из предложения 42. Контекстные синонимы в этих двух предложениях  — «шум» и «грубиян».","verifiedBy":"выведено из пояснения"},{"id":"R949","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 10—15 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза и двух личных местоимений. Напишите номер(-а) этого(-их) предложения(-ий).","lo":10,"hi":15,"s":[[10,"Я долго плакала, когда закончила читать повесть, и это были просветлённые, благодарные слёзы."],[11,"Я чувствовала себя счастливой и потому, что Марина Голубицкая написала эту прекрасную повесть о чудесном человеке, и потому, что жил этот человек — Елена Николаевна — в Перми, моём городе!"],[12,"А более всего меня радовала мысль, что на самом деле «время — честный человек»."],[13,"Как любила учительница своих учеников!"],[14,"И они отплатили ей взаимностью!"],[15,"Когда Елена Николаевна оказалась за границей, где страдала от ностальгии, одиночества и болезней, ученики писали, приезжали, помогали, снова писали, снова приезжали..."]],"a":[14],"why":"Личное местоимение «они» в предложении 14 заменяет существительное «ученики» из предложения 13, личное местоимение «ей» в предложении 14 заменяет существительное «учительница» из предложения 13. Союз «и» соединяет предложение 14 с предложением 13.","verifiedBy":"проверено по пояснению"},{"id":"R987","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 4—11 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":4,"hi":11,"s":[[4,"Детей не оттащишь от компьютера."],[5,"Сидят сутками."],[6,"Какие-то аськи, агенты, чаты, форумы...» «"],[7,"Я не понимаю, какое может быть от этого удовольствие."],[8,"Но сын сидит у монитора, смеётся чему-то, а то и кулаком по столу бьёт."],[9,"Мне кажется, он сходит с ума — разговаривает сам с собой». «"],[10,"Раньше играл в видеоигры, это отнимало много времени, уроки забросил, а теперь вообще из рук вон — будто его нет дома."],[11,"Целыми днями в Сети, говорит, у них там тусовка...»"]],"a":[9],"why":"Предложение 9 «Мне кажется, он сходит с ума  — разговаривает сам с собой» связано с предыдущим при помощи личного местоимения ОН (соответствует слову СЫН из предыдущего предложения).","verifiedBy":"ключ источника"},{"id":"R1025","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 2—7 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения и форм слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":2,"hi":7,"s":[[2,"Высшее, чего может достичь человек, — это мудрость."],[3,"Ей бы полагалось стать школьным предметом, мудрости надо учить."],[4,"Точнее, к мудрости надобно приучать — как к осторожности суждений, воздержанию от недостаточно обоснованных утверждений, умению принимать во внимание множество факторов, опираясь на то, что рождено разнообразием исторического опыта."],[5,"Это больше, чем знания."],[6,"Это ещё и интуиция, и отвращение к самообману."],[7,"Мудрый человек никогда не самонадеян: он не считает конечными полученные им результаты раздумий, он допускает их ошибочность, сопоставляя их с прямо противоположными утверждениями и находя пробелы в том, что казалось бесспорным."]],"a":[3],"why":"Личное местоимение «ей» в предложении 3 заменяет существительное «мудрость» из предложения 2. Также эти два предложения связывает то, что в 3-ем предложении употреблено слово «мудрость» из 2-го предложения, поставленное в дательный падеж.","verifiedBy":"ключ источника"},{"id":"R1063","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 15—18 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения и форм слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":15,"hi":18,"s":[[15,"Одну из самых сильных страниц в творческой биографии Маршака приоткрыл Борис Полевой, в ту пору — главный редактор журнала «Юность»."],[16,"Он уже слышал, что Маршак еле жив, что врачи борются даже не за дни, а за часы его жизни..."],[17,"И вдруг звонок у него в редакции: «С вами хочет говорить Самуил Яковлевич»."],[18,"Полевой не поверил."]],"a":[16],"why":"Личное местоимение «он» в предложении 16 заменяет «Борис Полевой» из предложения 15. Также эти два предложения связывает то, что слово «Маршака», употребленное в предложении 15 в родительном падеже, есть в предложении 16 в именительном падеже.","verifiedBy":"проверено по пояснению"},{"id":"R1101","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 29-34 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза и лексического повтора. Напишите номер(-а) этого(-их) предложения(-ий).","lo":29,"hi":34,"s":[[29,"...И так лежать на траве."],[30,"Но почему именно на траве?"],[31,"Что же, если не нравится, ложитесь на пыльную дорогу, на кирпичи, на обрезки железа, на кучу минерального удобрения, на сучковые доски."],[32,"Можно, конечно, расстелить на земле плащ."],[33,"Но я бы советовал — на траве."],[34,"Эти минуты сделаются, может быть, лучшими, памятными минутами вашей жизни."]],"a":[30],"why":"Предложение 30 связано с 29 при помощи повтора на «траве» и союза но.","verifiedBy":"выведено из пояснения"},{"id":"R1177","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 20—25 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения и слов одной тематической группы. Напишите номер(-а) этого(-их) предложения(-ий).","lo":20,"hi":25,"s":[[20,"Прошло почти пятьдесят лет."],[21,"Де Соссюр достиг преклонного возраста и умер малоизвестным."],[22,"Незадолго до смерти он трижды прочитал в Женевском университете, где был профессором, курс общего языкознания."],[23,"В первый год к нему пришло всего шесть слушателей, в последний — целых двенадцать!"],[24,"Как можно видеть, студенты на лекции де Соссюра, мягко говоря, не особенно стремились попасть."],[25,"А дальше начались поистине сказочные события."]],"a":[22,23],"why":"(21)Де Соссюр достиг преклонного возраста и умер малоизвестным. (22)Незадолго до смерти он трижды прочитал...","verifiedBy":"ключ источника"},{"id":"R1215","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 11—16 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения и форм слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":11,"hi":16,"s":[[11,"— Итоги подводить нам ещё рано, — продолжал выступающий, — но то,что мы сделали, это уже весомо."],[12,"Это дело чести..."],[13,"Романов Ф. С., мл. сержант, — про себя читал я."],[14,"Салямов М., рядовой, Санько А. Д., рядовой..."],[15,"Вчитываясь в эти фамилии, я как-то и не заметил, когда председателя сменила бойкая девчонка."],[16,"Слушал эту чистенькую расторопную девчонку, а передо мной встали в памяти картины, виденные там, на войне..."]],"a":[16],"why":"Указательное местоимение «эту» в предложении 16 указывает на определение девчонки из предложения 15.","verifiedBy":"ключ источника"},{"id":"R1253","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 19-24 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза. Напишите номер(-а) этого(-их) предложения(-ий).","lo":19,"hi":24,"s":[[19,"В последнее время на уроках литературы мне кажется, будто между нами, одноклассниками, бьются окна, срываются шторы, становится всё понятно..."],[20,"Мы отрываемся от художественного произведения, от рассказов Бунина и Куприна, пружиним литературными строчками, подпрыгиваем и улетаем за горизонты школьной программы, туда, где начинается жизнь..."],[21,"Углубляемся в тему любви, которая трогает больше всего, заставляет спорить, громко и страстно рассуждать..."],[22,"В любовь все верят одинаково."],[23,"И несправедливо выделять кого-то: юношей, девушек..."],[24,"Нет более или менее романтичных или сентиментальных."]],"a":[23],"why":"(22)В любовь все верят одинаково. (23)И несправедливо выделять кого-то: юношей, девушек...","verifiedBy":"выведено из пояснения"},{"id":"R1291","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 14-17 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения и форм слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":14,"hi":17,"s":[[14,"Начались осенние ливни и бури, по ночам тополь скрипел, стонал, бился ветвями о стену, словно просил защиты от непогоды."],[15,"Постепенно облетали листья с его ветвей, сначала с верхних, потом с нижних."],[16,"Листья струились ручьями, устилая балкон, и некоторые прилипали к стеклам и с ужасом глядели в комнату, чего-то ожидая."],[17,"И вот уже на тополе не осталось ни одного листочка, он стоял голый, чёрный, словно обгорелый, и на фоне синего неба видна была каждая чёрная веточка, каждая жилочка, было торжественно тихо и печально в природе, негреющее солнце светило по-летнему."]],"a":[15],"why":"(14)Начались осенние ливни и бури, по ночам тополь скрипел, стонал, бился ветвями о стену, словно просил защиты от непогоды. (15)Постепенно облетали листья с его ветвей, сначала с верхних, потом с нижних.","verifiedBy":"выведено из пояснения"},{"id":"R1367","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 11—22 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи лексического повтора. Напишите номер(-а) этого(-их) предложения(-ий).","lo":11,"hi":22,"s":[[11,"На самом ли деле он выражает свои мысли или бессознательно продолжает сценическую игру и говорит то, чего от него ждут поклонники?"],[12,"Посмотрите: я «свой», такой же, как все."],[13,"Отсюда и иронично-снисходительное отношение к образованности, и кокетливое ёрничанье: «Ученье — свет, а неученье — приятный полумрак», и надменное самолюбование."],[14,"Но вот передача закончилась."],[15,"Что осталось в душе тех, кто слушал артиста?"],[16,"Какие семена он посеял в доверчивых сердцах?"],[17,"Кого он сделал лучше?"],[18,"Кого он направил на путь творческого созидания?"],[19,"Когда одному известному ди-джею молоденькая журналистка задала эти вопросы, он просто фыркнул: да идите вы, я совсем не для этого..."],[20,"И в этом недоуменном возмущении «поп-звезды» проявляется её гражданская незрелость, её человеческая «недообразованность»."],[21,"А человек, который ещё не построил себя как личность, не осознал своей миссии в обществе, становится покорным слугой толпы, её вкусов и потребностей."],[22,"Он, может быть, и умеет петь, но не знает, для чего поёт."]],"a":[17,18],"why":"В предложениях 16-18 повторяются:","verifiedBy":"ключ источника"},{"id":"R1405","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 10-14 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза и притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":10,"hi":14,"s":[[10,"Если говорить словами великого поэта, то мы «сеем разумное, доброе, вечное»."],[11,"И в школьном классе, и в прекрасном зале на Фонтанке я вижу, как в глазах старшеклассников появляется пытливый блеск понимания и сопереживания, когда они слушают Достоевского, Чехова, Пушкина, Галича, Окуджаву, как глубокие мысли и чувства, высказанные на сказочно прекрасном русском языке, трудно переводимом на другие языки, находят свой путь к их разуму и сердцу."],[12,"И их реплики после концерта — «клёво!» — не меньшая награда, чем громкие аплодисменты или напряжённая, сознательная тишина во время выступлений."],[13,"Надо только сделать так, чтобы этот «птичий» подростковый сленг переплавился в их сознании в прекрасную русскую речь."],[14,"А что говорить о великой классической музыке, которая без слов — напрямую — испокон веку воздействовала на чувства людей!"]],"a":[12],"why":"(11)И в школьном классе, и в прекрасном зале на Фонтанке я вижу, как в глазах старшеклассников появляется пытливый блеск понимания и сопереживания, когда они слушают Достоевского, Чехова, Пушкина, Галича, Окуджаву, как глубокие мысли и чувства, высказанные на сказочно прекрасном русском языке, трудно переводимом на другие языки, находят свой путь к их разуму и сердцу. (12)И их реплики после концерта  — «клёво!»  — не меньшая награда, чем громкие аплодисменты или напряжённая, сознательная тишина во время выступлений.","verifiedBy":"выведено из пояснения"},{"id":"R1443","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 13-20 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза. Напишите номер(-а) этого(-их) предложения(-ий).","lo":13,"hi":20,"s":[[13,"Несколько веков тому назад, когда информационная сторона человеческих знаний была не столь обширна, встречались учёные мужи, «капсула» которых приближалась к «капсуле» всего человечества и, может быть, даже совпадала с ней: Аристотель, Архимед, Леонардо да Винчи..."],[14,"Теперь такого мудреца, который знал бы столько же, сколько знает человечество как таковое, найти нельзя."],[15,"Следовательно, про каждого можно сказать, что он ограниченный человек."],[16,"Но очень важно разделять знания и представления."],[17,"Чтобы пояснить свою мысль, возвращаюсь к нашему горняку в каменноугольном пласте."],[18,"Допустим условно и теоретически, что некоторые из горняков родились там, под землей, и ни разу не вылезали наружу."],[19,"Не читали книг, не имеют никакой информации, никакого представления о внешнем, запредельном (находящемся за пределами их забоя) мире."],[20,"Вот он выработал вокруг себя довольно обширное пространство и обитает в нём, думая, что мир ограничен его забоем."]],"a":[16],"why":"(15)Следовательно, про каждого можно сказать, что он ограниченный человек. (16)Но очень важно разделять знания и представления.","verifiedBy":"выведено из пояснения"},{"id":"R1481","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1—6 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза и личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":6,"s":[[1,"Для меня ясно одно: главные участники истории — это Люди и Время."],[2,"Не забывать Время — это значит не забывать Людей, не забывать Людей — это значит не забывать Время."],[3,"Количество дивизий, участвовавших в том или ином сражении, со скрупулёзной точностью подсчитывают историки."],[4,"Однако они не смогут подслушать разговор в окопе перед танковой атакой, увидеть страдание и слёзы в глазах восемнадцатилетней девушки-санинструктора, умирающей в полутьме полуразрушенного блиндажа, вокруг которого гудят прорвавшиеся немецкие танки, ощутить треск пулемётной очереди, убивающей жизнь."],[5,"Нам было тогда по двадцать лет."],[6,"Мы мечтали вернуться в тот солнечный довоенный мир, где солнце казалось нам праздничным солнцем, встающим над землёй изо дня в день по своей непреложной закономерности; трава была травой, предназначенной для того, чтобы расти; фонари — для того, чтобы освещать сухой апрельский тротуар, вечернюю толпу гуляющих, в которой идёшь и ты, восемнадцатилетний, загорелый, сильный."]],"a":[4],"why":"Личное местоимение «они» в предложении 4 заменяет существительное «историки» из предложения 3. Союз «однако» соединяет предложение 4 с предложением 3.","verifiedBy":"ключ источника"},{"id":"R1519","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 9—12 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза, наречия и личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":9,"hi":12,"s":[[9,"Работа нам предстоит немалая, — сказала одна из женщин, — дело в том, что по приказу гебитскомиссара Оппа мы должны были уничтожить все книги по прилагаемому списку, — и она достала из ящика целую пачку листков с тесными строками машинописи: это был список подлежавших уничтожению книг."],[10,"Мы переклеивали со старых учебников и разных других книг заглавные страницы, и нам удалось спасти почти всё, что подлежало уничтожению, — добавила женщина с удовлетворением, — так что не удивляйтесь, если том сочинений Пушкина, например, называется руководством по вышиванию."],[11,"Это было действительно так: две мужественные женщины спасли целую районную библиотеку, вклеивая в подлежавшие уничтожению книги другие названия или вкладывая их в другие переплёты."],[12,"А теперь они разбирались в своих богатствах, восстанавливали то, что по распоряжению назначенного директором библиотеки Крамма они должны были разорвать в клочки."]],"a":[12],"why":"12)А теперь они разбирались в своих богатствах, восстанавливали то, что по распоряжению назначенного директором библиотеки Крамма они должны были разорвать в клочки.","verifiedBy":"выведено из пояснения"},{"id":"R1557","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 19—23 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи лексических повторов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":19,"hi":23,"s":[[19,"Таким образом, справедливость означает именно неравенство: беречь ребёнка, помогать слабому, снисходить к уставшему, ухаживать за больным; проявлять больше строгости к безвольному, больше доверия честному, больше осторожности к болтуну; герою оказывать почести."],[20,"Справедливость поэтому — искусство неравенства, и она присуща лишь благородным душам."],[21,"У неё обострённое чувство реальности; проистекающая от доброго сердца и живой наблюдательности, она отвергает механический подход к людям."],[22,"Она хочет индивидуально подойти к каждому случаю, располагая человека к состраданию."],[23,"Она старается уловить в человеке его сущность и своеобразие и соответственно этому обходиться с ним."]],"a":[20,21,22,23],"why":"(19)Таким образом, справедливость означает именно неравенство: беречь ребёнка, помогать слабому, снисходить к уставшему, ухаживать за больным; проявлять больше строгости к безвольному, больше доверия честному, больше осторожности к болтуну; герою оказывать почести.","verifiedBy":"ключ источника"},{"id":"R1595","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 12-19 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза и лексического повтора. Напишите номер(-а) этого(-их) предложения(-ий).","lo":12,"hi":19,"s":[[12,"Островок был замкнут в кольцо прибоя, но штурман вызвался идти туда на вельботе."],[13,"Он уверил командира в том, что уже неоднократно высаживался здесь, что знает проходы в прибрежных камнях."],[14,"Он никогда даже близко здесь не был и не ведал никаких проходов."],[15,"3ато он хорошо понимал, что срок сдачи документации будет продлён, если удастся наладить маяк, не дожидаясь ослабления штормового ветра."],[16,"Нет, это не была совсем уж отчаянная авантюра."],[17,"Шаталов был хорошим моряком и румпель вельбота чувствовал не только ладонью, но и всем своим существом."],[18,"Просто судьба изменила..."],[19,"Он потерял ориентировку среди волн, бурунов, завес из брызг..."]],"a":[15],"why":"(14)Он никогда даже близко здесь не был и не ведал никаких проходов. (15)3ато он хорошо понимал, что срок сдачи документации будет продлён, если удастся наладить маяк, не дожидаясь ослабления штормового ветра","verifiedBy":"выведено из пояснения"},{"id":"R1633","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 22-25 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":22,"hi":25,"s":[[22,"Серёжка, сдувая с лица капли пота, рвал свою футболку на лоскуты и от усталости, кажется, уже не соображал, что я говорю."],[23,"Он дотащил меня до больницы, потом, тяжело дыша, сидел на кушетке и смотрел, как врач обрабатывает мою рану."],[24,"А на следующий день, когда я, хромая, вышел во двор, все уже знали, что перед смертью я просил передать привет Гальке Коршуновой."],[25,"И я сделался посмешищем всей школы."]],"a":[23],"why":"Личное местоимение «он» в предложении 23 заменяет имя собственное «Сережка» из предложения 22.","verifiedBy":"выведено из пояснения"},{"id":"R1709","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1—12 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения и слов одной тематической группы. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":12,"s":[[1,"Однажды зимой с телевизионных экранов Омска прозвучало обращение врачей к зрителям: пострадавшему человеку срочно требовалась донорская кровь."],[2,"Люди сидели в тёплых уютных квартирах, никто не знал о делах друг друга, никто не собирался, да и не мог контролировать человеческие поступки."],[3,"Любой человек мог потом сказать: я не смотрел телевизор, я обращения не слышал."],[4,"Но контролёр всё же у большинства был."],[5,"Высший нравственный контролёр — совесть."],[6,"Но ведь и только!"],[7,"Да, и только."],[8,"Но это «только», эта единственная избирательность и оказывалась главной в последующие минуты, когда человек начинал действовать."],[9,"На трамваях, на автобусах, на такси люди добирались до больницы."],[10,"Дежурные медсестры выходили их встречать."],[11,"3а 30 минут в больницу приехало 320 человек."],[12,"Пострадавший был спасён."]],"a":[10],"why":"(9)На трамваях, на автобусах, на такси люди добирались до больницы. (10)Дежурные медсестры выходили их встречать.","verifiedBy":"ключ источника"},{"id":"R1747","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 3—9 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи только притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":3,"hi":9,"s":[[3,"В какой-то мере — да."],[4,"Но в то же самое время, создавая новые символы-идеограммы, человечество не отказывается и от достижений тысячелетий — от фонетического письма."],[5,"Таким образом, наша письменность становится смешанной, «буквенно-идеографической»."],[6,"Например, тексты научных статей по математике или ядерной физике написаны именно таким буквенно-идеографическим письмом."],[7,"Преимущество его по сравнению с алфавитом очевидно."],[8,"Во-первых, идеограммы понятны независимо от языка (химические формулы, математические символы), во-вторых, они не только сокращают запись, но и помогают научному мышлению (прогресс математики обязан главным образом введению специальной символики, созданию «языка математики»)."],[9,"А в-третьих, такая символика становится понятной не только любому человеку, но и компьютерам."]],"a":[7],"why":"(6)Например, тексты научных статей по математике или ядерной физике написаны именно таким буквенно-идеографическим письмом. (7)Преимущество его по сравнению с алфавитом очевидно.","verifiedBy":"ключ источника"},{"id":"R1785","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 21-27 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":21,"hi":27,"s":[[21,"Однако и кроме возведения время от времени в культ какого-нибудь одного цветка, цветы имеют над людьми незаметную, но постоянную власть."],[22,"Потребность в них была велика во все времена."],[23,"Более того, по отношению общества к цветам можно было во все времена судить о самом обществе и о его здоровье либо болезни, о его тонусе и характере."],[24,"Государство в расцвете и силе — во всём мера."],[25,"Цветы в большой цене, однако без каких-либо патологических отклонений."],[26,"С разложением государственной крепости отношение к цветам принимает черты излишества и болезненности."],[27,"Разве это не своеобразный барометр?"]],"a":[22],"why":"Личное местоимение «них» в предложении 22 заменяет существительное «цветы» из предложения 21.","verifiedBy":"выведено из пояснения"},{"id":"R1823","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 38—47 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":38,"hi":47,"s":[[38,"А потом, когда я уже спустился в метро, у меня вдруг как будто сердце оборвалось."],[39,"Я вдруг подумал:"],[40,"«Это же моя мама!»"],[41,"Побежал наверх."],[42,"Поезд уже должен был отправляться."],[43,"Когда я заскочил в вагон, проводница уже никого не впускала."],[44,"Где-то в середине я их нашёл."],[45,"Какие-то люди заталкивали чемоданы на верхние полки, Наташка прыгала у окна, а мама сидела около самой двери и плакала."],[46,"Никто на её слёзы внимания не обращал."],[47,"Человек уезжает — мало ли..."]],"a":[46],"why":"(45)Какие-то люди заталкивали чемоданы на верхние полки, Наташка прыгала у окна, а мама сидела около самой двери и плакала. (46)Никто на её слёзы внимания не обращал","verifiedBy":"выведено из пояснения"},{"id":"R1861","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 7—12 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи контекстных синонимов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":7,"hi":12,"s":[[7,"Однажды в невесёлый час Вильгельм Кюхельбекер напишет мужу старшей сестры, известному учёному и педагогу Григорию Глинке, что в Лицее всё ему немило, что друзей нет и дел нет."],[8,"Родственник отвечал: «...жалею вместе с тобою о твоих неудачах», советовал крепче приналечь на науки, но винил и самого Кюхлю:"],[9,"«Ты напрасно надеешься найти друзей между ветрениками твоих лет, не созрев пока сам для чувства дружбы."],[10,"Вообще старайся воспользоваться золотою порой молодости твоей, занимаясь исключительно науками, в которых благо жизни нашей; не упускай притом из виду будущего своего назначения в обществе и сделай себя достойным его."],[11,"Не плачь обо всём и во всякое время; плаксивое лицо, точно как и слишком грустное расположение духа, нимало не сочетается с юношеским возрастом."],[12,"Привыкнув на все вещи смотреть с худой стороны, ты поневоле будешь несчастлив."]],"a":[8],"why":"(7)0днажды в невесёлый час Вильгельм Кюхельбекер напишет мужу старшей сестры, известному учёному и педагогу Григорию Глинке, что в Лицее всё ему немило, что друзей нет и дел нет. (8)Родственник отвечал: «...жалею вместе с тобою о твоих неудачах», советовал крепче приналечь на науки, но винил и самого Кюхлю:","verifiedBy":"ключ источника"},{"id":"R1899","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 8-11 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":8,"hi":11,"s":[[8,"Это — самая распространённая, самая злокачественная болезнь нашей речи."],[9,"Когда-то редкостный знаток русского языка и чудодей слова Корней Иванович Чуковский заклеймил её точным, убийственным названием."],[10,"Статья его так и называлась — «Канцелярит», и прозвучала она поистине как SOS."],[11,"He решаюсь сказать, что то был глас вопиющего в пустыне: к счастью, есть рыцари, которые, не щадя сил, сражаются за честь Слова."]],"a":[9],"why":"(10) Статья его (то есть чьё) так... (Корнея Чуковского из предложения 9).","verifiedBy":"выведено из пояснения"},{"id":"R1937","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 5—11 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи форм слова и указательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":5,"hi":11,"s":[[5,"А в горке этой, подвергшейся странному запустению неподалёку от центра столицы, шли вверх белые ступени, числом около семи, потом прекращались и начинались, кажется, вновь."],[6,"Какое-то глухое воспоминание колыхнулось в Яконове при виде этих белых ступеней, а куда вели ступени, плохо различалось в темноте: здание странной формы, одновременно как бы разрушенное и уцелевшее."],[7,"Лестница поднималась к широким железным дверям, закрытым наглухо и по колено заваленным слежавшимся щебнем."],[8,"Да!"],[9,"Да!"],[10,"Разящее воспоминание подхлестнуло Яконова."],[11,"Он оглянулся."]],"a":[6],"why":"(5)А в горке этой, подвергшейся странному запустению неподалёку от центра столицы, шли вверх белые ступени, числом около семи, потом прекращались и начинались, кажется, вновь. (6)Какое-то глухое воспоминание колыхнулось в Яконове при виде этих белых ступеней, а куда вели ступени, плохо различалось в темноте: здание странной формы, одновременно как бы разрушенное и уцелевшее.","verifiedBy":"ключ источника"},{"id":"R1975","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 10-16 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи формы слова и указательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":10,"hi":16,"s":[[10,"Впервые серьёзно начал я читать, когда ко дню рождения подарили мне книгу Льва Толстого «Хаджи-Мурат», голубую, с серебряным тиснением."],[11,"Эта книга оказалась для меня особенной на всю дальнейшую мою жизнь."],[12,"Я не только её вид помню, но помню запах, хотя нет сомнений, что это просто запах клея и коленкора..."],[13,"Я всегда завидовал моим сверстникам, у кого были и сохранились отцовские библиотеки."],[14,"Мне же многое приходилось открывать поздно."],[15,"Бунина, Хемингуэя, Ремарка я прочёл только в конце сороковых — середине пятидесятых годов."],[16,"А потом были годы, когда я пытался во что бы то ни стало объять необъятное и перечитал массу книг."]],"a":[11],"why":"Указательное местоимение «эта» в предложении 11 указывает на определение книги, данное в предложении 10. В предложениях 11-10 используется форма слова «книга».","verifiedBy":"выведено из пояснения"},{"id":"R2013","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 8—11 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи вводного слова и личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":8,"hi":11,"s":[[8,"Человеческие фамилии — вещь хитрая и тонкая."],[9,"Видимо, наличие их играет в жизни людей куда большую роль, чем кажется, если они могут так огорчать и радовать, нравиться и внушать отвращение, быть предметом досады или гордости."],[10,"Нередко случается, что фамилия становится источником бесконечных неприятностей для своего носителя; бывает — недоброжелатели превращают её в оружие, способное чувствительно ранить."],[11,"Очень часто выходит, что мы встречаем новое лицо по его фамилии, как «по одежке» в известной пословице; должно пройти известное время, чтобы человек это впечатление изменил или опроверг."]],"a":[9],"why":"Личное местоимение «их» в предложении 9 заменяет существительное «фамилии» из предложения 8. Также эти два предложения связывает вводное слово «видимо», употребленное в 9 предложении.","verifiedBy":"выведено из пояснения"},{"id":"R2469","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 18–23 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью лексического повтора. Напишите номер(-а) этого(-их) предложения(-ий).","lo":18,"hi":23,"s":[[18,"Впервые я читал книгу, под которой не мог нащупать дна."],[19,"Каким-то образом возникло ощущение моря."],[20,"Незнакомые сцены усадебной жизни воспринимались как родные."],[21,"Хотелось к ним."],[22,"Хотелось посмотреть, как аппетитно косит Левин, побывать с ним на охоте, поиграть с его умной собакой, посидеть с женщинами, которые варят варенье, и дождаться своей доли пенок."],[23,"Это был роман-дом, где хочется жить, но я еще этого не понимал."]],"a":[22],"why":"В предложениях 21—22 используется лексический повтор слова «хотелось».","verifiedBy":"ключ источника"},{"id":"R2508","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 6–13 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью личного и притяжательного местоимений. Напишите номер(-а) этого(-их) предложения(-ий).","lo":6,"hi":13,"s":[[6,"У Ростовых были именинницы Натальи, мать и меньшая дочь."],[7,"С утра, не переставая, подъезжали и отъезжали цуги, подвозившие поздравителей к большому, всей Москве известному дому графини Ростовой на Поварской."],[8,"Графиня с красивой старшею дочерью и гостями, не перестававшими сменять один другого, сидели в гостиной."],[9,"Графиня была женщина с восточным типом худого лица, лет сорока пяти, видимо изнуренная детьми, которых у ней было двенадцать человек."],[10,"Медлительность ее движений и говора, происходившая от слабости сил, придавала ей значительный вид, внушавший уважение."],[11,"Княгиня Анна Михайловна Друбецкая, как домашний человек, сидела тут же, помогая в деле принимания и занимания разговором гостей."],[12,"Молодежь была в задних комнатах, не находя нужным участвовать в приеме визитов."],[13,"Граф встречал и провожал гостей, приглашая всех к обеду."]],"a":[10],"why":"В этих предложениях есть личные и притяжательные местоимения: ней (предложение 9), ее (предложение 10), ей (предложение 10). В предложении 10 есть и личное, и притяжательное местоимения, обозначающие графиню из предыдущего предложения.","verifiedBy":"проверено по пояснению"},{"id":"R2665","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 7-11 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":7,"hi":11,"s":[[7,"Я не мог не восхититься тем, как трогательно и тщательно хранят в Стратфорде память о своём гениальном земляке."],[8,"Но наш гид, уроженец тех мест, быстро развеял мои иллюзии."],[9,"Улыбнувшись, он сказал, что современники и соседи поэта имели весьма приблизительное представление о его литературных занятиях."],[10,"И в церкви Шекспир был похоронен не как гений, а как примерный и достаточно щедрый прихожанин."],[11,"Я не мог в это поверить."]],"a":[9],"why":"Личное местоимение «он» в предложении 9 заменяет существительное «гид» из предложения 8.","verifiedBy":"выведено из пояснения"},{"id":"R7213","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 14-22 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения и лексического повтора. Напишите номер(-а) этого(-их) предложения(-ий).","lo":14,"hi":22,"s":[[14,"Что такое благодарность?"],[15,"Это ответ живого, любящего сердца на оказанное ему благодеяние."],[16,"Оно отвечает любовью на любовь, радостью на доброту, излучением на свет и тепло, верным служением на дарованную благодать."],[17,"Благодарность не нуждается в словесных изъявлениях, и иногда бывает лучше, чтобы человек переживал и проявлял её бессловесно."],[18,"Благодарность не есть и простое признание чужого благодеяния, ибо озлобленное сердце сопровождает такое признание чувством обиды, унижения или даже жаждою мести."],[19,"Нет, настоящая благодарность есть радость и любовь и в дальнейшем — потребность ответить добром на добро."],[20,"Эта радость вспыхивает сама, свободно и ведёт за собою любовь — свободную, искреннюю."],[21,"Дар есть зов, взывающий к доброму ответу."],[22,"Дар есть луч, требующий ответного излучения."]],"a":[20],"why":"Указанная связь есть между предложениями 19 и 20.","verifiedBy":"ключ источника"},{"id":"R9198","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 6−11 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":6,"hi":11,"s":[[6,"Дедушка, однажды наш класс убежал с урока, потом Димка рассказал об этом Маргарите Ивановне, и она наказала нас: мы не поехали в Москву."],[7,"Вот сидим мы в классе, наблюдая, как уезжает автобус без нас, и вдруг... −"],[8,"«А я знаю, кто предатель!» − вдруг говорит Миронова."],[9,"Ну, решила я, сейчас Миронова бабахнет про Димку."],[10,"Заметалась я, засуетилась, посмотрела на Димку и не узнала!"],[11,"Он стоял передо мной каким-то зелёным лунатиком − глаза у него из синих стали белыми."]],"a":[11],"why":"Предложение 11 связано с предыдущим с помощью личного местоимения ОН.","verifiedBy":"ключ источника"},{"id":"R51004","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 4–10 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":4,"hi":10,"s":[[4,"Жизнь — это путь."],[5,"Для того, кто хочет пройти его в угоду себе, он тёмен и неведом, ненадёжен, как игрушка в руках безрассудной фортуны."],[6,"Но для того, кто жизнь видит в служении своей Отчизне, этот путь наполнен особенным, непостижимым для прочих смыслом."],[7,"К общей цели его ведёт сама Россия."],[8,"Её живая душа станет верной советчицей в сомнениях, надёжной попутчицей в долгих странствиях, нежной утешительницей в горе, трудолюбивой помощницей в деяниях, мужественной соратницей в борьбе и битве."],[9,"Судьба великих сынов России всегда была открыта и ясна, потому что она кровно связана с судьбой народа, и биография каждого героя всегда совпадает с биографией его страны."],[10,"Самой жизнью уготовано им жить одной судьбой, разделять со страной её радость и скорбь."]],"a":[8],"why":"Указанное средство связи есть между предложениями 7 и 8.","verifiedBy":"ключ источника"},{"id":"R51014","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 53–59 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного и притяжательного местоимений. Напишите номер(-а) этого(-их) предложения(-ий).","lo":53,"hi":59,"s":[[53,"А под ивой за корягой жили налимы, их можно было нащупать тами толкнуть рукой."],[54,"А на реке пахло брёвнами, дымком от шалашей плотогонов, пахло тиной и ряской, пахло осиной старое корыто, на котором они по очереди плавали по реке."],[55,"Запахи эти ожили, дохнули из глубины картины."],[56,"Запах горячих от солнца чугунных столбов, старого причала."],[57,"К Лосеву вернулся тот огромный мальчишеский мир, шелестела листва, была жива ещё мать."],[58,"Он ощутил на голове её маленькую жёсткую руку."],[59,"Было чудо, что художник поймал и заключил навечно в эту белую рамку его, Лосева, воспоминание — со всеми красками, запахами, теплотой."]],"a":[58],"why":"Указанное средство связи есть между предложениями 57 и 58.","verifiedBy":"ключ источника"},{"id":"R51019","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 24–32 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи лексического повтора, личного местоимения и однокоренных слов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":24,"hi":32,"s":[[24,"Удивительная работа воспоминания."],[25,"Мы вспоминаем нечто по совершенно неизвестной нам причине."],[26,"Скажите себе: «Вот сейчас я вспомню что-нибудь из детства», закройте глаза и скажите это."],[27,"Вспомнится нечто совершенно непредвиденное вами."],[28,"Участие воли здесь исключено."],[29,"Картина зажигается, включённая какими-то инженерами позади вашего сознания."],[30,"Какая чудесная вещь — свобода воспоминаний!"],[31,"Какая прелесть в том, что они появляются, как им угодно, и никак мы не можем заставить себя вспомнить именно это, а не другое."],[32,"Разумеется, есть точная закономерность этого возникновения, но —дудки — мы её никогда не поймём."]],"a":[31],"why":"Указанная связь есть между предложениями 30 и 31:","verifiedBy":"ключ источника"},{"id":"R51024","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 11–18 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью указательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":11,"hi":18,"s":[[11,"В каждой стране есть свой Главный педагог — народ и есть Главный учебник — язык."],[12,"Я не должен объяснять, что такое счастье, я должен смиренно спросить об этом наш язык — в нём всё есть, из него всё поймёшь, прислушиваясь к слову в сегодняшней нашей речи."],[13,"Народная мысль содержится не только в пословицах и поговорках, в народной мудрости, но и в распространённых, обычных фразах и оборотах речи."],[14,"Поищем: с какими другими словами сочетается интересующее нас понятие, почему так можно сказать, а так нельзя."],[15,"Это никогда не бывает случайным."],[16,"Мы говорим: «счастливая доля», «счастливый случай», «счастливая судьба», «счастье привалило», «вытянул счастливый билет»."],[17,"Самые деятельные, всего достигшие своим трудом люди говорят: «Мне выпало счастье, мне дано счастье...»"],[18,"Счастье — фортуна, судьба, о которой мы ничего не знаем, и если его нет, то говорят: «Такая уж у меня судьба», «Видно, мне так на роду написано»."]],"a":[15],"why":"Указанное средство связи есть между предложениями 14 и 15.","verifiedBy":"ключ источника"},{"id":"R51029","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 33–41 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью союза и форм слова. Напишите номер(а) этого(-их) предложения(-ий).","lo":33,"hi":41,"s":[[33,"Расстреляв все диски, он спокойно подтаскивал к себе ящики с ручными гранатами и, прищурившись, кидал их одну за другой, пока немцы не отступали…"],[34,"Среди людей часто попадаются храбрецы."],[35,"Но только сознательная и страстная любовь к Родине может сделать из храбреца героя."],[36,"Ковалёв был истинный герой."],[37,"Он страстно, но очень спокойно любил Родину и ненавидел всех её врагов."],[38,"Командование неоднократно выдвигало Ковалёва на более высокую должность."],[39,"Но каждый раз он просил оставить его наводчиком и не разлучать с орудием."],[40,"— Наводчик — это моё настоящее дело, — говорил Ковалёв, — с другими обязанностями я так хорошо не справлюсь, уж вы мне поверьте, за чинами я не гонюсь."],[41,"Тогда был наводчиком и теперь до конца войны хочу быть наводчиком."]],"a":[35],"why":"Указанное средство связи есть между предложениями 34 и 35.","verifiedBy":"ключ источника"},{"id":"R51037","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 20–27 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью союза и притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-й).","lo":20,"hi":27,"s":[[20,"Знаменитое «Не верю!» Станиславского проникает сейчас во все жанры и виды искусства."],[21,"И если в кино динамика кадра и лихость сюжета могут отвлечь внимание зрителя от нестыковок и откровенной фальши, то печатное слово сразу выталкивает на поверхность всякое враньё, всё, что написано ради красного словца, высосано из пальца."],[22,"Воистину написанное пером не вырубишь топором."],[23,"Проверяя читательский багаж прошлых лет, прихожу к выводу, что я всегда неосознанно тянулся к авторам, которые не только отмечены писательским талантом, но и обладают выдающейся личной историей."],[24,"Биографией, как тогда говорили."],[25,"В советское время информация о личной жизни популярных авторов была дозированной, а порой и недоступной, о пиаре тогда никто и не догадывался."],[26,"Но крупицы их дел и поступков были у всех на слуху, оживляли образ и увеличивали наши симпатии и степень доверия."],[27,"Так было с Маяковским, так было с Высоцким и Визбором, с Солженицыным и Шаламовым."]],"a":[26],"why":"Указанное средство связи есть между предложениями 25 и 26.","verifiedBy":"ключ источника"},{"id":"R51042","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 27–34 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения, форм слова и контекстных синонимов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":27,"hi":34,"s":[[27,"Старшина распахнул плащ-палатку, и хлеб был встречен почтительным молчанием."],[28,"В этой-то почтительной тишине и раздался вопрос."],[29,"— А где?.."],[30,"Тут полбуханка была!"],[31,"Произошло лёгкое движение, тёмные лица повернулись ко мне, со всех сторон — глаза, глаза, жуткая насторожённость в них."],[32,"— Эй ты!"],[33,"Где?!"],[34,"Тебя спрашиваю!"]],"a":[28],"why":"Указанное средство связи есть между предложениями 27 и 28.","verifiedBy":"ключ источника"},{"id":"R51047","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 32–42 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим(-ими) с помощью притяжательного местоимения и однокоренных слов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":32,"hi":42,"s":[[32,"Позже я узнал её и в переплёте: «Детство», «Отрочество», «Юность» Льва Николаевича Толстого."],[33,"Вот так Толстой вошёл в мою жизнь, не представившись."],[34,"Иллюзия узнавания — непременная особенность классических текстов."],[35,"Их авторы — классики, потому что пишут для всех."],[36,"Это верно."],[37,"Но они ещё и потому вечные классики, что пишут для каждого."],[38,"Это верно в не меньшей степени."],[39,"Юный простак, я «купился» именно на последнее."],[40,"Эксперимент был проведён чисто: автора скрыли."],[41,"Магия имени не довлела над восприятием текста."],[42,"Текст сам отстоял своё величие."]],"a":[35],"why":"Указанное средство связи есть между предложениями 34 и 35.","verifiedBy":"ключ источника"},{"id":"R51052","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1–7 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью однокоренных слов и форм слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":7,"s":[[1,"С перебитой ногой я лежал у окна санитарного поезда спиной к движению."],[2,"Уходящая местность открывалась передо мной, и поэтому я увидел эти три танка, когда мы уже прошли мимо них."],[3,"Открыв люки, танкисты смотрели на нас."],[4,"Они были без шлемов, и мы приняли их за своих."],[5,"Потом люки закрылись, и это была последняя минута, когда ещё невозможно было предположить, что по санитарному эшелону, в котором находилось, вероятно, не меньше тысячи раненых, другие, здоровые люди могут стрелять из пушек."],[6,"Но именно это и произошло."],[7,"С железным скрежетом сдвинулись вагоны, меня подбросило, и я невольно застонал, навалившись на раненую ногу."]],"a":[3],"why":"Указанное средство связи есть между предложениями 2 и 3.","verifiedBy":"ключ источника"},{"id":"R51057","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 33–38 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения и форм слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":33,"hi":38,"s":[[33,"В двух километрах от реки на обочине дороги я увидел фанерный щит, рябой от дождя, с лозунгом: «Доярки, выполняйте среднефермские обязательства надоя!»"],[34,"Солнце вторично погасло в тихом и, казалось, обиженном небе."],[35,"Чтобы прийти в себя и избежать дальнейших возможных огорчений, я ушёл на Старицу и заночевал там на берегу, в старом шалаше под непроглядной сенью ив."],[36,"Я лежал на старом сене и почти всю ночь напролёт вспоминал стихи разных наших поэтов."],[37,"Это вернуло мне веру в могущество русского языка, в то, что ничто не сможет убить его, как нельзя убить звёзды, воздух, великую душу народа."],[38,"Русский язык принёс нам из далёких времён редкий подарок — «Слово о полку Игореве», степную ширь и горечь, трепет синих зарниц, звоны мечей."]],"a":[37],"why":"Указанное средство связи есть между предложениями 36 и 37.","verifiedBy":"ключ источника"},{"id":"R51062","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 22–26 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи лексического повтора. Напишите номер(-а) этого(-их) предложения(-ий).","lo":22,"hi":26,"s":[[22,"По ночам всё чаще и чаще слышу всхлипы собственного сердца: оно уморилось."],[23,"Устало болеть."],[24,"Я стал седым, и мне порой уступают место в общественном транспорте."],[25,"Уступают юноши и девушки, очень похожие на вас, ребята."],[26,"И тогда я думаю, что не дай им Бог повторить вашу судьбу."]],"a":[25],"why":"Указанное средство связи есть между предложениями 24 и 25.","verifiedBy":"ключ источника"},{"id":"R51067","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 36–41 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи сочинительного союза, лексического повтора и однокоренных слов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":36,"hi":41,"s":[[36,"Александр Блок написал в давние тяжёлые годы: Россия, нищая Россия, Мне избы серые твои, Твои мне песни ветровые — Как слёзы первые любви!"],[37,"Блок был прав, конечно."],[38,"Особенно в своём сравнении."],[39,"Потому что нет ничего человечнее слёз от любви, нет ничего, что бы так сильно и сладко разрывало сердце."],[40,"И нет ничего омерзительнее, чем равнодушие человека к своей стране, её прошлому, настоящему и будущему, к её языку, быту, к её лесам и полям, к её селениям и людям, будь они гении или деревенские сапожники."],[41,"В те годы, во время службы моей на санитарном поезде, я впервые ощутил себя русским до последней прожилки."]],"a":[40],"why":"Указанное средство связи есть между предложениями 39 и 40.","verifiedBy":"ключ источника"},{"id":"R51072","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 5–10 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза и однокоренных слов. Напишите номер(а) этого(-их) предложения(-ий).","lo":5,"hi":10,"s":[[5,"Комнаты были прохладные, полы крашеные, чисто вымытые, а в раскрытые окна бежал ветер."],[6,"И теперь, когда Андрей стал взрослым, каждая новая весна несла ему эти незабываемые запахи его детства — земли, травы, ветра."],[7,"Всё в мире открывала Андрею мать."],[8,"«Послушай, как тихо», — говорила она."],[9,"И он понял, что тишину можно слушать."],[10,"«Не зажигай света, посидим так», — просила она."]],"a":[9],"why":"Указанное средство связи есть между предложениями 8 и 9.","verifiedBy":"ключ источника"},{"id":"R51080","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 5–11 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью форм слов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":5,"hi":11,"s":[[5,"Идти предстояло вдоль берега."],[6,"После утреннего дождя земля ещё не просохла, и на тропке были хорошо видны уходившие в лес следы."],[7,"Впереди были заросли."],[8,"Школенко пополз через них налево; там виднелась яма, кругом неё рос бурьян."],[9,"Из ямы, в просвете между кустами бурьяна, был виден стоявший совсем близко миномёт и на несколько шагов подальше — ручной пулемёт: один немец стоял у миномёта, а шестеро сидели, собравшись в кружок, и ели из котелков."],[10,"Торопиться было незачем: цель была на виду."],[11,"Он прочно упёрся левой рукой в дно ямы, вцепился в землю так, чтобы рука не скользнула, и, приподнявшись, швырнул гранату."]],"a":[9],"why":"Указанное средство связи есть между предложениями 8 и 9.","verifiedBy":"ключ источника"},{"id":"R51085","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1–8 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью форм слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":8,"s":[[1,"В солнечный день я приехал в старинный посёлок Гусь-Железный полюбоваться на озеро, искупаться, поплавать в нём."],[2,"Доехал до речки, поднялся на бугор, глянул и..."],[3,"О ужас!"],[4,"Нет озера."],[5,"По широкой впадине, окаймлённой дальней опушкой бывшего прибрежного леса, текла, извиваясь, узкая, местами пересыхающая речушка."],[6,"И старинной плотины, высокой, кирпичной, с чугунными шлюзами, в тёмных казематах которой, по преданию, разбойная братия чеканила фальшивые деньги, тоже не было."],[7,"Шлюзы, регулировавшие сток, убрали, засыпали — и затянуло озеро тиной да ряской."],[8,"На месте этом проходила теперь обыкновенная дорожная насыпь; дорога делала крутой поворот, огибала белый двухэтажный барский дом, похожий на длинную казарму, заломанный чахлый парк и снова вырывалась на простор."]],"a":[7],"why":"Указанное средство связи есть между предложениями 6 и 7.","verifiedBy":"ключ источника"},{"id":"R51090","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 5–9 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью личного местоимения и однокоренных слов. Напишите номер(а) этого(-их) предложения(-ий).","lo":5,"hi":9,"s":[[5,"Для Радищева высшая радость, как известно, состояла в том, чтобы «соучастником быть во благоденствие себе подобных»."],[6,"И вот эти самые, казалось бы, музейно-величавые слова я услышал однажды от детского хирурга, доктора медицинских наук В. И. Францева, и относились они не к легендарной, отдалённой от нас столетиями личности, а к рабочему-лекальщику Сергею Степановичу Павлову."],[7,"Он создал уникальный хирургический инструмент, помогающий при операциях на сердце, — инструмент, который до этого хорошо делали только в Англии, где мы и покупали его."],[8,"Размеры инструмента, его суть Павлов узнал от инженера, сына которого оперировали в одной из московских клиник."],[9,"Павлов работал над инструментом вечерами и по выходным дням в течение ряда лет."]],"a":[7],"why":"Указанная связь есть между предложениями 6 и 7.","verifiedBy":"ключ источника"},{"id":"R51095","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 21–27 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":21,"hi":27,"s":[[21,"Образы природы сопровождают людей с самой глубокой древности."],[22,"Сцены охоты древние люди оставили нам в наследство на стенах пещер, на камнях в виде скупых царапин, изображающих лосей, кабанов, туров."],[23,"Нынешняя техника даёт возможность увидеть зверей и птиц в естественных красках и обстановке."],[24,"Мы видим эпизоды их жизни, и в душе появляется тёплое чувство."],[25,"Они где-то есть, эти звери, они ещё бегают, рычат, прячутся или проявляют, как и мы, люди, любопытство…"],[26,"Желая испытать это тёплое чувство, на городских этажах мы держим кошек, собак, попугаев, белок, рыбок в аквариуме."],[27,"Врачи говорят, что поглаживание кошки или кормление синицы с ладони целительны для человеческой психики."]],"a":[24],"why":"Указанная связь есть между предложениями 23 и 24.","verifiedBy":"ключ источника"},{"id":"R51100","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1–10 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(а) этого(-их) предложения(-ий).","lo":1,"hi":10,"s":[[1,"И всё-таки у Природы как целого, как единого творца есть свои любимцы, в которые она при строительстве вкладывает особенное старание, которые отделывает с особенным тщанием и наделяет особенной властью."],[2,"Таков, вне всякого сомнения, и Байкал."],[3,"Не зря его называют жемчужиной Сибири."],[4,"Не будем сейчас говорить о его богатствах, это отдельный разговор."],[5,"Байкал славен и свят другим: своей чудесной животворной силой, духом не былого, не прошедшего, как многое ныне, а настоящего, неподвластного времени и преобразованиям, исконного величия и заповедного могущества, духом самородной воли и притягательных испытаний."],[6,"Вспоминаю, как мы с товарищем моим, приехавшим ко мне в гости, долго шли и далеко ушли вдоль берега по старой Кругобайкальской дороге, одному из самых красивых и ярких мест южного Байкала."],[7,"Был август – лучшее, самое благодатное время на Байкале, когда нагревается вода и бушуют разноцветьем сопки, когда, кажется, даже камень цветёт, полыхая красками."],[8,"Когда солнце до блеска высвечивает снова выпавший снег на дальних гольцах в Саянах, которые представляются глазу во много раз ближе, чем они есть в действительности."],[9,"Когда уже и впрок запасся Байкал водой из тающих ледников и лежит сыто, спокойно, набираясь сил для осенних штормов."],[10,"Когда щедро играет подле берега под крики чаек рыба и когда на каждом шагу по дороге встречается то одна ягода, то другая – то малина, то смородина, красная и чёрная, то жимолость..."]],"a":[3],"why":"Указанная связь есть между предложениями 2 и 3.","verifiedBy":"ключ источника"},{"id":"R51105","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 7–15 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью форм слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":7,"hi":15,"s":[[7,"Саня приказал Щербаку отъехать в сторону и открыть огонь."],[8,"Саня, в сущности, плохо понимал, что происходит."],[9,"Комбат приказал не вырываться вперёд и двигаться за танками в ста метрах."],[10,"Щербак же повис на хвосте впереди идущей машины."],[11,"Тридцатьчетвёрка шла зигзагами, стреляя на ходу."],[12,"За ней тоже зигзагами вёл самоходку Щербак."],[13,"Саня не видел поля боя: мешала тридцатьчетвёрка."],[14,"Он приказал Щербаку отстать или свернуть в сторону."],[15,"Щербак, не ответив, продолжал плестись за танком."]],"a":[15],"why":"Указанная связь есть между предложениями 14 и 15.","verifiedBy":"ключ источника"},{"id":"R51110","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 7–10 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Запишите номер(а) этого(-их) предложения(-ий).","lo":7,"hi":10,"s":[[7,"Бывалого человека, меня и теперь радостно волнуют, неудержимо притягивают обширные просторы родной русской природы."],[8,"Люди, не порывающие связи с природой, не могут почувствовать себя вполне одинокими."],[9,"Как в мечтательном детстве, по-прежнему раскрыт перед ними прекрасный солнечный мир."],[10,"И, как в далёкие дни детства, над головою усталого путника, прилёгшего отдохнуть после утомительного похода, колышутся белые и золотые цветы, а высоко в небе кружит, высматривая добычу, ястреб."]],"a":[9],"why":"Указанное средство связи есть между предложениями 8 и 9.","verifiedBy":"ключ источника"},{"id":"R51115","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 39–44 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью лексического повтора и указательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":39,"hi":44,"s":[[39,"Голос страстей может быть громче голоса совести, но голос страстей совсем другой, чем тот спокойный и упорный голос, которым говорит совесть."],[40,"И как ни громко кричат страсти, они всё-таки робеют перед тихим, спокойным и упорным голосом совести."],[41,"Голосом этим говорит то вечное, что живёт в человеке."],[42,"Философ И. Кант говорил, что две вещи больше всего удивляют его."],[43,"Одно — это звёзды на небе, а другое — это закон добра в душе человека."],[44,"Истинное доброе в тебе самом, в твоей душе!"]],"a":[41],"why":"Указанное средство связи есть между предложениями 40 и 41.","verifiedBy":"ключ источника"},{"id":"R51120","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 36–45 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":36,"hi":45,"s":[[36,"В самом деле, давайте проведём нового человека, ну хоть парижанина или будапештца, по улице Тверской, по главной улице Москвы."],[37,"Чем поразим его воображение, какой такой жемчужиной зодчества?"],[38,"Каким таким свидетелем старины?"],[39,"Вот телеграф."],[40,"Вот гостиница."],[41,"Вот дом на углу Тверского бульвара, где кондитерский магазин."],[42,"Видели парижанин и будапештец подобные дома."],[43,"Ещё и получше."],[44,"Ничего не говорю."],[45,"Хорошие, добротные дома, но всё же интересны не они, а именно памятники: Кремль, Коломенское, Андроников монастырь."]],"a":[37],"why":"Указанное средство связи есть между предложениями 36 и 37.","verifiedBy":"ключ источника"},{"id":"R51125","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 38–49 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью личного местоимения и формы слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":38,"hi":49,"s":[[38,"— Ты погоди…"],[39,"Сразу-то не верь."],[40,"Ты погоди…"],[41,"Похоронки-то кто пишет?"],[42,"Писари."],[43,"А они при штабах, там бумаг страсть сколько…"],[44,"Вот и попутали."],[45,"А Евгения Ивановна со стоном перекатывалась лбом по столу, волосы рассыпались, липли к мокрым щекам."],[46,"Вдруг она оторвала голову от стола и замерла, вроде к чему-то прислушиваясь."],[47,"Пошарила в карманах ватника, вытащила бумагу, всхлипнула, подала Нине."],[48,"Нина прочитала."],[49,"Эта бумага была из военкомата, в ней значилось, что рядовой Завалов Николай Артамонович погиб в декабре 1941 года, а младший сержант Николай Николаевич с ноября 1941 года числится в пропавших без вести."]],"a":[46],"why":"Указанное средство связи есть между предложениями 45 и 46.","verifiedBy":"ключ источника"},{"id":"R51130","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 24–29 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью указательного местоимения, форм слова и синонимов. Напишите номер(а) этого(-их) предложения(-ий).","lo":24,"hi":29,"s":[[24,"Я не бичую себя, потому что тогда непременно начнёшь лгать и преувеличивать; но в этом-то нужно сознаться, — что такое настроение мало способствует уважению к себе."],[25,"Заглянешь в душу, — так там холодно и темно, так гадко-жалок этот бессильный страх перед окружающим!"],[26,"И кажется тебе, что никто никогда не переживал ничего подобного, что ты какой-то странный урод, выброшенный на свет теперешним странным, неопределённым временем…"],[27,"Тяжело жить так."],[28,"Меня спасала только работа; а работы мне, как земскому врачу, было много, особенно в последний год, — работы тяжёлой и ответственной."],[29,"Этого мне и нужно было; всем существом отдаться делу, совершенно забывая свои страхи, — вот была моя цель, смысл жизни."]],"a":[29],"why":"Указанное средство связи есть между предложениями 28 и 29.","verifiedBy":"ключ источника"},{"id":"R51135","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 3–11 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения и форм слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":3,"hi":11,"s":[[3,"Старые знакомые часто говорят матери: − Дима стал очень похож на отца."],[4,"Вылитый Пётр Андреевич!"],[5,"Вадиму приятно это слышать: ему хочется быть похожим на отца."],[6,"А Вера Фадеевна, улыбаясь грустно и сдержанно, отвечает: − Да, много общего есть…"],[7,"Отец погиб в начале войны, в декабре сорок первого года."],[8,"Это была его третья война, хотя профессия у отца была самая мирная − учитель."],[9,"Последние пятнадцать лет он работал директором школы."],[10,"И‚ когда отец вместе с другими ополченцами уезжал на фронт − это было в июле, на Белорусском вокзале, − провожать его пришло много учителей и школьной молодёжи."],[11,"Они стояли вокруг отца шумной, тесной толпой, говорили, перебивая друг друга, тёплые прощальные слова, а завуч, седенькая старушка в очках, даже всплакнула, и отцу пришлось утешать её."]],"a":[11],"why":"Указанное средство связи есть между предложениями 10 и 11.","verifiedBy":"ключ источника"},{"id":"R51140","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1–7 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью лексического повтора. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":7,"s":[[1,"Хотя лейтенанта Володина тошнило и голова его была как свинцом налита, хотя он чувствовал страшную слабость, у него подкашивались ноги и руки были словно чужие, он шёл сейчас к своему взводу, к селу, к позициям, где ещё гремел бой."],[2,"Шёл, чтобы выполнить солдатский долг."],[3,"За пылью, поднятой артиллерийскими снарядами, были едва видны крайние соломкинские избы."],[4,"Разрывы метались по полю, вспыхивали справа и слева вдоль шоссе, и между разрывами, лавируя, пробивались два «виллиса»."],[5,"Наконец «виллисы» вышли из-под обстрела и неожиданно оказались так близко, что он отчётливо увидел даже лица сидевших за ветровым стеклом."],[6,"Он сразу узнал генерал-лейтенанта, члена Военного совета Воронежского фронта, который вчера вместе с командующим осматривал оборонительные сооружения в Соломках."],[7,"Володин спохватился, хотел было отойти на обочину, но было уже поздно, передний «виллис», скрипнув тормозами, остановился прямо напротив него."]],"a":[2,6],"why":"Указанное средство связи есть между предложениями 1 и 2:","verifiedBy":"ключ источника"},{"id":"R51145","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 18–23 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":18,"hi":23,"s":[[18,"Операция шла долго."],[19,"Хирургу не раз вытирали потный лоб."],[20,"Больной лежал в забытьи под действием наркоза."],[21,"В вену его руки медленно, капля за каплей, вливалась живительная жидкость."],[22,"А Прасковья Андреевна, измученная бессонной ночью и плохими мыслями, уже сидела в вестибюле больницы."],[23,"После окончания операции хирург огорчил её: — Не стану скрывать: положение серьёзное, хотя сделано всё, что в наших силах."]],"a":[21],"why":"Указанное средство связи есть между предложениями 20 и 21.","verifiedBy":"ключ источника"},{"id":"R51150","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 17–21 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью союза. Напишите номер(-а) этого(-их) предложения(-ий).","lo":17,"hi":21,"s":[[17,"Принято считать, что телеграф, телефон, поезда, автомобили и лайнеры призваны экономить человеку его драгоценное время, высвобождать досуг, который можно употребить для развития своих духовных способностей."],[18,"Но произошёл удивительный парадокс."],[19,"Можем ли мы положа руку на сердце сказать, что времени у каждого из нас, пользующегося услугами техники, больше, чем его было у людей дотелефонной, дотелеграфной, доавиационной поры?"],[20,"Да боже мой!"],[21,"У каждого, кто жил тогда в относительном достатке (а мы все живём теперь в относительном достатке), времени было во много раз больше, хотя каждый тратил тогда на дорогу из города в город неделю, а то и месяц вместо наших двух-трёх часов."]],"a":[18],"why":"Указанное средство связи есть между предложениями 17 и 18.","verifiedBy":"ключ источника"},{"id":"R51155","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1–9 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения и форм слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":9,"s":[[1,"Утро следующего дня было холодным и пасмурным."],[2,"Услышав голос Андрея Ивановича, Наташа, как всегда, попыталась встать с постели, но едва она приподнялась, как голова её закружилась, и она снова неловко опустилась на землю."],[3,"Всё тело болело."],[4,"Сильная тошнота подступала к горлу. «"],[5,"Встать бы только!"],[6,"Только подняться бы на ноги!» — мысленно твердила девушка, проклиная свою слабость."],[7,"Она слышала, как легко и быстро поднялся Валерий."],[8,"Он даже насвистывал что-то."],[9,"Почему же у неё так кружится голова?"]],"a":[7],"why":"Указанное средство связи есть между предложениями 6 и 7.","verifiedBy":"ключ источника"},{"id":"R51160","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 24–30 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":24,"hi":30,"s":[[24,"Давно замечено: и лучшие, и худшие стороны человека выявляет беда."],[25,"Януш Корчак не только последние часы и минуты своего бытия, когда вместе с детьми принял мученическую смерть в фашистской газовой камере, но и всю предыдущую жизнь стоял рядом с бедой, точнее, жил в её гуще, работая с детьми-сиротами."],[26,"Сиротство, эта библейски древняя форма человеческого одиночества, требует сострадания и соучастия, самоотверженной и терпеливой любви настоящих гуманистов."],[27,"Януш Корчак первый из них, и первенство это измерено мерой его выбора, мерой честности."],[28,"Мера эта − смерть."],[29,"Не только поляки чтут выбор своего бессмертного учителя."],[30,"Его имя внесено в святцы и мировой педагогики, и элементарной человеческой порядочности."]],"a":[30],"why":"Указанное средство связи есть между предложениями 29 и 30.","verifiedBy":"ключ источника"},{"id":"R51165","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 19–25 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим(-ими) с помощью союза и притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":19,"hi":25,"s":[[19,"Третьяков посмотрел ему вслед, на один его сапог и на деревяшку."],[20,"Что ему объяснишь?"],[21,"Не приставишь оторванную ногу и не объяснишь."],[22,"А самое главное, что и себе не всё объяснишь."],[23,"В школе со слов учителей он знал, как и почему возникают войны, и успешно отвечал на отметку."],[24,"И их неизбежность при определённых условиях тоже была объяснима и проста."],[25,"Но тому, что он повидал за эти годы, не было лёгких объяснений."]],"a":[24],"why":"Указанное средство связи есть между предложениями 23 и 24.","verifiedBy":"ключ источника"},{"id":"R51170","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 24–28 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи лексического(-их) повтора(-ов). Напишите номер(-а) этого(-их) предложения(-ий).","lo":24,"hi":28,"s":[[24,"Однажды вместе с нашими ранеными ко мне в вагон внесли длинного, как жердь, австрийца в серых обмотках."],[25,"Он был ранен в горло и лежал, хрипя и поводя жёлтыми глазами."],[26,"Когда я проходил мимо, он пошевелил смуглой рукой."],[27,"Я думал, что он просит пить, нагнулся к его небритому, обтянутому пересохшей кожей лицу и услышал клекочущий шёпот: — Есмь славянин!"],[28,"Полонённый у велика-велика битва... брат мой."]],"a":[26,27],"why":"Указанное средство связи есть между предложениями 25 и 26.","verifiedBy":"ключ источника"},{"id":"R51175","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 11–19 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения и лексического повтора. Напишите номер(-а) этого(-их) предложения(-ий).","lo":11,"hi":19,"s":[[11,"«Может быть, у них тоже война, — думает Родимцев, — вот и ползут колонны мобилизованных на строительство рвов и укреплений."],[12,"Или это хозяин ставит себе новый дом, и тянутся плотники, штукатуры на работу…»"],[13,"Огромен мир, который видят его глаза, чует ухо, втягивают с воздухом ноздри."],[14,"Аршин земли на опушке леса, куст шиповника."],[15,"Как велик этот аршин земли!"],[16,"Как богат этот отцветший куст!"],[17,"По сухой земле молнией прошла трещина, муравьи проходят по мосту, в строгом порядке один за другим, а по ту сторону трещины терпеливо выжидают встречные."],[18,"Божья коровка, толстая, в красном сарафане, мечется, ищет перехода."],[19,"Ох ты!"]],"a":[15],"why":"Указанное средство связи есть между предложениями 14 и 15.","verifiedBy":"ключ источника"},{"id":"R51180","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1–7 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи определительного и указательного местоимений, формы слова и контекстных синонимов. Напишите номер(а) этого(-их) предложения(-ий).","lo":1,"hi":7,"s":[[1,"Нам лишь кажется, что, когда с нами что-то случается, это уникальное явление, единственное в своём роде."],[2,"На самом деле нет ни одной проблемы, которая уже не была бы отражена в мировой литературе: любовь, верность, ревность, измена, трусость, поиски смысла жизни…"],[3,"Всё это уже когда-то кем-то было пережито, передумано; найдены причины, ответы и советы и запечатлены на страницах художественной литературы."],[4,"Дело за малым: бери и читай!"],[5,"И всё найдёшь в книге."],[6,"Неслучайно Ф. М. Достоевский призывал: «Читайте!"],[7,"А остальное сделает жизнь»."]],"a":[3],"why":"Указанное средство связи есть между предложениями 2 и 3.","verifiedBy":"ключ источника"},{"id":"R54110","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1−4 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи форм слова. Запишите номер(а) этого(-их) предложения(-ий).","lo":1,"hi":4,"s":[[1,"Одно из забавных свойств человеческой природы заключается в том, что каждый человек стремится доигрывать собственный образ, навязанный ему окружающими людьми."],[2,"Иной пищит, а доигрывает."],[3,"Вот пример."],[4,"Однажды, когда я учился в школе, мы всем классом работали на одном пустыре, стараясь превратить его в место для культурного отдыха."]],"a":[2],"why":"Указанная связь есть между предложениями 1 и 2. Слово повторяется в разных формах в рядом стоящих предложениях.","verifiedBy":"ключ источника"},{"id":"R5307","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 4–8 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения и лексического повтора. Напишите номер(-а) этого(-их) предложения(-ий).","lo":4,"hi":8,"s":[[4,"Если нас связывают дом, дача, деньги, внешняя привлекательность или любые другие краткосрочные вещи, которые сегодня есть, а завтра нет, то с первыми же проблемами в этой сфере будут поставлены под угрозу и наши взаимоотношения."],[5,"Связи, в которых людей уже ничего не объединяет, похожи на потёмкинские деревни, где внешне всё нормально, но за красивым фасадом — одни проблемы и пустота."],[6,"Часто такие формальные связи хуже одиночества."],[7,"Людей объединяют совместно пережитые трудности и кризисные моменты."],[8,"Если в преодолении препятствий, в поиске решений все стороны в одинаковой мере прилагают усилия и сражаются за то, чтобы стало лучше, это не только укрепляет любые отношения, но и рождает новые, более глубокие, удивительные состояния души, открывающие новые горизонты и направляющие развитие событий в совсем иное русло."]],"a":[6],"why":"Предложение 6 связано с предыдущим при помощи указательного местоимения ТАКИЕ и лексического повтора слова СВЯЗИ.","verifiedBy":"выведено из пояснения"},{"id":"R7449","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1–8 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":8,"s":[[1,"Василий Конаков, или просто Вася, как звали мы его в полку, был командиром пятой роты."],[2,"Участок его обороны находился у самого подножия Мамаева кургана, господствующей над городом высоты, за овладение которой в течение всех пяти месяцев шли наиболее кровавые бои."],[3,"Участок был трудный, абсолютно ровный, ничем не защищённый, а главное, с отвратительными подходами, насквозь простреливавшимися противником."],[4,"Днём пятая рота была фактически отрезана от остального полка."],[5,"Снабжение и связь с тылом происходили только ночью."],[6,"Всё это очень осложняло оборону участка."],[7,"Надо было что-то предпринимать."],[8,"И Конаков решил сделать ход сообщения между своими окопами и железнодорожной насыпью."]],"a":[2],"why":"Предложение 2 связано с предыдущим с помощью притяжательного местоимения ЕГО.","verifiedBy":"ключ источника"},{"id":"R9905","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 28—34 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза и личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":28,"hi":34,"s":[[28,"Старик часто сидел на террасе в шезлонге, обложенный подушками, укутанный пледами, бледный, бородатый, всегда молчал и, если кто проходил мимо, отворачивался и закрывал глаза."],[29,"Вокруг старика, как трепетная птица, вилась его жена."],[30,"Женщина немолодая, сухая, лёгкая, с увядшим лицом и тревожно-счастливыми глазами."],[31,"И никогда она не сидела спокойно."],[32,"Всё что-то поправляла около своего больного."],[33,"То переворачивала газету, то взбивала подушку, то подтыкала плед, то бежала греть молоко, то капала лекарство."],[34,"Все эти услуги старик принимал с явным отвращением."]],"a":[31],"why":"Предложение 31 «И никогда она не сидела спокойно» связано с предыдущим с помощью личного местоимения ОНА и союза И.","verifiedBy":"ключ источника"},{"id":"R10001","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 34–42 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения и лексического повтора. Напишите номер(-а) этого(-их) предложения(-ий).","lo":34,"hi":42,"s":[[34,"Слова «это сделал я» не грозят ему смертью."],[35,"Почему же он боится их произнести?"],[36,"Я слышала, как очень храбрый человек, прошедший войну, сказал однажды: «Бывало страшно, очень страшно»."],[37,"Он говорил правду: ему бывало страшно."],[38,"Но он умел преодолеть свой страх и делал то, что велел ему долг: он сражался."],[39,"В мирной жизни, конечно, тоже может быть страшно."],[40,"Я скажу правду, а меня за это исключат из школы..."],[41,"Скажу правду – уволят с работы..."],[42,"Уж лучше промолчу."]],"a":[37],"why":"Предложение 37 связано с предыдущим с помощью лексического повтора «страшно» и личного местоимения «он».","verifiedBy":"ключ источника"},{"id":"R10838","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1–6 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":6,"s":[[1,"Иногда к дяде Коле приходил в гости сельский аптекарь."],[2,"Звали этого аптекаря Лазарем Борисовичем."],[3,"С первого взгляда это был довольно странный аптекарь."],[4,"Он носил студенческую тужурку."],[5,"На его широком носу едва держалось пенсне на чёрной тесёмочке."],[6,"Аптекарь был низенький, коренастый и очень язвительный человек."]],"a":[5],"why":"(4)Он носил студенческую тужурку. (5)На его широком носу едва держалось пенсне на чёрной тесёмочке. Притяжательное местоимение его в предложении 5 относится к слову он в предложении 4.","verifiedBy":"ключ источника"},{"id":"R12365","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1–7 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":7,"s":[[1,"Счастливая, счастливая, невозвратимая пора детства!"],[2,"Как не любить, не лелеять воспоминаний о ней?"],[3,"Воспоминания эти освежают, возвышают мою душу и служат для меня источником лучших наслаждений…"],[4,"Набегавшись досыта, сидишь, бывало, за чайным столом, на своём высоком креслице."],[5,"Уже поздно, давно выпил свою вечернюю чашку молока с сахаром, сон смыкает глаза, но не трогаешься с места, сидишь и слушаешь."],[6,"Maman говорит с кем-нибудь, и звуки голоса её так сладки, так приветливы."],[7,"Одни звуки эти так много говорят моему сердцу!"]],"a":[2],"why":"Рассмотрим связь между предложениями. Ищем в них личные местоимения: местоимений личных нет в №3-7.","verifiedBy":"ключ источника"},{"id":"R13741","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 12–17 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза и личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":12,"hi":17,"s":[[12,"Около ветряной мельницы босой белоголовый мальчик лет семи, который пас гусей, подбежал поближе к дороге, остановился, чуть шевеля румяными губами, восхищённо рассматривая проходивших мимо красноармейцев."],[13,"А Николай пристально посмотрел на него и в изумлении широко раскрыл глаза: до чего же похож!"],[14,"Такие же, как у старшего сынишки, широко поставленные голубые глаза, такие же льняные волосы…"],[15,"Неуловимое сходство было и в чертах лица, и во всей небольшой плотно сбитой фигурке."],[16,"Где-то он теперь, его маленький, бесконечно родной Николенька Стрельцов?"],[17,"Захотелось ещё раз взглянуть на мальчика, так разительно похожего на сына, но Николай сдержался: перед боем не нужны ему воспоминания, от которых размякает сердце."]],"a":[13],"why":"Предложение 13 связано с предыдущим с помощью союза А и личного местоимения «него».","verifiedBy":"ключ источника"},{"id":"R14078","source":"РЕШУ ЕГЭ","prompt":"Из предложений 1–6 найдите такое (-ие), которое (-ые) связано (-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого (-их) предложения(-ий).","lo":1,"hi":6,"s":[[1,"Мой отец и исправник были поражены тем, что нам пришлось переночевать в доме Селивана, которого все в округе считали колдуном и разбойником и который, как мы думали, хотел нас убить и воспользоваться нашими вещами и деньгами..."],[2,"Кстати, о деньгах."],[3,"При упоминании о них тётушка сейчас же воскликнула: – Ах, боже мой!"],[4,"Да где же моя шкатулка?"],[5,"В самом деле, где же эта шкатулка и лежащие в ней тысячи?"],[6,"Её, представьте себе, не было!"]],"a":[3,6],"why":"Предложение №3 связано со вторым с помощью личного местоимения НИХ.","verifiedBy":"ключ источника"},{"id":"R16879","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 4−9 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью указательного местоимения, лексического повтора и форм слов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":4,"hi":9,"s":[[4,"Я говорю про любовь к человеку, которая, смотря по большей или меньшей силе души, сосредоточивается на одном, на некоторых или изливается на многих."],[5,"Про любовь к матери, к отцу, к брату, к детям, к товарищу, к подруге, к соотечественнику, про любовь к человеку."],[6,"Любовь красивая заключается в любви к красоте самого чувства и его выражения."],[7,"Люди, которые любят красивой любовью, очень мало заботятся о взаимности как об обстоятельстве, не имеющем никакого влияния на красоту и приятность чувства."],[8,"Они часто переменяют предметы своей любви, так как их главная цель состоит только в том, чтоб приятное чувство любви было постоянно возбуждаемо."],[9,"Для того чтобы поддержать в себе это приятное чувство, они постоянно в самых изящных выражениях говорят о своей любви как самому предмету, так и всем тем, кому даже и нет до этой любви никакого дела."]],"a":[9],"why":"Предложение 9 связано с предыдущим с помощью указательного местоимения «это», лексического повтора слова «они» и форм слов: приятное чувство (именительный и винительный падежи), любви (родительный и предложный падежи).","verifiedBy":"ключ источника"},{"id":"R17218","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 5−12 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения, форм слова и контекстных синонимов. Напишите номер(а) этого(-их) предложения(-ий).","lo":5,"hi":12,"s":[[5,"Я плыл на лодке вниз по реке и вдруг услышал, как в небе кто-то начал осторожно переливать воду из звонкого стеклянного сосуда в другой такой же сосуд."],[6,"Вода булькала, позванивала, журчала."],[7,"Звуки эти заполняли всё пространство между рекой и небосводом."],[8,"Это курлыкали журавли."],[9,"Я поднял голову."],[10,"Большие косяки журавлей тянулись один за другим прямо к югу."],[11,"Они уверенно и мерно шли на юг, где солнце играло трепещущим золотом в затонах Оки, летели в тёплую страну."],[12,"Я бросил вёсла и долго смотрел на журавлей."]],"a":[11],"why":"Предложение 11 связано с предыдущим при помощи личного местоимения «они», форм слова «югу−юг» и контекстных синонимов «тянулись−шли−летели».","verifiedBy":"ключ источника"},{"id":"R24318","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 15−21 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения и форм слов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":15,"hi":21,"s":[[15,"Лев Толстой нас вдохновит своим озарением: «Мне говорят, я несвободен, а я взял и поднял правую руку»."],[16,"Чехов насторожит категорическим императивом: «В человеке всё должно быть прекрасно…»"],[17,"В свою очередь, Достоевский нам сообщит: «Широк, слишком широк русский человек, я бы сузил» и «Красотою спасётся мир»."],[18,"Следовательно, люди испокон веков тянутся к дельной книге по той причине, что испытывают потребность в общении с самыми светлыми умами, и удовлетворить её не могут ни домашние, ни приятели, ни газеты."],[19,"Откуда взялась эта потребность, точно сказать нельзя, но можно предположить: таковая заключена в самой природе человека как пожизненного слушателя Высших курсов, как мыслителя и творца."],[20,"Словом, скорее всего прав поэт Бродский: «Человек —это то, что он читает»."],[21,"По крайней мере, человек —это не так просто, как полагают материалисты, и мыслящие особи должны быть постоянно настороже."]],"a":[19],"why":"Сопоставьте соседние предложения и найдите названные в условии средства связи. Правильные номера сверены с исходным материалом.","verifiedBy":"ключ источника"},{"id":"R24507","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 24  — 28 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":24,"hi":28,"s":[[24,"И я вдруг ощутил, что взгляды всех устремлены на меня, ощутил, что ко мне, к старшему командиру, к комбату, словно к центральной точке боя, притянуто обострённое внимание: все, чудилось, ждали, что скажет, как поступит комбат."],[25,"И, отчётливо сознавая, что совершаю безумие, я рванулся вперёд, чтобы подать заразительный пример."],[26,"Но меня тотчас с силой схватил за плечи, вдавил в снег старший политрук Толстунов: – Не дури, не смей, комбат!"],[27,"Его приятно-грубоватое лицо в один миг переменилось: лицевые мышцы напряглись, окаменели."],[28,"Он оттолкнулся, чтобы резким движением встать, но теперь я схватил его за руку."]],"a":[27],"why":"Предложение 27 связано с предложением 26 с помощью притяжательного местоимения «его».","verifiedBy":"ключ источника"},{"id":"R30027","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 9–14 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью союза, форм слов и синонимов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":9,"hi":14,"s":[[9,"Одним словом, кому мила степь, кому - горы, кому - морское, пропахшее рыбой побережье, а кому - родная среднерусская природа, тихие красавицы реки с жёлтыми кувшинками и белыми лилиями, доброе, тихое солнышко маленького города..."],[10,"И чтобы жаворонок пел над полем ржи, и чтобы скворечник — на берёзе перед крыльцом."],[11,"Было бы бессмысленно перечислять все приметы русской природы."],[12,"Но из тысяч примет и признаков складывается то общее, что мы зовём нашей родной природой и что мы, любя, быть может, и море, и горы, любим всё же сильнее, чем что-либо иное на всём белом свете."],[13,"Всё это так."],[14,"Но нужно сказать, что это чувство любви к родной природе в нас не стихийно, оно не только возникло само собой, поскольку мы родились и выросли среди природы, но и воспитано в нас литературой, живописью, музыкой, теми великими учителями нашими, которые жили прежде нас, тоже любили родную землю и передали свою любовь нам, потомкам."]],"a":[12],"why":"Предложение 12 связано с предыдущим при помощи союза «но», форм слова «приметы  — примет» и синонимов «приметы  — признаки».","verifiedBy":"ключ источника"},{"id":"R37277","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 25−30 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения, лексического повтора и форм слова. Напишите номер(-а) этого(-их) предложения(-ий).","lo":25,"hi":30,"s":[[25,"Между китами и мышами огромное число животных, которым Земля стала родным домом."],[26,"И во главе всего сущего стоит человек."],[27,"Он часто решает, кому жить, а кому в жизни должно быть отказано."],[28,"Миллионы лет отбирала Природа животных, определяя места, где они могут жить, где могут кормиться."],[29,"Человек давно изучил эти места и первым тянется к добыче, разрушает среду, в которой животным комфортно."],[30,"Так разрушаются основы нашего общего Дома."]],"a":[29],"why":"Предложение 29 связано с предложением 28 с помощью указательного местоимения «эти», лексического повтора «места» и форм слова «животных  — животным».","verifiedBy":"ключ источника"},{"id":"R38483","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 9−16 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью союза и лексических повторов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":9,"hi":16,"s":[[9,"Собственно, вокруг работы и вращалась вся жизнь."],[10,"Она начиналась рано утром и затихала поздно вечером, но она как-то не угнетала людей, не озлобляла — с ней засыпали, с ней просыпались."],[11,"Никто не хвастался сделанным, никого не оскорбляли за промах, но — учили..."],[12,"Думаю, что от такого устройства мира и самоощущения в нём очень близко к самым высоким понятиям о чести, достоинстве и прочим мерилам нравственного роста человека."],[13,"Неужели в том только и беда, что слов этих «честь», «достоинство» там не знали?"],[14,"Но там знали всё, чем жив и крепок человек и чем он нищий: ложь есть ложь, корысть есть корысть, праздность и суесловие..."],[15,"Ни в чём там не заблуждались: больше того, мало-мальски заметные недостатки в человеке, ещё в маленьком, губились на корню."],[16,"Если в человечке обнаруживалась склонность к лени, то она никак не выгораживалась, не объяснялась никакими редкими способностями ребенка — она была просто ленью, потому высмеивалась, истреблялась."]],"a":[14],"why":"Предложение 14 связано с предложением 13 с помощью союза «но», лексического повтора «знали».","verifiedBy":"ключ источника"},{"id":"R39832","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 5−15 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения. Запишите номер(а) этого(-их) предложения(-ий).","lo":5,"hi":15,"s":[[5,"В класс заглянула Женя Румянцева: — Серёжа, можно тебя на минутку?"],[6,"У меня странное предложение!"],[7,"Давай встретимся через десять лет!"],[8,"Шутливость совсем не была свойственна Жене, и я спросил серьёзно: — Зачем?"],[9,"— Мне интересно, каким ты станешь."],[10,"Ты ведь очень нравился мне все эти годы."],[11,"Я думал, что Жене Румянцевой неведомы ни эти слова, ни эти чувства."],[12,"Жизнь её протекала в двух сферах: в напряжённой общественной работе и в мечтаниях о звёздных мирах."],[13,"Немногие из нас твёрдо определили свой дальнейший жизненный путь, а Женя с шестого класса знала, что будет астрономом и никем другим."],[14,"Между нами никогда не было дружеской близости."],[15,"В поисках разгадки я мысленно пробегал прошлое, но ничего не нашёл в нём, кроме одной встречи на Чистых прудах…"]],"a":[12],"why":"Условию соответствует предложение 12:","verifiedBy":"ключ источника"},{"id":"R44223","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 10−15 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим с помощью притяжательного местоимения. Напишите номер(а) этого(-их) предложения(-ий).","lo":10,"hi":15,"s":[[10,"А литературу вёл у нас человек, ради которого я и начал свой рассказ."],[11,"Юрий Викторович Подлипчук школьных учебников не признавал."],[12,"Учились мы по конспектам его вдохновенных лекций, которые торопливо записывали неумелой рукой (всё-таки не студенты, девятый класс)."],[13,"Ещё считалось важным знать тексты, то есть собственно литературу (при этом Достоевский, например, требовался почти весь, вплоть до «Братьев Карамазовых»)."],[14,"Сейчас уже не вспомнить всего, что он говорил и как объяснял, какие имена попутно всплывали."],[15,"Его эрудиция и начитанность были феноменальны."]],"a":[12,15],"why":"Условию соответствуют предложения 12 и 15.","verifiedBy":"ключ источника"},{"id":"R45065","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 15–22 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения и однокоренного слова. Запишите номер(а) этого(-их) предложения(-ий).","lo":15,"hi":22,"s":[[15,"Я иду чёрной лошадиной тропой, на лицо липнут невидимые нити паутины, с детским беззащитным писком вьются передо мной комары, хотя кусают они совсем не по-детски."],[16,"Мой взгляд останавливается на красных, в белых крапинках, шапках мухоморов."],[17,"Потом вижу, как дятел, опершись на растопыренный хвост, колотит своим неутомимым носом сухую древесину."],[18,"В лицо мне хлещут ветки крушины, и вот уже я на сухом месте, и нога едет на скользких иглах."],[19,"Загудел в соснах ветер, и сосны отозвались беззащитным ропотом."],[20,"Мне кажется, что в их кронах вздыхает огромный богатырь-тугодум, который с наивностью младенца копит свою мощь не себе, а другим."],[21,"Под это добродушное дыхание, словно из древних веков, нечёткой белопарусной армадой выплывают облачные фрегаты."],[22,"Мне кажется, что я слышу, как растёт на полях трава, я ощущаю каждую травинку, с маху сдёргиваю сапоги и босиком выбегаю на рыжий песчаный берег, снова стою над рекой и бросаю лесные шишки в синюю тугую воду, в эту прохладную русалочью постель, и смотрю, как расходятся и умирают водяные круги."]],"a":[21],"why":"Предложение 21 связано с предыдущим с помощью указательного местоимения «это» и однокоренного слова «вздыхает  — дыхание»","verifiedBy":"ключ источника"},{"id":"R50144","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 29−36 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи сочинительного союза и форм(ы) слов(а). Напишите номер(а) этого(-их) предложения(-ий).","lo":29,"hi":36,"s":[[29,"Рождается желание глубоко постигнуть, осмыслить и сопоставить одно явление с другим."],[30,"Отсюда наш интерес к истории искусства, литературы."],[31,"Интерес к биографии создателей гениальных творений."],[32,"К процессу их творчества, к той эпохе, в которую они жили."],[33,"Разрозненные впечатления соединяются в общую картину культуры."],[34,"Каждому явлению отводится свое место."],[35,"И каждое оценивается не только само по себе, но и в сопоставлении с другими."],[36,"Значительное, великое мы научаемся отличать от пошлого и от преходящего."]],"a":[35],"why":"Предложение 35 связано с предыдущим при помощи сочинительного союза И и формы слова «каждому  — каждое».","verifiedBy":"ключ источника"},{"id":"R50462","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 29−36 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи сочинительного союза и форм(ы) слов(а). Напишите номер(а) этого(-их) предложения(-ий).","lo":29,"hi":36,"s":[[29,"Рождается желание глубоко постигнуть, осмыслить явления и сопоставить одно явление с другим."],[30,"Отсюда наш интерес к истории искусства, литературы, к биографии создателей гениальных творений, к процессу их творчества, к той эпохе, в которую они жили."],[31,"Разрозненные впечатления соединяются в общую картину культуры."],[32,"Каждому явлению отводится своё место."],[33,"И каждое явление оценивается не только само по себе, но и в сопоставлении с другими."],[34,"Значительное, великое мы научаемся отличать от пошлого и преходящего."],[35,"Великие творения слушаем, смотрим и перечитываем неоднократно."],[36,"И с каждым разом находим в творениях всё больше красот."]],"a":[33,36],"why":"Предложение 33 связано с предыдущим при помощи сочинительного союза И и форм слова «каждому  — каждое», «явлению»  —«явление».","verifiedBy":"ключ источника"},{"id":"R58380","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 1−8 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза, частицы, лексических повторов и форм(ы) слов(а). Запишите номер(а) этого(-их) предложения(-ий).","lo":1,"hi":8,"s":[[1,"Однажды мне довелось побывать на Северном Урале."],[2,"Я сидел на каменной осыпи1 одного из отрогов2 вершины Кваркуш."],[3,"Из-за сопки3 медленно поднималось солнце, и сопка то озарялась с восточной стороны, то снова делалась сумеречной от наползающих на неё облаков."],[4,"Но вот солнце оказалось на горбу сопки, ударило лучами по облакам и густым туманам."],[5,"Снег засверкал на вершине, облака потускнели, нехотя сползли в ущелья, и мир разделился надвое."],[6,"Вверху были сопки, с белыми зайцами на спинах, все в солнечном сиянии, все в сверкании."],[7,"А внизу всё затоплено, закрыто."],[8,"Это был тот час, когда неживая чернота сопок и осыпей окутывалась призрачным дымком и сопки не отпугивали, а манили к себе этой призрачной загадочностью."]],"a":[4],"why":"Предложение 4 связано с 3-м при помощи указанных средств.","verifiedBy":"ключ источника"},{"id":"R59320","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 33−39 найдите такое (-ие), которое (-ые) связано (-ы) с предыдущим при помощи форм(ы) слов(а). Запишите номер(а) этого(-их) предложения (-ий).","lo":33,"hi":39,"s":[[33,"В дождливое утро ударили наши орудия — началась артподготовка, закачалась земля под ногами, посыпались последние плоды с деревьев в парке, и лист закружило вверху."],[34,"Командир взвода приказал мне сматывать связь и следовать в атаку."],[35,"Я как бежал с катушкой на шее, так и споткнулся, и мысли оборвались: богиня Венера стояла без головы, и руки у неё были оторваны, а возле забросанного землёй фонтана лежали Абдрашитов и поляк, засыпанные белыми осколками и пылью гипса."],[36,"Оба они были убиты."],[37,"Лежало на боку ведёрко, и вывалилось из него серое тесто гипса, валялась отбитая голова богини."],[38,"Стояла изувеченная, обезображенная богиня Венера."],[39,"А у ног её лежали два человека, пытавшихся исцелить побитую красоту."]],"a":[35,38],"why":"Предложение 35 связано с 34-м при помощи формы местоимения «Я»:","verifiedBy":"ключ источника"},{"id":"R59691","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 17–25 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения, однокоренного слова и форм(ы) слов(а). Запишите номер(а) этого(-их) предложения(-ий).","lo":17,"hi":25,"s":[[17,"А разве можно забыть геройство гвардейских дивизий, железную дисциплину военных училищ или запасные полки, рвущиеся на фронт из каких-нибудь далёких тыловых лагерей."],[18,"Разве забудешь безмолвный Донбасс сорок третьего года, разбитые города Белоруссии и знаменитый Бобруйский котёл, где на много километров сплошным навалом, друг на друге — искорёженные немецкие танки, орудия, бронетранспортёры, машины."],[19,"Армейская жизнь была суровой, но сколько в ней было неожиданного тепла!"],[20,"Я служил ещё по первому году, когда однажды к нашей землянке подошёл сержант из соседней роты и спросил: «Помкомвзвода дома?»"],[21,"Этот вопрос потряс меня."],[22,"То есть как дома?"],[23,"Дом далеко отсюда."],[24,"Разве здесь дом?"],[25,"А спустя несколько месяцев я и сам говорил так."]],"a":[21],"why":"Указанная связь есть только между предложениями 20 и 21.","verifiedBy":"ключ источника"},{"id":"R66819","source":"РЕШУ ЕГЭ","prompt":"Среди предложений 7–12 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим предложением при помощи лексического повтора, указательного местоимения и однокоренного слова. Запишите номер(а) этого(-их) предложения(-ий).","lo":7,"hi":12,"s":[[7,"Я завидую моим далёким предкам — их упорству, силе огромной..."],[8,"Я бы сегодня не знал, куда деваться с такой силищей."],[9,"Представляю, с каким трудом проделали они этот путь — с Севера Руси, с Волги, с Дона на Алтай."],[10,"Я только представляю, а они его прошли."],[11,"Я склоняюсь перед их памятью, благодарю их самым дорогим словом, какое только удалось сберечь у сердца: они обрели — себе и нам — прекрасную Родину."],[12,"Дело не в красоте, дело, наверное, в том, что даёт Родина."]],"a":[8],"why":"Проанализируем связь предложений в указанном фрагменте:","verifiedBy":"ключ источника"},{"id":"S16471","source":"Школково","prompt":"Среди предложений 29-36 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Запишите номер(а) этого(-их) предложения(-ий).","lo":29,"hi":36,"s":[[29,"Думал я, что теперь из него сделать, да и решил кучу деревьев на том месте изобразить."],[30,"Приношу нынче профессору. «"],[31,"Так, так, н-да."],[32,"А откуда у вас здесь, поручик, кусты взялись?»"],[33,"Мне бы нужно было так и рассказать, как всё было."],[34,"Ну, может быть, засмеялся бы только."],[35,"Впрочем, нет, не рассмеётся – немец, педант."],[36,"Я и говорю ему: «Здесь действительно кусты растут»."]],"a":[31,34],"why":"В данном отрывке есть два предложения, которые связаны с предыдущими при помощи указанного в задании средства. Предложение 31 начинается с личного местоимения «они», заменяющего сочетание «двух мальчиков» из предложения 30. В предложении 34 используется личное местоимение «(к) ним», заменяющее существительное «мальчики» из предложения 33.\n\nОбратите внимание: в предложении 35 есть личное местоимение «они», однако оно заменяет существительное «мальчики» из ТОГО ЖЕ предложения, а не предыдущего.","verifiedBy":"ключ источника"},{"id":"S16481","source":"Школково","prompt":"Среди предложений 55-62 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи лексического повтора и однокоренных слов. Запишите номер(а) этого(-их) предложения(-ий).","lo":55,"hi":62,"s":[[55,"— Почему?"],[56,"— А потому, что блеск от полировки и хрустальная игра его затмят."],[57,"Это и нужно, потому что иной человек не может получать от музыки впечатления, ежели видит, как она происходит."],[58,"Хрусталю я дам слабый дымчатый цвет с золотизной."],[59,"Только вторые клавиши сделаю из чёрного хрусталя, а так весь рояль будет как снежный."],[60,"Светиться должен и звенеть."],[61,"У меня нет воображения рассказать вам, какой это должен быть звон."],[62,"Вася уехал в начале зимы."]],"a":[57],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. В предложении 57 есть существительное «садовник» (единственное число, именительный падеж), употреблённое в той же грамматической форме в предложении 56, а также существительное (имя собственное) «Вера» (корень – -ВЕР-), являющееся однокоренным существительному (имени собственному) «Верочка» (корень – -ВЕР-, суффикс – -ОЧК-) из предложения 56.\n\nОбратите внимание: в предложении 58 есть глагол «посадить» и местоимение «он», которые также используются в 57-м. Однако в ответ идут только те предложения, которые содержат все указанные в задании средства связи.\nОтвет: 57\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S16498","source":"Школково","prompt":"Среди предложений 18-23 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи форм(ы) слов(а) и личного местоимения. Запишите номер(а) этого(-их) предложения(-ий).","lo":18,"hi":23,"s":[[18,"Средства связи позволили всему миру одновременно следить за полётом."],[19,"Коммуникации создали глобальное сопереживание."],[20,"С тех пор возможности соучастия увеличились."],[21,"Мир может не только одновременно слышать, но и видеть."],[22,"Недавнее футбольное первенство мира смотрел одновременно миллиард людей."],[23,"Во всех странах одновременно ахали, волновались, кричали у своих экранов – цивилизация не знала таких масштабов, таких выбросов психической энергии."]],"a":[20],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. В предложении 20 использовано личное местоимение «мы», заменяющее сочетание «я со своим приятелем» из предложения 19, кроме того, в предложении 20 есть существительное (имя собственное) «Прорвы» (родительный падеж), являющееся формой существительного (имени собственного) «(на) Прорву» (винительный падеж) из 19-го.\n\nОбратите внимание: личное местоимение является средством связи только тогда, когда оно заменяет существительное из предыдущего предложения, поэтому предложения 18, 19, 22, содержащие личные местоимения «мы» и «я», не могут войти в ответ (кроме того, первое предложение из диапазона (в нашем случае – 18), согласно заявлениям составителей, не может включаться в ответ). В предложении 23 есть существительное «(за) чаем» (творительный падеж), являющееся формой существительного «чай» (винительный падеж) из предложения 22, однако в ответ идут только те предложения, которые содержат все указанные в задании средства связи.\nОтвет: 20\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S16529","source":"Школково","prompt":"Среди предложений 37-45 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения и однокоренных слов. Запишите номер(а) этого(-их) предложения(-ий).","lo":37,"hi":45,"s":[[37,"Крупные муравьи: черноголовики."],[38,"Такой тяпнет – сразу подскочишь, и Колька (босиком ведь) на всякий случай подальше держался."],[39,"— Вот какое беспокойство вам будет, — сказал Егор."],[40,"А там подальше чуть — ещё поляночка имеется, я наглядел."],[41,"Давайте пособлю с пожитками-то: и вам покойно, и им привычно."],[42,"— Для ревматизма они полезные, муравьи-то, — задумчиво сказал плешивый."],[43,"Вот если у кого ревматизм..."],[44,"— Ой! — взвилась пегая."],[45,"Кусаются, проклятые!.."]],"a":[42],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. В предложении 42 есть притяжательное местоимение «его» (не путать с личным местоимением: устойчивости – чьей? – его), заменяющее существительное «общество» из предложения 41, а также существительное «устойчивости» (приставка – -У-, корень – -СТОЙ-, суффиксы: -ЧИВ-, -ОСТ-), являющееся однокоренным наречию «устойчиво» (приставка – -У-, корень – -СТОЙ-, суффиксы: -ЧИВ-, -О-) из предложения 41.\n\nОбратите внимание: притяжательное местоимение «своих» (предложение 39) относится к существительному «группой» из ТОГО ЖЕ предложения, поэтому не служит для связи предложений. В предложении 38 есть притяжательное местоимение «их» (соучастие – чьё? – их), однако в ответ идут только те предложения, которые содержат все указанные в задании средства связи.\nОтвет: 42\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S16574","source":"Школково","prompt":"Среди предложений 1-11 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения, лексического повтора и форм(ы) слов(а). Запишите номер(а) этого(-их) предложения(-ий).","lo":1,"hi":11,"s":[[1,"Об этом человеке носились странные слухи: говорили, что он был нелюдим, ни с кем не знался, вечно сидел один, занимаясь химией, проводил жизнь за микроскопом, читал даже за обедом и ненавидел женское общество."],[2,"О нём сказано в «Горе от ума»: — Он химик, он ботаник, Князь Фёдор, наш племянник, От женщин бегает и даже от меня."],[3,"Мои родственники называли его не иначе как Химик, придавая этому слову порицательный смысл и подразумевая, что химия вовсе не может быть занятием порядочного человека."],[4,"С самого начала нашего знакомства Химик увидел, что я серьёзно занимаюсь, и стал уговаривать, чтоб я бросил «пустые» занятия литературой и принялся за естественные науки."],[5,"Химик дал мне речь Кювьé о геологических переворотах."],[6,"Видя, что чтение у меня идёт на пользу, он предложил превосходные собрания, снаряды, гербарии и даже собственное руководство."],[7,"Он на своей почве был очень занимателен, чрезвычайно учён, остёр и даже любезен; но для этого не надобно было ходить дальше обезьян; от камней до орангутана его всё интересовало, далее он неохотно пускался, особенно в философию, которую считал болтовнёй."],[8,"Он не был ни консерватором, ни отсталым человеком, он просто не верил в людей, то есть верил, что эгоизм – исключительное начало всех действий, находил, что его сдерживает только безумие одних и невежество других."],[9,"Меня возмущал его материализм."],[10,"Поверхностный и со страхом пополам вольтерианизм наших отцов нисколько не был похож на материализм Химика."],[11,"Его взгляд отличался спокойствием, последовательностью, завершённостью и напоминал известный ответ Лаланда Наполеону."]],"a":[11],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи нужных средств. Предложение 11 начинается с указательного местоимения «этот», указывающего на слово «талант» из 10-го, а также содержит слово «талант» (именительный падеж), использованное в той же грамматической форме в предложении 10 (перед нами лексический повтор), и местоимение «тебя» (винительный падеж), являющееся формой местоимений «ты» (именительный падеж) и «(у) тебя» (родительный падеж) из предложения 10.\n\nОбратите внимание: в предложении 2 есть указательное местоимение «(на) это», указывающее на жалобы на непонимание, упомянутые в предложении 1, а также глагол «(не) жаловались», являющийся формой глагола «жаловался» из предложения 1. В предложении 4 есть глагол «(не) понимаешь», являющийся формой глагола «понимают» из 3-го, и местоимение «ты», форма которого есть в предложении 3 («тебя»), а также указательное местоимение «это» (однако если связь с помощью форм слова осуществляется между двумя предложениями, то связь с помощью указательного местоимения реализуется внутри предложения: «это» = непонимание человеком себя). В предложении 5 есть местоимения «тебя», «тебе» и глагол «понимаю» – они являются формами местоимения «ты» и глагола «(не) понимаешь» из предложения 4. В предложениях 6 и 7 использованы местоимения «я», осуществляющие связь при помощи лексического повтора с предложениями 5 и 6 соответственно, кроме того, в предложении 7 есть существительное «качества», употреблённое в той же грамматической форме в предложении 6 (лексический повтор). В предложении 8 использовано личное местоимение «ты», форма которого есть в предложении 7 («тебя»). В предложениях 9 и 10 есть личные местоимения «ты», связывающие эти предложения с 8-м и 9-м соответственно при помощи лексического повтора (также в предложении 10 есть местоимение «(у) тебя», осуществляющее связь с помощью формы слова). Однако в ответ идут только те предложения, которые содержат все указанные в задании средства связи.\nОтвет: 11\nРазобрать с репетитором\nКурсы\nВсё необходимое для достижения цели","verifiedBy":"ключ источника"},{"id":"S16578","source":"Школково","prompt":"Среди предложений 4-8 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения и форм(ы) слов(а). Запишите номер(а) этого(-их) предложения(-ий).","lo":4,"hi":8,"s":[[4,"Дача стояла в углу сада, окружённая цветником..."],[5,"Цветничок был маленький, далеко не пышный, а фруктовый сад ещё очень молодой."],[6,"Росли в нём груши и яблони-дички, абрикосы, персики, миндаль."],[7,"В последние годы сад уже начал приносить кое-какие плоды, доставляя Антону Павловичу много забот и трогательного, какого-то детского удовольствия."],[8,"Когда наступало время сбора миндальных орехов, то их снимали и в чеховском саду."]],"a":[6],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. Предложение 6 содержит личное местоимение «он», которое заменяет существительное (имя собственное) «Химик» из предложения 5. Также в этом предложении есть местоимение «(у) меня» (родительный падеж), которое является формой местоимения «мне» (дательный падеж) из предложения 5.\n \nОбратите внимание: личное местоимение является средством связи только тогда, когда оно заменяет существительное из предыдущего предложения. По этой причине местоимения «он», содержащиеся в предложениях 7-8, не связывают их с предыдущими (перед нами пример связи при помощи лексического повтора). В предложении 8 также использовано личное местоимение «его» (винительный падеж), являющееся формой местоимения «он» из того же предложения. В предложении 7 есть личное местоимение «его» (винительный падеж), которое является формой местоимения «он» (именительный падеж) из предложения 6, однако в ответ идут только те предложения, которые содержат все указанные в задании средства связи.\nОтвет: 6\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S16588","source":"Школково","prompt":"Среди предложений 17-23 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза и наречия. Запишите номер(а) этого(-их) предложения(-ий).","lo":17,"hi":23,"s":[[17,"В груди этого учёного человека билось чудное, ангельское сердце."],[18,"Ведь жители города были для него чужие, не родные, но он любил их, как детей, и не жалел для них своей жизни."],[19,"У него самого была чахотка, он кашлял, но, когда его звали к больному, забывал про свою болезнь, не щадил себя и, задыхаясь, взбирался на горы, как бы высоки они ни были."],[20,"Он пренебрегал зноем и холодом, презирал голод и жажду."],[21,"Денег он не брал, и, странное дело, когда умирал пациент, то доктор шёл вместе с родственниками за гробом и плакал."],[22,"Признательность жителей не имела границ."],[23,"В городке и его окрестностях не было человека, который позволил бы себе не только сделать ему что-нибудь неприятное, но даже подумать об этом."]],"a":[21],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. Предложение 21 начинается с сочинительного союза «И», а также содержит наречие «тогда», указывающее на время, упомянутое в предложении 20.\n\nОбратите внимание: предложение 17 содержит наречие «здесь (же)», однако оно не связывает это предложение с предыдущим, связь с помощью союза тоже отсутствует (в данном случае «ведь» – частица, а союзы «И» связывают однородные члены); кроме того, первое предложение из диапазона, по заявлению составителей, не может войти в ответ). В предложении 18 есть сочинительный противительный союз «А», однако в ответ идут только те предложения, которые содержат все указанные в задании средства связи. В предложении 22 есть наречие «так» и союз «И», однако они нужны для построения связей внутри одного предложения («так» указывает на степень проявления идеи о красоте грядущей жизни в произведениях Чехова, союз «И» связывает однородные члены («печально», «прекрасно»)). В предложении 23 используются наречие «как», подчинительный союз «когда» и сочинительный союз «или», однако они не связывают данное предложение с предыдущим (наречие указывает на степень проявления признака, подчинительный союз вводит придаточную часть СПП, а сочинительный – связывает однородные члены).\nОтвет: 21\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S16592","source":"Школково","prompt":"Среди предложений 29-39 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного и личного местоимений, однокоренных слов. Запишите номер(а) этого(-их) предложения(-ий).","lo":29,"hi":39,"s":[[29,"Но что кричать в этом грохоте!"],[30,"Единственно возможной командой тут был собственный пример – надёжный командирский приказ: делай как я."],[31,"Лемешенко вырвал из запала чеку и бросил гранату под сетку ограды."],[32,"Дыра получилась небольшая и неровная."],[33,"Разорвав на плече гимнастёрку, сержант протиснулся сквозь сетку, оглянулся – следом, пригнувшись, бежал Ахметов, вскакивал с пулемётом Натужный, рядом прогремели ещё разрывы гранат."],[34,"Тогда он, уже не останавливаясь, изо всех сил рванулся вперёд, отчаянно стуча резиновыми подошвами по скользкой брусчатке площади."],[35,"И вдруг случилось что-то непонятное."],[36,"Площадь покачнулась, одним краем вздыбилась куда-то вверх и больно ударила его в бок и лицо."],[37,"Он почувствовал, как коротко и звонко брякнули о твёрдые камни его медали, близко, возле самого лица брызнули и застыли в пыли капли чьей-то крови."],[38,"Потом он повернулся на бок, всем телом чувствуя неподатливую жёсткость камней, откуда-то из синего неба взглянули в его лицо испуганные глаза Ахметова, но сразу же исчезли."],[39,"Ещё какое-то время сквозь гул стрельбы он чувствовал рядом сдавленное дыхание, гулкий топот ног, а потом всё это поплыло дальше, к церкви, где, не утихая, гремели выстрелы."]],"a":[39],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. В предложении 39 есть личное местоимение «(против) него», заменяющее существительное «убийца» из 38-го, а также притяжательное местоимение «его» (не путать с формой личного местоимения «он»: в виновности – чьей? – его), относящееся к тому же существительному «убийца» из предложения 38. Кроме того, в предложении 39 используется существительное «виновности» (корень – -ВИН-, суффиксы: -ОВН-, -ОСТЬ-), являющееся однокоренным существительному «вину» (корень – -ВИН-) из предложения 38.\n\nОбратите внимание: в предложении 31 есть личные местоимения «он» и «его» (не путать с притяжательным местоимением: уличать – кого? – его), которые заменяют существительное «шалопай» из предложения 30, однако в ответ идут только те предложения, которые содержат все указанные в задании средства связи. В предложении 32 используется личное местоимение «(у) него», оно является формой местоимений «он» и «его» из 31-го => это связь с помощью форм слова, а не личного местоимения (личное местоимение является средством связи только тогда, когда оно заменяет существительное из предыдущего предложения).\nОтвет: 39\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S16595","source":"Школково","prompt":"Среди предложений 26-31 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личных местоимений. Запишите номер(а) этого(-их) предложения(-ий).","lo":26,"hi":31,"s":[[26,"Это внушило некоторое почтение."],[27,"Все они начали помаленьку понимать, что я уже читал такие книги, которых они не могли читать, и понимал такие вещи (не входившие в состав нашего специального курса), о которых они и не слыхивали."],[28,"Дико и насмешливо смотрели они на это, но нравственно подчинялись, тем более что даже учителя обращали на меня внимание по этому поводу."],[29,"Насмешки прекратились, но осталась неприязнь, и установились холодные, натянутые отношения."],[30,"Под конец я сам не выдержал: с летами развивалась потребность в людях, в друзьях."],[31,"Я попробовал было начать сближаться с иными; но всегда это сближение выходило неестественно и так само собой и оканчивалось."]],"a":[28],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанного в задании средства. В предложении 28 использовано личные местоимения «его» (не путать с притяжательным местоимением: осенило – кого? – его) и «он», заменяющие существительное «сержанта» из предложения 27.\n\nОбратите внимание: личное местоимение является средством связи только тогда, когда оно заменяет существительное из предыдущего предложения, поэтому предложение 30, содержащее местоимение «я», в ответ не войдёт.\nОтвет: 28\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S16599","source":"Школково","prompt":"Среди предложений 18-27 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения. Запишите номер(а) этого(-их) предложения(-ий).","lo":18,"hi":27,"s":[[18,"Он назвал все вещи именами и воспел всё, что видел и о чём думал, и воспел свой труд."],[19,"И дремучий мир, на который он накинул волшебную сеть слова, покорился ему, как обузданный конь, и стал его достоянием, и для потомков его стал Родиной – землёй о́ттич и де́дич."],[20,"Русский народ создал огромную устную литературу: мудрые пословицы и хитрые загадки, весёлые и печальные обрядовые песни, торжественные былины, героические, волшебные, бытовые и пересмешные сказки."],[21,"Напрасно думать, что эта литература была лишь плодом народного досуга."],[22,"Она была достоинством и умом народа."],[23,"Она становила и укрепляла его нравственный облик, была его исторической памятью, праздничными одеждами его души и наполняла глубоким содержанием всю его размеренную жизнь, текущую по обычаям и обрядам, связанным с его трудом, природой и почитанием отцов и дедов."],[24,"Недаром пращур плёл волшебную сеть русского языка: вся широкая, творческая, страстная, взыскующая душа народа русского нашла отражение в нашем искусстве XIX века."],[25,"Оно стало мировым и во многом повело за собой искусство Европы и Америки."],[26,"Русская наука дала миру великих химиков, физиков и математиков."],[27,"Первая паровая машина была изобретена в России, так же как и вольтова дуга, беспроволочный телеграф и многое другое."]],"a":[26],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи нужного средства. Предложение 26 начинается с указательного местоимения «это», указывающего на успехи рассказчика в учёбе, упомянутые в предложении 25.\n\nСложный момент: в предложении 23 есть указательное местоимение «тем», которое отсылает к ненависти, упомянутой в предложении 22. Однако предложение 23 также связано с 22-м при помощи форм слова: «они» (именительный падеж) – «их» (родительный падеж); «мне», «(ко) мне» (дательный падеж) – «я» (именительный падеж). По заявлению составителей, в идущем в ответ предложении должны быть только указанные в задании средства связи, в нашем случае используется ещё одно дополнительное средство => предложение 23 не включается в ответ.\nОтвет: 26\nРазобрать с репетитором\nРазберите ошибки с репетитором\nПервое занятие бесплатно. Преподаватель объяснит трудные задания варианта","verifiedBy":"ключ источника"},{"id":"S24324","source":"Школково","prompt":"Среди предложений 19-23 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения, форм(ы) слов(а) и однокоренных слов. Запишите номер(а) этого(-их) предложения(-й).","lo":19,"hi":23,"s":[[19,"Это общий гипноз."],[20,"Надо, чтобы за дверью каждого довольного, счастливого человека стоял кто-нибудь с молоточком и постоянно напоминал бы стуком, что есть несчастные, что, как бы он ни был счастлив, жизнь рано или поздно покажет ему когти, стрясётся беда – болезнь, бедность, потери, и его никто не увидит и не услышит, как теперь он не видит и не слышит других."],[21,"Но человека с молоточком нет, счастливый живёт себе, и мелкие житейские заботы волнуют его слегка, как ветер осину, – и всё обстоит благополучно."],[22,"В ту ночь мне стало понятно, как я тоже был доволен и счастлив."],[23,"Я тоже за обедом и на охоте поучал, как жить, как веровать, как управлять народом."]],"a":[21],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи нужных средств. В предложении 21 есть указательное местоимение «эта», указывающее на «огромную устную литературу» из предложения 20. Кроме того, в предложении 21 используется существительное «литература» (именительный падеж), форма которого есть в 20-м («литературу» – винительный падеж), а также прилагательное «народного» (корень – -НАРОД-, суффикс – -Н-), являющееся однокоренным существительному «народ» (корень – -НАРОД-) из предыдущего предложения.\n\nОбратите внимание: в предложении 22 есть существительное «народа» (корень – -НАРОД-), являющееся однокоренным прилагательному «народного» (корень – -НАРОД-, суффикс – -Н-) из 21-го, однако в ответ идут только те предложения, которые содержат все указанные в задании средства связи.\nОтвет: 21\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S59094","source":"Школково","prompt":"Среди предложений 1-8 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения и форм(ы) слов(а). Запишите номер(а) этого(-их) предложения(-ий).","lo":1,"hi":8,"s":[[1,"Пропала совесть."],[2,"По-старому толпились люди на улицах и в театрах; по-старому они то догоняли, то перегоняли друг друга; по-старому суетились и ловили на лету куски, и никто не догадывался, что чего-то вдруг стало недоставать и что в общем жизненном оркестре перестала играть какая-то дудка."],[3,"Многие начали даже чувствовать себя бодрее и свободнее."],[4,"Легче сделался ход человека; ловчее стало подставлять ближнему ногу, удобнее льстить, пресмыкаться, обманывать, наушничать и клеветать."],[5,"Всякую болезнь вдруг как рукой сняло; люди не шли, а как будто неслись; ничто не огорчало их, ничто не заставляло задуматься; и настоящее, и будущее – всё, казалось, так и отдавалось им в руки, – им, счастливцам, не заметившим пропажи совести."],[6,"Совесть пропала вдруг... почти мгновенно!"],[7,"Ещё вчера эта надоедливая приживалка так и мелькала перед глазами, так и чудилась возбуждённому воображению, и... ничего!"],[8,"Исчезли досадные призраки, а вместе с ними улеглась и та нравственная смута, которую приводила за собой обличительница-совесть."]],"a":[3],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи нужных средств. Предложение 3 начинается с указательного местоимения «это», указывающего на крыжовник, упомянутый в предложении 2, кроме того, приложение 3 содержит существительное «крыжовник» (именительный падеж), форма которого есть в предложении 2 («крыжовнику» – устаревшая форма родительного падежа (так называемый партитивный падеж)).\n\nОбратите внимание: в предложении 4 есть существительное «(на) крыжовник» (винительный падеж), являющееся формой существительного «крыжовник» (именительный падеж) из 3-го, однако в ответ идут только те предложения, которые содержат все указанные в задании средства связи.\nОтвет: 3\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S78163","source":"Школково","prompt":"Среди предложений 1-7 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения и контекстных синонимов. Запишите номер(а) этого(-их) предложения(-ий).","lo":1,"hi":7,"s":[[1,"В Московском университете преподаётся студентам декламация, то есть искусство говорить красиво и выразительно."],[2,"Нельзя не порадоваться этому прекрасному нововведению."],[3,"Мы, русские люди, любим поговорить и послушать, но ораторское искусство у нас в совершенном загоне."],[4,"В земских и дворянских собраниях, учёных заседаниях, на парадных обедах и ужинах мы застенчиво молчим или же говорим вяло, беззвучно, тускло, не зная, куда девать руки."],[5,"Нам говорят слово, а мы в ответ – десять, потому что не умеем говорить коротко и не знакомы с той грацией речи, когда при наименьшей затрате сил достигается известный эффект."],[6,"У нас много присяжных поверенных1, прокуроров, профессоров, проповедников, в которых по существу их профессий должно бы предполагать ораторскую жилку."],[7,"У нас много учреждений, в которых по обязанностям службы много и долго говорят, но у нас совсем нет людей, умеющих выражать свои мысли ясно, коротко и просто."]],"a":[7],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи нужных средств. В предложении 7 используется указательное местоимение «эта», указывающее на существительное «совесть» из предложения 6. Также в предложении 7 есть существительное «приживалка», которое в данном контексте синонимично существительному «совесть» из предложения 6.\nОтвет: 7\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S78207","source":"Школково","prompt":"Среди предложений 8-12 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза и форм(ы) слов(а). Запишите номер(а) этого(-их) предложения(-ий).","lo":8,"hi":12,"s":[[8,"Цветы в оранжерее жили непонятной для людей жизнью."],[9,"Один только урод Столетник был изгнанником в этой семье."],[10,"Он не знал никогда ни дружбы, ни участия, ни сострадания, ни разу в продолжение многих лет ничья любовь не согрела его своим теплом."],[11,"И он так привык к общему презрению, что давно уже переносил его молча, затаив в глубине души острое страдание."],[12,"Привык он быть и постоянным предметом общих насмешек."]],"a":[12],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. Предложение 12 начинается с сочинительного противительного союза «А», а также содержит глагол «рассказать» (инфинитив), форма которого есть в предложении 11 – «рассказывают» (настоящее время, 3-е лицо, множественное число).\n\nОбратите внимание: в предложениях 8, 10 и 11 есть сочинительные и подчинительные союзы, однако они не осуществляют связь этих предложений с предыдущими, а работают внутри одного и того же предложения (используются для связи однородных членов, частей сложноподчинённого и сложносочинённого предложений). Кроме того, в ответ идут только те предложения, которые содержат все указанные в задании средства связи, а первое предложение из диапазона (в нашем случае – 8), согласно заявлениям составителей, не может войти в ответ.\nОтвет: 12\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S78240","source":"Школково","prompt":"Среди предложений 1-7 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи определительного местоимения и форм(ы) слов(а). Запишите номер(а) этого(-их) предложения(-ий).","lo":1,"hi":7,"s":[[1,"В дни зимних вьюг, когда вся земля, всё на земле: дома, деревья – тряслось, выло, плакало, скука вливалась в мастерскую волною, тяжкой, как свинец, давила людей, умерщвляя в них всё живое."],[2,"Трезвый, Капендюхин неутомимо издевался над Ситановым, высмеивая его страсть к стихам и его несчастный роман, грязно, но безуспешно возбуждая ревность."],[3,"Ситанов слушал издёвки казака молча, безобидно, а иногда даже сам смеялся вместе с Капендюхиным."],[4,"Спали они рядом и по ночам долго шёпотом беседовали."],[5,"Эти беседы не давали мне покоя: хотелось знать, о чём могут по-дружески говорить люди, так непохожие один на другого?"],[6,"Но, когда я подходил к ним, казак ворчал: — Тебе чего надо?"],[7,"А Ситанов точно не видел меня."]],"a":[3],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. Предложение 3 начинается с определительного местоимения «другие», указывающего на слово «цветов» из предложения 2. Кроме того, в предложении 3 есть существительные «аромата» (единственное число, родительный падеж) и «цветы» (множественное число, именительный падеж), являющиеся формами существительных «ароматами» (множественное число, творительный падеж) и «цветов» (множественное число, родительный падеж) из 2-го.\n\nОбратите внимание: в предложении 2 есть существительные «оранжереи» (родительный падеж) и «цветов» (родительный падеж), являющиеся формами существительных «(в) оранжерее» (предложный падеж) и «цветы» (винительный падеж) из 1-го, однако в ответ идут только те предложения, которые содержат все указанные в задании средства связи.\nОтвет: 3\nРазобрать с репетитором\nИнтенсивы\nГлубокий разбор тем, требующих дополнительного внимания","verifiedBy":"ключ источника"},{"id":"S81125","source":"Школково","prompt":"Среди предложений 2-7 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения, однокоренных слов и синонимов. Запишите номер(а) этого(-их) предложения(-й).","lo":2,"hi":7,"s":[[2,"Круглая фигура, большой живот, маленькая лысая голова и добродушные глаза, светившиеся любовью к ближним."],[3,"Когда он сидел в кресле, сложив пухлые руки на животе, вращая большими пальцами, и с тихой улыбкой глядел на собеседника, его можно было бы принять за олицетворение спокойной совести."],[4,"В действительности это был опасный хищник."],[5,"Ябедник, обладавший острым пером, знанием законов и судопроизводства, внушал среднему обывателю суеверный ужас."],[6,"Это был злой волшебник, знающий магическое слово, которое отдаёт в его руки чужую судьбу."],[7,"Усадьба Антония Банькевича представляла нечто вроде заколдованного круга."]],"a":[5],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи нужных средств. Предложение 5 начинается с указательного местоимения «эти», указывающее на ночные разговоры Ситанова с Капендюхиным, упомянутые в предложении 4. Кроме того, в предложении 5 есть существительное «беседы» (корень – -БЕСЕД-), являющееся однокоренным глаголу «беседовали» (корень – -БЕСЕД-, суффиксы: -ОВА-, -Л-) из 4-го, а также глагол «говорить», являющийся синонимом тому же глаголу «беседовали» из предложения 4.\nОтвет: 5\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S162673","source":"Школково","prompt":"Среди предложений 1-5 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения и контекстных антонимов. Запишите номер(а) этого(-их) предложения(-ий).","lo":1,"hi":5,"s":[[1,"Антон Павлович Чехов уже в первых рассказах своих умел открыть в тусклом море пошлости её трагически мрачные шутки."],[2,"Стоит только внимательно прочитать его «юмористические» рассказы, чтобы убедиться, как много жестокого и противного скорбно видел и стыдливо скрывал автор за смешными словами и положениями."],[3,"Он был как-то целомудренно скромен, он не позволял себе громко и открыто сказать людям: «Да будьте же вы... порядочнее!» – тщетно надеясь, что они сами догадаются о настоятельной необходимости для них быть порядочнее."],[4,"Ненавидя всё пошлое и грязное, он описывал мерзости жизни благородным языком поэта, с мягкой усмешкой юмориста, и за прекрасной внешностью его рассказов мало заметен полный горького упрёка их внутренний смысл."],[5,"Почтеннейшая публика, читая «Дочь Альбиона», смеётся и едва ли видит в этом рассказе гнуснейшее издевательство сытого барина над человеком одиноким, всему и всем чужим."]],"a":[4],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи упомянутых в задании средств. В предложении 4 используется указательное местоимение «это», указывающее на местоимение «он» из предложения 3, а также прилагательное «опасный», являющееся в данном контексте антонимом прилагательному «спокойной», использованному в предложении 3.\nОтвет: 4\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S164648","source":"Школково","prompt":"Среди предложений 3-7 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения и форм(ы) слов(а). Запишите номер(а) этого(-их) предложения(-ий).","lo":3,"hi":7,"s":[[3,"Но Костя постепенно успокоился."],[4,"Молодость шла и брала своё."],[5,"Даже удивительно, как минутами он умел быть счастливым."],[6,"Неистребимое что-то."],[7,"Казалось, школа никогда много для него не значила."]],"a":[7],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. В предложении 7 использовано указательное местоимение «эти», указывающее на существительное «людям» из предложения 6. Также в предложении 7 есть существительное «люди» (именительный падеж), форма которого использована в предложении 6 («людям» – дательный падеж).\n\nОбратите внимание: в предложении 5 есть указательное местоимение «этом», а также существительное «рассказе» (единственное число, предложный падеж), форма которого использована в предложении 4 («рассказов» – множественное число, родительный падеж). Однако оба слова относятся к имени собственному «Дочь Альбиона», использованному в ТОМ ЖЕ предложении (с предыдущим предложением связи нет). В предложении 6 употреблено существительное «рассказов» (множественное число, родительный падеж), форма которого есть в предложении 5 («рассказе» – единственное число, предложный падеж), однако в ответ идут только те предложения, которые содержат все указанные в задании средства связи.\nОтвет: 7\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S205142","source":"Школково","prompt":"Среди предложений 22-29 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим предложением при помощи личных и притяжательных местоимений, контекстных синонимов. Запишите номер(а) этого(-их) предложения(-ий).","lo":22,"hi":29,"s":[[22,"Михайлов ещё раз кисло улыбнулся, сконфузился и замигал глазами."],[23,"Ковалёв и его Верочка переглянулись и не могли удержаться от улыбки."],[24,"— Очень приятно-с, — забормотал хозяин."],[25,"К вашим услугам-с..."],[26,"Михайлов, кисло улыбаясь и потирая руки, повёл гостей по другую сторону дома."],[27,"Ковалёв надел очки и с видом знатока-туриста, обозревающего достопримечательности, стал осматривать имение."],[28,"Всё было ветхо, запущено, но в общем дом понравился."],[29,"Перед ним в нескольких шагах от парадного крыльца блистал пруд."]],"a":[23],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. В предложении 23 есть личные местоимения «он», заменяющие существительное «бурундуком» из предложения 22, а также притяжательные местоимения «его» (не путать с формой личного местоимения «он»: защёчные мешки – чьи? – его; рот – чей? – его), относящиеся к существительному «бурундуком» из предложения 22. Кроме того, глагол «возвращался» из предложения 23 в данном контексте синонимичен глаголу «появлялся» из 22-го.\n \nОбратите внимание: личное местоимение является средством связи только тогда, когда оно заменяет существительное из предыдущего предложения, поэтому предложения 24, 25, 29, содержащие личные местоимения «меня», «я», в ответ не идут. В предложении 27 есть притяжательное местоимение «своей» и личное местоимение «их», однако они относятся к существительным «бурундук» и «грибов, орехов» из ТОГО ЖЕ предложения, а не из предыдущего. В предложении 29 есть личное местоимение «ему», однако оно относится к существительному «бурундук» из ТОГО ЖЕ предложения, а не из предыдущего. В предложении 22 есть притяжательное местоимение «свою», однако оно не заменяет существительное/личное местоимение из предыдущего предложения, кроме того, согласно заявлениям составителей, первое предложение из указанного в условии диапазона не может войти в ответ.\nОтвет: 23\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S172894","source":"Школково","prompt":"Среди предложений 23-27 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи однокоренных слов. Запишите номер(а) этого(-их) предложения(-ий).","lo":23,"hi":27,"s":[[23,"— Извольте, поколю."],[24,"— Хорошо, посмотрим."],[25,"Скворцов заторопился и, не без злорадства, потирая руки, вызвал из кухни кухарку."],[26,"Оборвыш пожал плечами и нерешительно пошёл за кухаркой."],[27,"Стоя у окна, Скворцов видел, как кухарка и оборвыш вышли чёрным ходом на двор и по грязному снегу направились к сараю."]],"a":[27],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанного в задании средства. В предложении 27 есть существительное «ёлку» (корень – -ЁЛ-, суффикс -К-), а в предложении 26 используется однокоренное ему существительное «ёлочка» (корень – -ЁЛ-, суффиксы – -ОЧ-, -К-).\n\nОбратите внимание: в предложении 24 есть однокоренные слова «глаза» (корень – -ГЛАЗ-) и «глазки» (корень – -ГЛАЗ-, суффикс – -К-), однако они оба располагаются в ОДНОМ И ТОМ ЖЕ предложении, связи с 23-м нет.\nОтвет: 27\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S171345","source":"Школково","prompt":"Среди предложений 27-32 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения. Запишите номер(а) этого(-их) предложения(-й).","lo":27,"hi":32,"s":[[27,"Хорошо, что наука ещё не дошла до того, чтобы знать, о чём думает человек."],[28,"А то как бы презирал её Андрей!"],[29,"Иногда, слушая, он закрывал глаза и лоб рукой, и тогда ей казалось: он не здесь, не с ней."],[30,"За что он любит меня? — снова и снова спрашивала себя Саша и с тревогой, осторожно дотрагивалась до его руки."],[31,"Словно опомнившись, он смотрел на неё прозревшими глазами, улыбался, легонько отвечал на её пожатие и отбирал руку, опять уходил в недоступный Саше свой мир."],[32,"И вот однажды случилось чудо."]],"a":[29],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанного в задании средства. В предложении 29 использовано притяжательное местоимение «его» (не путать с формой личного местоимения «он»: к ногам – чьим? – его), указывающее на существительные «лжеучитель» и «лжестудент» из предложения 28.\n\nОбратите внимание: местоимение «его» из предложения 30 является личным, а не притяжательным: поставил – что? – его (= полено).\nОтвет: 29\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S173603","source":"Школково","prompt":"Среди предложений 10-16 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи лексического повтора. Запишите номер(а) этого(-их) предложения(-ий).","lo":10,"hi":16,"s":[[10,"Приём должен был начаться в шесть часов."],[11,"Ровно в шесть дверь открылась, и вошёл Горький."],[12,"Посетители в приёмной разделялись на принёсших рукописи и на тех, кто ждал решения участи."],[13,"Горький подошёл ко второй группе."],[14,"В руках он держал тетради; на некоторых из них его рукой было написано больше, чем рукой автора."],[15,"С каждым он говорил сосредоточенно и долго, слушал собеседника с всепоглощающим жадным вниманием."],[16,"Мнение своё он высказывал прямо и сурово, выбирая слова, силу которых мы узнали много позже, через годы и десятилетия, когда слова эти, прошедшие в душе нашей длинный, неотвратимый путь, сделались правилом и направлением жизни."]],"a":[12,16],"why":"В данном отрывке есть два предложения, которые связаны с предыдущими при помощи лексического повтора. В предложении 12 есть личное местоимение «он» (именительный падеж), которое используется и в предложении 11. В предложении 16 есть личное местоимение «она» (именительный падеж), употреблённое в той же грамматической форме в предложении 15.","verifiedBy":"ключ источника"},{"id":"S208117","source":"Школково","prompt":"Среди предложений 6-9 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим предложением при помощи притяжательного местоимения. Запишите номер(а) этого(-их) предложения(-ий).","lo":6,"hi":9,"s":[[6,"Я составил перечень упражнений и стал неуклонно следовать ему."],[7,"С 1946 по 1953 год я учился в Саратовском суворовском училище."],[8,"Времени для личной тренировки в распорядке дня не было."],[9,"Поэтому я вставал за полчаса до подъёма, лишая себя блаженного получаса юношеского сна."]],"a":[7],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанного в задании средства. В предложении 7 есть притяжательное местоимение «его» (не путать с формой личного местоимения «он»: редактором – чьим? – его), указывающее на слова «журнал “Летопись”» и «ежемесячником» из предложения 6.\nОтвет: 7\nРазобрать с репетитором\nПредыдущий раздел\nСледующий раздел\n8 800 302-92-79info@shkolkovo.net\nТелеграм БОТТехническая поддержка\nКаталог курсов\nЕГЭОГЭОлимпиадыКружкиДВИШкольный курсДругие курсыВсе курсы\nЛегендарный интенсив. Щелчок\nАкции и скидкиСпециальные программы\nБесплатно\nАвторская база задачКонструктор вариантовКвизыТеорияПлатформа БОБРПриложение БОБРБесплатные интенсивы по олимпиадам\nПлатформа Школково\nНаши преподавателиРепетиторыОтзывы о ШколковоКонтактыБиржа работыСведения об образовательной организации\nТехническая поддержка\nДля СМИ и партнёровМедиа «Журналково»\nМероприятия\nПервая математическая олимпиадаТурнир математических игрВсероссийский пробник Школково\nОбразовательная лицензия\n№ Л035-01298-77/00646528\nот 05 апреля 2023\nРеестр российского ПО\nРеестровая запись №27761\nот 06.05.2025\nИТ-деятельность\nСведения о деятельности в области\nинформационных технологий\nПриложение БОБР\nЛичный кабинет объединяет платформы БОБР и Школково. Можно смотреть уроки без интернета и настраивать уведомления под себя.\nRuStoreAppStore\nПартнёр\nСтатус проекта «Сколково»\nПолитика конфиденциальностиПользовательское соглашениеДоговор офертыПартнерское соглашение\n©2026 «Школково». Все права защищены.ООО «Школково» ИНН 7736263932\nОнлайн школа подготовки к ЕГЭ и ОГЭ — платформа Школково\nКаталог курсов\nРепетиторы\nБесплатно\nОтзывы\nАкции\nКонтакты\nКаталог задач\nКаталог заданий ЕГЭ по русскому языку\nЕГКР\nТема №26. Средства связи предложений в тексте\n06 ЕГКР\n01. Вспоминай формулы\nпо каждой теме\n02. Решай новые задачи\nкаждый день\n03. Вдумчиво разбирай\nрешения\n04. Готовиться с платформой\n«Школково» — ЛЕГКО!\nПолучи персональную скидку на курсы подготовки к экзаменам\nХочу получить огромную скидку\nПодтемы раздела №26. средства связи предложений в тексте\nРешаем задачи","verifiedBy":"ключ источника"},{"id":"S113766","source":"Школково","prompt":"Среди предложений 17-21 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения. Запишите номер(а) этого(-их) предложения(-ий).","lo":17,"hi":21,"s":[[17,"Он поедет скоро туда, опять увидит свою Новороссию[1], её степи, неподвижные, безмолвные, с угрюмыми скирдами сена на горизонте, ясную тихую речку в камышах с далёкою далью сёл, церквей, белых хаток, высоких и стройных тополей."],[18,"И спит это всё там теперь в ярком сиянье весёлого дня, молодой весны, радостных надежд."],[19,"Правда, там нет лесов."],[20,"Здесь, под Петербургом, он только узнал эти леса, полянки среди них; здесь, под Петербургом, только узнал он и аромат этих распускающихся лесов, и мощное пробуждение их сразу от зимней спячки."],[21,"Осень – на юге; весна – на севере."]],"a":[18],"why":"Нужно найти предложение(-я), связанное(-ые) с предыдущим при помощи притяжательного местоимения. \n \nПритяжательные местоимения – разряд местоимений, которые указывают на признак предмета по его принадлежности к чему-либо или кому-либо («мой», «наш», «твой», «ваш», «его», «её», «их», «свой» и их формы).\n \n(17)То была эпоха могучего американского атлета Пола Эндерсона. (18)Я жадно впитывал крохи сведений о его тренировках из спортивных журналов. (19)Я старался разгадать природу этой поразительной силы. (20)Я не связывал её лишь с весом. (21)Должно было быть в тренировках Эндерсона и нечто своё, отличное от принятого, того, к чему мы привыкли.\n \nВ данном фрагменте есть только одно предложение, которое связано с предыдущим при помощи притяжательного местоимения. В предложении 18 использовано притяжательное местоимение «его», которое указывает на принадлежность Полу Эндерсону (данное имя собственное употреблено в предложении 17, т. е. притяжательное местоимение заменяет существительное из предыдущего предложения): (о) тренировках (чьих?) его (не путать с формой личного местоимения «он»: увидеть (кого?) его). \n\nОбратите внимание: в предложении 20 используется личное местоимение «её» (заменяет существительное «силы» из предложения 19), омонимичное притяжательному местоимению «её»; различить их можно по вопросу (в данном случае задаётся вопрос косвенного падежа, а не «чей?», «чья?» и т. д.): не связывал (что?) её [силу] лишь с весом. В предложении 21 есть притяжательное местоимение «своё», однако оно не относится к существительному/личному местоимению из предложения 20 => не связывает два предложения (связь при помощи притяжательного местоимения осуществляется только в том случае, если оно заменяет существительное или личное местоимение из предыдущего предложения). Местоимение «своё» в данном случае соответствует принадлежности Полу Эндерсону, а не субъекту «я» из предложения 20.\nОтвет: 18\nРазобрать с репетитором\nНаборы\nКомбо-тарифы сразу по нескольким предметам","verifiedBy":"ключ источника"},{"id":"S173613","source":"Школково","prompt":"Среди предложений 4-10 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи вводного слова, лексического повтора и личного местоимения. Запишите номер(а) этого(-их) предложения(-ий).","lo":4,"hi":10,"s":[[4,"Громадные венецианские окна выходили на улицу, и он отчётливо помнил себя в этой квартире с высокими комнатами, маленького, затерянного в ней, всегда одинокого, так как дядя или не бывал дома, или сидел в своём кабинете."],[5,"Он помнил себя сидящим на подоконнике этих громадных окон, как смотрел он на проходящих, как слушал шарманку, как тоскливо замирали её последние высокие ноты в весеннем воздухе."],[6,"Как-то в понедельник отец дал ему рубль на покупку учебника арифметики, стоившего тридцать пять копеек."],[7,"До субботы остальные шестьдесят пять копеек оставались у него в кармане."],[8,"А соблазнов было так много."],[9,"К пяти часам вечера его начинал мучить обыкновенно голод."],[10,"Он очень любил швейцарский сыр, любил французские булки, особенные – с двойным животиком, слегка солёные."]],"a":[6],"why":"Нужно найти предложение(-я), связанное(-ые) с предыдущим при помощи вводного слова, лексического повтора и личного местоимения.\n \nВводные слова – слова, выражающие разные оттенки значений, не являющиеся членами предложения и не связанные с другими членами предложения грамматически. \n \nЛексический повтор – повторение в определённой части текста одного и того же слова, конструкции (в одинаковой грамматической форме).\n \nЛичные местоимения – местоимения, которые указывают на лицо или предмет, но конкретно их не обозначают («я», «ты», «он», «она», «оно», «мы», «вы», «они»; их формы: «меня», «тебе», «ему» и др.).\n \n(4)Там, в открытых окнах, был май, лёгкий ветерок качал занавески, доносился аромат распускающихся деревьев, сверкало солнце, грохотали мостовые. (5)Карташёв кладёт в последний раз в жизни этот мел и повторяет мысленно «довольно», стараясь как можно сознательнее пережить это мгновение. (6)Итак, довольно, он инженер. (7)То, к чему четырнадцать лет стремился с многотысячным риском сорваться, достигнуто.\n(8)Каким недостижимым ещё вчера казалось это счастье, и отчего теперь, когда цель достигнута, безумная радость не охватывает его неудержимым порывом, отчего он чувствует только, что устал, что хочет спать и что то, к чему он стремился, теперь, когда это достигнуто, кажется ему таким ничтожным, нестόящим…\n(9)И потом, положив мел и отойдя в глубь залы, Карташёв продолжал ощущать всё ту же охватившую его пустоту, в которой как будто вдруг потерял себя.\n(10)Ему казалось, что нет больше ни его, ни всех этих людей, здесь стоявших, волновавшихся. (11)Что все они только тени, быстро-быстро проносящиеся в пространстве времени.\n\nВ данном фрагменте есть только одно предложение, которое связано с предыдущим при помощи указанных в задании средств. Предложение 6 начинается с вводного слова «итак», относящегося к категории «связь мыслей, итог». Кроме того, в предложении 6 использовано личное местоимение «он», которое заменяет существительное (имя собственное) «Карташёв», употреблённое в предложении 5, и слово «довольно», которое также уже было использовано в предложении 5.\nОтвет: 6\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S173628","source":"Школково","prompt":"Среди предложений 1-7 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения. Запишите номер(а) этого(-их) предложения(-ий).","lo":1,"hi":7,"s":[[1,"В русском человеке нет европейской угловатости, непроницаемости, неподатливости."],[2,"Он со всеми уживается и во всё вживается."],[3,"Он сочувствует всему человеческому вне различия национальности, крови и почвы."],[4,"Он находит и немедленно допускает разумность в том, в чём хоть сколько-нибудь есть общечеловеческого интереса."],[5,"У него инстинкт общечеловечности."],[6,"Он угадывает общечеловеческую черту даже в самых резких исключительностях других народов."],[7,"Тотчас же соглашает, примиряет их в своей идее, находит им место в своём умозаключении и нередко открывает точку соединения и примирения в совершенно противоположных, сопернических идеях двух различных европейских наций, – в идеях, которые сами собою, у себя дома, ещё до сих пор, к несчастью, не находят способа примириться между собою, а может быть, и никогда не примирятся."]],"a":[6],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанного в задании средства. Предложение 6 содержит притяжательное местоимение «наши», которое относится к личному местоимению «мы» из предложения 5 (связь с помощью притяжательного местоимения реализуется в том случае, если оно заменяет имя существительное/личное местоимение из предыдущего предложения). \n\nОбратите внимание: в предложениях 1 и 2 используются притяжательные местоимения «своему» и «своей», однако в обоих случаях реализуется связь внутри предложения. Кроме того, согласно заявлениям составителей, первое предложение из диапазона не может войти в ответ.\nОтвет: 6\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S173633","source":"Школково","prompt":"Среди предложений 1-7 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи форм(ы) слов(а) и однокоренного слова. Запишите номер(а) этого(-их) предложения(-ий).","lo":1,"hi":7,"s":[[1,"Побеждён быть не может народ, в самых бедствиях гордый своим именем, в самых горестных потерях не лишившийся добрых нравов, среди жесточайших оборотов судьбы хранящий твёрдо веру в законы праотцов!"],[2,"Москва была несколько дней во власти иноплеменных, Москва превращена в пепел, но дух свободы и любовь к Отечеству не переставали никогда оживлять древнюю столицу России."],[3,"Добродетели сии сопровождают ныне мирного гражданина в изгнание из мест родины и неразлучны с воином, кипящим отмстить за пепел родных жилищ и права свои."],[4,"Могучи мышцами и духом потомки славных воинов – и Россия побеждена быть не может!"],[5,"Каждый день слышу повествования о твёрдости жителей, необходимостью в Москве заключённых во время пребывания там французов."],[6,"Спросите, кто были сии жители?"],[7,"Нищие, сирые, бедные вдовы, бесприютные и слабые старцы."]],"a":[5,6],"why":"В данном отрывке есть два предложения, которые связаны с предыдущими при помощи указанных в задании средств. Предложение 5 содержит местоимение «(у) него» (родительный падеж), которое является формой местоимения «он» (именительный падеж) из предложения 4, и существительное «общечеловечности» (корни: -ОБЩ- и -ЧЕЛОВЕЧ-, суффиксы: -Н- и -ОСТ-), являющееся однокоренным прилагательному «общечеловеческого» (корни: -ОБЩ- и -ЧЕЛОВЕЧ-, суффикс – -ЕСК-). Предложение 6 начинается с местоимения «он» (именительный падеж), а в 5-ом содержится его форма – «(у) него» (родительный падеж), также в первом из упомянутых предложений есть прилагательное «общечеловеческую» (корни: -ОБЩ- и -ЧЕЛОВЕЧ-, суффикс – -ЕСК-), оно является однокоренным существительному «общечеловечности» (корни -ОБЩ- и -ЧЕЛОВЕЧ-, суффиксы: -Н- и -ОСТ-). \n\nОбратите внимание: в предложении 3 есть местоимение «всему» (единственное число, дательный падеж), являющееся формой местоимений «(во) всё» (единственное число, винительный падеж) и «(со) всеми» (множественное число, творительный падеж), однако в ответ идут только те предложения, которые содержат все указанные в задании средства связи.\nОтвет: 56\nРазобрать с репетитором\nКурсы\nВсё необходимое для достижения цели","verifiedBy":"ключ источника"},{"id":"S173638","source":"Школково","prompt":"Среди предложений 13-18 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения. Запишите номер(а) этого(-их) предложения(-ий).","lo":13,"hi":18,"s":[[13,"Вдова вела процесс «по праву бедности», не внося гербовых пошлин, и ей предсказывали неудачу, так как дело всё-таки было запутанное, а на суд было оказано давление."],[14,"Однако процесс был решён в пользу вдовы, причём все знали, что этим она обязана исключительно твёрдости отца..."],[15,"Сенат как-то неожиданно скоро утвердил решение, и скромная вдова стала сразу одной из богатейших помещиц не только в уезде, но и, пожалуй, в губернии."],[16,"Когда она опять явилась в нашу квартиру, на этот раз в коляске, все с трудом узнавали в ней прежнюю скромную просительницу: она как будто даже помолодела и сияла радостью и счастьем."],[17,"Отец принял её очень радушно, с тою благосклонностью, которую мы обыкновенно чувствуем к людям, нам много обязанным."],[18,"Но когда она попросила «разговора наедине», то вскоре вышла из кабинета с покрасневшим лицом и слезами на глазах."]],"a":[16],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи нужного средства. В предложении 16 содержится указательное местоимение «тому», которое относится ко всему предложению 15. \n\nОбратите внимание: в предложении 13 есть указательное местоимение «тем», однако первое предложение из перечня, согласно заявлениям составителей, не может пойти в ответ, а сама связь осуществляется внутри предложения («тем» входит в состав фразеологизма «вместе с тем»).\nОтвет: 16\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S173821","source":"Школково","prompt":"Среди предложений 13-20 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза и форм(ы) слов(а). Запишите номер(а) этого(-их) предложения(-ий).","lo":13,"hi":20,"s":[[13,"Возле того проулочка, что вёл к снежным кедрачам[3], участковый приостановился."],[14,"Снег под валенками скрипеть перестал, и послышались взрывы моторов, комариный вой электропил и тугой стон замёрзшей земли."],[15,"Эти звуки были чужеродны деревне, отдельны от рёва трактора «Беларусь», эти звуки деревне не принадлежали и принадлежать не могли, так как деревенскими не были."],[16,"Звуки издавали тайга, кедрачи, что клином шли в деревню с юга."],[17,"Там, в кедрачах, вот уже второй месяц работал передвижной лесопункт, вырубающий мачтовый сосняк и кедры."],[18,"Лесопункт, как и кедрач, наступал на деревню с юга, и с каждым днём всё явственнее становились звуки."],[19,"На лесопункте круглые сутки выли моторы, раздавались мужские голоса; с рассвета до темноты валились на землю деревья; днём и ночью горели костры, а только ночью врезались в темень и снег кинжальные лучи прожекторов."],[20,"Круглые сутки выл и гремел лесопункт, похожий на парикмахерскую машинку, что оставляет за собой неровный след на зябкой коже."]],"a":[14,18],"why":"В данном отрывке есть два предложения, которые связаны с предыдущими при помощи указанных в задании средств. Предложение 14 начинается с сочинительного противительного союза «ОДНАКО», а также содержит существительное «процесс» (именительный падеж), форма которого есть в предложении 13 («(вела что?) процесс»), и существительное «вдовы» (родительный падеж), являющееся формой существительного «вдова» (именительный падеж) из предложения 13. Предложение 18 начинается с сочинительного противительного союза «НО», также содержит личное местоимение «она» (именительный падеж), форма которого есть в предложении 17 («её» – винительный падеж; не путать с притяжательным местоимением: принял (кого?) её).\n\nОбратите внимание: Предложение 20 начинается с сочинительного противительного союза «НО», однако в ответ идут только те предложения, которые содержат все указанные в задании средства связи. В предложениях 13 и 16 содержатся сочинительные и подчинительные союзы, однако они осуществляют связь внутри ОДНОГО предложения, а не между соседними. Кроме того, согласно заявлениям составителей, первое предложение из диапазона (в нашем случае – 13) не может войти в ответ. В предложении 15 есть существительное «вдова» (именительный падеж), форма которого есть в 14-м («вдовы» – родительный падеж), однако сочинительный союз «И» из этого предложения используется для связи частей сложносочинённого предложения => связи с предложением 13 при помощи союза нет.","verifiedBy":"ключ источника"},{"id":"S173828","source":"Школково","prompt":"Среди предложений 13-23 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного наречия, форм(ы) слов(а) и однокоренного слова. Запишите номер(а) этого(-их) предложения(-ий).","lo":13,"hi":23,"s":[[13,"Я буду богат и независим."],[14,"Уверенность эта появилась во мне очень рано, она была самой простой, самой инстинктивной мыслью моего детства, и то, что я был членом бедной семьи, не только не ослабляло этой надежды, но даже, напротив, ещё более способствовало её укреплению."],[15,"В семье мне говорили, что не в знатности и не в богатстве дело, а в одарённости и настойчивости, и ставили мне в пример многих, кто, выйдя из нищеты, достигал высот, до которых редкому богатству и редкой знатности удавалось дотянуться."],[16,"Я был совершенно спокоен за своё будущее."],[17,"Поэтому я никогда не завидовал."],[18,"Если и существовал круг людей, куда порой трудно было мне проникнуть, то зато между вещами, замкнутыми этим кругом, и мною существовало содружество, и в нём главенствовал я."],[19,"Чужая ограда не пугала меня и не угнетала моих чувств."],[20,"Напротив, поставив на неё локти и глядя в чужой сад, я как бы взвешивал то, чем обладали другие, сравнивая его с тем, чем буду обладать я."],[21,"Ни статуи чужих садов, ни цветники, ни дорожки, сверкающие суриком гравия, не раздражали моего самолюбия, когда я, маленький гимназист, приходил из города готовить к переэкзаменовкам богатых сверстников."],[22,"Мир на самом деле принадлежит мне."],[23,"Это была самая простая, самая инстинктивная мысль моего детства."]],"a":[17],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи нужных средств. Предложение 17 начинается с указательного наречия «там», указывающего на территорию, упомянутую в предложении 16. Также предложение 17 содержит слово «(в) кедрачах» (предложный падеж), являющееся формой слова «кедрачи» (именительный падеж) из 16-го, и существительное «кедры» (корень – -КЕДР-), являющееся однокоренным существительному «кедрачи» (корень – -КЕДР-, суффикс – -АЧ-) из предложения 16.\n\nОбратите внимание: в предложении 16 есть существительное «звуки» (винительный падеж), являющееся формой существительного «звуки» (именительный падеж) из 15-го. В предложении 18 есть слово «кедрач» (единственное число, именительный падеж), являющееся формой слова «(в) кедрачах» (множественное число, предложный падеж) из предложения 17. В предложении 20 употреблено существительное «лесопункт» (именительный падеж), форма которого есть в предложении 19 («(на) лесопункте» – предложный падеж). Однако в ответ идут только те предложения, которые содержат все указанные в задании средства связи.\nОтвет: 17\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S174299","source":"Школково","prompt":"Среди предложений 1-6 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи форм(ы) слов(а). Запишите номер(а) этого(-их) предложения(-ий).","lo":1,"hi":6,"s":[[1,"На пароходе было тесно."],[2,"Повсюду сидели амурские рыбаки и старатели[1]."],[3,"И невесело было у всех на душе."],[4,"Владивосток был занят японцами, на Хабаровск наступали чехи, калмыковцы, семёновцы."],[5,"Хоть на короткое время, но враг одолел, и приходилось кому уходить в тайгу, кому скрываться в городе или уезжать туда, где тебя никто не мог бы узнать."],[6,"Среди этой толпы был и я."]],"a":[3,6],"why":"В данном отрывке есть два предложения, которые связаны с предыдущими при помощи указанного в задании средства. Предложение 3 начинается со слова «дороги» (множественное число, именительный падеж), форма которого есть в предложении 2 («дорог» – множественное число, родительный падеж). Предложение 6 содержит прилагательное «желтоватые» (множественное число, винительный падеж), которое является формой слова «желтоватую» (единственное число, женский род, винительный падеж) из предложения 5.\nОтвет: 36\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S175775","source":"Школково","prompt":"Среди предложений 21-30 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи противительного союза и притяжательного местоимения. Запишите номер(а) этого(-их) предложения(-ий).","lo":21,"hi":30,"s":[[21,"Дескать, взрослый, с портфелем, в очках, да ещё и книжку читает, а вот пять копеек пожалел."],[22,"Среди взрослых, к сожалению, встречаются люди, которые рады другого в чём-то заподозрить."],[23,"Хорошему не удивляются: мол, так и быть должно."],[24,"Зато, будто на весёлом спектакле, оживляются, когда в «нарушители» попадаешь."],[25,"Были, конечно, и такие пассажиры, которые отнеслись ко мне иначе."],[26,"«Вы получше поищите, гражданин."],[27,"Да не спешите."],[28,"Я же видела, как вы клали», – сказала женщина, одной рукой держась за поручень, другой – за сумку, доверху набитую покупками. «"],[29,"Как же видела, если только вошла?"],[30,"А этот (указывая на меня) давно уже едет», – недовольно буркнул крепкий мужчина, сидевший возле неё и читавший газету."]],"a":[23],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. Предложение 23 начинается с сочинительного противительного союза «НО», также в нём использовано притяжательное местоимение «моего», заменяющее личное местоимение «я» из предложения 22. \n\nОбратите внимание: в предложении 24 есть местоимение «их», однако оно в данном случае является личным, а не притяжательным (спросил – кого? – их); сравните: «их книги» (чьи?).\nОтвет: 23\nРазобрать с репетитором\nРазберите ошибки с репетитором\nПервое занятие бесплатно. Преподаватель объяснит трудные задания варианта","verifiedBy":"ключ источника"},{"id":"S178709","source":"Школково","prompt":"Среди предложений 14-19 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи подчинительного союза, личного местоимения и однокоренных слов. Запишите номер(а) этого(-их) предложения(-ий).","lo":14,"hi":19,"s":[[14,"Иные глаза выражали просьбу: кого угодно, только не меня."],[15,"Я смотрел на ребят – уже улыбаясь им."],[16,"Вдруг и мне захотелось сделать что-то очень доброе, хорошее."],[17,"Открыл книгу, с которой ехал в автобусе и на которую теперь уже не сердился (то был Пушкин), и весь урок читал его стихи, а закончил строчками: Друзья мои, прекрасен наш союз! Он, как душа, неразделим и вечен..."],[18,"Передо мной и впрямь сидели уже не школьники, ученики, а друзья, которые не позволили мне быть мрачным и сердитым."],[19,"Ведь в таком настроении (буду откровенен) учитель порой бывает придирчив."]],"a":[15],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. Предложение 15 начинается с подчинительного союза «чтобы», указывающего на цель воспитания, упомянутую в предложении 14. Также в предложении 15 использовано личное местоимение «он», заменяющее существительное «ученика» из 14-го, и существительные «ученика» (корень – -УЧ-, суффиксы: -Е- и -НИК-), «долг» (корень – -ДОЛГ-), являющиеся однокоренными существительному «учителем» (корень – -УЧ-, суффиксы: -И- и -ТЕЛ-) и краткому прилагательному «должен» (корень – -ДОЛЖ-, суффикс – -ЕН-) из предложения 14.\nОтвет: 15\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S179703","source":"Школково","prompt":"Среди предложений 35-39 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза и лексического повтора. Запишите номер(а) этого(-их) предложения(-ий).","lo":35,"hi":39,"s":[[35,"И на трёх мальчиков сразу напал неудержимый кашель."],[36,"Она не сделала ни одного замечания."],[37,"Она хорошо знала, как бесполезны они бывают порой."],[38,"— А теперь, — сказала учительница, — будем заниматься."],[39,"Вы остановились на Грибоедове..."]],"a":[38],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. Предложение 38 начинается с сочинительного союза «И», также в нём используется сочетание «тридцать “спасибо”», которое встречается в той же форме и в предложении 37 (перед нами лексический повтор). \n\nОбратите внимание: в предложении 37 есть слово «спасибо», которое также используется в предложении 36, однако в ответ идут только те предложения, которые содержат все указанные в задании средства связи. В предложении 35 есть подчинительный союз «КОГДА», а в предложении 36 – сочинительный союз «И», однако они осуществляют связь внутри предложений, а не между соседними (связывают части сложноподчинённого предложения и однородные члены соответственно). Кроме того, согласно заявлениям составителей, первое предложение из диапазона (в нашем случае – 35) не может войти в ответ.\nОтвет: 38\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S182949","source":"Школково","prompt":"Среди предложений 45-55 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза, однокоренных слов и лексического повтора. Запишите номер(а) этого(-их) предложения(-ий).","lo":45,"hi":55,"s":[[45,"У того же мальчишки меня приняли бы куда лучше и ласковей."],[46,"Но я не мог этого сделать."],[47,"На душе у меня было погано."],[48,"Что-то давило и угнетало, и я не знал, как мне быть, о чём разговаривать с хозяйкой."],[49,"И всё-таки я должен был остаться здесь."],[50,"Почему?"],[51,"Зачем?"],[52,"Этого я не смог бы объяснить."],[53,"На столе горела лампа."],[54,"Около неё, будто окаменелая, сидела хозяйка."],[55,"— Почему не спите?"]],"a":[47],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. Предложение 47 начинается с сочинительного союза «И», который связывает названное предложение с предыдущим. Кроме того, в предложении 47 использовано прилагательное «детская» (корень – -ДЕТ-, суффикс – -СК-), являющееся однокоренным существительному «дети» (корень – -ДЕТ-) из 46-го; также в предложении 47 есть личное местоимение «её» (привела в спокойствие (кого?) её) в форме винительного падежа, которое использовано в предложении 46 в той же форме (дети проверяли (кого?) её), то есть перед нами лексический повтор. \n\nОбратите внимание: предложение 55 связано с 54-м при помощи форм слова («книги» – множественное число, именительный падеж; «книг» – множественное число, родительный падеж). В предложении 51 использовано числительное «(с) пятой» (родительный падеж), а в предложении 50 есть числительное «(на) пятой» в форме предложного падежа; в предложении 53 использовано числительное «(со) второй» (родительный падеж), а в предложении 52 есть числительное «(на) второй» в форме предложного падежа => это связь при помощи форм слова, а не лексического повтора.\nОтвет: 47\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S183402","source":"Школково","prompt":"Среди предложений 7-15 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Запишите номер(а) этого(-их) предложения(-ий).","lo":7,"hi":15,"s":[[7,"Верующий уточнил бы: награда Бога."],[8,"Атеист сказал бы: награда нашей нравственной природы."],[9,"На что верующий мог бы спросить: а откуда взялась ваша нравственная природа?"],[10,"Но этот спор вечен."],[11,"Когда перед нами истинно талантливое произведение, это всегда субъективно честно, но охват истины зависит и от силы таланта, и знания предмета, и того идеала честности, который выработан данным писателем."],[12,"Вдохновение поднимает писателя на вершину его идеала."],[13,"Но вершины идеала Льва Толстого или просто хорошего писателя Алексея Писемского находятся на разном уровне, и тут наша собственная честность в измерении их достижений должна учитывать это."],[14,"Толстой со своей высоты видит всех и потому виден всем."],[15,"Просто одарённый писатель со своей высоты тоже видит кое-что и виден каким-то людям."]],"a":[8,11],"why":"В данном отрывке есть два предложения, которые связаны с предыдущими при помощи указанного в задании средства. В предложении 8 использовано личное местоимение «её», заменяющее существительное «избушка» из предложения 7. В предложении 11 есть личное местоимение «она», которое заменяет существительное «женщина» из предложения 10. \n\nОбратите внимание: личное местоимение является средством связи только тогда, когда оно заменяет существительное из предыдущего предложения, поэтому предложения 9 и 15, в которых использованы личные местоимения «я» и «вы», в ответ не войдут. В предложении 9 также использовано личное местоимение «она», однако оно заменяет существительное «калитку» из ТОГО ЖЕ предложения, а не из предыдущего. Предложение 12, содержащее личное местоимение «я» (именительный падеж), связано с 11-м при помощи формы слова («меня» – винительный падеж). Предложение 13, содержащее личное местоимение «мне» (дательный падеж), связано с 12-м при помощи формы слова («я» – именительный падеж). В предложении 14 есть личное местоимение «(у) меня», однако оно также не заменяет никакое существительное из предложения 13 (а по смыслу эти предложения не связаны даже при помощи формы слова) => не включается в ответ.","verifiedBy":"ключ источника"},{"id":"S201920","source":"Школково","prompt":"Среди предложений 19-23 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим предложением при помощи вводной конструкции, лексического повтора и однокоренных слов. Запишите номер(а) этого(-их) предложения(-ий).","lo":19,"hi":23,"s":[[19,"Вдохновение может заблуждаться, но оно не может лгать."],[20,"Точнее говоря, всё истинно вдохновенное всегда истинно правдиво, но адресат может быть ложным."],[21,"Представим себе поэта, написавшего гениальное стихотворение о животворной разумности движения светила с запада на восток."],[22,"Можем ли мы наслаждаться таким стихотворением, зная, что оно не соответствует законам астрономии?"],[23,"Безусловно, можем! В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. Предложение 20 начинается с вводной конструкции «точнее говоря», относящейся к категории «способ оформления мыслей» (уточняет сказанное в предыдущем предложении), а также содержит глагол «может» (настоящее время, единственное число, 3-е лицо), употреблённый в той же форме в предложении 19. Кроме того, в предложении 20 есть прилагательные «вдохновенное» (корень – -ВДОХНОВ-, суффикс – -ЕНН-) и «ложным» (корень – -ЛОЖ-, суффикс – -Н-), являющиеся однокоренными существительному «вдохновение» (корень – -ВДОХНОВ-, суффикс – -ЕНИ-) и глаголу «лгать» (корень – -ЛГ-, суффикс – -А-) из 19-го предложения соответственно. Обратите внимание: предложение 22 связано с 21-м при помощи форм слова («стихотворением» – единственное число, творительный падеж; «(написавшего) стихотворение» – единственное число, винительный падеж), а не однокоренных слов. Предложение 23 начинается с вводного слова «безусловно» и содержит глагол «можем» (настоящее время, множественное число, 1-е лицо), употреблённый в той же форме в предложении 22. Однако в ответ идут только те предложения, которые содержат все указанные в задании средства связи. Ответ: 20"]],"a":[20],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. Предложение 20 начинается с вводной конструкции «точнее говоря», относящейся к категории «способ оформления мыслей» (уточняет сказанное в предыдущем предложении), а также содержит глагол «может» (настоящее время, единственное число, 3-е лицо), употреблённый в той же форме в предложении 19. Кроме того, в предложении 20 есть прилагательные «вдохновенное» (корень – -ВДОХНОВ-, суффикс – -ЕНН-) и «ложным» (корень – -ЛОЖ-, суффикс – -Н-), являющиеся однокоренными существительному «вдохновение» (корень – -ВДОХНОВ-, суффикс – -ЕНИ-) и глаголу «лгать» (корень – -ЛГ-, суффикс – -А-) из 19-го предложения соответственно.\n \nОбратите внимание: предложение 22 связано с 21-м при помощи форм слова («стихотворением» – единственное число, творительный падеж; «(написавшего) стихотворение» – единственное число, винительный падеж), а не однокоренных слов. Предложение 23 начинается с вводного слова «безусловно» и содержит глагол «можем» (настоящее время, множественное число, 1-е лицо), употреблённый в той же форме в предложении 22. Однако в ответ идут только те предложения, которые содержат все указанные в задании средства связи.\nОтвет: 20\nРазобрать с репетитором\nПредыдущий раздел\nСледующий раздел\n8 800 302-92-79info@shkolkovo.net\nТелеграм БОТТехническая поддержка\nКаталог курсов\nЕГЭОГЭОлимпиадыКружкиДВИШкольный курсДругие курсыВсе курсы\nЛегендарный интенсив. Щелчок\nАкции и скидкиСпециальные программы\nБесплатно\nАвторская база задачКонструктор вариантовКвизыТеорияПлатформа БОБРПриложение БОБРБесплатные интенсивы по олимпиадам\nПлатформа Школково\nНаши преподавателиРепетиторыОтзывы о ШколковоКонтактыБиржа работыСведения об образовательной организации\nТехническая поддержка\nДля СМИ и партнёровМедиа «Журналково»\nМероприятия\nПервая математическая олимпиадаТурнир математических игрВсероссийский пробник Школково\nОбразовательная лицензия\n№ Л035-01298-77/00646528\nот 05 апреля 2023\nРеестр российского ПО\nРеестровая запись №27761\nот 06.05.2025\nИТ-деятельность\nСведения о деятельности в области\nинформационных технологий\nПриложение БОБР\nЛичный кабинет объединяет платформы БОБР и Школково. Можно смотреть уроки без интернета и настраивать уведомления под себя.\nRuStoreAppStore\nПартнёр\nСтатус проекта «Сколково»\nПолитика конфиденциальностиПользовательское соглашениеДоговор офертыПартнерское соглашение","verifiedBy":"ключ источника"},{"id":"S150552","source":"Школково","prompt":"Среди предложений 1-7 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи однокоренного слова. Запишите номер(а) этого(-их) предложения(-ий).","lo":1,"hi":7,"s":[[1,"Милостивая государыня, на Ваше письмо от 20 февраля отвечаю лишь теперь, через месяц, за недосугом и нездоровьем, а потому весьма прошу Вас не рассердиться."],[2,"Вы пишете и задаёте вопросы, на которые надо писать вместо ответа трактаты, а не письма."],[3,"Да и вопросы-то разрешаются лишь всею жизнию."],[4,"Из письма Вашего я заключаю, что Вы добрая мать и многим озабочены насчёт Вашего подрастающего ребёнка."],[5,"Но к чему Вам разрешение тех вопросов, которые Вы мне прислали, – не могу понять."],[6,"Вы слишком многим задаётесь и болезненно беспокоитесь."],[7,"Дело может быть ведено́ гораздо проще."]],"a":[7],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанного в задании средства. В предложении 7 использовано прилагательное «водная» (корень – -ВОД-, суффикс – -Н-), являющееся однокоренным существительному «вода» (корень – -ВОД-) из предложения 6.\n \nОбратите внимание: в предложении 1 использованы однокоренные слова «леса» (корень – -ЛЕС-) и «лесной» (корень – -ЛЕС-, суффикс – -Н-), однако связь осуществляется внутри одного предложения, а не между соседними. \n \nВажный момент: в предложении 4 используется глагол «вижу» (корень – -ВИЖ-), а в предложении 5 – отглагольное прилагательное «видный» (корень – -ВИД-, суффикс – -Н-); они являются однокоренными, однако не связывают два предложения (глагол описывает действие рассказчика, а отглагольное прилагательное характеризует ком). К тому же упомянутые предложения связаны с помощью указательного местоимения и форм слова: местоимение «эти» указывает на пузыри, о которых речь идёт в предыдущем предложении; «распускает (кого? что?) пузыри» и «пузыри мчатся» (в предложении 4 существительное используется в форме В.п., а в предложении 5 – в форме Им.п.). Следовательно, предложение 5 не может пойти в ответ, так как правильный ответ (по заявлению составителей) априори подразумевает отсутствие иных средств связи, кроме указанных в задании.\nОтвет: 7\nРазобрать с репетитором\nНаборы\nКомбо-тарифы сразу по нескольким предметам","verifiedBy":"ключ источника"},{"id":"S143888","source":"Школково","prompt":"Среди предложений 15-19 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения. Запишите номер(а) этого(-их) предложения(-ий).","lo":15,"hi":19,"s":[[15,"Какое тогда откроется над мёртвой Вселенной одухотворённое человеческое небо!"],[16,"Но когда ещё это будет, а пока каждый из нас должен стать между своим небом и астрономическими телами и должен выбрать для себя такое место, чтобы видно было и своё небо, и то, подлежащее изменению."],[17,"Просто говоря, каждый из нас должен найти собственное полезное место в общем творчестве мира и потом держаться его."],[18,"Мир, с которым в душе мы приходим, в миллион раз прекрасней того, что мы потом узнаём о нём из книг."],[19,"Разве можно чудеса звёздного неба в какой-нибудь мере сравнить с тем, что открывает нам астрономия?"]],"a":[16,18],"why":"В данном отрывке есть несколько предложений, связанных с предыдущим при помощи указательного местоимения. Предложение 16 начинается с указательного местоимения «этого», отсылающего ко всему, что героиня уже дала своему ребёнку (об этом говорится в предложении 15; оно обобщает информацию из предыдущего абзаца, в котором подробно описано, что именно родители могут дать своим детям). В предложении 18 также употреблено указательное местоимение «этого», которое указывает на упомянутое в предложении 17 влияние детских впечатлений на человека.\n \nОбратите внимание: в ответ нужно выписать все предложения, содержащие указанные в задании средства связи, иначе ответ не будет засчитан.","verifiedBy":"ключ источника"},{"id":"S150559","source":"Школково","prompt":"Среди предложений 1-7 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения и форм(ы) слов(а). Запишите номер(а) этого(-их) предложения(-ий).","lo":1,"hi":7,"s":[[1,"Анна Павловна, прикрыв одной рукой глаза от солнца, другой указывала сыну попеременно на каждый предмет."],[2,"— Погляди-ка, — говорила она, — какой красотой Бог одел поля наши!"],[3,"Вон с тех полей одной ржи до пятисот четвертей сберём; а вон и пшеничка есть, и гречиха."],[4,"А лес-то как разросся!"],[5,"Дровец с своего участка мало-мало на тысячу продадим."],[6,"А дичи, дичи что!"],[7,"И ведь всё это твоё, милый сынок: я только твоя приказчица."]],"a":[4,7],"why":"В данном отрывке есть два предложения, которые связаны с предыдущими при помощи указанных в задании средств. В предложении 4 использовано личное местоимение «(у) него» (форма местоимения «он»), заменяющее существительное «автор» из предложения 3. Кроме того, в этом предложении есть существительное «жизнь» (единственное число, винительный падеж: исключающей – что? – жизнь), являющееся формой существительного «жизнь» (единственное число, именительный падеж) из предложения 3. В предложении 7 употреблено личное местоимение «(на) неё» (форма местоимения «она»), заменяющее существительное «незабудкой» из предложения 6. Также в предложении 7 есть существительное «незабудка» (единственное число, именительный падеж), форма которого использована в 6-м («незабудкой» – единственное число, творительный падеж).\n \nОбратите внимание: в предложении 2 использовано личное местоимение «нам», однако оно не является средством связи предложений, поскольку в предложении 1 нет существительного, которое заменялось бы этим местоимением. В предложениях 2 и 5 используются притяжательные местоимения: «в бездушии – чьём? – её» и «со звёздами – чьими? – его» (не путайте с личными местоимениями «она» и «он» в соответствующих формах).","verifiedBy":"ключ источника"},{"id":"S150562","source":"Школково","prompt":"Среди предложений 1-8 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения. Запишите номер(а) этого(-их) предложения(-ий).","lo":1,"hi":8,"s":[[1,"Счастлив путник, который после длинной, скучной дороги с её холодами, слякотью, грязью, невыспавшимися станционными смотрителями, бряканьями колокольчиков, починками, перебранками, ямщиками, кузнецами и всякого рода дорожными подлецами видит наконец знакомую крышу с несущимися навстречу огоньками, и предстанут пред ним знакомые комнаты, радостный крик выбежавших навстречу людей, шум и беготня детей и успокоительные тихие речи, прерываемые пылающими лобзаниями, властными истребить всё печальное из памяти."],[2,"Счастлив семьянин, у кого есть такой угол, но горе холостяку!"],[3,"Счастлив писатель, который мимо характеров скучных, противных, поражающих печальною своею действительностью, приближается к характерам, являющим высокое достоинство человека, который из великого омута ежедневно вращающихся образов избрал одни немногие исключения, который не изменял ни разу возвышенного строя своей лиры, не ниспускался с вершины своей к бедным, ничтожным своим собратьям и, не касаясь земли, весь повергался в свои далеко отторгнутые от неё и возвеличенные образы."],[4,"Вдвойне завиден прекрасный удел его: он среди них как в родной семье; а между тем далеко и громко разносится его слава."],[5,"Он окурил упоительным куревом людские очи; он чудно польстил им, сокрыв печальное в жизни, показав им прекрасного человека."],[6,"Всё, рукоплеща, несётся за ним и мчится вслед за торжественной его колесницей."],[7,"Великим всемирным поэтом именуют его, парящим высоко над всеми другими гениями мира, как парит орёл над другими высоко летающими."],[8,"При одном имени его уже объемлются трепетом молодые пылкие сердца, ответные слёзы ему блещут во всех очах..."]],"a":[6],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанного в задании средства. Предложение 6 содержит притяжательное местоимение «моими», относящееся к личному местоимению «я» из предложения 5. \n \nОбратите внимание: в предложении 1 есть притяжательное местоимение «мои», однако оно априори не может связывать два предложения. Притяжательное местоимение «своего» также не связывает предложение 5 с предыдущим (речь идёт об отце и матери, которые занимались устройством хозяйства; они упоминаются именно в 5-ом предложении), а предложение 8 не связано с 7-м при помощи притяжательного местоимения «нашими», так как оно не заменяет личное местоимение или существительное из предыдущего предложения.\nОтвет: 6\nРазобрать с репетитором\nКурсы\nВсё необходимое для достижения цели","verifiedBy":"ключ источника"},{"id":"S150564","source":"Школково","prompt":"Среди предложений 10-15 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи лексического повтора. Запишите номер(а) этого(-их) предложения(-ий).","lo":10,"hi":15,"s":[[10,"Здешний селянин, как будто увидев надежду полей своих, с ним погибшую, останавливает соху на незаконченной борозде."],[11,"«Кто защитит плоды трудов моих, — восклицает он, — когда судьба отняла у нас защитника?!»"],[12,"Мать ведёт детей своих к гробу великого."],[13,"«Он был спаситель своего Отечества, — говорит она."],[14,"Поклонитесь его праху и молитесь, чтобы Всевышний послал Родине подобного заступника!»"],[15,"Но как словами представить сердечное сокрушение российских воинов?"]],"a":[14],"why":"В данном отрывке есть одно предложение, связанное с предыдущим при помощи указанного в задании средства. Предложение 14 начинается с личного местоимения «ему» (дательный падеж), с этого же слова в той же форме начинается и предложение 13; кроме того, лексическим повтором, связывающим два предложения, также выступает местоимение «им» (творительный падеж) – оно используется в обоих предложениях. \n \nОбратите внимание: в предложении 11 повторяется личное местоимение «ему», а в предложении 15 – конструкция «ибо не признаёт современный суд», однако это связь при помощи лексического повтора внутри ОДНОГО И ТОГО ЖЕ предложения, а не между соседними предложениями. В предложении 15 используется существительное «в перл – чего? – созданья» (единственное число, родительный падеж), а в предложении 14 это слово употреблено в другой форме – «назовёт ничтожными и низкими – кого? что? – созданья» (множественное число, винительный падеж) => перед нами формы слова, а не лексический повтор.\n\nВажно! Это задание составлено некорректно. В «Навигаторе» от ФИПИ говорится, что явление грамматических вариантов учитывается: например, такие словоупотребления, как «её» – «(у) неё» («она» в форме родительного падежа), также считаются лексическим повтором при условии, что оба местоимения отнесены к одному и тому же лицу. В приведённом отрывке упомянутые грамматические варианты используются: «(11)Ему не собрать народных рукоплесканий, ему не зреть признательных слёз и единодушного восторга взволнованных им душ. (12)К нему не полетит навстречу шестнадцатилетняя девушка с закружившеюся головою и геройским увлеченьем. (13)Ему не позабыться в сладком обаянье им же исторгнутых звуков». Условие, описанное в «Навигаторе», соблюдено: местоимения отнесены к одному лицу – речь идёт о писателе; используются грамматические варианты формы дательного падежа местоимения «он» («ему» – «(к) нему» – «ему»); лексический повтор выступает как средство связи. Следовательно, предложения 12 и 13 также должны пойти в ответ.\nОтвет: 14\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S150565","source":"Школково","prompt":"Среди предложений 10-17 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения и синонимов. Запишите номер(а) этого(-их) предложения(-ий).","lo":10,"hi":17,"s":[[10,"Но вот я дунул в неё, и она стала похожа на человеческую руку."],[11,"Что-то, чего я понять не мог, дунуло в глубину моего скомканного, измученного, искалеченного существа и выпрямило меня, мурашками оживающего тела пробежало там, где уже, казалось, не было чувствительности, заставило всего «хрустнуть» именно так, когда человек растёт, заставило также бодро проснуться и наполнило расширившуюся грудь, весь выросший организм свежестью и светом."],[12,"Мне невозможно было даже мысли допустить, чтобы в эту минуту я мог подумать жить чем-нибудь таким, что составляло простую житейскую необходимость той поры, то есть того времени, когда я был скомканной перчаткой."],[13,"Опять позволить скомкать себя так, как это было час тому назад и всю жизнь до этого часа?"],[14,"Нет, нет!"],[15,"Я не мог даже есть, пить в этот день, до такой степени мне казалось это ненужным и обидным для того нового, что я бережно нёс в себе."],[16,"С этого дня я почувствовал не то что потребность, а прямо необходимость, неизбежность самого, так сказать, безукоризненного поведения: сказать что-нибудь не то, что до́лжно, хотя бы даже для того, чтобы не обидеть человека, смолчать о чём-нибудь нехорошем, затаив его в себе, сказать пустую, ничего не значащую фразу единственно из приличия, делать какое-нибудь дело, которое могло бы отозваться в душе малейшим стеснением или, напротив, могло малейшим образом стеснить чужую душу, теперь, с этого памятного дня, сделалось немыслимым."],[17,"Это значило потерять счастие ощущать себя человеком, которое мне стало знакомо и которое я не смел желать убавить даже на волосок."]],"a":[14],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. В предложении 14 использовано притяжательное местоимение «его» (не путать с формой личного местоимения «он»: праху (чьему?) его), относящееся к личному местоимению «он» из предложения 13. Кроме того, в этом предложении есть существительное «Родине», являющееся синонимом существительному «Отечества» из предложения 13.\n\nОбратите внимание: в предложениях 10-13 используются притяжательные местоимения «своих», «моих», «своих», «своего» соответственно, однако связь осуществляется внутри указанных предложений (притяжательное местоимение является средством связи тогда, когда оно заменяет существительное или личное местоимение из предыдущего предложения; в данном случае этого не наблюдается); кроме того, упомянутые предложения не связаны с предыдущими при помощи синонимов, что также противоречит условию задания.\nОтвет: 14\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S150566","source":"Школково","prompt":"Среди предложений 5-11 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи форм(ы) слов(а) и личного местоимения. Запишите номер(а) этого(-их) предложения(-ий).","lo":5,"hi":11,"s":[[5,"Мне нетерпеливо хотелось обнять её и поблагодарить за снисхождение к моим бросаниям из стороны в сторону, к моим отступлениям против её желаний, – за всё, что она для меня сделала."],[6,"Я ждал минуты, когда увижу старого Николая, бывшего отцовского слугу, носившего меня на руках и любившего меня, будто родного сына."],[7,"Я вспоминал, как Николай часами караулил, когда меня пустят гулять, брал на руки, водил по полям и рощам, рассказывал разные истории и сказки."],[8,"Сердце моё окончательно размягчилось, когда при въезде на последний пригорок передо мной открылась долина речки Смедвы."],[9,"Сама Смедва блеснула в своих изгибах, замкнутых зеленеющими склонами с их рощами, когда в глубине обрисовался тёмный старый сад с его липовыми аллеями и подле него крыша нашего дома."],[10,"Когда тарантас въехал на двор, матушка стояла на крыльце и махала платком, из-за её плеча выглядывал чепец бабушки."],[11,"Николай, окончательно поседевший, белый как лунь, и дворовые окружили меня."]],"a":[8],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. В предложении 8 использовано личное местоимение «она», заменяющее существительное «перчатку» из предложения 7. Кроме того, в нём есть существительное «руку» (единственное число, винительный падеж), форма которого использована в предложении 7 («(в) руке» – единственное число, предложный падеж).\n \nОбратите внимание: личное местоимение является средством связи только тогда, когда оно заменяет существительное из предыдущего предложения, поэтому предложения 5, 6, 7, 10, 11, в которых использованы личные местоимения, в ответ не войдут. Кроме того, важно помнить о том, что, согласно заявлениям составителей, первое предложение из диапазона (в нашем случае – 5-е) не может войти в ответ.\nОтвет: 8\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S150567","source":"Школково","prompt":"Среди предложений 15-20 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения и лексических повторов. Запишите номер(а) этого(-их) предложения(-ий).","lo":15,"hi":20,"s":[[15,"Во владельце стала заметнее обнаруживаться скупость; сверкнувшая в жёстких волосах его седина, верная подруга её, помогла ей ещё более развиться."],[16,"Учитель-француз был отпущен, потому что сыну пришла пора на службу; мадам была прогнана, потому что оказалась не безгрешною в похищении Александры Степановны."],[17,"Сын определился в полк и написал отцу уже по своём определении, прося денег на обмундировку; весьма естественно, что он получил на это то, что называется в простонародии шиш."],[18,"Наконец, последняя дочь, остававшаяся с ним в доме, умерла, и старик очутился один сторожем, хранителем и владетелем своих богатств."],[19,"Одинокая жизнь дала сытную пищу скупости, которая, как известно, имеет волчий голод и чем более пожирает, тем становится ненасытнее."],[20,"Человеческие чувства, которые и без того не были в нём глубоки, мелели ежеминутно, и каждый день что-нибудь утрачивалось в этой изношенной развалине."]],"a":[18],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. В предложении 18 есть слова «тишина» (единственное число, именительный падеж), «меня» (винительный падеж), «я» (именительный падеж), употреблённые в тех же формах в предложении 17 (=> лексический повтор). Также в нём использовано указательное местоимение «эта», указывающее на тишину, упомянутую в предложении 17.\n\nОбратите внимание: в предложениях 16, 19, 20 есть личные местоимения «я» (именительный падеж), использующиеся в той же форме в предложениях 15, 18, 19 соответственно (=> лексический повтор). Однако в ответ идут только те предложения, которые содержат все указанные в задании средства связи.\nОтвет: 18\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S150568","source":"Школково","prompt":"Среди предложений 1-9 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного и личного местоимений. Запишите номер(а) этого(-их) предложения(-ий).","lo":1,"hi":9,"s":[[1,"Любовь к животным была тоже выдающейся чертой этого странного человека Игнатовича."],[2,"Бывали целые периоды, когда наше скромное жильё положительно превращалось в лечебницу."],[3,"Целую неделю он возился с замёрзшей вороной, которую вернул к жизни, а больную лошадь водил в поводу на прогулку по два раза в день, не смущаясь насмешками."],[4,"И замечательно, что чем более он сердился на человека, тем более нежности отдавал животным."],[5,"Он не только признавал в них ум, память, соображение, совесть, но даже считал эти стороны интеллекта исключительно их принадлежностью, совершенно чуждой человеку..."],[6,"При этом он становился дьявольски, невыносимо остроумен и саркастичен, и порой мне некуда было скрыться в периоды его мизантропии, я совершенно изнемогал под градом его парадоксов и начинал, право же, чувствовать себя действительно ниже всякого скота, в то время как какая-нибудь собака со спиной, перешибленной поленом досужего бездельника, казалась мне чуть не сознательным страдальцем и философом."],[7,"Впрочем, когда эти припадки проходили, он опять оживал, опять парил под небесами и декламировал «мировые симфонии»."],[8,"В то время он тоже получил место на прииске, что-то вроде смотрителя материального склада..."],[9,"В практических вопросах я всегда имел преимущество."]],"a":[5],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. В предложении 5 использовано притяжательное местоимение «его» (не путать с формой личного местоимения «он»: в чертах лица (чьего?) его), указывающее на существительное «хозяина» из предложения 4. Также в этом предложении есть личное местоимение «его» (не путать с притяжательным местоимением «его»: приятно слушать (кого?) его), заменяющее существительное «хозяина» из предложения 4.\n\nОбратите внимание: в предложении 8 есть притяжательное местоимение «его», указывающее на существительное «учителя-француза» из предложения 7, однако в ответ идут только те предложения, которые содержат все указанные в задании средства связи. В предложениях 1-2 используются личные местоимения «он» и «к нему», «у него» соответственно, но они не заменяют существительные из предыдущих предложений и не содержат притяжательных местоимений => в ответ не идут.\nОтвет: 5\nРазобрать с репетитором\nРазберите ошибки с репетитором\nПервое занятие бесплатно. Преподаватель объяснит трудные задания варианта","verifiedBy":"ключ источника"},{"id":"S150569","source":"Школково","prompt":"Среди предложений 13-21 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Запишите номер(а) этого(-их) предложения(-ий).","lo":13,"hi":21,"s":[[13,"Как ели сеют своими шишками, так и люди берутся за кисть, за перо, за смычок, чтобы один вырос и дал посев."],[14,"Природа, как и жизнь, не поддаётся логическому определению; и спроси́те любого, что он понимает в слове «природа»."],[15,"Никто не даст всеохватывающего определения: одному – это дрова и стройматериалы, другому – цветы и пенье птиц, третьему – небо, четвёртому – воздух, и так без конца."],[16,"И в то же время каждый человек понимает, что это не всё."],[17,"Нечто большее, чем личный интерес, мы почувствовали к природе во время Великой Отечественной войны, мы понимали: это Родина, наш дом."],[18,"Природа явилась нам как Родина, и Родина-мать обратилась в Отечество."],[19,"Почему же чувство Родины овладевает нами, когда мы слышим крик родной птицы, слышанной в детстве, или песенку, или запах скромного цветка?"],[20,"Каждый из нас, путешествуя, непременно что-нибудь открывает для себя вдали новое."],[21,"И вернувшись домой, открывает глаза на знакомое и обогащает и расширяет свою родину: чувство Родины есть движение к свету."]],"a":[16,17],"why":"В данном отрывке есть два предложения, которые связаны с предыдущими при помощи указанного в задании средства. В предложении 16 использовано личное местоимение «(из) них» («они» в форме родительного падежа), заменяющее существительное «полыньи» из предложения 15. В предложении 17 использовано личное местоимение «(на) них» («они» в форме винительного падежа), заменяющее существительное «уток» из предложения 16.\n\nОбратите внимание: личное местоимение является средством связи только тогда, когда оно заменяет существительное из предыдущего предложения, поэтому предложения 13 и 18, в которых использованы личные местоимения, в ответ не войдут. Кроме того, важно помнить о том, что, согласно заявлениям составителей, первое предложение из диапазона (в нашем случае – 13-е) не может войти в ответ.","verifiedBy":"ключ источника"},{"id":"S150572","source":"Школково","prompt":"Среди предложений 5-9 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза, лексических повторов, форм(ы) слов(а) и антонимов. Запишите номер(а) этого(-их) предложения(-ий).","lo":5,"hi":9,"s":[[5,"Не чувствуешь любви к людям – сиди смирно, занимайся собой, вещами, чем хочешь, но только не людьми."],[6,"Только начни обращаться с людьми без любви – и в один миг станешь не человеком, а зверем: и людям повредишь и себя замучаешь."],[7,"Если ты обижен человеком, то на обиду ты можешь отвечать, как собака, как корова, как лошадь: либо бежать от обидчика, если обидчик сильнее тебя, либо огрызаться, бодаться, брыкаться."],[8,"А можешь отвечать на обиду как разумный человек – можешь сказать себе: человек этот обидел меня, это его дело; моё же дело – делать то, что я считаю хорошим: делать ему то, чего я себе желаю."],[9,"Когда видишь людей, всегда всем недовольных, всех и всё осуждающих, хочется сказать им следующие слова: «Ведь вы не затем живёте, чтобы понять нелепость жизни, осудить её, посердиться и умереть."]],"a":[6],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. Предложение 6 начинается с сочинительного противительного союза «НО», который позволяет выразить контраст между мыслями, содержащимися в предложениях 5 и 6. Кроме того, оно содержит существительное «человек» (единственное число, именительный падеж), которое используется в той же форме в предложении 5 (=> лексический повтор), существительное «(в) природе» (единственное число, предложный падеж), являющееся формой существительного «природа» (единственное число, именительный падеж) из предложения 5, и глагол «умирает», являющийся антонимом глаголу «рождается» из предложения 5.\n\nОбратите внимание: в предложении 7 использован глагол «умирает» (единственное число, 3-е лицо), употреблённый в той же форме в предложении 6 (=> лексический повтор), а также существительные «(в) природу» (единственное число, винительный падеж) и «врагами» (множественное число, творительный падеж), формы которых есть в предложении 6 («(в) природе» – единственное число, предложный падеж; «врагов» – множественное число, родительный падеж). В предложении 8 есть существительные «природа» (единственное число, именительный падеж) и «борьбы» (единственное число, родительный падеж), формы которых использованы в предложении 7 («(в) природу» – единственное число, винительный падеж; «(в) борьбе» – единственное число, предложный падеж). В предложении 9 использовано существительное «природа» (единственное число, именительный падеж), употреблённое в той же форме в предложении 8 (=> лексический повтор), и существительное «человеку» (единственное число, дательный падеж), являющееся формой существительного «человека» (единственное число, родительный падеж) из предложения 8. Однако в ответ идут только те предложения, которые содержат все указанные в задании средства связи.\nОтвет: 6\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S150574","source":"Школково","prompt":"Среди предложений 1-5 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи форм(ы) слов(а). Запишите номер(а) этого(-их) предложения(-ий).","lo":1,"hi":5,"s":[[1,"Однажды Александр Иванович Куприн в разговоре о великом Льве Николаевиче Толстом выразился таким образом: «Старик нас всех обокрал: за что ни возьмёшься – уж им написано»."],[2,"Шутливость замечания этого очевидна, и всё-таки так велико, так разнообразно художественное наследие Толстого, так разносторонне, на протяжении полувека изображена им жизнь русского общества, что, заменив слово «обокрал» словом «предупредил», приходится согласиться с А.И. Куприным по существу дела."],[3,"Толстым не оставлено без внимания ни малейшее душевное движение человеческое."],[4,"Читая «Анну Каренину», с изумлением, с подавленностью убеждаешься, что здесь изображена главным образом вся русская жизнь того времени, вся русская душа в её целом, а уж затем, в огромном узоре этом, в этой сплошной толпе лиц, страданий, судеб, уделяешь необходимое внимание собственно романтической интриге."],[5,"Толстой как художник является демократом в самом возвышенном значении этого слова."]],"a":[3,4],"why":"В данном отрывке есть два предложения, которые связаны с предыдущими при помощи указанного в задании средства. Предложение 3 начинается с личного местоимения «ему» (дательный падеж), которое является формой личного местоимения «он» (именительный падеж) из предложения 2. В предложении 4 есть личное местоимение «он» (именительный падеж), форма которого употреблена в предложении 3 («ему» – дательный падеж), в предложении 4 также содержится определительное местоимение «всем» (творительный падеж), форма которого употреблена в предложении 3 («всего» – родительный падеж).","verifiedBy":"ключ источника"},{"id":"S150575","source":"Школково","prompt":"Среди предложений 18-24 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи лексического повтора и форм(ы) слов(а). Запишите номер(а) этого(-их) предложения(-ий).","lo":18,"hi":24,"s":[[18,"Может быть, все ушли из него и забыли нас, маленьких девочек, прижавшихся к окну в тёмной огромной комнате?"],[19,"Около своего плеча вижу испуганный, круглый глаз сестры."],[20,"Она смотрит на меня – заплакать ей или нет?"],[21,"И тут я вспоминаю моё сегодняшнее дневное впечатление, такое яркое, такое красивое, что забываю сразу и тёмный дом, и тускло-тоскливую улицу."],[22,"— Лена! — говорю я громко и весело."],[23,"Я сегодня видела конку!"],[24,"Я не могу рассказать ей всё о том безмерно радостном впечатлении, какое произвела на меня конка."]],"a":[22],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. В предложении 22 использовано существительное (имя собственное) «Россия» (именительный падеж), употреблённое в той же форме в предложении 21 (=> лексический повтор), а также существительное (имя собственное) «(в) Толстом» (предложный падеж), являющееся формой существительного (имени собственного) «Толстой» (именительный падеж) из предложения 21.\n\nОбратите внимание! Предложения 19 и 24 не связаны с предыдущими при помощи форм слова: «он» – личное местоимение, а «его» из 18-го – притяжательное (произведений – чьих? – его); «она» – личное местоимение, а «её» из 23-го – притяжательное (лик – чей? – её). Это местоимения разных разрядов => разные слова.\nОтвет: 22\nРазобрать с репетитором\nИнтенсивы\nГлубокий разбор тем, требующих дополнительного внимания","verifiedBy":"ключ источника"},{"id":"S150576","source":"Школково","prompt":"Среди предложений 12-17 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(а) этого(-их) предложения(-ий).","lo":12,"hi":17,"s":[[12,"Чехову не нравилась Европа."],[13,"Нет, например, описаний музеев, упоминаний о шедеврах живописи."],[14,"Правда ли, что не нравилась?"],[15,"Этот вопрос остаётся, пожалуй, открытым."],[16,"Я не могу вспомнить имени какого-либо великого русского или европейского художника в произведениях Чехова."],[17,"Никаких появившихся, скажем, по ассоциации воспоминаний о Рафаэле, или Рубенсе, или Рембрандте."]],"a":[17],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанного в задании средства. В предложении 17 использовано личное местоимение «он», заменяющее существительное «дом» из предложения 16.\n\nОбратите внимание: личное местоимение является средством связи только тогда, когда оно заменяет существительное из предыдущего предложения, поэтому предложения 12-16, в которых использованы личные местоимения, в ответ не войдут. Так, предложение 13 связано с 12-м, а 14-е – с 13-м при помощи лексических повторов местоимения «мы»; предложение 15 связано с 14-м при помощи формы слова («мы» – именительный падеж, «нам» – дательный); 16-е предложение связано с 15-м при помощи лексического повтора местоимения «нам». Кроме того, важно помнить о том, что, согласно заявлениям составителей, первое предложение из диапазона (в нашем случае – 12-е) не может войти в ответ.\nОтвет: 17\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S150577","source":"Школково","prompt":"Среди предложений 25-33 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи вводного слова (сочетания слов) и форм(ы) слов(а). Запишите номер(а) этого(-их) предложения(-ий).","lo":25,"hi":33,"s":[[25,"Все настроения равноценны в искусстве, ибо ни одно не повторится."],[26,"Каждое дорого уже потому, что оно единственное."],[27,"Чем яснее поймёт кто свою душу, тем чище и возвышеннее будут его думы и чувства."],[28,"Стремление глубже понять себя, идти всё вперёд, уже святыня."],[29,"Нет осуждения думам и чувствам истинного художника."],[30,"Иное в отдельности ещё неполная правда, но, как часть души, может быть необходимым."],[31,"Тот более велик из художников, кто глубже понял и полнее пересказал свою душу."],[32,"Это наша ограниченность делит художников на великих и меньших."],[33,"В малом мире человека, как в великом мире вселенной, всё находится в связи, всё дышит взаимным согласием."]],"a":[31],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. Предложение 31 начинается с вводного слова «конечно», относящегося к категории «уверенность», также в нём есть личное местоимение «(у) меня» (родительный падеж), являющееся формой личного местоимения «я» (именительный падеж) из предложения 30. \n\nОбратите внимание: в предложении 28 есть вводная конструкция «может быть», а в предложении 29 – вводные слова «скажем». В предложении 26 использовано существительное (имя собственное) «Чехова» (родительный падеж) и существительное «писателях» (множественное число, предложный падеж), являющиеся формами существительного (имени собственного) «Чехов» (именительный падеж) и существительного «писателем» (единственное число, творительный падеж) из предложения 25 соответственно. В предложении 32 употреблено личное местоимение «я» (именительный падеж), форма которого есть в предложении 31 («(у) меня» – родительный падеж). Однако в ответ идут только те предложения, которые содержат все указанные в задании средства связи; к тому же вводные слова, употреблённые в предложении 29, не связывают его с предыдущим.\nОтвет: 31\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S150169","source":"Школково","prompt":"Среди предложений 14-23 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза, указательного местоимения и форм(ы) слов(а). Запишите номер(а) этого(-их) предложения(-ий).","lo":14,"hi":23,"s":[[14,"В комнате у Ивана Петровича."],[15,"Когда я утомлюсь совершенно, до полного отупения, то всё бросаю и бегу сюда, и вот забавляюсь этой штукой час-другой..."],[16,"Иван Петрович и Софья Александровна щёлкают на счётах, а я сижу подле них за своим столом и мажу – и мне тепло, покойно, и сверчок кричит."],[17,"Но это удовольствие я позволяю себе не часто, раз в месяц... (Показывая на картограмме.)"],[18,"Теперь смотрите сюда."],[19,"Картина нашего уезда, каким он был 50 лет назад."],[20,"Тёмно- и светло-зелёная краска означает леса; половина всей площади занята лесом."],[21,"Где по зелени положена красная сетка, там водились лоси, козы..."],[22,"Я показываю тут и флору, и фауну."],[23,"На этом озере жили лебеди, гуси, утки, и, как говорят старики, птицы всякой было видимо-невидимо: носилась она тучей."]],"a":[17,23],"why":"В данном отрывке есть два предложения, которые связаны с предыдущими при помощи указанных в задании средств. Предложение 17 начинается с сочинительного противительного союза «А». Кроме того, в нём использовано существительное «личину» (единственное число, винительный падеж), форма которого есть в предложении 16 («личин» – множественное число, родительный падеж). Также в предложении 17 есть указательное местоимение «такую», указывающее на одну из личин, упомянутых в предложении 16.\nПредложение 23 начинается с сочинительного противительного союза «НО». Кроме того, в нём использовано существительное «раздумьям» (множественное число, дательный падеж), являющееся формой существительного «раздумья» (множественное число, именительный падеж) из предложения 22. Также в предложении 23 есть указательное местоимение «этим», указывающее на раздумья, упомянутые в предложении 22.\n\nВажно: в ответ нужно выписать все предложения, содержащие указанные в задании средства связи, иначе ответ не будет засчитан.","verifiedBy":"ключ источника"},{"id":"S150170","source":"Школково","prompt":"Среди предложений 17-23 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи однокоренного слова. Запишите номер(а) этого(-их) предложения(-ий).","lo":17,"hi":23,"s":[[17,"Способ придушения, наиболее распространённый ввиду своей доступности, – он требует только двух здоровых рук, – удобен ещё в том смысле, что даёт возможность критику рассмотреть «язык» у придушенного и таким образом определить и стиль."],[18,"И чем критик безразличнее, чем менее доступна ему разница между розой и лопухом; чем более он слеп, глух и бестолков, тем продуктивнее его работа и тем больше он приближается к возвышенному образу Фемиды с завязанными глазами или сурового Рока."],[19,"Ум, чуткость, широкий взгляд на мир, талант и образованность вредны критику."],[20,"Способность к увлечениям – также."],[21,"И наоборот: наилучшим орудием критика в борьбе является невежество и безразличие к судьбам искусства и людей."],[22,"Только при наличии этих условий критик приобретает ту великую и непобедимую свободу в борьбе с талантом, которая позволяет ему без оглядки шельмовать Достоевского, находить бездарным Льва Толстого и «Ревизора» признавать фарсом."],[23,"Как бы он осмелился закидать камнями «Анну Каренину» или «Братьев Карамазовых», не носи он столь твёрдого панциря, не будь он глух и слеп!"]],"a":[21],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанного в задании средства. В предложении 21 использовано существительное «зелени» (корень – -ЗЕЛЕН-), являющееся однокоренным сложному прилагательному «светло-зелёная» (корни – -СВЕТ- и -ЗЕЛЁН-) из предложения 20.\nОтвет: 21\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S150172","source":"Школково","prompt":"Среди предложений 3-8 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи союза и указательного местоимения. Запишите номер(а) этого(-их) предложения(-ий).","lo":3,"hi":8,"s":[[3,"На угрозу пытки и смерти неустрашимый юноша протянул руку над огнём пылающего жертвенника и сжёг её, не дрогнув ни одним мускулом лица."],[4,"Не глядя на горящую руку, он говорил царю: — Царь, люди моей Родины не боятся войны."],[5,"Они не боятся страданий, лишений и смерти."],[6,"Мы не допустим тебя в наш город Рим."],[7,"Сегодня триста таких же смелых, как я, юношей поклялись умереть или убить тебя до восхода луны..."],[8,"Двадцать пять веков славит человечество этот подвиг."]],"a":[5],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. Предложение 5 начинается с сочинительного противительного союза «НО», кроме того, в нём использовано указательное местоимение «это», указывающее на описанный в предложении 4 результат покровительства таланту.\n\nОбратите внимание: в предложениях 4 и 7 используются союзы, однако они не связывают эти предложения с предыдущими и выполняют свои функции внутри одного и того же предложения. Важно помнить о том, что в ответ идут только те предложения, которые содержат все указанные в задании средства связи (именно поэтому предложение 8, в котором в качестве средства связи используется сочинительный союз «И», не идёт в ответ).\nОтвет: 5\nРазобрать с репетитором\nНаборы\nКомбо-тарифы сразу по нескольким предметам","verifiedBy":"ключ источника"},{"id":"S150174","source":"Школково","prompt":"Среди предложений 10-16 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения, контекстных синонимов и форм(ы) слов(а). Напишите номер(а) этого(-их) предложения(-ий).","lo":10,"hi":16,"s":[[10,"Но должник её был травленый зверь и всё равно ни на какие её письма не отвечал."],[11,"А между тем время уходит, приближается срок закладной – и перед бедной женщиной, которая уповала дожить свой век в своём домишке, вдруг разверзается страшная перспектива холода и голода с увечной дочерью и маленькою внучкою."],[12,"Старушка в отчаянии поручила свою больную и ребёнка доброй соседке, а сама собрала кое-какие крохи и полетела в Петербург «хлопотать»."],[13,"Хлопоты её вначале были очень успешны: адвокат ей встретился участливый и милостивый, и в суде ей решение вышло скорое и благоприятное."],[14,"Но как дошло дело до исполнения – тут и пошла закорюка, да такая, что и ума к ней приложить было невозможно."],[15,"Не то чтобы полиция или иные какие приставы должнику мирволили – говорят, что тот им самим давно надоел и что они все старушку очень жалеют и рады ей помочь, да не смеют..."],[16,"Было у него какое-то такое могущественное родство или свойство, что нельзя было его приструнить, как всякого иного грешника."]],"a":[16],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. В предложении 16 использовано указательное местоимение «этого», указывающее на «лешего», упомянутого в предложении 15. Кроме того, в нём есть существительное «леший» (единственное число, именительный падеж), форма которого использована в предложении 15 («лешего» – единственное число, винительный падеж). Также в предложении 16 использовано слово «самодура», которое в данном контексте является синонимом к слову «лешего» из предложения 15.\n \nОбратите внимание: в предложениях 12, 13 и 14 есть существительное «вольницей», оно используется в одной и той же форме (единственное число, творительный падеж) => перед нами связь при помощи лексического повтора, а не форм слова. \nПри этом использованное в предложении 12 существительное «вольницей» (единственное число, творительный падеж) является формой существительного «вольница» (единственное число, именительный падеж) из предложения 11. А в предложении 13 использован глагол «зовёт» (настоящее время), форма которого есть в предложении 12 («звал» – прошедшее время). Однако в ответ идут только те предложения, которые содержат все указанные в задании средства связи.\nВажно: слово «того» в предложении 12 используется в составе вводной конструкции «кроме того» => связь при помощи указательного местоимения не осуществляется.\nОтвет: 16\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S150175","source":"Школково","prompt":"Среди предложений 1-7 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи однокоренных слов и форм(ы) слов(а). Напишите номер(а) этого(-их) предложения(-ий).","lo":1,"hi":7,"s":[[1,"Надя, голубка, ты пишешь, что тебя пугает наше счастье."],[2,"Боже мой!"],[3,"И меня оно иногда пугает – так оно велико."],[4,"Иногда мне кажется, что это всё просто сон и что вот проснись – всё исчезнет."],[5,"В эти минуты мне так тяжело."],[6,"Одна из таких минут была, когда я получил твоё предпоследнее письмо, на которое вчера ответил."],[7,"Но зато, прочитав его, я более чем когда-нибудь убедился, что это не сон, что мы любим друг друга и что мы сойдёмся."]],"a":[3],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. В предложении 3 использовано существительное «дом» (корень – -ДОМ-), а в предложении 2 – однокоренное ему существительное «домик» (корень – -ДОМ-, суффикс – -ИК-). В предложении 3 также есть существительное «франт» (именительный падеж, единственное число), форма которого есть в предложении 2 («франта» – единственное число, родительный падеж).\n\nОбратите внимание: в предложениях 4, 5 и 6 есть существительное «старушка», а в предложениях 1 и 2 – существительное «дело», они используются в одной и той же форме (единственное число, именительный падеж) => перед нами связь при помощи лексического повтора, а не форм слова. В предложении 7 есть личное местоимение «он» (именительный падеж), форма которого использована в предложении 6 («ему» – дательный падеж), однако в ответ идут только те предложения, которые содержат все указанные в задании средства связи.\nОтвет: 3\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S150176","source":"Школково","prompt":"Среди предложений 12-15 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи лексического повтора. Запишите номер(а) этого(-их) предложения(-ий).","lo":12,"hi":15,"s":[[12,"Они жили и раньше, во всех веках, среди всех народов, но, ещё бескрылые, проходили в жизни незаметно, тоскуя смутно по неведомым воздушным сферам, или в судорожных попытках умерли безвестно, осмеянные безумцы, поруганные, голодные изобретатели."],[13,"— Monsieur, — сказал однажды Блерио1 на парижском аэродроме своему ученику, русскому авиатору, после первого совместного полёта, — с этого дня летайте самостоятельно, я сегодня же выдам вам ваш brevet2."],[14,"Вы родились птицей."],[15,"В самом деле, в них много чего-то от свободных и сильных птиц – в этих смелых, живых и гордых людях."]],"a":[13],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанного в задании средства. В предложении 13 использовано личное местоимение «я» (именительный падеж), которое также есть в предложении 12.\n\nОбратите внимание: в предложении 14 повторяется слово «недоверие», а в предложении 15 – слова «добро», «люди» и «я» => связь при помощи лексического повтора в обоих случаях осуществляется внутри ОДНОГО И ТОГО ЖЕ предложения, а не между соседними предложениями. Кроме того, в предложении 14 используется существительное «(к) людям» (множественное число, дательный падеж), оно является формой существительного «люди» (множественное число, именительный падеж) из предложения 15 => осуществляется связь с помощью форм слова (лексический повтор – повторение слов в одной и той же форме).\nОтвет: 13\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S150177","source":"Школково","prompt":"Среди предложений 11-18 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи притяжательного местоимения. Запишите номер(а) этого(-их) предложения(-ий).","lo":11,"hi":18,"s":[[11,"Без молний и громов, без режущего глазá блеска?"],[12,"Когда я думаю о Пушкине, немедленно и отчётливо представляется мне та Россия, которую я люблю и знаю."],[13,"Я знаю его с той поры, как начал читать."],[14,"Лет семи-восьми, в гостях, я уединился с книгой Пушкина, прочёл «Руслана и Людмилу», и у меня до сего времени, несмотря на тот бессильный читательский возраст, остаётся ясное сознание, что я очень хорошо понимал всё, что читал у Пушкина – в первый раз."],[15,"Путь воплощения строк в образы, а образов – в подлинную действительность был краток, мгновенен и оставил сознание не чтения, а переживания."],[16,"Так было и дальше."],[17,"Входя в книги Пушкина, я переживал всё, что было написано в них, с простотой летнего дня и со всей сложностью человеческой души."],[18,"Так полно переложить в свои книги самого себя, так лукаво, с такой подкупающей улыбкой заставить книгу обернуться Александром Сергеевичем – мог только он один."]],"a":[17],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанного в задании средства. В предложении 17 использовано притяжательное местоимение «их» (не путать с формой личного местоимения «они»: глаза (чьи?) их), относящееся к личному местоимению «(у) них» из предложения 16.\n\nОбратите внимание: в предложении 13 есть притяжательное местоимение «своему», однако оно указывает на принадлежность Блерио, упомянутому в ЭТОМ ЖЕ предложении.\nОтвет: 17\nРазобрать с репетитором\nКурсы\nВсё необходимое для достижения цели","verifiedBy":"ключ источника"},{"id":"S150178","source":"Школково","prompt":"Среди предложений 1-8 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи однокоренных слов. Запишите номер(а) этого(-их) предложения(-ий).","lo":1,"hi":8,"s":[[1,"Однажды вечером, подготовляясь к завтрашнему уроку по проклятой фортификации, Александров громко и злобно чертыхнулся: — Нет, когда же я, чёрт побери, освоюсь с этой фортификационной путаницей, да будут прокляты и она, и полковник Колосов."],[2,"Сосед его по койке, скромный, тихий, благовоспитанный Прибиль, сказал сочувственно: — Послушайте-ка, друг Александров, не сердитесь на то, что я ввязываюсь не в своё дело."],[3,"Я уже давно замечаю, что у вас постоянные недоразумения с фортификацией."],[4,"Мне кажется, что я могу вам немножко помочь, если вы, конечно, позволите."],[5,"Всё дело в сущем пустяке, который можно в одну минуту удалить."],[6,"Вот, например, мой портсигар."],[7,"Предположим, что он вам очень понравился и вам хочется заказать мастеру совершенно точно такой же."],[8,"Что вы для этого делаете?"]],"a":[5],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанного в задании средства. В предложении 5 использовано существительное «суду» (корень – -СУД-), являющееся однокоренным глаголу «судить» (корень – -СУД-, суффикс – -И-) из предложения 4.\n\nОбратите внимание: в предложениях 1 и 2, 3 и 4 используются слова «искусства» и «писать» соответственно. Это одни и те же слова в одной и той же форме => осуществляется связь при помощи лексического повтора, а не однокоренных слов.\nОтвет: 5\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S150180","source":"Школково","prompt":"Среди предложений 17-22 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи контекстных синонимов. Запишите номер(а) этого(-их) предложения(-ий).","lo":17,"hi":22,"s":[[17,"И вот он оставляет своим наследникам рудник в таком положении, что долго и много надобно трудиться, чтобы снова докопаться хотя до того места, до которого он был прежде разработан."],[18,"Всё это было бы легче для наследников, если бы они были богаты; но мог ли владелец, так небрегший о своём благосостоянии, уберечь сокровища, наследованные им?"],[19,"Нет, он оставил им в наследство только жалкие остатки."],[20,"Итак, этот нерадивый владелец не только замедлил разработку рудника на всё время, в которое владел им, но и задержал надолго дальнейшую его разработку и для будущих поколений."],[21,"А когда настоящее поколение умножит массу знаний, им наследованных, тогда, без сомнения, благодетельное влияние его деятельности распространится на всю будущность образования человечества."],[22,"Таким образом, молодое поколение имеет величайшее влияние и на будущие успехи человечества на пути образования."]],"a":[19],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанного в задании средства. В предложении 19 использовано существительное (имя собственное) «Колосов», которое в данном контексте является синонимом к существительному «полковника» из предложения 18.\nОтвет: 19\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S150181","source":"Школково","prompt":"Среди предложений 1-6 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения, частиц, однокоренных слов и форм(-ы) слов(а). Запишите номер(а) этого(-их) предложения(-ий).","lo":1,"hi":6,"s":[[1,"Погода после мокрого снега уже дня три стояла тихая, тёплая и ясная."],[2,"На улицах не видно было клочка снега, грязное тесто заменилось мокрой мостовой и быстрыми ручьями."],[3,"С крыш уже на солнце стаивали последние капели, в палисаднике на деревьях надувались почки, на дворе была сухая дорожка к конюшне мимо замёрзлой кучи навоза, и около крыльца между камнями зеленела мшистая травка."],[4,"Был тот особенный период весны, который сильнее всего действует на душу человека: яркое, на всём блестящее, но не жаркое солнце, ручьи и проталинки, пахучая свежесть в воздухе и нежно-голубое небо с длинными прозрачными тучками."],[5,"Не знаю почему, но мне кажется, что в большом городе ещё ощутимее и сильнее на душу влияние этого первого периода рождения весны, – меньше видишь, но больше предчувствуешь."],[6,"Я стоял около окна, в которое утреннее солнце сквозь двойные рамы бросало пыльные лучи на пол моей невыносимо надоевшей классной комнаты, и решал на чёрной доске какое-то длинное алгебраическое уравнение."]],"a":[6],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи нужных средств. В предложении 6 использовано указательное местоимение «то», указывающее на развитие физических сил, упомянутое в предложении 5. Кроме того, в предложении 6 есть частица «же» (в данном случае стоит после местоимения и употребляется для указания на сходство), существительное «развитием» (приставка – РАЗ-, корень – -ВИ-, суффикс – -ТИ-), являющееся однокоренным глаголу «развиваются» (приставка – РАЗ-, корень – -ВИ-, суффикс – -ВА-) из предложения 5. Также в предложении 6 использовано существительное «сил» (множественное число, родительный падеж), являющееся формой существительного «силы» (множественное число, именительный падеж) из предложения 5.\n\nОбратите внимание: в предложении 1 использованы однокоренные слова «совершенствуется» и «усовершенствование», однако связь осуществляется внутри ОДНОГО И ТОГО ЖЕ предложения, а не между соседними (кроме того, первое предложение из диапазона не может войти в ответ). В предложении 2 есть указательное местоимение «этого», указывающее на совершенствование человеческого рода, упомянутое в предложении 1. Однако в ответ идут только те предложения, которые содержат все указанные в задании средства связи. В предложении 5 есть существительное «силы» (множественное число, именительный падеж), форма которого использована в предложении 4 («(в прежние) силы» – множественное число, винительный падеж), а также глагол «развиваются» (приставка – РАЗ-, корень – -ВИ-, суффикс – -ВА-), являющийся однокоренным существительному «развитие» (приставка – РАЗ-, корень – -ВИ-, суффикс – -ТИ-) из предложения 4. Кроме того, предложение 5 содержит усилительную частицу «и» и указательное местоимение «такие». Однако это местоимение указывает на обстоятельства, описанные в ЭТОМ ЖЕ предложении, а не в предыдущем (такие обстоятельства (какие?), что силы нашего тела развиваются, как говорят, не по дням, а по часам).\nОтвет: 6\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S150182","source":"Школково","prompt":"Среди предложений 4-10 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи лексического повтора и однокоренных слов. Запишите номер(а) этого(-их) предложения(-ий).","lo":4,"hi":10,"s":[[4,"Ну хорошо, дружба возможна."],[5,"А возможна ли любовь?"],[6,"А что такое любовь?"],[7,"А бывает любовь с первого взгляда?"],[8,"Судя по «Евгению Онегину», бывает."],[9,"Но ведь Писарев подвергал сомнению чувство Татьяны и смеялся над ним?"],[10,"Нет, Саша считала, что любви с первого взгляда быть не может."]],"a":[7],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. В предложении 7 есть личное местоимение «я» (именительный падеж), употреблённое в той же форме в предложении 6, а также существительное «Алгебру» (корень – -АЛГЕБР-), являющееся однокоренным прилагательному «алгебраическое» (корень – -АЛГЕБР-, суффиксы – -А-, -ИЧЕСК-) из предложения 6.\n\nОбратите внимание: в предложении 5 есть слова «сильнее», «(на) душу», «весны», использованные в той же форме в предложении 4. Однако в ответ идут только те предложения, которые содержат все указанные в задании средства связи.\nОтвет: 7\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S150183","source":"Школково","prompt":"Среди предложений 26-32 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи указательного местоимения. Запишите номер(а) этого(-их) предложения(-ий).","lo":26,"hi":32,"s":[[26,"Горел Верден, Реймский собор, в котором в своё время бракосочеталась с французским королём дочь Ярослава Мудрого."],[27,"Появились первые танки, и впервые аэропланы стали сбрасывать бомбы."],[28,"Однако в музеях по-прежнему висели необыкновенные картины, прекрасные, как деревья на закате."],[29,"Во сне я иногда вижу своё пребывание в Европе, которого никогда не было."],[30,"Чаще всего мне снится Краков в виде стены, идущей кверху вдоль дороги, – старой стены, с которой свисают растения, стучащие по ней ветками и шелестящие цветами..."],[31,"Я ещё люблю вспоминать."],[32,"Я мало что знаю о жизни."]],"a":[30],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи нужного средства. В предложении 30 использовано указательное местоимение «это», указывающее на неловкость, описанную в предложении 29.\n\nОбратите внимание: в предложении 27 используется указательное местоимение «этот», однако оно не связывает упомянутое предложение с предыдущим, поскольку в нём не говорится о дворе.\nОтвет: 30\nРазобрать с репетитором\nРазберите ошибки с репетитором\nПервое занятие бесплатно. Преподаватель объяснит трудные задания варианта","verifiedBy":"ключ источника"},{"id":"S150185","source":"Школково","prompt":"Среди предложений 20-24 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи наречия, форм(ы) слов(а) и вводного слова. Запишите номер(а) этого(-их) предложения(-ий).","lo":20,"hi":24,"s":[[20,"Повторяю: несчастие в этом случае так глубоко, что никогда не остаётся бесследным."],[21,"Я не говорю о себе лично, но думается, что всякий убеждённый писатель, который испытал на себе влияние такой изолированности, знает, о чём я пишу."],[22,"Всякий, кто встречался и с ненавистью, и с бесчестными передержками, и с равнодушием, и с насмешкой, мечтал о том, чтобы ему улыбнулось прямое, осязательное сочувствие."],[23,"Последнее так далеко порой теряется в читательской массе, что лишь предположительно может ободрить писателя."],[24,"Зато минуты подобного ободрения самые дорогие в жизни."]],"a":[22],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. В предложении 22 использовано наречие «так», указывающее на способ создания произведений, описанный в предложении 21. Кроме того, в предложении 22 есть вводное слово «например», относящееся к категории «связь мыслей», и глагол «писал» (прошедшее время, единственное число), являющийся формой глагола «пишут» (настоящее время, 3-е лицо, множественное число) из предложения 21.\n\nОбратите внимание: в предложении 21 использованы вводные конструкции «так сказать», «может быть» и вводное слово «конечно», но они не связывают упомянутое предложение с предыдущим. В предложении 24 есть наречие «так», указывающее на способ создания произведений, описанный в предложении 23. Однако в ответ идут только те предложения, которые содержат все указанные в задании средства связи.\nОтвет: 22\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S150186","source":"Школково","prompt":"Среди предложений 17-24 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи лексического повтора. Запишите номер(а) этого(-их) предложения(-ий).","lo":17,"hi":24,"s":[[17,"Студент после долгого молчания обернулся ко мне и сказал тихо: — Знаете, на что похожи эти бесконечные огни?"],[18,"Они вызывают во мне представление о чём-то давно умершем, жившем тысячи лет тому назад."],[19,"Когда-то на этом свете жили филистимляне и амалекитяне, вели войны, играли роль, а теперь их и след простыл."],[20,"Так и с нами будет."],[21,"Теперь мы строим железную дорогу, стоим вот и философствуем, а пройдут тысячи две лет, и от этой насыпи и от всех этих людей, которые теперь спят после тяжёлого труда, не останется и пыли."],[22,"— А вы эти мысли бросьте... — сказал инженер серьёзно и наставительно."],[23,"— Почему?"],[24,"— А потому..."]],"a":[22],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанного в задании средства. В предложении 22 есть определительное местоимение «всякий», которое употреблено в предложении 21 в той же форме.\nОтвет: 22\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S150187","source":"Школково","prompt":"Среди предложений 1-11 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения и однокоренных слов. Запишите номер(а) этого(-их) предложения(-ий).","lo":1,"hi":11,"s":[[1,"На фронтах день и ночь, не переставая, идут ожесточённые бои."],[2,"Сталь и железо, выкованные на всех заводах Европы, разрушительным ливнем обрушиваются на наши города и сёла."],[3,"Но ничто уже не может помочь врагу."],[4,"Он отступает."],[5,"Горы трупов его солдат устилают наши степи, леса и поля."],[6,"И эти горы вырастают с каждым шагом, с каждым метром земли, на которую вступала нога неприятеля."],[7,"Враг рвался к победе, но она даётся только тем, у кого чистые помыслы и горячее сердце."],[8,"Она в сердце нашего бойца, отстаивающего честь, свободу и мирный труд Родины."],[9,"Как сказочная царевна, она хранится там за семью замками, ключи от которых в руках доброй волшебницы."],[10,"Люди называют её правдой."],[11,"Эта правда неотделима от любви к матери, любви к своему детству и детству своих детей, неотделима от любви к свободе, к родной земле и ко всем людям Родины."]],"a":[2,6],"why":"В данном отрывке есть два предложения, которые связаны с предыдущими при помощи указанных в задании средств. В предложении 2 использовано личное местоимение «она», заменяющее существительное «собака» из предложения 1, а также глагол «лает» (корень – -ЛА-), являющийся однокоренным глаголу «залаяла» (приставка – ЗА-, корень – -ЛА-, суффиксы – -Я- и -Л-) из 1-го предложения. В предложении 6 использовано личное местоимение «(за) ним» (форма местоимения «он»), заменяющее существительное «огонёк» из предложения 5, а также существительные «огонь» (корень – -ОГОНЬ-) и «огней» (корень – -ОГН-), являющиеся однокоренными существительному «огонёк» (корень – -ОГОН-, суффикс – -ЁК-) из 5-го предложения.\n\nОбратите внимание: в предложении 5 использовано личное местоимение «нас», которое является формой местоимения «мы» из 4-го. А личное местоимение «мы» не связывает предложение 4 с предложением 3, так как не заменяет какое-либо существительное из него (личное местоимение является средством связи только тогда, когда оно заменяет существительное из предыдущего предложения).","verifiedBy":"ключ источника"},{"id":"S16538","source":"Школково","prompt":"Среди предложений 16-24 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи лексического повтора и притяжательного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":16,"hi":24,"s":[[16,"Там ведь, без сомнения, живут другие существа, у которых, может быть, нет столько грубых нужд, как у нас, и потому они, должно быть, против нас лучше, чище, меньше самолюбивы и больше сострадательны и добры…"],[17,"— Но ведь это фантазия, — заметила мама."],[18,"Тётя ей не отвечала."],[19,"— Притом мы все очень грешны – зачем нам мечтать так высоко! — молвила мать, конечно без всякого намёка для тёти."],[20,"Тётя её слышала и произнесла тихо: — Надо подниматься."],[21,"— Да ведь как это сказать…"],[22,"Матушка, кажется, побоялась сбиться с линии, а тётя ничего более не говорила: она озабоченно копошилась, ища что-то в своём дорожном бауле, а Гильдегарда в это время достала из тёмного кожаного футляра что-то такое, что я принял за ручную аптечку, и перешла с этим к окну, в которое смотрелось небо, усеянное звёздами."],[23,"Мама вышла."],[24,"Тётя закрыла баул, подошла к столу, на котором горели две свечки, и обе их потушила, а потом подошла к англичанке и тихо её обняла."]],"a":[22],"why":"В предложении 22 повторяется местоимение «она», которое было употреблено в 21. Кроме того, 22 предложение связано с предыдущим при помощи притяжательного местоимения «его», относящегося к слову «народа»: облик (чей?) его. \nОтвет: 22\nРазобрать с репетитором\nНаборы\nКомбо-тарифы сразу по нескольким предметам","verifiedBy":"ключ источника"},{"id":"S16585","source":"Школково","prompt":"Среди предложений 1-10 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения. Напишите номер(-а) этого(-их) предложения(-ий).","lo":1,"hi":10,"s":[[1,"Мне хотелось бы на прощание (в мои годы всякое свидание с людьми есть прощание) вкратце сказать вам, как, по моему понятию, надо жить людям для того, чтобы жизнь наша не была злом и горем, какою она теперь кажется большинству людей, а была бы тем благом и радостью, какою она и должна быть."],[2,"Всё дело в том, как понимает человек свою жизнь."],[3,"Если понимать свою жизнь так, что она дана мне, Ивану, Петру, Марье, чтобы добыть как можно больше всяких радостей, удовольствий, счастья этому «я», Ивану, Петру, Марье, то жизнь всегда и для всех будет несчастна и озлобленна."],[4,"Несчастная и озлобленная жизнь будет потому, что всего, чего хочется для себя одному человеку, хочется и всякому другому."],[5,"А так как каждому хочется всякого добра как можно больше для себя и добро это одно и то же для всех людей, то добра этого для всех всегда недостаёт."],[6,"И если люди живут каждый для себя – не миновать им отнимать друг у друга, бороться, злиться друг на друга, и от этого жизнь их не бывает счастливою."],[7,"Если временами люди и добудут себе того, чего им хочется, то им всегда мало, и они стараются добыть всё больше и больше и, кроме того, ещё и боятся, что у них отнимут то, что они добыли, и завидуют тем, которые добыли то, чего у них нет."],[8,"Так что если люди понимают свою жизнь каждый в своём теле, то жизнь таких людей не может не быть несчастною."],[9,"Такая она и есть теперь для всех таких людей."],[10,"А такою, то есть несчастною, жизнь не должна быть."]],"a":[2,5],"why":"В предложении 2 содержится форма личного местоимения «им» («они»), которая заменяет Тётю Полли и Гильдегарду, упомянутых в предыдущем предложении. Предложение 5 связано с 4 при помощи формы личного местоимения «их» («они»), которая заменяет существительное «женщин».","verifiedBy":"ключ источника"},{"id":"S16625","source":"Школково","prompt":"Среди предложений 21-24 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи лексического повтора и форм слова. Напишите номер(-а) этого(-их)предложения(-ий).","lo":21,"hi":24,"s":[[21,"Штабс-капитанское жалованье, на него не раскутишься."],[22,"— Не покупай яблок, накопишь побольше, чем за колечко дадут; да и мало ли на чём можно сберечь!"],[23,"Каждый раз, когда мама уходила, Серёжа решительно говорил ей: — Мама, без кольца не смей приходить."],[24,"Наконец, решили написать отцу, – как он скажет, так и сделать."]],"a":[24],"why":"В предложении 24 повторяется сочетание слов «только бы», которое использовано в предыдущем предложении; также там содержится существительное «благом», являющееся формой слова «благо», употреблённого в предложении 23 (изменился только падеж). \n \nОтвет: 24\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S81160","source":"Школково","prompt":"Среди предложений 26-32 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи форм слов, притяжательного местоимения и контекстных синонимов. Напишите номер(-а) этого(-их) предложения(-ий).","lo":26,"hi":32,"s":[[26,"В подавляющих случаях человек, берущий на себя смелость написать и напечатать роман, стихи, пьесу и т.п., не имеет достаточного багажа: ни развития, ни умения обобщать, ни опыта жизни."],[27,"Это понятно: пыл творчества появляется на заре жизни."],[28,"Часто молодой писатель – это только талант."],[29,"То же и о читателе."],[30,"Воспринимать искусство, может быть, столь же трудно, как и творить его."],[31,"И опять самый яростный читатель – молодой, начинающий путь жизни."],[32,"И здесь выявляется важная и нужная роль критики: быть школой для читателя и писателя, быть университетом, энциклопедией, повышать культурный уровень того и другого."]],"a":[30],"why":"Необходимо найти такое предложение, которое связано с предыдущим при помощи форм слов, притяжательного местоимения и контекстных синонимов. \n \nФормы слова – варианты одного и того же слова, которые отличаются грамматическими значениями (у существительных меняется падеж или число; у прилагательных – род, число или падеж; у глагола – время, число, лицо или род; местоимение меняется в зависимости от того, какую часть речи заменяет).\n\nКонтекстные синонимы – это слова обычно одной и той же части речи, которые в определённом контексте приобретают схожее значение. \nПритяжательные местоимения – разряд местоимений, которые указывают на признак предмета по его принадлежности к чему-либо или кому-либо («мой», «твой», «их», «его», «её», «свой», «наш», «ваш»).\n \n(29)Прошло несколько дней, пришли ответы из армии от Серёжина отца и Серёже, и маме. (30)Серёжа своё письмо распечатал, а читать не может: сердце бьётся от нетерпения узнать, что в том письме написано, которое мама читает. \n\nВ указанном отрывке есть только одно предложение, связанное с предыдущим при помощи формы слова, притяжательного местоимения и контекстного синонима. В предложении 30 использовано имя собственное «Сережа» (именительный падеж), форма которого «Сереже» (дательный падеж) использована в предложении 29. Также предложение 30 содержит притяжательное местоимение «своё», которое указывает на принадлежность письма Сереже. Существительное «письмо» является контекстным синонимом к существительному «ответы», которое использовано в предложении 29.\nОтвет: 30\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S87165","source":"Школково","prompt":"Среди предложений 11-15 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим только при помощи однокоренных слов. Запишите номер(а) этого(-их) предложения(-ий).","lo":11,"hi":15,"s":[[11,"Душа тесно сливается с радостною жизнью мира."],[12,"Всюду вокруг эта близкая, родная душа, единая жизнь – в людях, в животных, даже в растениях – «веселы были растения», даже в самой земле: «земля живёт несомненною, живою, тёплою жизнью, как и все мы, взятые от земли»."],[13,"Не разумом, не умственным путём познаёт Толстой это единство, а проникновением другого рода, несравненно более полным и глубоким, чем проникновения разума."],[14,"И в чудесном этом единении бледнеет, как-то странно теряет свою жгучую важность ряд вопросов, тяжко мучающих душу Достоевского, – вопросов о бессмертии, о Боге…"],[15,"И крепко, всей душою, всем существом своим Толстой знает, что человек сотворён для счастья, что человек может и должен быть прекрасен и счастлив на земле."]],"a":[13],"why":"В данном отрывке есть одно предложение, которое связано с предыдущим только при помощи однокоренного слова. Предложение 13 содержит глагол «вспомнить» (корень -ПОМН-), который является однокоренным существительному «воспоминаний» (корень -ПОМИН-), употребленному в предложении 12. Обратите внимание: в предложении 11 есть глагол «помнишь», он является однокоренным существительному «воспоминаний», однако предложение 12 присоединяется к предыдущему ещё и с помощью союза «И» => в ответ не входит, так как задание предполагает наличие только названного в условии средства связи.\nОтвет: 13\nРазобрать с репетитором\nКурсы\nВсё необходимое для достижения цели","verifiedBy":"ключ источника"},{"id":"S87170","source":"Школково","prompt":"Среди предложений 1-8 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим только при помощи форм слов. Запишите номер(а) этого(-их) предложения(-ий).","lo":1,"hi":8,"s":[[1,"Турченко очень редко показывался в уездном свете, потому что три четверти жизни проводил в лесу."],[2,"Лес был его настоящею семьёю и, кажется, единственной страстной привязанностью к жизни."],[3,"В городе над ним за глаза посмеивались и считали чудаком."],[4,"Имея полную и бесконтрольную возможность подторговывать в свою пользу лесными делянками, отводимыми на сруб, он жил только на своё полуторастарублёвое жалованье, – жалованье поистине нищенское, если принять во внимание ту культурную, ответственную и глубоко важную работу, которую самоотверженно нёс на своих плечах целые двадцать лет этот удивительный Иван Иванович."],[5,"Право, только среди чинов лесного корпуса, в этом распрозабытом из всех забытых ведомств, да ещё среди земских врачей, загнанных, как почтовые клячи, мне и приходилось встречать этих чудаков, фанатиков дела и бессребреников."],[6,"Под его надзором и охраной было двадцать семь тысяч десятин казённого леса, да ещё по просьбе миллионеров братьев Солодаевых он присматривал за их громадными, прекрасно сохранёнными лесами в южной части уезда."],[7,"Но и этого ему было мало: он самовольно взял под своё покровительство и все окрестные – смежные и чересполосные – крестьянские леса."],[8,"Совершая для крестьян за гроши, а чаще безвозмездно разные межевые работы и лесообходные съёмки, он собирал сходы, говорил горячо и просто о великом значении в сельском хозяйстве больших лесных площадей и заклинал крестьян беречь лес пуще глаза."]],"a":[2,3],"why":"В данном отрывке есть два предложения, которые связаны с предыдущими при помощи форм слова. В предложении 2 содержится существительное «жизнь» (винительный падеж), которое является формой существительного «жизни» (дательный падеж), употребленного в предложении 1; также в предложении 2 есть имя собственное «Достоевский» (именительный падеж), которое является формой слова «Достоевского» (родительный падеж) из предложения 1. В предложении 3 есть местоимение «нами» (творительный падеж), которое является формой слова «нас» (винительный падеж) из предложения 2. Обратите внимание: в предложении 4 есть существительное «пустоты» (родительный падеж), оно является формой существительного «пустота» (именительный падеж) из предложения 3, однако предложение 4 присоединяется к предыдущему ещё и с помощью союза «И» => в ответ не входит, так как задание предполагает наличие только названного в условии средства связи.\nОтвет: 23\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S87190","source":"Школково","prompt":"Среди предложений 4-10 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи форм слов и синонимов. Запишите номер(а) этого(-их) предложения(-ий).","lo":4,"hi":10,"s":[[4,"Кормить лошадей остановились мы в большом селе Бахчи-Салах у знакомого моего дедушки."],[5,"В комнатах не было ни ветра, ни пыли, но было так же неприятно, душно и скучно, как в степи и по дороге."],[6,"Помню, запылённый и изморённый зноем, сидел я в углу на зелёном сундуке."],[7,"Хозяин не спеша вышел в сени и крикнул: — Машя!"],[8,"Ступай наливай чай!"],[9,"Где ты?"],[10,"Послышались торопливые шаги, и в комнату вошла девушка лет шестнадцати, в простом ситцевом платье и в белом платочке."]],"a":[7],"why":"Нужно найти предложение, связанное с предыдущим при помощи форм слова и синонимов.\n \nФорма слова – варианты одного и того же слова, которые отличаются грамматическими значениями (у существительных меняется падеж или число; у прилагательных – род, число или падеж; у глагола – время, число, лицо или род; местоимение меняется в зависимости от того, какую часть речи заменяет).\n \nСинонимы – это слова обычно одной части речи, различные по написанию и звучанию, но близкие по значению.\n \n(4)Мне хотелось путешествовать не официально, не приехать и «осматривать», а жить и смотреть на всё, не задавая себе утомительных уроков осматривать ежедневно по стольку-то улиц, музеев, зданий, церквей. (5)От такого путешествия остаётся в голове хаос улиц, памятников, да и то ненадолго.\n(6)Вообще, большая ошибка – стараться собирать впечатления: получишь чего не надо, а что надо, то ускользнёт. (7)Если путешествуешь не для специальной цели, нужно, чтобы впечатления нежданно и незвано сами собирались в душу. (8)Оттого я довольно равнодушно пошёл вслед за другими в Британский музей. (9)Мы целое утро осматривали древности, этрусские, египетские и другие залы, потом змей, рыб, насекомых – почти всё то, что есть и в Петербурге, в Вене, в Мадриде. (10)Оттого меня тянуло всё на улицу: хотелось побродить не между мумиями, а среди живых людей.\n\nВ предложенном фрагменте есть только одно предложение, связанное с предыдущим при помощи форм слова и синонимов. Предложение 7 содержит глагол “собирались” (3 лицо, множественное число, прошедшее время), которое является формой слова “собирать” (инфинитив). Также в предложении 7 есть слово “нужно”, которое является синонимом слову “надо” из предложения 6.\nОтвет: 7\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S87205","source":"Школково","prompt":"Среди предложений 1-9 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи форм слова. Запишите номер(а) этого(-их) предложения(-ий).","lo":1,"hi":9,"s":[[1,"Об этом человеке носились странные слухи: говорили, что он был нелюдим, ни с кем не знался, вечно сидел один, занимаясь химией, проводил жизнь за микроскопом, читал даже за обедом и ненавидел женское общество."],[2,"О нём сказано в «Горе от ума»: — Он химик, он ботаник, Князь Фёдор, наш племянник, От женщин бегает и даже от меня."],[3,"Мои родственники называли его не иначе как Химик, придавая этому слову порицательный смысл и подразумевая, что химия вовсе не может быть занятием порядочного человека."],[4,"С самого начала нашего знакомства Химик увидел, что я серьёзно занимаюсь, и стал уговаривать, чтоб я бросил «пустые» занятия литературой, а принялся бы за естественные науки."],[5,"Он дал мне речь Кювьé о геологических переворотах и де Кандóлеву растительную органографию."],[6,"Видя, что чтение идёт на пользу, он предложил свои превосходные собрания, снаряды, гербарии и даже своё руководство."],[7,"Он на своей почве был очень занимателен, чрезвычайно учён, остёр и даже любезен; но для этого не надобно было ходить дальше обезьян; от камней до орангутанга его всё интересовало, далее он неохотно пускался, особенно в философию, которую считал болтовнёй."],[8,"Он не был ни консерватором, ни отсталым человеком, он просто не верил в людей, то есть верил, что эгоизм – исключительное начало всех действий, и находил, что его сдерживает только безумие одних и невежество других."],[9,"Меня возмущал его материализм."]],"a":[4],"why":"Нужно найти предложение, связанное с предыдущим при помощи форм слова.\n \nФорма слова – варианты одного и того же слова, которые отличаются грамматическими значениями (у существительных меняется падеж или число; у прилагательных – род, число или падеж; у глагола – время, число, лицо или род; местоимение меняется в зависимости от того, какую часть речи заменяет).\n \n(1)Помню, будучи ещё гимназистом V или VI класса, я ехал с дедушкой в Ростов-на-Дону. (2)День был августовский, знойный, томительно скучный. (3)От жара и сухого, горячего ветра, гнавшего нам навстречу облака пыли, слипались глаза, сохло во рту; не хотелось ни глядеть, ни говорить, ни думать. (4)Кормить лошадей остановились мы в большом селе Бахчи-Салах у знакомого моего дедушки.\n(5)В комнатах не было ни ветра, ни пыли, но было так же неприятно, душно и скучно, как в степи и по дороге. (6)Помню, запылённый и изморённый зноем, сидел я в углу на зелёном сундуке. (7)Хозяин не спеша вышел в сени и крикнул:\n— Машя! (8)Ступай наливай чай! (9)Где ты?\n\nВ указанном отрывке есть только одно предложение, которое связано с предыдущим при помощи форм слова. Предложение 4 содержит местоимение “мы” (именительный падеж), которое является формой слова “нам” (дательный падеж) из предложения 3.\nОтвет: 4\nРазобрать с репетитором","verifiedBy":"ключ источника"},{"id":"S183393","source":"Школково","prompt":"Среди предложений 4-8 найдите такое(-ие), которое(-ые) связано(-ы) с предыдущим при помощи личного местоимения и форм слова. Запишите номер(а) этого(-их) предложения(-ий).","lo":4,"hi":8,"s":[[4,"С самого начала нашего знакомства Химик увидел, что я серьёзно занимаюсь, и стал уговаривать, чтоб я бросил «пустые» занятия литературой, а принялся бы за естественные науки."],[5,"Он дал мне речь Кювьé о геологических переворотах и де Кандóлеву растительную органографию."],[6,"Видя, что чтение идёт на пользу, он предложил свои превосходные собрания, снаряды, гербарии и даже своё руководство."],[7,"Он на своей почве был очень занимателен, чрезвычайно учён, остёр и даже любезен; но для этого не надобно было ходить дальше обезьян; от камней до орангутанга его всё интересовало, далее он неохотно пускался, особенно в философию, которую считал болтовнёй."],[8,"Он не был ни консерватором, ни отсталым человеком, он просто не верил в людей, то есть верил, что эгоизм – исключительное начало всех действий, и находил, что его сдерживает только безумие одних и невежество других. В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. Предложение 5 содержит личное местоимение «он», которое заменяет существительное (имя собственное) «Химик» из предложения 4. Также в этом предложении есть местоимение «мне» (дательный падеж), которое является формой местоимения «я» (именительный падеж) из предложения 4. Обратите внимание: личное местоимение является средством связи только тогда, когда оно заменяет существительное из предыдущего предложения. По этой причине местоимения «он», содержащиеся в предложениях 6-8, не связывают их с предыдущими (перед нами пример связи при помощи лексического повтора). В предложении 7 также использовано личное местоимение «его» (винительный падеж), являющееся формой местоимения «он» из того же предложения. Кроме того, в предложении 8 есть личное местоимение «его», однако оно заменяет существительное «эгоизм» из ЭТОГО ЖЕ предложения, а не из предыдущего. Ответ: 5"]],"a":[5],"why":"В данном отрывке есть только одно предложение, связанное с предыдущим при помощи указанных в задании средств. Предложение 5 содержит личное местоимение «он», которое заменяет существительное (имя собственное) «Химик» из предложения 4. Также в этом предложении есть местоимение «мне» (дательный падеж), которое является формой местоимения «я» (именительный падеж) из предложения 4.\n\nОбратите внимание: личное местоимение является средством связи только тогда, когда оно заменяет существительное из предыдущего предложения. По этой причине местоимения «он», содержащиеся в предложениях 6-8, не связывают их с предыдущими (перед нами пример связи при помощи лексического повтора). В предложении 7 также использовано личное местоимение «его» (винительный падеж), являющееся формой местоимения «он» из того же предложения. Кроме того, в предложении 8 есть личное местоимение «его», однако оно заменяет существительное «эгоизм» из ЭТОГО ЖЕ предложения, а не из предыдущего.\nОтвет: 5\nРазобрать с репетитором\nПредыдущий раздел\nСледующий раздел\n8 800 302-92-79info@shkolkovo.net\nТелеграм БОТТехническая поддержка\nКаталог курсов\nЕГЭОГЭОлимпиадыКружкиДВИШкольный курсДругие курсыВсе курсы\nЛегендарный интенсив. Щелчок\nАкции и скидкиСпециальные программы\nБесплатно\nАвторская база задачКонструктор вариантовКвизыТеорияПлатформа БОБРПриложение БОБРБесплатные интенсивы по олимпиадам\nПлатформа Школково\nНаши преподавателиРепетиторыОтзывы о ШколковоКонтактыБиржа работыСведения об образовательной организации\nТехническая поддержка\nДля СМИ и партнёровМедиа «Журналково»\nМероприятия\nПервая математическая олимпиадаТурнир математических игрВсероссийский пробник Школково\nОбразовательная лицензия\n№ Л035-01298-77/00646528\nот 05 апреля 2023\nРеестр российского ПО\nРеестровая запись №27761\nот 06.05.2025\nИТ-деятельность\nСведения о деятельности в области\nинформационных технологий\nПриложение БОБР\nЛичный кабинет объединяет платформы БОБР и Школково. Можно смотреть уроки без интернета и настраивать уведомления под себя.\nRuStoreAppStore\nПартнёр\nСтатус проекта «Сколково»\nПолитика конфиденциальностиПользовательское соглашениеДоговор офертыПартнерское соглашение","verifiedBy":"ключ источника"}];
